def build_compare_shard_prompt(remove_headers: bool) -> str:
    part1 = """أنت خبير تدقيق نصوص عربية. ستتلقى:
1) جزء من ملف PDF الأصلي (مرفق) — صفحات محددة.
2) النص المستخرج من هذا الجزء (مُلصق في الرسالة).

مهمتك: **اكتشف ما إذا كان قد سقط أي محتوى** من النص المستخرج بمقارنته بالـ PDF.

"""
    if remove_headers:
        part2 = """وضع الاستخراج: **حذف الترويسات والهوامش وأرقام الصفحات** — لذلك:
• تجاهل: التشكيل، الترويسات/الهوامش/أرقام الصفحات إن حُذفت عمداً، فروق الأسطر، تصحيحات OCR البسيطة.
• ركّز على: جمل/فقرات/اقتباسات/أحاديث/أبيات من **متن النص** مفقودة."""
    else:
        part2 = """وضع الاستخراج: **الاحتفاظ بالترويسات والهوامش وأرقام الصفحات** — لذلك:
• تجاهل: التشكيل فقط، فروق الأسطر البسيطة، تصحيحات OCR البسيطة.
• ركّز على: أي محتوى مفقود بما فيه الترويسات/الهوامش/أرقام الصفحات/الحواشي/المتن."""

    part3 = """

⚠️ تنبيه مهم جداً:
• **لا تفترض التطابق** قبل المقارنة الفعلية الدقيقة.
• قارن **كل فقرة** من PDF بما يقابلها في النص المستخرج.
• إن وجدت فقرة أو جملة في PDF غير موجودة في المستخرج: سجّلها مهما كان حجمها.
• كن **متحفّظاً** — في حال الشك اعتبره فجوة وسجّلها.
• لا تكتفِ بالقول "النصان متطابقان" دون تدقيق فعلي بند ببند.

⚠️ قاعدة صارمة لانقطاع النص والجمل والآيات بين الأجزاء:
• عندما ينتهي الجزء المرفق بمنتصف جملة أو منتصف آية أو منتصف حديث (بسبب انقطاع الصفحات عند حد الجزء)، وكان النص المستخرج متوقفاً عند نفس الكلمة الظاهرة في الـ PDF: **فهذا سليم تماماً وليس فجوة أو نقصاً**.
• **ممنوع** اعتبار انقطاع الجملة أو الآية أو الحديث بين الأجزاء "فجوة" أو "نقصاً" طالما أن النص المستخرج طابق تماماً جميع الكلمات الظاهرة في صفحات الجزء المرفق.
• الفجوات والنقص تُسجَّل **فقط** إذا كانت هناك كلمات أو فقرات **ظاهرة داخل صفحات الجزء المرفق** وغائبة عن النص المستخرج.


أخرج JSON فقط:
{
  "shard_assessment": "ممتاز | جيد | متوسط | ضعيف",
  "coverage_pct": 0-100,
  "missing_items": [
    {
      "snippet": "نص قصير مفقود (50-200 حرف)",
      "location_hint": "وصف الموقع التقريبي في الجزء",
      "severity": "خطير | متوسط | بسيط"
    }
  ],
  "notes": "ملاحظات موجزة"
}
لا تكتب أي شيء خارج JSON."""
    return part1 + part2 + part3


# ═══════════════════════════════════════════════════════════════════
#  PHASE 2 & 4 GENERAL HELPERS
# ═══════════════════════════════════════════════════════════════════

def safe_call(fn, *args, log=None, **kwargs):
    try:
        return fn(*args, **kwargs)
    except Exception as e:
        if log:
            try: log(f"[safe_call] {fn.__name__ if hasattr(fn, '__name__') else str(fn)}: {e}")
            except Exception: pass
        return None


def _stat_or_none(path: Path):
    try:
        return path.stat().st_mtime
    except Exception:
        return None


def _file_metrics_path_key(path) -> str:
    """مفتاح موحّد لمسارات الملفات دون حلّ symlinks أو لمس القرص."""
    try:
        return os.path.normcase(os.path.abspath(os.path.expanduser(os.fspath(path))))
    except Exception:
        return str(path)


def cached_by_mtime(counter_fn: Callable[[Path], int]) -> Callable[[Path], int]:
    """كاش محدود لعدّادات الملفات، يبطل تلقائياً بتغير الوقت أو الحجم."""
    @lru_cache(maxsize=1024)
    def _cached_fn(path_str: str, mtime_ns: int, size: int) -> int:
        return counter_fn(Path(path_str))

    def wrapper(path: Path) -> int:
        try:
            path = Path(path)
            stat = path.stat()
            path_str = str(path.resolve())
            return _cached_fn(path_str, int(stat.st_mtime_ns), int(stat.st_size))
        except Exception:
            try:
                return counter_fn(Path(path))
            except Exception:
                return 0
    return wrapper


class BookPaths:
    def __init__(self, output_dir: Path, book_stem: str):
        self.output_dir = Path(output_dir)
        self.book_stem = book_stem
    @property
    def data_dir(self) -> Path:
        return get_book_data_dir(self.output_dir, self.book_stem)
    @property
    def parts(self) -> Path:
        return get_book_parts_dir(self.output_dir, self.book_stem)
    @property
    def shards(self) -> Path:
        return get_book_shards_dir(self.output_dir, self.book_stem)
    @property
    def checkpoints(self) -> Path:
        return get_book_checkpoints_dir(self.output_dir, self.book_stem)
    @property
    def compare(self) -> Path:
        return get_book_compare_dir(self.output_dir, self.book_stem)
    @property
    def meta_path(self) -> Path:
        return get_book_meta_path(self.output_dir, self.book_stem)


def resolve_ascii_safe_upload_path(src_path: Path, cache_key: str, tmp_root: Optional[Path] = None, ext: str = ".pdf", original_fallback_name: Optional[str] = None) -> Tuple[Path, str]:
    """يرجع (مسار آمن للرفع, اسم آمن) - يبني نسخة مؤقتة ASCII فقط عند الحاجة."""
    src_path = Path(src_path)
    original_name = original_fallback_name if original_fallback_name else src_path.name
    
    def is_ascii_safe(s: str) -> bool:
        try:
            s.encode("ascii")
            return True
        except UnicodeEncodeError:
            return False

    if is_ascii_safe(str(src_path)) and is_ascii_safe(original_name):
        return src_path, original_name

    safe_name = f"{cache_key}{ext}" if not cache_key.endswith(ext) else cache_key

    candidates = []
    if tmp_root:
        candidates.append(Path(tmp_root))
    else:
        try:
            candidates.append(Path(tempfile.gettempdir()) / "gemini_pdf_safe")
        except Exception:
            pass
        if sys.platform == "win32":
            candidates.append(Path("C:/Temp/gemini_pdf_safe"))
            candidates.append(Path(os.environ.get("TEMP", "C:/Temp")) / "gemini_pdf_safe")
        else:
            candidates.append(Path("/tmp/gemini_pdf_safe"))

    tmp_dir = None
    for d in candidates:
        try:
            d.mkdir(parents=True, exist_ok=True)
            if is_ascii_safe(str(d)):
                tmp_dir = d
                break
            if tmp_dir is None:
                tmp_dir = d
        except Exception:
            continue

    if tmp_dir is None:
        raise RuntimeError("تعذر إنشاء مجلد مؤقت آمن لرفع الملف")

    safe_path = tmp_dir / safe_name
    try:
        if (not safe_path.exists()) or safe_path.stat().st_size != src_path.stat().st_size:
            shutil.copy2(str(src_path), str(safe_path))
    except Exception as e:
        raise RuntimeError(f"تعذر نسخ الملف لمسار ASCII آمن: {e}")

    return safe_path, safe_name



def fast_upload_pdf(api_key: str, file_path: Path, display_name: str,
                    stop_event: threading.Event,
                    log: Callable[[str], None] = lambda m: None) -> "types.File":
    """رفع PDF بجلسة resumable وبكتل صغيرة قابلة للاستئناف.

    لا يُحمّل الملف كله إلى الذاكرة. حدّ محاولات النقل يخص الفشل المتكرر
    فقط، لا عدد الكتل؛ لذلك تُرفع الملفات الأكبر من خمس كتل كاملةً. عند
    انقطاع النقل لا تُعاد أي كتلة قبل الاستعلام عن حجم البيانات المؤكد من
    الخادم (X-Goog-Upload-Size-Received).
    """
    file_path = Path(file_path)
    size = file_path.stat().st_size
    if size <= 0:
        raise RuntimeError("ملف PDF فارغ")
    if stop_event.is_set():
        raise InterruptedError("توقف")

    # حد RPM اختياري يخص استدلال النموذج؛ رفع الملفات له سقف مستقل.
    throttle_key_send(api_key, stop_event, log, purpose="upload")
    try:
        import httpx
    except Exception:
        client = genai.Client(
            api_key=api_key,
            http_options=types.HttpOptions(timeout=600_000))
        try:
            register_stop_component("clients", client)
        except Exception:
            pass
        try:
            return client.files.upload(
                file=str(file_path),
                config=types.UploadFileConfig(mime_type="application/pdf",
                                              display_name=display_name))
        finally:
            try:
                unregister_stop_component("clients", client)
            except Exception:
                pass
            try:
                if hasattr(client, "close"):
                    client.close()
            except Exception:
                pass

    base = "https://generativelanguage.googleapis.com"
    chunk_size = 8 * 1024 * 1024
    max_consecutive_failures = 5
    consecutive_failures = 0
    no_progress_count = 0
    last_reported_pct = -1
    offset = 0
    last_err: Optional[Exception] = None

    # استخدم اتصال HTTP واحداً للجلسة حتى يعاد استخدام TLS/keep-alive بين الكتل.
    with httpx.Client(timeout=httpx.Timeout(600.0, connect=30.0)) as hc:
        try:
            register_stop_component("clients", hc)
            if stop_event.is_set():
                raise InterruptedError("توقف")
            try:
                response = hc.post(
                    base + "/upload/v1beta/files",
                    params={"key": api_key},
                    json={"file": {"display_name": display_name,
                                   "mime_type": "application/pdf"}},
                    headers={
                        "X-Goog-Upload-Protocol": "resumable",
                        "X-Goog-Upload-Command": "start",
                        "X-Goog-Upload-Header-Content-Length": str(size),
                        "X-Goog-Upload-Header-Content-Type": "application/pdf",
                    },
                    timeout=httpx.Timeout(30.0, connect=15.0))
            except Exception as exc:
                raise RuntimeError(f"تعذر بدء جلسة الرفع: {exc}") from exc
            if response.status_code != 200:
                raise RuntimeError(
                    f"تعذر بدء رفع ({response.status_code}): {response.text[:250]}")
            upload_url = response.headers.get("x-goog-upload-url", "")
            if not upload_url:
                raise RuntimeError("لم يُرجع الخادم رابط الرفع (x-goog-upload-url)")

            while True:
                if stop_event.is_set():
                    raise InterruptedError("توقف")
                remaining = max(0, size - offset)
                send_len = min(chunk_size, remaining)
                command = ("upload, finalize"
                           if offset + send_len >= size else "upload")
                try:
                    with file_path.open("rb") as fh:
                        fh.seek(offset)
                        data = fh.read(send_len)
                    if len(data) != send_len:
                        raise OSError("تعذرت قراءة كتلة الرفع كاملةً من الملف")
                    response = hc.post(
                        upload_url,
                        headers={
                            "X-Goog-Upload-Command": command,
                            "X-Goog-Upload-Offset": str(offset),
                            "Content-Type": "application/pdf",
                        },
                        content=data)
                    code = int(response.status_code)
                    if code not in (200, 308):
                        detail = f"فشل الرفع ({code}): {response.text[:250]}"
                        # 429/أخطاء العميل لا تتحسن بإعادة الكتلة أو الملف.
                        if code == 429 or (400 <= code < 500 and code not in (408, 409)):
                            raise RuntimeError(detail)
                        raise RuntimeError(detail)

                    # واجهة Google resumable تعيد هذا الرأس عند التقدم؛ لا تعتمد
                    # على X-Goog-Upload-Offset الذي لا يُعاد في كل إصدارات الخدمة.
                    received = (response.headers.get("x-goog-upload-size-received")
                                or response.headers.get("x-goog-upload-offset"))
                    if received is not None:
                        confirmed = int(received)
                    elif code == 200:
                        # 200 إقرار نجاح للكتلة كاملة إذا لم يُرسل رأس الحجم.
                        confirmed = offset + send_len
                    else:
                        # 308 بلا حجم مؤكد: استعلم قبل أي إرسال إضافي.
                        raise RuntimeError(
                            "استجابة 308 لم تتضمن حجم الرفع المؤكد؛ يلزم الاستعلام عن الإزاحة")
                    if confirmed < offset or confirmed > size:
                        raise RuntimeError(
                            f"إزاحة رفع غير صالحة من الخادم: {confirmed} من {size}")
                    if confirmed == offset:
                        no_progress_count += 1
                        if no_progress_count > 2:
                            raise RuntimeError(
                                "لم يؤكد الخادم تقدماً في الرفع بعد الاستعلامات؛ "
                                "أُوقفنا لمنع إعادة إرسال البيانات بلا نهاية")
                    else:
                        no_progress_count = 0
                    offset = confirmed
                    consecutive_failures = 0

                    pct = int(100 * offset / size)
                    if pct >= last_reported_pct + 20 or pct >= 100:
                        log(f"جارٍ رفع PDF: {pct}% ({offset / 1024 / 1024:.1f}/"
                            f"{size / 1024 / 1024:.1f} MB)")
                        last_reported_pct = pct

                    if command.endswith("finalize") and code == 200:
                        meta = (response.json() or {}).get("file", {})
                        if not meta.get("name"):
                            raise RuntimeError("لم يُرجع الخادم الملف (name مفقود)")
                        log(f"اكتمل رفع {meta.get('name')} ({size / 1024 / 1024:.1f} MB)")
                        return types.File._from_response(response=meta, kwargs={})
                    # 308 أو إقرار كتلة أخيرة غير نهائي: حلقة تالية ترسل finalize
                    # بصفر بايت إذا أكد الخادم استلام الملف كله.
                    continue

                except InterruptedError:
                    raise
                except Exception as exc:
                    last_err = exc
                    status_code = getattr(exc, "status_code", None)
                    if status_code is None:
                        status_code = getattr(getattr(exc, "response", None),
                                              "status_code", None)
                    if status_code is None:
                        match = re.search(r"\((\d{3})\)", str(exc))
                        if match:
                            try:
                                status_code = int(match.group(1))
                            except Exception:
                                status_code = None
                    if status_code is not None:
                        status_code = int(status_code)
                        if status_code == 429 or (400 <= status_code < 500
                                                  and status_code not in (408, 409)):
                            raise RuntimeError(str(exc)) from exc

                    consecutive_failures += 1
                    if consecutive_failures > max_consecutive_failures:
                        break

                    # لا تُعد إرسال الكتلة حتى يُرجع الخادم حجمها المؤكد.
                    confirmed = None
                    query_error = None
                    for query_attempt in range(2):
                        if stop_event.is_set():
                            raise InterruptedError("توقف")
                        try:
                            query = hc.post(
                                upload_url,
                                headers={"X-Goog-Upload-Command": "query"},
                                timeout=httpx.Timeout(30.0, connect=15.0))
                            qcode = int(query.status_code)
                            if qcode == 429 or (400 <= qcode < 500
                                                and qcode not in (408, 409)):
                                raise RuntimeError(
                                    f"استعلام جلسة الرفع مرفوض ({qcode}): {query.text[:200]}")
                            if qcode != 200:
                                query_error = RuntimeError(
                                    f"استعلام الإزاحة أعاد HTTP {qcode}")
                            else:
                                raw_size = (query.headers.get("x-goog-upload-size-received")
                                            or query.headers.get("x-goog-upload-offset"))
                                if raw_size is None:
                                    query_error = RuntimeError(
                                        "استعلام الرفع لم يتضمن X-Goog-Upload-Size-Received")
                                else:
                                    confirmed = int(raw_size)
                                    if confirmed < 0 or confirmed > size:
                                        raise RuntimeError(
                                            f"إزاحة مؤكدة غير صالحة: {confirmed} من {size}")
                                    break
                        except Exception as query_exc:
                            query_error = query_exc
                            qstatus = getattr(query_exc, "status_code", None)
                            if qstatus is None:
                                qstatus = getattr(getattr(query_exc, "response", None),
                                                  "status_code", None)
                            try:
                                qstatus = int(qstatus) if qstatus is not None else None
                            except Exception:
                                qstatus = None
                            if qstatus == 429 or (qstatus is not None and 400 <= qstatus < 500
                                                  and qstatus not in (408, 409)):
                                raise RuntimeError(str(query_exc)) from query_exc
                        if query_attempt == 0:
                            interruptible_sleep(1.0, stop_event)

                    if confirmed is None:
                        raise RuntimeError(
                            "تعذّر تأكيد موضع جلسة الرفع؛ أُوقف الإرسال لتجنب إعادة "
                            f"رفع بيانات سبق إرسالها. السبب: {query_error or last_err}") from last_err
                    if confirmed > offset:
                        log(f"انقطع الرفع؛ أكد الخادم {confirmed / 1024 / 1024:.1f} MB — "
                            "سيُستأنف من الإزاحة المؤكدة فقط")
                    offset = confirmed
                    delay = min(8.0, 1.5 * (2 ** (consecutive_failures - 1)))
                    interruptible_sleep(delay, stop_event)
            raise RuntimeError(f"فشل رفع الملف بعد محاولات الاستئناف: {last_err}")
        finally:
            try:
                unregister_stop_component("clients", hc)
            except Exception:
                pass

def _downscale_pdf_for_detection(src_path: Path, out_dir: Path,
                                 target_width: int,
                                 stop_event: Optional[threading.Event] = None
                                 ) -> Optional[Path]:
    """يعيد رسم صفحات PDF كصور JPEG بعرض ~target_width بكسل ويركبها PDF جديد
    (لرفع كشف التقسيم فقط). يحتاج مكتبة pymupdf الاختيارية؛ ترجع None عند
    عدم توفرها أو أي خطأ. كشف التقسيم لا يحتاج دقة عالية: يكفي قراءة
    العناوين ونهايات الجمل، والتصغير يوفّر وقت الرفع على الصوايع البطيئة
    وكمية توكنز الصور في الطلب نفسه."""
    try:
        try:
            import pymupdf as _fitz
        except Exception:
            import fitz as _fitz
    except Exception:
        return None
    try:
        out_dir = Path(out_dir)
        out_dir.mkdir(parents=True, exist_ok=True)
        out_path = out_dir / f"ds_{Path(src_path).stem}.pdf"
        doc = _fitz.open(str(src_path))
        newdoc = _fitz.open()
        try:
            for pno in range(doc.page_count):
                if stop_event is not None and stop_event.is_set():
                    raise InterruptedError("توقف")
                page = doc[pno]
                r = page.rect
                if r.width <= 0 or r.height <= 0:
                    continue
                zoom = min(4.0, max(0.05, float(target_width) / float(r.width)))
                pix = page.get_pixmap(matrix=_fitz.Matrix(zoom, zoom),
                                      alpha=False)
                jpg = pix.tobytes("jpeg", jpg_quality=72)
                npage = newdoc.new_page(width=r.width, height=r.height)
                npage.insert_image(npage.rect, stream=jpg)
        finally:
            try:
                doc.close()
            except Exception:
                pass
        if newdoc.page_count == 0:
            try:
                newdoc.close()
            except Exception:
                pass
            return None
        newdoc.save(str(out_path), garbage=3, deflate=True)
        try:
            newdoc.close()
        except Exception:
            pass
        return out_path
    except InterruptedError:
        raise
    except Exception:
        return None



def wait_for_file_active(client, file_obj, stop_event: threading.Event,
                          log: Callable[[str], None] = lambda m: None,
                          timeout: float = 180.0,
                          on_progress: Optional[Callable[[int], None]] = None,
                          initial_progress: int = 60):
    """ينتظر حتى يصبح ملف Gemini API بحالة ACTIVE، يرمي InterruptedError أو TimeoutError عند الحاجة.

    ✅ فشل سريع: إذا كان خطأ الاستطلاع بسبب حصة/معدل (429) أو تكرر الفشل عدة
    مرات، يُرمى استثناء فوراً (بدل استهلاك المهلة كاملة) — حتى ينتقل المستدعي
    للمفتاح التالي مباشرة. سابقاً كان كل مفتاح محظور يستهلك ~3 دقائق في
    استطلاع يفشل بلا فائدة، وهذا كان سبب «الرفع» الذي يستغرق دقائق طويلة.
    """
    t0 = time.time()
    name = getattr(file_obj, "name", None) or getattr(file_obj, "uri", "")
    progress = initial_progress
    consecutive_errors = 0
    while True:
        if stop_event.is_set():
            raise InterruptedError("توقف")
            
        try:
            state = getattr(getattr(file_obj, "state", None), "name", None) or str(getattr(file_obj, "state", ""))
        except Exception:
            state = ""
            
        if state == "ACTIVE":
            if on_progress:
                on_progress(100)
            return file_obj
            
        # ✅ حالة FAILED حقيقية بعد مهلة السماح القصيرة = فشل فوري، لا انتظار المهلة كاملة
        if state == "FAILED" and time.time() - t0 > 5:
            raise RuntimeError("الملف المرفوع فشل على الخادم (state=FAILED)")
            
        if time.time() - t0 > timeout:
            raise TimeoutError(f"انتهت مهلة تجهيز الملف المرفوع (state={state})")
            
        interruptible_sleep(2.0, stop_event)
        
        if on_progress:
            progress = min(progress + 10, 95)
            on_progress(progress)
            
        try:
            if name:
                fname = str(name)
                if "/" in fname:
                    fname = fname.split("/")[-1]
                file_obj = client.files.get(name=fname if not str(name).startswith("files/") else str(name))
                consecutive_errors = 0
            else:
                break
        except Exception as e:
            consecutive_errors += 1
            elapsed = int(time.time() - t0)
            # ✅ خطأ حصة/معدل: المفتاح نفسه محظور — الاستطلاع سيفشل طوال المهلة،
            #    نخرج فوراً ليتم ترحيل المحاولة للمفتاح التالي.
            if is_quota_error(e):
                # النص الكامل بلا تقطيع حتى تتعرف is_quota_error على الخطأ
                # وتُقيّد المفتاح في cooldown بدل اعتباره فشلاً عادياً.
                raise RuntimeError(f"المفتاح في حالة حصة/تقييد أثناء تجهيز الملف: {e}")
            # ✅ أخطاء متكررة (~6 محاولات ≈ 15 ثانية): الاتصال/الملف لا يستجيب،
            #    لا معنى لإكمال المهلة.
            if consecutive_errors >= 6:
                raise RuntimeError(f"أخطاء متكررة في تجهيز الملف خلال {elapsed}ث ({str(e)[:120]})")
            log(f"⏳ انتظار تفعيل الملف على الخادم ({elapsed}ث)... ({e})")
            interruptible_sleep(1.0, stop_event)
            
    return file_obj


def _generic_pdf_splitter(source_pdf: Path, shards_dir: Path, pages_per_batch: int,
                          log: Callable[[str], None], stop_event: Optional[threading.Event],
                          on_progress: Optional[Callable[[int, int], None]],
                          custom_ranges: Optional[List[Tuple[int, int]]],
                          backend_name: str,
                          read_total_pages: Callable[[Path], int],
                          write_shard: Callable[[Any, int, int, Path], None],
                          get_reader: Callable[[Path], Any] = lambda p: None,
                          check_existing_shard: Callable[[Path, int, int], bool] = lambda p, s, e: False,
                          on_start: Callable[[], None] = lambda: None
                          ) -> List[PDFShard]:
    on_start()
    reader = get_reader(source_pdf)
    total_pages = read_total_pages(source_pdf)
    log(f"   📃 إجمالي الصفحات: {total_pages}" if backend_name != "builtin" else f"   📃 صفحات تقديرية: {total_pages}")
    if total_pages == 0:
        raise RuntimeError("الملف فارغ!")
        
    ranges = custom_ranges if custom_ranges else []
    if not ranges:
        ranges = []
        current = 0
        while current < total_pages:
            end = min(current + pages_per_batch, total_pages)
            ranges.append((current + 1, end))
            current = end

    shards: List[PDFShard] = []
    idx = 1
    for page_start, page_end in ranges:
        try:
            _check_stop(stop_event)
            fname = f"shard_{idx:04d}_p{page_start:04d}-{page_end:04d}.pdf"
            spath = shards_dir / fname
            expected_pages = page_end - page_start + 1
            
            if spath.exists() and spath.stat().st_size > 100:
                if check_existing_shard(spath, page_start, page_end):
                    log(f"   ♻️  جزء {idx} موجود")
                    md5 = _compute_md5(spath)
                    shards.append(PDFShard(idx, page_start, page_end, expected_pages, spath, md5))
                    if on_progress: on_progress(idx, 0)
                    continue
                else:
                    if backend_name != "builtin":
                        safe_call(spath.unlink)
            
            write_shard(reader, page_start, page_end, spath)
            
            temp_shard = PDFShard(idx, page_start, page_end, expected_pages, spath, "")
            valid, note = is_valid_split_input(temp_shard)
            if not valid:
                log(f"   ⚠️  فشل تحقق جزء {idx}: {note} — سيتم تجاوزه")
                continue
                
            md5 = _compute_md5(spath)
            size_kb = spath.stat().st_size / 1024
            shards.append(PDFShard(idx, page_start, page_end, expected_pages, spath, md5))
            if backend_name == "builtin":
                log(f"   📄 جزء وهمي {idx}: نطاق {page_start}-{page_end}")
            else:
                log(f"   ✂️  جزء {idx}: صفحات {page_start}-{page_end} ({size_kb:.1f} KB)" if backend_name == "pypdf" else f"   ✂️  جزء {idx}: {page_start}-{page_end} ({size_kb:.1f} KB)")
            if on_progress: on_progress(idx, 0)
        except InterruptedError:
            raise
        except Exception as e:
            log(f"   ⚠️  فشل تقسيم الجزء {idx} ({page_start}-{page_end}): {e}")
        finally:
            idx += 1
            
    if backend_name == "builtin":
        log(f"✅ {len(shards)} جزء (builtin)")
    else:
        log(f"✅ تم التقسيم: {len(shards)} جزء" if backend_name == "pypdf" else f"✅ التقسيم تم: {len(shards)} جزء")
    return shards


