def make_spin(min_v: int, max_v: int, step: int = 1) -> QSpinBox:
    sb = QSpinBox()
    sb.setRange(min_v, max_v)
    sb.setSingleStep(step)
    sb.setMinimumWidth(100)
    sb.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Preferred)
    sb.setAlignment(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
    return sb

def make_dspin(min_v: float, max_v: float, step: float = 0.1, decimals: int = 2) -> QDoubleSpinBox:
    sb = QDoubleSpinBox()
    sb.setRange(min_v, max_v)
    sb.setSingleStep(step)
    sb.setDecimals(decimals)
    sb.setMinimumWidth(100)
    sb.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Preferred)
    sb.setAlignment(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
    return sb

def make_form_layout() -> QFormLayout:
    layout = QFormLayout()
    layout.setLabelAlignment(Qt.AlignmentFlag.AlignLeft)
    layout.setFieldGrowthPolicy(QFormLayout.FieldGrowthPolicy.ExpandingFieldsGrow)
    layout.setHorizontalSpacing(10)
    layout.setVerticalSpacing(8)
    return layout

