def coverage_color(pct: int, assessment: str = "") -> str:
    """يرجع كود اللون Hex حسب نسبة التغطية أو التقييم: ≥95 أخضر, ≥80 أصفر, ≥60 برتقالي, أقل أحمر."""
    a = assessment.strip() if assessment else ""
    if pct >= 95 or a == "ممتاز": return "#a6e3a1"
    if pct >= 80 or a == "جيد": return "#f9e2af"
    if pct >= 60 or a == "متوسط": return "#fab387"
    return "#f38ba8"

def _make_part_actions_button(main_window_ref, shard_idx: int) -> QWidget:
    widget = QWidget()
    widget.setLayoutDirection(Qt.LayoutDirection.RightToLeft)
    layout = QHBoxLayout(widget)
    layout.setContentsMargins(2, 2, 2, 2)
    layout.setSpacing(4)
    
    btn_txt = QPushButton("📝")
    btn_txt.setFixedSize(26, 26)
    btn_txt.setToolTip("فتح الملف النصي المستخرج للجزء")
    btn_txt.setStyleSheet("font-size: 12px; padding: 0;")
    
    # Resolve MainWindow reference
    mw = main_window_ref
    if not hasattr(mw, "_open_part_file") and hasattr(mw, "main_window"):
        mw = mw.main_window
    elif not hasattr(mw, "_open_part_file") and hasattr(mw, "parentWidget") and mw.parentWidget():
        if hasattr(mw.parentWidget(), "_open_part_file"):
            mw = mw.parentWidget()
        elif hasattr(mw.parentWidget(), "main_window"):
            mw = mw.parentWidget().main_window
            
    btn_txt.clicked.connect(lambda: mw._open_part_file(shard_idx))
    
    btn_pdf = QPushButton("📄")
    btn_pdf.setFixedSize(26, 26)
    btn_pdf.setToolTip("فتح ملف الـ PDF الأصلي للجزء")
    btn_pdf.setStyleSheet("font-size: 12px; padding: 0;")
    btn_pdf.clicked.connect(lambda: mw._open_pdf_shard_file(shard_idx))
    
    layout.addWidget(btn_txt)
    layout.addWidget(btn_pdf)
    return widget


def _resolve_part_actions_main_window(main_window_ref):
    """تُرجع مرجع MainWindow (أو ما يعادله) الذي يملك دوال إجراءات الجزء،
    بنفس منطق البحث المستخدم في _make_part_actions_button."""
    mw = main_window_ref
    if not hasattr(mw, "_open_part_file") and hasattr(mw, "main_window"):
        mw = mw.main_window
    elif not hasattr(mw, "_open_part_file") and hasattr(mw, "parentWidget") and mw.parentWidget():
        if hasattr(mw.parentWidget(), "_open_part_file"):
            mw = mw.parentWidget()
        elif hasattr(mw.parentWidget(), "main_window"):
            mw = mw.parentWidget().main_window
    return mw


def _build_part_actions_menu(main_window_ref, shard_idx: int) -> QMenu:
    """✅ قائمة سياقية موحّدة لإجراءات الجزء (بديل عمود 'إجراء' في جداول المقارنة):
    فتح الملف المستخرج / فتح ملف الأصل / إعادة مقارنة الجزء / إعادة استخراج الجزء."""
    mw = _resolve_part_actions_main_window(main_window_ref)
    menu = QMenu()
    menu.setLayoutDirection(Qt.LayoutDirection.RightToLeft)

    act_open_extracted = menu.addAction("📝 فتح الملف المستخرج")
    act_open_extracted.triggered.connect(lambda: mw._open_part_file(shard_idx))

    act_open_original = menu.addAction("📄 فتح ملف الأصل")
    act_open_original.triggered.connect(lambda: mw._open_pdf_shard_file(shard_idx))

    menu.addSeparator()

    act_recompare = menu.addAction("🔍 إعادة مقارنة الجزء")
    act_recompare.triggered.connect(lambda: mw._recompare_single_part(shard_idx))

    act_reextract = menu.addAction("♻️ إعادة استخراج الجزء")
    act_reextract.triggered.connect(lambda: mw._reextract_single_part(shard_idx))

    return menu


def _install_part_context_menu(table: "QTableWidget", main_window_ref, idx_col: int = 0):
    """✅ تفعيل قائمة سياقية بزر الفأرة الأيمن على صفوف جدول نتائج مقارنة،
    تعرض: فتح الملف المستخرج / فتح ملف الأصل / إعادة مقارنة الجزء / إعادة استخراج الجزء.
    idx_col: رقم العمود الذي يحتوي رقم الجزء (نصاً) لكل صف."""
    table.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)

    def _on_ctx_menu(pos):
        row = table.rowAt(pos.y())
        if row < 0:
            return
        try:
            it = table.item(row, idx_col)
            shard_idx = int(it.text()) if it else None
        except Exception:
            shard_idx = None
        if shard_idx is None:
            return
        table.selectRow(row)
        menu = _build_part_actions_menu(main_window_ref, shard_idx)
        menu.exec(table.viewport().mapToGlobal(pos))

    table.customContextMenuRequested.connect(_on_ctx_menu)

# ═══════════════════════════════════════════════════════════════════

def build_inline_comparator(output_dir, book_stem, compare_model, cfg,
                             on_partial_result, on_log, stop_event,
                             api_keys, global_key_mgr,
                             request_counter=None) -> InlineComparator:
    workers = cfg.get("compare_parallel_workers", 3)
    workers = max(1, min(workers, len(api_keys), 25))
    comparator = InlineComparator(
        output_dir=output_dir,
        book_stem=book_stem,
        model_id=compare_model["id"],
        model_family=compare_model["family"],
        cfg=cfg,
        on_partial_result=on_partial_result,
        on_log=on_log,
        stop_event=stop_event,
        api_keys=api_keys,
        global_key_mgr=global_key_mgr,
        parallel_workers=workers,
        request_counter=request_counter)
    try:
        register_stop_component("comparators", comparator)
    except Exception:
        pass
    return comparator


def wait_and_generate_final_report(comparator: InlineComparator, total_shards: int,
                                    timeout: float, stop_event: threading.Event,
                                    log: Callable[[str], None],
                                    on_final: Callable[[dict], None]) -> None:
    log("⏳ انتظار اكتمال الفحص (مع إعادة المحاولات)...")
    comparator.wait_until_done(timeout=timeout)
    if not stop_event.is_set():
        log("📊 توليد التقرير الشامل المُحدَّث...")
        try:
            summary = comparator.generate_final_report(total_shards=total_shards)
            if summary:
                on_final(summary)
        except Exception as e:
            log(f"⚠️  فشل التقرير: {e}")


def bootstrap_book_runtime(output_dir: Path, book_stem: str, tokens_path: Path,
                           cfg: dict, app_dir: Path, is_txt: bool,
                           source_path_for_context: Optional[Path],
                           global_state_filename: Optional[str] = None,
                           log_fn: Optional[Callable[[str], None]] = None
                           ) -> Tuple[KeyPool, Checkpoint, Optional[TxtContextManager]]:
    checkpoints_dir = get_book_checkpoints_dir(output_dir, book_stem)
    checkpoints_dir.mkdir(parents=True, exist_ok=True)
    
    ckpt = Checkpoint(checkpoints_dir / "checkpoint.json")
    global_state_path = app_dir / (global_state_filename or "keys_global_state.json")
    
    pool = KeyPool(
        tokens_path,
        checkpoints_dir / "keys_state.json",
        cfg,
        global_state_path=global_state_path
    )
    
    txt_ctx_mgr = None
    if is_txt and source_path_for_context:
        if should_upload_full_txt_context(cfg):
            txt_ctx_mgr = TxtContextManager(source_path_for_context, log_fn if log_fn else (lambda m: None))

    try:
        register_stop_component("keypools", pool)
        register_stop_component("checkpoints", ckpt)
    except Exception:
        pass

    return pool, ckpt, txt_ctx_mgr


def rebuild_and_save_final_output(output_dir: Path, book_stem: str, parts_dir: Path,
                                   shards: List["PDFShard"], is_txt: bool,
                                   log: Callable[[str], None],
                                   make_backup: bool = True) -> Optional[Path]:
    try:
        pieces = []
        missing_in_rebuild = []
        for s in shards:
            pf = parts_dir / f"{book_stem}_part_{s.idx:04d}.txt"
            if pf.exists():
                try:
                    pieces.append(pf.read_text(encoding="utf-8", errors="replace").rstrip())
                except Exception:
                    missing_in_rebuild.append(s.idx)
            else:
                missing_in_rebuild.append(s.idx)
                
        suffix = "_معالج" if is_txt else "_مستخرج"
        final_path = output_dir / f"{book_stem}{suffix}.txt"
        
        if not pieces:
            log("⚠️  لا يوجد أجزاء لإعادة البناء — الملف القديم محفوظ")
            return None
            
        # ✅ v9.2: أُزيلت خاصية إنشاء نسخة احتياطية (.bak) عند إعادة بناء الملف
        # النهائي — كانت تُربك المستخدم بملفين متشابهين لكل كتاب دون فائدة
        # حقيقية واضحة.
                    
        final_text = "\n\n".join(pieces)
        atomic_write_text(final_path, final_text, encoding="utf-8")
        
        try:
            _fp = Path(final_path)
            _name = _fp.name
            for _suf in ["_مستخرج.INCOMPLETE.txt", "_معالج.INCOMPLETE.txt", "_مستخرج.txt", "_معالج.txt"]:
                if _name.endswith(_suf):
                    _bstem = _name[:-len(_suf)]
                    break
            else:
                _bstem = _fp.stem
            save_book_meta(_fp.parent, _bstem, {"final_output_file": str(_fp)})
        except Exception as _e_meta:
            try:
                LOGGER.debug("save final_output_file meta: %s", _e_meta)
            except Exception:
                pass
                
        log(f"✅ أُعيد بناء الملف النهائي: {final_path.name} "
            f"({len(pieces)}/{len(shards)} جزء, "
            f"{count_words(final_text):,} كلمة)")
            
        if missing_in_rebuild:
            log(f"⚠️  أجزاء مفقودة في إعادة البناء: {missing_in_rebuild[:20]}")
            
        return final_path
    except Exception as e:
        log(f"⚠️  فشل إعادة الدمج: {e}")
        return None



