def _custom_map_value(mapping: Optional[Dict[str, str]], path: Path, default: str = "") -> str:
    """استرجاع اختيار الكتاب حتى لو اختلف تمثيل المسار بين الواجهة والعامل."""
    if not mapping:
        return default
    candidates = []
    for value in (path, Path(path)):
        try:
            value_path = Path(value)
            candidates.extend([
                str(value_path),
                str(value_path.absolute()),
                str(value_path.resolve()),
                os.path.relpath(str(value_path), start=os.getcwd()),
            ])
        except Exception:
            candidates.append(str(value))
    for key in dict.fromkeys(candidates):
        value = mapping.get(key)
        if value is not None and str(value).strip():
            return str(value).strip()
    return default


def safe_print(*args, **kwargs):
    try:
        text = " ".join(str(a) for a in args)
        sys.stdout.write(text + kwargs.get("end", "\n"))
        sys.stdout.flush()
        try:
            logging.getLogger("pdf_master").info(text)
        except Exception:
            pass
    except Exception:
        pass


def resolve_app_icon_path(app_dir: Path) -> Optional[Path]:
    """✅ v29.3: مسار الأيقونة المرافقة للبرنامج بعد التحزيم."""
    candidates = [
        Path(app_dir) / "extract_pdf.ico",
        Path(app_dir) / "pdf_master.ico",
        Path(app_dir) / "pdf_master_icon.png",
        Path(app_dir) / "assets" / "extract_pdf.ico",
        Path(app_dir) / "assets" / "pdf_master.ico",
        Path(app_dir) / "icons" / "extract_pdf.ico",
    ]
    for p in candidates:
        try:
            if p.exists() and p.is_file() and p.stat().st_size > 0:
                return p
        except Exception:
            continue
    return None


def resolve_splash_path(app_dir: Path) -> Optional[Path]:
    """✅ v29.3: صورة شاشة الإقلاع."""
    for name in ("splash.png", "splash.jpg", "assets/splash.png", "icons/splash.png"):
        p = Path(app_dir) / name
        try:
            if p.exists() and p.is_file():
                return p
        except Exception:
            continue
    return None


def setup_app_logging(app_dir=None):
    """✅ v28.7: تسجيل مركزي بملف دوّار 5MB × 3."""
    logger = logging.getLogger("pdf_master")
    if getattr(logger, "_pdf_master_configured", False):
        return logger
    logger.setLevel(logging.DEBUG)
    logger.propagate = False
    try:
        base = Path(app_dir) if app_dir else Path.cwd()
        log_path = base / "pdf_master_pro.log"
        fh = RotatingFileHandler(str(log_path), maxBytes=5*1024*1024, backupCount=3, encoding="utf-8")
        fh.setLevel(logging.DEBUG)
        fmt = logging.Formatter("%(asctime)s | %(levelname)s | %(threadName)s | %(message)s",
                                datefmt="%Y-%m-%d %H:%M:%S")
        fh.setFormatter(fmt)
        logger.addHandler(fh)
        sh = logging.StreamHandler(sys.stderr)
        sh.setLevel(logging.WARNING)
        sh.setFormatter(fmt)
        logger.addHandler(sh)
        logger._pdf_master_configured = True  # type: ignore[attr-defined]
        logger.info("=== بدء جلسة PDF Master Pro ===")
    except Exception as e:
        try:
            sys.stderr.write(f"[logging setup failed] {e}\n")
        except Exception:
            pass
    return logger


