# ✅ v29.0: أقفال لكل مسار meta لمنع lost updates بين الخيوط
_BOOK_META_LOCKS: Dict[str, threading.RLock] = {}
_BOOK_META_LOCKS_GUARD = threading.Lock()


def _book_meta_lock_for(path: Path) -> threading.RLock:
    key = str(Path(path).resolve()) if path else str(path)
    with _BOOK_META_LOCKS_GUARD:
        lk = _BOOK_META_LOCKS.get(key)
        if lk is None:
            lk = threading.RLock()
            _BOOK_META_LOCKS[key] = lk
        return lk


def load_book_meta(output_dir: Path, book_stem: str) -> dict:
    path = get_book_meta_path(output_dir, book_stem)
    data = read_json_file_safe(path, {}) or {}
    return data if isinstance(data, dict) else {}


def save_book_meta(output_dir: Path, book_stem: str, meta: dict) -> None:
    # ✅ v29.0: قفل لكل ملف meta + كتابة ذرية
    try:
        path = get_book_meta_path(output_dir, book_stem)
        path.parent.mkdir(parents=True, exist_ok=True)
        with _book_meta_lock_for(path):
            existing = load_book_meta(output_dir, book_stem)
            existing.update(meta or {})
            existing["updated_at"] = datetime.now().isoformat(timespec="seconds")
            atomic_write_text(path, json.dumps(existing, ensure_ascii=False, indent=2), encoding="utf-8")
    except Exception as e:
        try:
            LOGGER.error("[book_meta] save error: %s", e)
        except Exception:
            pass
        safe_print(f"[book_meta] save error: {e}")


def minimum_extraction_word_count_for_units(units: int, is_txt: bool = False) -> int:
    """حد أدنى متحفظ لاكتشاف الاستجابات الفارغة/المبتورة بوضوح فقط."""
    units = max(1, int(units or 1))
    if is_txt:
        return max(2, min(40, int(math.ceil(units * 0.05))))
    return max(8, min(120, units * 8))


@lru_cache(maxsize=2048)
def _cached_is_part_complete(path_str: str, mtime: float, size: int, min_words: int) -> bool:
    """✅ v28.7: فحص سريع مع cache (path+mtime+size)."""
    try:
        if size <= 0:
            return False
        with open(path_str, "r", encoding="utf-8", errors="replace") as f:
            head = f.read(4096)
        if is_model_refusal(head):
            return False
        head_words = count_words(head)
        if size <= 4096:
            return head_words >= min_words
        est_words = max(head_words, int(size / 12))
        return est_words >= min_words
    except Exception as e:
        try:
            LOGGER.warning("is_part_complete failed for %s: %s", path_str, e)
        except Exception:
            pass
        return False


def is_part_complete(pf: Path, min_words: int = 10) -> bool:
    """✅ v28.7: لا يقرأ الملف كاملاً — رأس 4KB + تقدير + cache."""
    try:
        if not pf.is_file():
            return False
        st = pf.stat()
        if st.st_size <= 0:
            return False
        return _cached_is_part_complete(str(pf.resolve()), float(st.st_mtime), int(st.st_size), int(min_words))
    except Exception as e:
        try:
            LOGGER.warning("is_part_complete outer failed: %s", e)
        except Exception:
            pass
        return False


def detect_completed_part_indices(output_dir: Path, book_stem: str,
                                  expected_indices: Optional[Set[int]] = None
                                  ) -> Set[int]:
    completed: Set[int] = set()
    parts_dir = get_book_parts_dir(output_dir, book_stem)
    ckpt_path = get_book_checkpoints_dir(output_dir, book_stem) / "checkpoint.json"
    checkpoint_data = {}
    try:
        if ckpt_path.exists():
            loaded = json.loads(ckpt_path.read_text(encoding="utf-8", errors="replace"))
            if isinstance(loaded, dict):
                checkpoint_data = loaded
    except Exception:
        checkpoint_data = {}

    def _required_words(rec) -> int:
        try:
            start = int(rec.get("page_start"))
            end = int(rec.get("page_end"))
            units = max(1, end - start + 1)
            return minimum_extraction_word_count_for_units(
                units, bool(rec.get("is_txt", False)))
        except Exception:
            return 10

    if parts_dir.exists():
        for pf in parts_dir.glob(f"{book_stem}_part_*.txt"):
            try:
                m = re.search(r'_part_(\d{4})\.txt$', pf.name)
                if not m:
                    continue
                idx = int(m.group(1))
                if expected_indices and idx not in expected_indices:
                    continue
                rec = checkpoint_data.get(str(idx), {})
                if not is_part_complete(pf, min_words=_required_words(rec)):
                    continue
                completed.add(idx)
            except Exception:
                continue

    # لا يكفي status=ok أو وجود بايتات: افحص النص نفسه وبحد يتناسب مع النطاق
    # المحفوظ في checkpoint، كيلا تُعتمد ملفات الأجزاء القصيرة القديمة بصمت.
    for key, rec in checkpoint_data.items():
        try:
            idx = int(key)
        except Exception:
            continue
        if expected_indices and idx not in expected_indices:
            continue
        if not isinstance(rec, dict) or rec.get("status") != "ok":
            continue
        output_file = rec.get("output_file") or ""
        candidate = Path(output_file) if output_file else (parts_dir / f"{book_stem}_part_{idx:04d}.txt")
        if candidate.exists() and is_part_complete(
                candidate, min_words=_required_words(rec)):
            completed.add(idx)

    return completed


def read_json_file_safe(path: Path, default: Any):
    # ✅ v27.0: قراءة JSON بشكل آمن مع fallback موحد
    try:
        if path.exists():
            return json.loads(path.read_text(encoding="utf-8", errors="replace"))
    except Exception:
        pass
    return default


def format_timestamp_human(ts: float) -> str:
    # ✅ v27.0: تنسيق عربي مبسّط لتواريخ المكتبة/السجل
    try:
        return datetime.fromtimestamp(ts).strftime("%Y-%m-%d %H:%M")
    except Exception:
        return "—"


def parse_shard_filename(shard_path: Path) -> Optional[Tuple[int, int, int, bool]]:
    # ✅ v27.0: تحليل اسم shard لاسترجاع الفهرس والنطاق ونوع الملف
    try:
        m = re.match(r"shard_(\d+)_([pL])(\d+)-(\d+)$", shard_path.stem, re.IGNORECASE)
        if not m:
            return None
        idx = int(m.group(1))
        start = int(m.group(3))
        end = int(m.group(4))
        is_txt = m.group(2).upper() == "L" or shard_path.suffix.lower() in SUPPORTED_TXT_EXTS
        return idx, start, end, is_txt
    except Exception:
        return None


def compare_assess_overall(avg_coverage: int, critical: int) -> str:
    # ✅ v27.0: نسخة محلية من تقييم التقرير الشامل بدون طلبات API
    if critical >= 5 or avg_coverage < 60:
        return "ضعيف"
    if critical >= 2 or avg_coverage < 80:
        return "متوسط"
    if avg_coverage < 95:
        return "جيد"
    return "ممتاز"


def compare_build_recommendations(critical: int, medium: int, worst: List[int]) -> str:
    # ✅ v27.0: توصيات محلية لعرض التقارير المحفوظة من القرص
    recs: List[str] = []
    if critical > 0:
        recs.append(f"⚠️ مراجعة فورية للأجزاء الخطيرة ({critical} فجوة).")
    if medium > 0:
        recs.append(f"📌 مراجعة الفجوات المتوسطة ({medium}).")
    if worst:
        recs.append(f"🔍 ركّز على الأجزاء الأقل تغطية: {worst}.")
    if not recs:
        recs.append("✅ النتائج ممتازة — لا توصيات حرجة.")
    return " ".join(recs)


def build_local_compare_summary_from_results(results_map: Dict[int, 'ShardComparisonResult'],
                                             total_shards: int) -> Optional[dict]:
    # ✅ v27.0: إعادة بناء التقرير الشامل محلياً من partial.json دون استهلاك كوتة
    try:
        results = sorted(results_map.values(), key=lambda r: r.shard_idx)
        if not results:
            return None
        total_missing = sum(len(r.missing_items) for r in results)
        critical = sum(1 for r in results for m in r.missing_items if m.get("severity") == "خطير")
        medium = sum(1 for r in results for m in r.missing_items if m.get("severity") == "متوسط")
        minor = sum(1 for r in results for m in r.missing_items if m.get("severity") == "بسيط")
        # ✅ v28.7: متوسط التغطية من المُقارَن فقط — لا خلط مع 0% لغير المقارن
        compared_indices = {r.shard_idx for r in results if r.error is None}
        not_compared_count = max(0, int(total_shards) - len(compared_indices))
        coverages = [r.coverage_pct for r in results if r.error is None and r.coverage_pct >= 0]
        avg_coverage = int(sum(coverages) / len(coverages)) if coverages else 0
        worst = sorted([r for r in results if r.error is None], key=lambda r: r.coverage_pct)[:3]
        worst_idx = [r.shard_idx for r in worst]
        return {
            "overall_assessment": compare_assess_overall(avg_coverage, critical),
            "coverage_estimate_pct": avg_coverage,
            "not_compared_count": not_compared_count,
            "total_missing_items": total_missing,
            "critical_count": critical,
            "medium_count": medium,
            "minor_count": minor,
            "summary": (f"تمت مقارنة {len(results)}/{total_shards} جزء، غير مُقارَن: {not_compared_count}. "
                        f"متوسط التغطية {avg_coverage}%. "
                        f"إجمالي الفجوات {total_missing} "
                        f"(خطير: {critical}, متوسط: {medium}, بسيط: {minor})."),
            "recommendations": compare_build_recommendations(critical, medium, worst_idx),
            "worst_shards": worst_idx,
            "_compared_shards": len(results),
            "_total_shards": total_shards,
        }
    except Exception:
        return None


def load_partial_compare_results_file(partial_path: Path) -> Dict[int, 'ShardComparisonResult']:
    # ✅ v27.0: تحميل partial.json إلى كائنات النتائج المعروفة في الواجهة
    loaded: Dict[int, 'ShardComparisonResult'] = {}
    try:
        raw = read_json_file_safe(partial_path, {}) or {}
        for key, value in raw.items():
            try:
                rec = ShardComparisonResult(**value)
                loaded[int(key)] = rec
            except Exception:
                continue
    except Exception:
        pass
    return loaded


def load_final_compare_summary_file(compare_dir: Path,
                                    partial_results: Dict[int, 'ShardComparisonResult'],
                                    total_shards: int) -> Optional[dict]:
    # ✅ v27.0: تحميل final.json أو إعادة بنائه محلياً عند غيابه
    try:
        final_path = compare_dir / "final.json"
        data = read_json_file_safe(final_path, None)
        if isinstance(data, dict) and data:
            return data
    except Exception:
        pass
    return build_local_compare_summary_from_results(partial_results, total_shards)


def has_saved_compare_data(compare_dir: Path) -> bool:
    # ✅ v4.7: التحقق المضمون الشامل من وجود أي مقارنات محفوظة بأي صيغة قديمة أو حديثة
    try:
        if not compare_dir.exists():
            return False
        for name in ["partial.json", "final.json", "report.txt", "summary.json", "checkpoint.json"]:
            if (compare_dir / name).exists():
                return True
        if any(p.is_file() for p in compare_dir.iterdir()):
            return True
    except Exception:
        pass
    return False


def find_existing_final_output_file(output_dir: Path, book_stem: str) -> Optional[Path]:
    """اكتشاف كفء وسريع جداً للملف النهائي أو الجزئي المكتمل دون مسح المجلد بالكامل."""
    try:
        output_dir_p = Path(output_dir)
        safe_stem = safe_book_dir_name(book_stem)

        # 1. فحص book_meta أولاً
        try:
            meta = load_book_meta(output_dir_p, book_stem)
            fof = meta.get("final_output_file") if isinstance(meta, dict) else None
            if fof:
                p = Path(fof)
                if not p.is_absolute():
                    p = output_dir_p / p
                if p.exists():
                    return p
        except Exception:
            pass

        # 2. فحص مسارات صريحة سريعة دون glob
        candidates = [
            output_dir_p / f"{book_stem}.txt",
            output_dir_p / f"{safe_stem}.txt",
            output_dir_p / f"{book_stem}_مستخرج.txt",
            output_dir_p / f"{safe_stem}_مستخرج.txt",
            output_dir_p / f"{book_stem}_معالج.txt",
            output_dir_p / f"{safe_stem}_معالج.txt",
            output_dir_p / f"{book_stem}_مستخرج.INCOMPLETE.txt",
            output_dir_p / f"{safe_stem}_مستخرج.INCOMPLETE.txt",
        ]
        for c in candidates:
            if c.exists():
                return c

        # 3. فحص مجلد الوجهة بـ listdir مرة واحدة سريعة دون glob متعدد
        if output_dir_p.exists():
            for fname in os.listdir(output_dir_p):
                if fname.endswith(".txt") and (book_stem in fname or safe_stem in fname):
                    p = output_dir_p / fname
                    if p.is_file():
                        return p
    except Exception:
        pass
    return None


def rebuild_txt_shards_from_metadata(source_txt: Path, shards_dir: Path,
                                     shards: List['PDFShard'],
                                     log: Callable[[str], None]) -> List['PDFShard']:
    # ✅ v27.0: إعادة إنشاء shards النصية من المصدر الأصلي عندما تكون محذوفة
    shards_dir.mkdir(parents=True, exist_ok=True)
    all_lines = read_txt_lines(source_txt)
    src_md5 = _compute_md5(source_txt)
    rebuilt: List[PDFShard] = []
    for shard in sorted(shards, key=lambda s: s.idx):
        try:
            spath = shards_dir / f"shard_{shard.idx:04d}_L{shard.line_start:06d}-{shard.line_end:06d}.txt"
            chunk_lines = all_lines[max(0, shard.line_start - 1): shard.line_end]
            content = "".join(f"{i:6d} | {ln}\n" for i, ln in enumerate(chunk_lines, start=shard.line_start))
            atomic_write_text(spath, content, encoding="utf-8")
            rebuilt.append(PDFShard(
                idx=shard.idx, page_start=shard.line_start, page_end=shard.line_end,
                pages_count=max(0, shard.line_end - shard.line_start + 1),
                shard_path=spath, shard_md5=src_md5, is_txt=True,
                line_start=shard.line_start, line_end=shard.line_end))
        except Exception as e:
            try:
                log(f"⚠️  تعذر إعادة إنشاء shard TXT {shard.idx}: {e}")
            except Exception:
                pass
    return rebuilt


def rebuild_shards_from_source(source_path: Path, shards_dir: Path,
                               shards: List['PDFShard'],
                               log: Callable[[str], None]) -> List['PDFShard']:
    # ✅ v27.0: إعادة إنشاء shards من المصدر الأصلي عند حذف مجلد الشظايا
    if not shards or not source_path.exists():
        return []
    try:
        if shards[0].is_txt:
            return rebuild_txt_shards_from_metadata(source_path, shards_dir, shards, log)
        custom_ranges = [(s.page_start, s.page_end) for s in sorted(shards, key=lambda s: s.idx)]
        return split_pdf_into_shards(
            source_path, shards_dir, 1, log,
            custom_ranges=custom_ranges, custom_ranges_exact=True)
    except Exception as e:
        try:
            log(f"⚠️  فشل إعادة إنشاء shards من المصدر: {e}")
        except Exception:
            pass
        return []


def is_valid_split_input(shard) -> Tuple[bool, str]:
    path = shard.shard_path
    try:
        if not path.exists():
            return False, "ملف الجزء غير موجود"
        size = path.stat().st_size
        if size <= 100:
            return False, f"حجم ملف الجزء غير صالح ({size} bytes)"
        if shard.is_txt:
            lines = get_txt_line_count(path)
            if lines <= 0:
                return False, "جزء TXT فارغ"
            return True, ""
        if PDF_BACKEND != "builtin":
            pages = get_pdf_page_count(path)
            if pages <= 0:
                return False, "عدد صفحات الجزء = 0"
            if shard.pages_count > 0 and pages != shard.pages_count:
                return False, f"عدد الصفحات الفعلي {pages} لا يطابق المتوقع {shard.pages_count}"
        return True, ""
    except Exception as e:
        return False, str(e)


