#  مُقسِّم PDF
# ═══════════════════════════════════════════════════════════════════

def _raw_pdf_page_count(pdf_path: Path) -> int:
    # PyMuPDF يقرأ فهرس الصفحات غالباً بأقل كلفة من مسح كل الصفحات
    # عبر pikepdf/pypdf؛ اترك المحرك البديل للملفات التي لا يقبلها.
    try:
        try:
            import pymupdf as _fast_fitz
        except ImportError:
            import fitz as _fast_fitz
        with _fast_fitz.open(str(pdf_path)) as fast_doc:
            return int(fast_doc.page_count)
    except Exception:
        pass
    try:
        if PDF_BACKEND == "pikepdf":
            import pikepdf
            with pikepdf.open(pdf_path) as pdf:
                return len(pdf.pages)
        elif PDF_BACKEND == "pypdf":
            return len(_PypdfReader(str(pdf_path)).pages)
        elif PDF_BACKEND == "pdfrw":
            import pdfrw
            return len(pdfrw.PdfReader(str(pdf_path)).pages)
        elif PDF_BACKEND == "pymupdf":
            # ✅ v10.6: الغصن الناقص — بدونها كانت صفحة أي جزء = 0
            #    فتُرفض كل الأجزاء في التفتيش (وكان يظهر «0 جزء»)
            try:
                import pymupdf as _f
            except ImportError:
                import fitz as _f
            with _f.open(str(pdf_path)) as pdf:
                return int(pdf.page_count)
        elif PDF_BACKEND == "builtin":
            return _builtin_count_pages(pdf_path)
    except Exception as e:
        safe_print(f"خطأ صفحات: {e}")
    return 0

get_pdf_page_count = cached_by_mtime(_raw_pdf_page_count)


def _builtin_count_pages(pdf_path: Path) -> int:
    try:
        with open(pdf_path, "rb") as f:
            data = f.read()
        count = 0
        for m in re.finditer(rb'/Type\s*/Page(?![sA-Za-z])', data):
            count += 1
        return count
    except Exception:
        return 0


@dataclass
class PDFShard:
    idx: int
    page_start: int
    page_end: int
    pages_count: int
    shard_path: Path
    shard_md5: str = ""
    is_txt: bool = False
    line_start: int = 0
    line_end: int = 0


def _check_stop(stop_event):
    if stop_event and stop_event.is_set():
        raise InterruptedError("توقف")


def _compute_md5(p: Path) -> str:
    h = hashlib.md5()
    with open(p, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 16), b""):
            h.update(chunk)
    return h.hexdigest()


def split_pdf_into_shards(source_pdf: Path, shards_dir: Path,
                            pages_per_batch: int, log: Callable[[str], None],
                            stop_event: Optional[threading.Event] = None,
                            on_progress: Callable[[int, int], None] = None,
                            custom_ranges: Optional[List[Tuple[int, int]]] = None,
                            custom_ranges_exact: bool = False
                            ) -> List[PDFShard]:
    shards_dir.mkdir(parents=True, exist_ok=True)
    log(f"📂 قراءة PDF لتقسيمه: {source_pdf.name}")
    log(f"   🔧 المحرك: {PDF_BACKEND}")

    # ✅ v28.0: تطبيق حد معدل الاستخراج على كل قسم من التقسيم المخصص
    if custom_ranges and not custom_ranges_exact:
        original_n = len(custom_ranges)
        custom_ranges = expand_ranges_by_batch_limit(custom_ranges, pages_per_batch)
        if len(custom_ranges) != original_n:
            log(f"✂️ التقسيم المخصص: {original_n} قسم → {len(custom_ranges)} دفعة "
                f"(حد {pages_per_batch} صفحة/دفعة)")

    if PDF_BACKEND == "pikepdf":
        return _split_with_pikepdf(source_pdf, shards_dir, pages_per_batch,
                                   log, stop_event, on_progress,
                                   custom_ranges=custom_ranges)
    elif PDF_BACKEND == "pypdf":
        return _split_with_pypdf(source_pdf, shards_dir, pages_per_batch,
                                   log, stop_event, on_progress,
                                   custom_ranges=custom_ranges)
    elif PDF_BACKEND == "pdfrw":
        return _split_with_pdfrw(source_pdf, shards_dir, pages_per_batch,
                                   log, stop_event, on_progress,
                                   custom_ranges=custom_ranges)
    elif PDF_BACKEND == "pymupdf":
        return _split_with_pymupdf(source_pdf, shards_dir, pages_per_batch,
                                   log, stop_event, on_progress,
                                   custom_ranges=custom_ranges)
    else:
        return _split_with_builtin(source_pdf, shards_dir, pages_per_batch,
                                     log, stop_event, on_progress,
                                     custom_ranges=custom_ranges)


def _split_with_pypdf(source_pdf, shards_dir, pages_per_batch,
                       log, stop_event, on_progress,
                       custom_ranges: Optional[List[Tuple[int, int]]] = None) -> List[PDFShard]:
    def read_total_pages(p):
        return len(_PypdfReader(str(p)).pages)

    def write_shard(reader, start, end, dest):
        writer = _PypdfWriter()
        for pn in range(start - 1, end):
            _check_stop(stop_event)
            writer.add_page(reader.pages[pn])
        try:
            root = writer._root_object
            for key in ("/StructTreeRoot", "/MarkInfo", "/Outlines",
                        "/Names", "/AcroForm", "/OpenAction"):
                if key in root:
                    del root[key]
        except Exception as e:
            log(f"   ⚠️ تعذر تنظيف الأوبجكتات المشتركة: {e}")
        try:
            writer.compress_identical_objects(remove_orphans=True, remove_identicals=True)
        except Exception:
            pass
        with open(dest, "wb") as f:
            writer.write(f)

    def check_existing_shard(spath, start, end):
        try:
            check = _PypdfReader(str(spath))
            return len(check.pages) == (end - start + 1)
        except Exception:
            return False

    return _generic_pdf_splitter(
        source_pdf, shards_dir, pages_per_batch, log, stop_event, on_progress, custom_ranges,
        backend_name="pypdf",
        read_total_pages=read_total_pages,
        write_shard=write_shard,
        get_reader=lambda p: _PypdfReader(str(p)),
        check_existing_shard=check_existing_shard
    )


def _split_with_pdfrw(source_pdf, shards_dir, pages_per_batch,
                        log, stop_event, on_progress,
                        custom_ranges: Optional[List[Tuple[int, int]]] = None) -> List[PDFShard]:
    import pdfrw
    def read_total_pages(p):
        return len(pdfrw.PdfReader(str(p)).pages)

    def write_shard(reader, start, end, dest):
        import pdfrw
        writer = pdfrw.PdfWriter()
        for pn in range(start - 1, end):
            _check_stop(stop_event)
            writer.addpage(reader.pages[pn])
        writer.write(str(dest))

    def check_existing_shard(spath, start, end):
        try:
            import pdfrw
            check = pdfrw.PdfReader(str(spath))
            return len(check.pages) == (end - start + 1)
        except Exception:
            return False

    return _generic_pdf_splitter(
        source_pdf, shards_dir, pages_per_batch, log, stop_event, on_progress, custom_ranges,
        backend_name="pdfrw",
        read_total_pages=read_total_pages,
        write_shard=write_shard,
        get_reader=lambda p: pdfrw.PdfReader(str(p)),
        check_existing_shard=check_existing_shard
    )


def _split_with_pikepdf(source_pdf, shards_dir, pages_per_batch,
                         log, stop_event, on_progress,
                         custom_ranges: Optional[List[Tuple[int, int]]] = None) -> List[PDFShard]:
    import pikepdf

    def read_total_pages(p):
        with pikepdf.open(p) as pdf:
            return len(pdf.pages)

    def write_shard(reader, start, end, dest):
        # استراتيجية "إعادة البناء الجذري":
        # نقوم بإنشاء ملف جديد تماماً ونسخ الصفحات ككائنات مستقلة لقطع الروابط مع الموارد الضخمة غير المستخدمة.
        with pikepdf.new() as writer:
            for pn in range(start - 1, end):
                _check_stop(stop_event)
                # الطريقة الصحيحة لنسخ الصفحات بين ملفات مختلفة في pikepdf
                writer.pages.append(reader.pages[pn])
            
            # تنظيف شامل للموارد غير المشار إليها لتقليل الحجم
            writer.remove_unreferenced_resources()
            
            # محاولة ضغط الموارد المتبقية (الصور والجداول)
            try:
                writer.compress_resources(pikepdf.Compression.all_)
            except Exception:
                pass
            
            # حفظ الملف مع تفعيل خيارات التنظيف الإضافية
            writer.save(dest, linearize=False, object_stream_mode=pikepdf.ObjectStreamMode.generate)

    def check_existing_shard(spath, start, end):
        try:
            with pikepdf.open(spath) as check:
                return len(check.pages) == (end - start + 1)
        except Exception:
            return False

    return _generic_pdf_splitter(
        source_pdf, shards_dir, pages_per_batch, log, stop_event, on_progress, custom_ranges,
        backend_name="pikepdf",
        read_total_pages=read_total_pages,
        write_shard=write_shard,
        get_reader=lambda p: pikepdf.open(p),
        check_existing_shard=check_existing_shard
    )


def _split_with_pymupdf(source_pdf, shards_dir, pages_per_batch,
                        log, stop_event, on_progress,
                        custom_ranges: Optional[List[Tuple[int, int]]] = None) -> List[PDFShard]:
    # ✅ v10.3 (إصلاح التهنيج): تقسيم حقيقي خفيف بالذاكرة عبر pymupdf —
    #    البديل القديم (builtin) كان ينسخ الملف كاملاً لكل جزء (110 جزء
    #    = 110 نسخة كاملة من الكتاب على القرص → تجميد النظام)
    def _get_fitz():
        try:
            import pymupdf as _f
        except ImportError:
            import fitz as _f
        return _f

    def read_total_pages(p):
        _f = _get_fitz()
        d = _f.open(str(p))
        try:
            return int(d.page_count)
        finally:
            try:
                d.close()
            except Exception:
                pass

    def write_shard(reader, start, end, dest):
        _f = _get_fitz()
        out = _f.open()
        try:
            out.insert_pdf(reader, from_page=int(start) - 1,
                           to_page=int(end) - 1)
            out.save(str(dest), garbage=3, deflate=True)
        finally:
            try:
                out.close()
            except Exception:
                pass

    def check_existing_shard(spath, start, end):
        _f = _get_fitz()
        try:
            d = _f.open(str(spath))
            try:
                return int(d.page_count) == (end - start + 1)
            finally:
                d.close()
        except Exception:
            return False

    return _generic_pdf_splitter(
        source_pdf, shards_dir, pages_per_batch, log, stop_event, on_progress, custom_ranges,
        backend_name="pymupdf",
        read_total_pages=read_total_pages,
        write_shard=write_shard,
        get_reader=lambda p: _get_fitz().open(str(p)),
        check_existing_shard=check_existing_shard
    )


def _split_with_builtin(source_pdf, shards_dir, pages_per_batch,
                        log, stop_event, on_progress,
                        custom_ranges: Optional[List[Tuple[int, int]]] = None) -> List[PDFShard]:
    def on_start():
        log("⚠️" * 20)
        log("⚠️  تنبيه مهم: استخدام builtin backend!")
        log("⚠️  الكفاءة منخفضة جداً — الملف الكامل يُنسخ لكل جزء!")
        log("⚠️  الكوتة ستُستهلك بشكل مضاعف (كل جزء = الملف كاملاً)")
        log("⚠️  النموذج مُوجَّه عبر البرومبت لمعالجة النطاق المحدد فقط")
        log("⚠️  لأداء أفضل بكثير: pip install pypdf  أو  pip install pdfrw")
        log("⚠️" * 20)

    def read_total_pages(p):
        return _builtin_count_pages(p) or 1

    def write_shard(reader, start, end, dest):
        shutil.copy2(str(source_pdf), str(dest))

    def check_existing_shard(spath, start, end):
        return spath.exists()

    return _generic_pdf_splitter(
        source_pdf, shards_dir, pages_per_batch, log, stop_event, on_progress, custom_ranges,
        backend_name="builtin",
        read_total_pages=read_total_pages,
        write_shard=write_shard,
        check_existing_shard=check_existing_shard,
        on_start=on_start
    )


def cleanup_shards(shards_dir: Path, log: Callable[[str], None]) -> None:
    try:
        if shards_dir.exists():
            shutil.rmtree(shards_dir)
            log(f"🧹 حُذفت الأجزاء المؤقتة: {shards_dir}")
    except Exception as e:
        log(f"⚠️  تعذر الحذف: {e}")


