#  مُقسِّم ملفات TXT
# ═══════════════════════════════════════════════════════════════════

def _raw_txt_line_count(txt_path: Path) -> int:
    try:
        with open(txt_path, "r", encoding="utf-8", errors="replace") as f:
            return sum(1 for _ in f)
    except Exception as e:
        safe_print(f"خطأ قراءة أسطر: {e}")
    return 0

get_txt_line_count = cached_by_mtime(_raw_txt_line_count)


@lru_cache(maxsize=1024)
def _raw_txt_word_count(path_str: str, mtime_ns: int, size: int) -> int:
    """عدّ تزايدي للكلمات، بكاش مرتبط ببصمة الملف، دون تحميله كله إلى الذاكرة."""
    count = 0
    try:
        with open(path_str, "r", encoding="utf-8", errors="replace") as stream:
            for line in stream:
                count += len(normalize(line).split())
        return count
    except Exception:
        return 0


def get_txt_word_count(txt_path: Path) -> int:
    try:
        path = Path(txt_path)
        stat = path.stat()
        return _raw_txt_word_count(
            str(path.resolve()), int(stat.st_mtime_ns), int(stat.st_size))
    except Exception:
        return 0


def _words_from_text(text: str) -> List[str]:
    return re.findall(r"\S+", text or "")


def _paragraphs_from_text(text: str) -> List[str]:
    # فقرات تفصلها أسطر فارغة؛ السطور المتجاورة تعد فقرة واحدة.
    raw = re.split(r"\n\s*\n+", (text or "").replace("\r\n", "\n").replace("\r", "\n"))
    return [p.strip() for p in raw if p and p.strip()]


def _looks_like_abbreviation(fragment: str) -> bool:
    """هل النقطة في نهاية المقطع اختصار أو رقم لا نهاية جملة؟"""
    frag = (fragment or "").rstrip()
    m = re.search(r"(\S+)\.$", frag)
    if not m:
        return False
    token = m.group(1)
    if re.fullmatch(r"[\d\u0660-\u0669]+", token):
        return True                                   # رقم: 5. أو 12.
    if re.fullmatch(r"[\d\u0660-\u0669]+[.,][\d\u0660-\u0669]+", token):
        return True                                   # عدد عشري: 1.5
    if len(token) <= 2:
        return True                                   # اختصار أو حرف أول: ص. أو ج.
    return False


def _sentences_from_text(text: str) -> List[str]:
    """تقسيم نص إلى جمل: فقرات -> جمل -> دفعات (لا كلمات).

    يتجنب القطع عند النقاط التي تكون أرقاماً أو اختصارات أو أحرفاً أولية.
    """
    text = (text or "").strip()
    if not text:
        return []
    parts = re.split(r"(?<=[.!\u061F\u00A1])\s+", text)
    merged: List[str] = []
    for part in parts:
        part = part.strip()
        if not part:
            continue
        # إن كانت النقطة اختصاراً نضمّ الجزء التالي إليه
        if merged and _looks_like_abbreviation(merged[-1]):
            merged[-1] = merged[-1] + " " + part
        else:
            merged.append(part)
    # ضمّ الجمل القصيرة جداً (أقل من 3 كلمات) بما قبلها: غالباً ليست جملة مستقلة
    out: List[str] = []
    for sent in merged:
        if out and count_words(sent) < 3:
            out[-1] = out[-1] + " " + sent
        else:
            out.append(sent)
    return [x for x in out if x.strip()]


def read_txt_lines(txt_path: Path) -> List[str]:
    try:
        with open(txt_path, "r", encoding="utf-8", errors="replace") as f:
            return f.read().splitlines()
    except Exception as e:
        safe_print(f"خطأ قراءة ملف نصي: {e}")
        return []


def split_txt_into_shards(source_txt: Path, shards_dir: Path,
                            lines_per_batch: int,
                            log: Callable[[str], None],
                            stop_event: Optional[threading.Event] = None,
                            on_progress: Callable[[int, int], None] = None,
                            custom_ranges: Optional[List[Tuple[int, int]]] = None,
                            custom_ranges_exact: bool = False
                            ) -> List[PDFShard]:
    """تقسيم TXT بالكلمات لا بالأسطر، مع احترام الفقرات قدر الإمكان."""
    shards_dir.mkdir(parents=True, exist_ok=True)
    max_words = max(1, int(lines_per_batch or 1000))
    log(f"📂 قراءة TXT لتقسيمه بالكلمات: {source_txt.name}")
    try:
        full_text = source_txt.read_text(encoding="utf-8", errors="replace")
    except Exception as e:
        raise RuntimeError(f"تعذر قراءة الملف: {e}")
    total_words = count_words(full_text)
    log(f"   📝 إجمالي الكلمات: {total_words:,}")
    if total_words == 0:
        raise RuntimeError("الملف النصي فارغ!")

    chunks: List[Tuple[int, int, str]] = []

    if custom_ranges:
        original_n = len(custom_ranges)
        ranges = list(custom_ranges) if custom_ranges_exact else expand_ranges_by_batch_limit(custom_ranges, max_words)
        if (not custom_ranges_exact) and len(ranges) != original_n:
            log(f"✂️ التقسيم المخصص TXT: {original_n} نطاق → {len(ranges)} دفعة (حد {max_words} كلمة/دفعة)")
        words = _words_from_text(full_text)
        for w_start, w_end in ranges:
            _check_stop(stop_event)
            w_start = max(1, int(w_start)); w_end = min(len(words), int(w_end))
            if w_start > w_end:
                continue
            chunk_text = " ".join(words[w_start-1:w_end]).strip()
            if chunk_text:
                chunks.append((w_start, w_end, chunk_text))
    else:
        current_parts: List[str] = []
        current_count = 0
        chunk_start = 1
        next_word = 1
        for para in _paragraphs_from_text(full_text):
            _check_stop(stop_event)
            wc = count_words(para)
            if wc <= 0:
                continue
            # الفقرة الطويلة جداً تُقسّم بالكلمات لأنها أكبر من الحد.
            if wc > max_words:
                if current_parts:
                    chunks.append((chunk_start, next_word - 1, "\n\n".join(current_parts).strip()))
                    current_parts = []
                    current_count = 0
                    chunk_start = next_word
                # الفقرة الطويلة تُقسّم إلى جمل أولاً، ثم تُجمَّع الجمل في
                # دفعات: فقرات -> جمل -> دفعات (لا كلمات)، حتى لا تُقطع جملة.
                sentences = _sentences_from_text(para)
                overlong = 0
                if sentences:
                    buf: List[str] = []
                    buf_wc = 0

                    def _flush_buf() -> None:
                        nonlocal buf, buf_wc, next_word
                        if not buf:
                            return
                        text_part = " ".join(buf).strip()
                        if text_part:
                            start_w = next_word
                            end_w = next_word + buf_wc - 1
                            chunks.append((start_w, end_w, text_part))
                            next_word = end_w + 1
                        buf, buf_wc = [], 0

                    for sent in sentences:
                        sw = count_words(sent)
                        if sw <= 0:
                            continue
                        if buf and (buf_wc + sw) > max_words:
                            _flush_buf()
                        if sw > max_words:
                            # جملة واحدة أطول من حد الدفعة: لا مفر من قطعها
                            overlong += 1
                            words = _words_from_text(sent)
                            pos = 0
                            while pos < len(words):
                                part_words = words[pos:pos + max_words]
                                start_w = next_word
                                end_w = next_word + len(part_words) - 1
                                chunks.append((start_w, end_w, " ".join(part_words).strip()))
                                next_word = end_w + 1
                                pos += max_words
                            buf, buf_wc = [], 0
                            continue
                        buf.append(sent)
                        buf_wc += sw
                    _flush_buf()
                    if overlong:
                        log(f"   ⚠️ {overlong} جملة أطول من حد الدفعة "
                            f"({max_words} كلمة) — قُطعت اضطراراً")
                else:
                    words = _words_from_text(para)
                    pos = 0
                    while pos < len(words):
                        part_words = words[pos:pos + max_words]
                        start_w = next_word
                        end_w = next_word + len(part_words) - 1
                        chunks.append((start_w, end_w, " ".join(part_words).strip()))
                        next_word = end_w + 1
                        pos += max_words
                chunk_start = next_word
                continue
            # لو إضافة الفقرة ستتجاوز الحد، اقطع قبلها لا داخلها.
            if current_parts and (current_count + wc) > max_words:
                chunks.append((chunk_start, next_word - 1, "\n\n".join(current_parts).strip()))
                current_parts = [para]
                current_count = wc
                chunk_start = next_word
                next_word += wc
            else:
                if not current_parts:
                    chunk_start = next_word
                current_parts.append(para)
                current_count += wc
                next_word += wc
        if current_parts:
            chunks.append((chunk_start, next_word - 1, "\n\n".join(current_parts).strip()))

    shards: List[PDFShard] = []
    src_md5 = _compute_md5(source_txt)
    for idx, (word_start, word_end, chunk_text) in enumerate(chunks, start=1):
        _check_stop(stop_event)
        if not chunk_text.strip():
            continue
        fname = f"shard_{idx:04d}_W{word_start:08d}-{word_end:08d}.txt"
        spath = shards_dir / fname
        if not spath.exists():
            try:
                with open(spath, "w", encoding="utf-8") as f:
                    f.write(f"[نطاق الكلمات: {word_start}-{word_end}]\n\n")
                    f.write(chunk_text.rstrip() + "\n")
            except Exception as e:
                log(f"   ⚠️  فشل حفظ جزء {idx}: {e}")
                continue
        size_kb = spath.stat().st_size / 1024
        shards.append(PDFShard(
            idx=idx, page_start=word_start, page_end=word_end,
            pages_count=word_end - word_start + 1,
            shard_path=spath, shard_md5=src_md5,
            is_txt=True, line_start=word_start, line_end=word_end))
        log(f"   ✂️  جزء {idx}: كلمات {word_start}-{word_end} ({size_kb:.1f} KB)")
        if on_progress: on_progress(idx, 0)
    log(f"✅ تم تقسيم TXT بالكلمات: {len(shards)} جزء")
    return shards


