class SettingsManager:
    def __init__(self, app_dir: Path):
        self.app_dir = app_dir
        self.settings_file = app_dir / "pdf_settings.json"
        self.data: Dict[str, Any] = dict(DEFAULT_SETTINGS)
        self._lock = threading.RLock()
        self.load()

    def load(self) -> None:
        if self.settings_file.exists():
            try:
                saved = json.loads(self.settings_file.read_text(
                    encoding="utf-8", errors="replace"))
                for k, v in saved.items():
                    if k in self.data:
                        self.data[k] = v
                # ✅ v24.0: ترحيل — أي مفتاح جديد في DEFAULT_SETTINGS
                # غير موجود في الملف المحفوظ يأخذ قيمته الافتراضية تلقائياً
                migrated = []
                for k, v in DEFAULT_SETTINGS.items():
                    if k not in saved:
                        migrated.append(k)
                if migrated:
                    safe_print(f"[settings] migration: added {migrated}")
            except Exception as e:
                safe_print(f"[settings] load error: {e}")

    def save(self) -> None:
        with self._lock:
            try:
                # ✅ v27.0: حفظ الإعدادات بذريّة لتجنب تلف الملف أثناء الإغلاق/الترحيل
                atomic_write_text(
                    self.settings_file,
                    json.dumps(self.data, ensure_ascii=False, indent=2),
                    encoding="utf-8")
            except Exception as e:
                safe_print(f"[settings] save error: {e}")

    def get(self, key: str, default=None) -> Any:
        return self.data.get(key, default)

    def set(self, key: str, value: Any) -> None:
        with self._lock:
            self.data[key] = value

    def reset_to_defaults(self, preserve_keys: List[str] = None) -> None:
        preserved = {}
        if preserve_keys:
            for k in preserve_keys:
                if k in self.data:
                    preserved[k] = self.data[k]
        with self._lock:
            self.data = dict(DEFAULT_SETTINGS)
            for k, v in preserved.items():
                self.data[k] = v
        self.save()

    def copy_extraction_model_to_compare(self):
        """
        نسخ model_id الحالي إلى compare_model_id وحفظ الإعدادات.
        يجب استدعاؤها فقط حين يضغط المستخدم زرًا صريحًا لذلك.
        """
        try:
            with self._lock:
                self.data["compare_model_id"] = self.data.get("model_id", "")
                self.data["compare_model_family"] = self.data.get("model_family", "")
            self.save()
        except Exception:
            pass


def format_timestamp_human_iso(iso_str: str) -> str:
    try:
        if not iso_str:
            return "—"
        dt = datetime.fromisoformat(iso_str)
        return dt.strftime("%Y-%m-%d %H:%M")
    except Exception:
        return iso_str


class BatchAnalysisDatabase:
    """قاعدة SQLite مستقلة لحفظ تحليلات تقسيم PDF مع بصمة الملف ونطاق التحليل."""
    def __init__(self, app_dir: Path):
        self.app_dir = Path(app_dir)
        self.path = self.app_dir / "pdf_batch_analysis.sqlite3"
        self._lock = threading.RLock()
        self._initialize()

    def _connect(self):
        conn = sqlite3.connect(str(self.path), timeout=10)
        conn.row_factory = sqlite3.Row
        return conn

    def _initialize(self):
        self.app_dir.mkdir(parents=True, exist_ok=True)
        with self._lock, self._connect() as conn:
            conn.execute("""
                CREATE TABLE IF NOT EXISTS batch_analysis (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    source_path TEXT NOT NULL,
                    source_name TEXT NOT NULL,
                    source_size INTEGER NOT NULL DEFAULT 0,
                    source_mtime REAL NOT NULL DEFAULT 0,
                    total_pages INTEGER NOT NULL DEFAULT 0,
                    scope_start INTEGER NOT NULL DEFAULT 1,
                    scope_end INTEGER NOT NULL DEFAULT 0,
                    boundaries_json TEXT NOT NULL,
                    sequence_text TEXT NOT NULL,
                    model_id TEXT NOT NULL DEFAULT '',
                    model_family TEXT NOT NULL DEFAULT '',
                    analysis_mode TEXT NOT NULL DEFAULT '',
                    warnings_json TEXT NOT NULL DEFAULT '[]',
                    created_at TEXT NOT NULL,
                    updated_at TEXT NOT NULL,
                    UNIQUE(source_path, source_size, source_mtime, scope_start, scope_end)
                )
            """)
            conn.execute("CREATE INDEX IF NOT EXISTS idx_batch_analysis_lookup ON batch_analysis(source_path, scope_start, scope_end, updated_at)")
            conn.commit()

    @staticmethod
    def _file_fingerprint(source_path: Path):
        try:
            st = source_path.stat()
            return int(st.st_size), float(st.st_mtime)
        except Exception:
            return 0, 0.0

    def save(self, source_path: Path, total_pages: int, scope_start: int,
             scope_end: int, boundaries: List[int], model: Optional[dict] = None,
             analysis_mode: str = "", warnings: Optional[List[str]] = None) -> dict:
        source_path = Path(source_path).resolve()
        size, mtime = self._file_fingerprint(source_path)
        now = datetime.now().isoformat(timespec="seconds")
        boundaries = [int(x) for x in boundaries]
        model = model or {}
        warnings = [str(x) for x in (warnings or []) if x]
        record = {
            "source_path": str(source_path),
            "source_name": source_path.name,
            "source_size": size,
            "source_mtime": mtime,
            "total_pages": int(total_pages or 0),
            "scope_start": int(scope_start or 1),
            "scope_end": int(scope_end or total_pages or 0),
            "boundaries": boundaries,
            "sequence_text": "-".join(str(x) for x in boundaries),
            "model_id": str(model.get("id", "") or ""),
            "model_family": str(model.get("family", "") or ""),
            "analysis_mode": str(analysis_mode or ""),
            "warnings": warnings,
            "created_at": now,
            "updated_at": now,
        }
        with self._lock, self._connect() as conn:
            conn.execute("""
                INSERT INTO batch_analysis
                (source_path, source_name, source_size, source_mtime, total_pages,
                 scope_start, scope_end, boundaries_json, sequence_text, model_id,
                 model_family, analysis_mode, warnings_json, created_at, updated_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                ON CONFLICT(source_path, source_size, source_mtime, scope_start, scope_end)
                DO UPDATE SET source_name=excluded.source_name,
                    total_pages=excluded.total_pages,
                    boundaries_json=excluded.boundaries_json,
                    sequence_text=excluded.sequence_text,
                    model_id=excluded.model_id,
                    model_family=excluded.model_family,
                    analysis_mode=excluded.analysis_mode,
                    warnings_json=excluded.warnings_json,
                    updated_at=excluded.updated_at
            """, (record["source_path"], record["source_name"], record["source_size"],
                  record["source_mtime"], record["total_pages"], record["scope_start"],
                  record["scope_end"], json.dumps(boundaries, ensure_ascii=False),
                  record["sequence_text"], record["model_id"], record["model_family"],
                  record["analysis_mode"], json.dumps(warnings, ensure_ascii=False),
                  now, now))
            conn.commit()
        return record

    def latest(self, source_path: Path, scope_start: int = 1,
               scope_end: Optional[int] = None) -> Optional[dict]:
        source_path = Path(source_path).resolve()
        with self._lock, self._connect() as conn:
            if scope_end is None:
                row = conn.execute(
                    "SELECT * FROM batch_analysis WHERE source_path=? ORDER BY updated_at DESC, id DESC LIMIT 1",
                    (str(source_path),)).fetchone()
            else:
                row = conn.execute(
                    "SELECT * FROM batch_analysis WHERE source_path=? AND scope_start=? AND scope_end=? ORDER BY updated_at DESC, id DESC LIMIT 1",
                    (str(source_path), int(scope_start), int(scope_end))).fetchone()
        if row is None:
            return None
        try:
            data = dict(row)
            data["boundaries"] = [int(x) for x in json.loads(data.get("boundaries_json") or "[]")]
            data["warnings"] = [str(x) for x in json.loads(data.get("warnings_json") or "[]")]
            data["file_changed"] = (
                data["source_size"], data["source_mtime"]
            ) != self._file_fingerprint(source_path)
            return data
        except Exception as exc:
            safe_print(f"[batch_analysis] read error: {exc}")
            return None


class KnownRootsManager:
    """مدير للمسارات المعروفة ومجلدات الإخراج النشطة لضمان تماسك الجلسات والمكتبة."""
    def __init__(self, app_dir: Path):
        self.app_dir = app_dir
        self.path = app_dir / "known_output_roots.json"
        self._lock = threading.RLock()

    def _load_locked(self) -> List[dict]:
        try:
            data = read_json_file_safe(self.path, [])
            if isinstance(data, list):
                return data
        except Exception:
            pass
        return []

    def _save_locked(self, records: List[dict]) -> None:
        try:
            sorted_records = sorted(records, key=lambda r: str(r.get("last_used") or ""), reverse=True)
            atomic_write_text(
                self.path,
                json.dumps(sorted_records, ensure_ascii=False, indent=2),
                encoding="utf-8")
        except Exception as e:
            safe_print(f"[roots_manager] save error: {e}")

    def add_or_update_root(self, path_str: str, label: Optional[str] = None):
        if not path_str:
            return
        p_resolved = str(Path(path_str).resolve())
        with self._lock:
            try:
                records = self._load_locked()
                found = False
                for r in records:
                    if str(Path(r["path"]).resolve()) == p_resolved:
                        r["last_used"] = datetime.now().isoformat()
                        if label:
                            r["label"] = label
                        found = True
                        break
                if not found:
                    records.append({
                        "path": str(Path(path_str).absolute()),
                        "last_used": datetime.now().isoformat(),
                        "label": label or ""
                    })
                self._save_locked(records)
            except Exception as e:
                safe_print(f"[roots_manager] add_or_update_root error: {e}")

    def get_all_roots(self) -> List[dict]:
        with self._lock:
            return self._load_locked()

    def remove_root(self, path_str: str):
        if not path_str:
            return
        p_resolved = str(Path(path_str).resolve())
        with self._lock:
            try:
                records = self._load_locked()
                records = [r for r in records if str(Path(r["path"]).resolve()) != p_resolved]
                self._save_locked(records)
            except Exception as e:
                safe_print(f"[roots_manager] remove_root error: {e}")

    def cleanup_unreachable(self, stop_event=None):
        try:
            with self._lock:
                records = list(self._load_locked())
            valid_paths = set()
            original_paths = set()
            for record in records:
                if stop_event is not None and stop_event.is_set():
                    return
                try:
                    raw_path = str(record.get("path") or "")
                    original_paths.add(raw_path)
                    if raw_path and Path(raw_path).exists():
                        valid_paths.add(raw_path)
                except Exception:
                    continue
            if stop_event is not None and stop_event.is_set():
                return
            if len(valid_paths) == len(original_paths):
                return
            with self._lock:
                current = self._load_locked()
                # لا تمسح جذوراً أُضيفت/عُدّلت أثناء فحص المسارات القديمة.
                filtered = [record for record in current
                            if str(record.get("path") or "") not in original_paths
                            or str(record.get("path") or "") in valid_paths]
                if len(filtered) != len(current):
                    self._save_locked(filtered)
        except Exception as e:
            safe_print(f"[roots_manager] cleanup_unreachable error: {e}")


class HistoryManager:
    # ✅ v27.0: مدير سجل دائم وآمن للخيوط لكل عمليات الاستخراج
    def __init__(self, app_dir: Path, max_records_getter: Optional[Callable[[], int]] = None):
        self.app_dir = app_dir
        self.path = app_dir / "extraction_history.json"
        self._lock = threading.RLock()
        self._max_records_getter = max_records_getter or (lambda: 500)

    def _load_locked(self) -> List[dict]:
        try:
            data = read_json_file_safe(self.path, [])
            if isinstance(data, list):
                return data
        except Exception:
            pass
        return []

    def _sorted(self, records: List[dict]) -> List[dict]:
        try:
            return sorted(
                records,
                key=lambda r: (str(r.get("finished_at") or ""), str(r.get("started_at") or ""), str(r.get("id") or "")),
                reverse=True)
        except Exception:
            return list(records)

    def _save_locked(self, records: List[dict]) -> None:
        try:
            atomic_write_text(
                self.path,
                json.dumps(self._sorted(records), ensure_ascii=False, indent=2),
                encoding="utf-8")
        except Exception as e:
            safe_print(f"[history] save error: {e}")

    def add_record(self, record: dict):
        with self._lock:
            try:
                records = self._load_locked()
                records.append(dict(record))
                max_records = max(1, int(self._max_records_getter() or 500))
                records = self._sorted(records)[:max_records]
                self._save_locked(records)
            except Exception as e:
                safe_print(f"[history] add_record error: {e}")

    def get_all(self) -> List[dict]:
        with self._lock:
            try:
                return self._sorted(self._load_locked())
            except Exception as e:
                safe_print(f"[history] get_all error: {e}")
                return []

    def delete_record(self, record_id: str):
        with self._lock:
            try:
                records = self._load_locked()
                new_records = [r for r in records if str(r.get("id")) != str(record_id)]
                if len(new_records) != len(records):
                    self._save_locked(new_records)
                    return True
            except Exception as e:
                safe_print(f"[history] delete_record error: {e}")
        return False

    def delete_with_data(self, record_id: str, delete_files: bool):
        removed = None
        with self._lock:
            try:
                records = self._load_locked()
                kept: List[dict] = []
                for record in records:
                    if removed is None and str(record.get("id")) == str(record_id):
                        removed = dict(record)
                    else:
                        kept.append(record)
                if removed is not None:
                    self._save_locked(kept)
            except Exception as e:
                safe_print(f"[history] delete_with_data error: {e}")
                removed = None
        if removed is not None and delete_files:
            try:
                output_dir = Path(str(removed.get("output_dir") or "")).expanduser()
                if str(output_dir):
                    data_dir = get_book_data_dir(output_dir, str(removed.get("book_stem") or ""))
                    if data_dir.exists():
                        shutil.rmtree(data_dir, ignore_errors=True)
                final_path = removed.get("final_path")
                if final_path:
                    fp = Path(str(final_path)).expanduser()
                    if fp.exists():
                        try:
                            fp.unlink()
                        except Exception:
                            pass
            except Exception as e:
                safe_print(f"[history] delete files error: {e}")
        return removed

    def clear_all(self):
        with self._lock:
            try:
                self._save_locked([])
                return True
            except Exception as e:
                safe_print(f"[history] clear_all error: {e}")
                return False


def get_default_prompt(with_tashkeel: bool, remove_headers: bool) -> str:
    return build_extract_prompt_pdf(with_tashkeel, remove_headers)



def build_translate_prompts(src_code: str, tgt_code: str) -> Tuple[str, str]:
    src_name = get_lang_name(src_code)
    tgt_name = get_lang_name(tgt_code)
    if tgt_code == "ar":
        tashkeel_note = "**شكّل النص العربي المُترجَم تشكيلاً كاملاً** حسب السياق."
    else:
        tashkeel_note = f"احرص على دقة القواعد والإملاء في {tgt_name}."
    pdf_p = (PROMPT_TRANSLATE_TEMPLATE
              .replace("{SRC_NAME}", src_name)
              .replace("{TGT_NAME}", tgt_name)
              .replace("{TASHKEEL_NOTE}", tashkeel_note))
    txt_p = (PROMPT_TXT_TRANSLATE_TEMPLATE
              .replace("{SRC_NAME}", src_name)
              .replace("{TGT_NAME}", tgt_name)
              .replace("{TASHKEEL_NOTE}", tashkeel_note))
    return pdf_p, txt_p


DEFAULT_CUSTOM_GENERATION_PROMPT = """أنت خبير قياس وتقويم تربوي. اقرأ النص المرفق بعمق شديد وغطِّ كل مسألة فقهية وحكم ودليل ورد فيها، مهما بدا صغيراً.

**محور الأسئلة (مهم):** ركّز حصراً على المسائل الفقهية وأحكامها وأدلتها (الأقوال، الخلاف بين الأئمة، الحجج، عللها). **تجنّب الأسئلة السطحية** مثل تراجم الرواة في الحواشي، أو معاني مفردات لغوية هامشية، أو تفاصيل شكلية لا تمس حكماً أو دليلاً — إلا إذا كانت ضرورية لفهم حكم فقهي مباشرة.

النوعان: اختيار من متعدد (4 خيارات) وصح/خطأ. لا تخرج بأي معلومة من خارج النص.

**منع التكرار (إلزامي):** قبل كتابة أي سؤال، تحقق أنه لا يسأل عن نفس الحكم/الدليل/المعلومة التي سبق أن سألت عنها بأي صياغة أخرى. كل مسألة أو دليل يُسأل عنه مرة واحدة فقط بالزاوية الأهم فيه.

قواعد الجودة:
- المشتتات في الاختيار من متعدد معقولة ومن نفس مجال السؤال.
- عبارات الخطأ في صح/خطأ خاطئة بشكل قاطع لا جزئي، بلا نفي مزدوج.
- كل سؤال مبني حرفياً على النص، وكل شرح يشير لموضعه فيه.

قواعد إلزامية للدقة الحسابية:
1. توزيع مواضع الإجابة في الاختيار من متعدد يجب أن يكون متوازناً فعلياً بين 0 و1 و2 و3 بفارق سؤال واحد كحد أقصى.
2. توازن صح/خطأ يجب أن يكون فعلياً بفارق سؤال واحد كحد أقصى.
3. نص answer في الاختيار من متعدد نسخة حرفية طبق الأصل من أحد عناصر options.

**العدد: 125 سؤالاً على الأقل — شرط إلزامي.** اسأل عن كل مسألة فقهية من عدة زوايا جوهرية مختلفة: الحكم، الدليل، العلة، القول المخالف، حجته، الفرق بين المسائل، وتطبيقات وردت في النص، مع منع التكرار السطحي.

الإخراج: JSON صالح واحد فقط، بلا أي نص أو أسوار Markdown قبله أو بعده، بهذا الهيكل:
{"meta":{"total_questions":0,"multiple_choice_count":0,"true_false_count":0,"true_false_true_count":0,"true_false_false_count":0,"answer_position_distribution":{"0":0,"1":0,"2":0,"3":0}},"multiple_choice_questions":[{"id":1,"question":"","options":["","","",""],"correct_index":0,"answer":"","explanation":"","source_section":""}],"true_false_questions":[{"id":1,"question":"","answer":true,"explanation":"","source_section":""}]}

قبل التسليم، راجع القائمة الكاملة وتأكد فعلياً من عدم التكرار، وعدم السطحية، وصحة عدّ correct_index وتوازن true/false ومطابقة meta للقائمة النهائية.
"""


DEFAULT_CUSTOM_COMPARE_PROMPT = """راجع بنك الأسئلة (JSON) مقابل النص المصدر المرفق معاً، وأعطني تقريراً مختصراً بالنقاط فقط:

1. صحة JSON: هل هو كائن واحد صالح فعلاً؟
2. الدقة: اذكر أرقام أي أسئلة فيها معلومة غير مطابقة للنص أو إجابة خاطئة.
3. تطابق answer مع options حرفياً (احسب الاستثناءات).
4. التوزيع الفعلي لـ correct_index (احسبه) قارنه بما في meta.
5. التوازن الفعلي true/false (احسبه) قارنه بما في meta.
6. التكرار: أي أسئلة مكررة أو شبه مكررة.
7. التغطية: أي معلومات/فقرات في النص لم يُسأل عنها إطلاقاً.

اختم بقائمة أرقام الأسئلة الواجب حذفها أو تصحيحها.

أخرج JSON صالحاً واحداً فقط وبالعربية بالمفاتيح: shard_assessment, coverage_pct, missing_items, notes.
"""

def ensure_custom_prompt(app_dir: Path) -> None:
    prompts_dir = app_dir / "prompts"
    prompts_dir.mkdir(exist_ok=True)
    f = prompts_dir / "custom_prompt.txt"
    old_defaults = {PROMPT_EXTRACT_WITH_TASHKEEL_REMOVE_HEADERS.strip(), PROMPT_TXT_OCR_CLEANUP.strip()}
    if (not f.exists()) or (f.read_text(encoding="utf-8", errors="replace").strip() in old_defaults):
        f.write_text(DEFAULT_CUSTOM_GENERATION_PROMPT, encoding="utf-8")
    f2 = prompts_dir / "custom_txt_prompt.txt"
    if (not f2.exists()) or (f2.read_text(encoding="utf-8", errors="replace").strip() in old_defaults):
        f2.write_text(DEFAULT_CUSTOM_GENERATION_PROMPT, encoding="utf-8")
    f3 = prompts_dir / "custom_compare_prompt.txt"
    if (not f3.exists()) or (not f3.read_text(encoding="utf-8", errors="replace").strip()):
        f3.write_text(DEFAULT_CUSTOM_COMPARE_PROMPT, encoding="utf-8")


