# ═══════════════════════════════════════════════════════════════════
#  Quota & Keys
# ═══════════════════════════════════════════════════════════════════

class QuotaKind(Enum):
    PER_MINUTE = "rpm"
    PER_DAY = "rpd"
    UNKNOWN = "unknown"


def parse_429(exc) -> Tuple[QuotaKind, float]:
    msg = str(exc)
    kind = QuotaKind.UNKNOWN
    if "PerDay" in msg or ("free_tier_requests" in msg.lower() and "PerMinute" not in msg):
        kind = QuotaKind.PER_DAY
    if "PerMinute" in msg or "RequestsPerMinute" in msg:
        kind = QuotaKind.PER_MINUTE
    delay = 0.0
    m = re.search(r"['\"]retryDelay['\"]\s*:\s*['\"](\d+(?:\.\d+)?)s['\"]", msg)
    if m:
        delay = float(m.group(1))
    else:
        m = re.search(r"retry in (\d+(?:\.\d+)?)\s*s", msg, re.IGNORECASE)
        if m:
            delay = float(m.group(1))
    if delay > 600 and kind == QuotaKind.UNKNOWN:
        kind = QuotaKind.PER_DAY
    elif 0 < delay <= 600 and kind == QuotaKind.UNKNOWN:
        kind = QuotaKind.PER_MINUTE
    return kind, delay


def is_quota_error(exc) -> bool:
    msg = str(exc)
    has_429 = ("RESOURCE_EXHAUSTED" in msg
               or bool(re.search(r"(?<!\\d)429(?!\\d)", msg))
               or "code': 429" in msg or "code\": 429" in msg)
    if not has_429:
        return False
    quota_indicators = ["quota", "rate", "limit", "exhausted", "PerDay", "PerMinute"]
    if any(ind in msg for ind in quota_indicators):
        return True
    return has_429


# ═══════════════════════════════════════════════════════════════════
#  ✅ v10.14: Pacific-time helpers + جدول الحصص المنشورة (Free) +
#  تصنيف دقيق لأخطاء 429 (كوتة حقيقية مقابل تخفيف حمل)
# ═══════════════════════════════════════════════════════════════════

def _pacific_offset_hours(dt_utc=None) -> int:
    """فرق توقيت المحيط الهادئ عن UTC بالساعات (-7 صيفًا، -8 شتاءً).

    تُصفَّر حصص Google اليومية (RPD) عند منتصف الليل بتوقيت المحيط
    الهادئ — لا التوقيت المحلي. يعمل دون قاعدة بيانات tz (مهم لنسخة
    Windows المجمعة): يحاول zoneinfo أولًا ثم قاعدة التوقيت الصيفي.
    """
    try:
        from zoneinfo import ZoneInfo
        from datetime import timezone
        dt = dt_utc or datetime.now(timezone.utc)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        off = dt.astimezone(ZoneInfo("America/Los_Angeles")).utcoffset()
        return int(off.total_seconds() // 3600)
    except Exception:
        pass
    try:
        from datetime import timezone
        now = dt_utc or datetime.now(timezone.utc)
        y = now.year
        d1 = datetime(y, 3, 1)    # الأحد الثاني من مارس (بدء الصيفي)
        dst_start = d1 + timedelta(days=((6 - d1.weekday()) % 7) + 7)
        d2 = datetime(y, 11, 1)   # الأحد الأول من نوفمبر (نهايته)
        dst_end = d2 + timedelta(days=((6 - d2.weekday()) % 7))
        naive = now.replace(tzinfo=None)
        if datetime(y, dst_start.month, dst_start.day, 10) <= naive < datetime(
                y, dst_end.month, dst_end.day, 9):
            return -7
        return -8
    except Exception:
        return -7


def pacific_now() -> datetime:
    from datetime import timezone
    return datetime.now(timezone.utc) + timedelta(hours=_pacific_offset_hours())


def pacific_today_key() -> str:
    return pacific_now().strftime("%Y-%m-%d")


def seconds_until_pacific_midnight() -> float:
    now = pacific_now().replace(tzinfo=None)
    nxt = (now + timedelta(days=1)).replace(hour=0, minute=0, second=5, microsecond=0)
    return max(1.0, (nxt - now).total_seconds())


def fmt_duration(secs: float) -> str:
    """مدة بشرية مختصرة: «45 ث» / «12 د» / «3 س 20 د» / «2 ي 5 س»."""
    try:
        s = max(0, int(secs))
    except Exception:
        return "؟"
    if s < 60:
        return f"{s} ث"
    m, s = divmod(s, 60)
    if m < 60:
        return f"{m} د" if s == 0 else f"{m} د {s} ث"
    h, m = divmod(m, 60)
    if h < 24:
        return f"{h} س" if m == 0 else f"{h} س {m} د"
    d, h = divmod(h, 24)
    return f"{d} ي" if h == 0 else f"{d} ي {h} س"


