# ═══════════════════════════════════════════════════════════════════
#  Shard Uploader
# ═══════════════════════════════════════════════════════════════════

class ShardUploader:
    def __init__(self, shard: PDFShard):
        self.shard = shard
        self._safe_temp_path: Optional[Path] = None

    @staticmethod
    def _is_ascii_safe(s: str) -> bool:
        try:
            s.encode("ascii"); return True
        except UnicodeEncodeError:
            return False

    def _get_upload_path(self, log) -> Tuple[Path, str]:
        ext = ".txt" if self.shard.is_txt else ".pdf"
        cache_key = f"shard_{self.shard.shard_md5[:12]}_{self.shard.idx:04d}"
        try:
            path, name = resolve_ascii_safe_upload_path(self.shard.shard_path, cache_key, ext=ext)
            self._safe_temp_path = path
            return path, name
        except Exception as e:
            log(f"⚠️  نسخة آمنة فشلت: {e}")
            return self.shard.shard_path, self.shard.shard_path.name

    def get_or_upload(self, client: genai.Client, key_state: KeyState,
                       log, stop_event: threading.Event,
                       on_progress: Callable[[int], None] = None,
                       force_fresh: bool = False) -> types.File:
        if stop_event.is_set():
            raise InterruptedError("توقف")
        if not force_fresh:
            cached = key_state.uploaded_shards.get(self.shard.shard_md5)
            if cached:
                try:
                    f = client.files.get(name=cached)
                    if f.state.name == "ACTIVE":
                        log(f"♻️  جزء مرفوع سابقاً ({key_state.masked}): جزء {self.shard.idx}")
                        if on_progress: on_progress(100)
                        return f
                except Exception:
                    pass
        else:
            key_state.uploaded_shards.pop(self.shard.shard_md5, None)
        return self._upload_fresh(client, key_state, log, stop_event, on_progress)

    def _upload_fresh(self, client, key_state, log, stop_event,
                        on_progress=None) -> types.File:
        if stop_event.is_set():
            raise InterruptedError("توقف")
        upload_path, safe_name = self._get_upload_path(log)
        size_kb = upload_path.stat().st_size / 1024
        mime = "text/plain" if self.shard.is_txt else "application/pdf"
        kind_label = "TXT" if self.shard.is_txt else "PDF"
        log(f"📤 رفع جزء {kind_label} {self.shard.idx} ({size_kb:.1f} KB): "
            f"{self.shard.page_start}-{self.shard.page_end}")
        if on_progress: on_progress(10)
        if not wait_for_network_if_needed({}, stop_event, log):
            raise InterruptedError("توقف")
        throttle_key_send(key_state.key, stop_event, log, purpose="upload")
        try:
            f = client.files.upload(
                file=str(upload_path),
                config=types.UploadFileConfig(
                    mime_type=mime, display_name=safe_name))
        except UnicodeEncodeError:
            f = client.files.upload(
                file=str(upload_path),
                config=types.UploadFileConfig(mime_type=mime))
        if on_progress: on_progress(60)
        
        f = wait_for_file_active(client, f, stop_event, log=log, on_progress=on_progress, initial_progress=60)
        
        if f.state.name != "ACTIVE":
            raise RuntimeError(f"فشل رفع الجزء: state={f.state.name}")
        if on_progress: on_progress(100)
        key_state.uploaded_shards[self.shard.shard_md5] = f.name
        log(f"✅ رُفع جزء {self.shard.idx}: {f.name}")
        return f


# ═══════════════════════════════════════════════════════════════════
#  TXT Context Uploader
# ═══════════════════════════════════════════════════════════════════

class TxtContextManager:
    def __init__(self, txt_path: Path, log: Callable[[str], None]):
        self.txt_path = txt_path
        self.log = log
        self._md5 = _compute_md5(txt_path)
        self._lock = threading.RLock()
        self._uploaded: Dict[str, str] = {}

    @staticmethod
    def _is_ascii_safe(s: str) -> bool:
        try:
            s.encode("ascii"); return True
        except UnicodeEncodeError:
            return False

    def _get_safe_path(self) -> Tuple[Path, str]:
        cache_key = f"ctx_{self._md5[:12]}"
        try:
            return resolve_ascii_safe_upload_path(self.txt_path, cache_key, ext=".txt")
        except Exception:
            return self.txt_path, self.txt_path.name

    def get_or_upload(self, client: genai.Client, api_key: str,
                       stop_event: threading.Event,
                       force_fresh: bool = False) -> Optional[types.File]:
        with self._lock:
            if not force_fresh:
                cached_name = self._uploaded.get(api_key)
                if cached_name:
                    try:
                        f = client.files.get(name=cached_name)
                        if f.state.name == "ACTIVE":
                            return f
                    except Exception:
                        self._uploaded.pop(api_key, None)
            else:
                self._uploaded.pop(api_key, None)
        if stop_event.is_set():
            return None
        upload_path, safe_name = self._get_safe_path()
        self.log(f"📤 رفع الملف الكامل كسياق مرجعي ({safe_name})...")
        throttle_key_send(api_key, stop_event, self.log, purpose="upload")
        try:
            f = client.files.upload(
                file=str(upload_path),
                config=types.UploadFileConfig(
                    mime_type="text/plain", display_name=safe_name))
        except Exception as e:
            self.log(f"⚠️  فشل رفع السياق: {e}")
            return None
            
        f = wait_for_file_active(client, f, stop_event, log=self.log)
        
        if f.state.name != "ACTIVE":
            self.log(f"⚠️  حالة ملف السياق غير نشطة: {f.state.name}")
            return None
        with self._lock:
            self._uploaded[api_key] = f.name
        self.log(f"✅ السياق المرجعي جاهز: {f.name}")
        return f


# ═══════════════════════════════════════════════════════════════════
#  Thinking config + generate_content_stream
# ═══════════════════════════════════════════════════════════════════

def build_thinking_config(model_family: str, cfg: Optional[dict] = None):
    """مستوى تفكير النموذج: منخفض/معدوم - متوسط - عالي."""
    try:
        level = str((cfg or {}).get("thinking_level", "low") or "low")
        if level in ("off", "none", "low"):
            if model_family == "3":
                return types.ThinkingConfig(thinking_level="low")
            elif model_family == "2.5":
                return types.ThinkingConfig(thinking_budget=0)
        if level == "medium":
            if model_family == "3":
                return types.ThinkingConfig(thinking_level="medium")
            elif model_family == "2.5":
                return types.ThinkingConfig(thinking_budget=8192)
        if level == "high":
            if model_family == "3":
                return types.ThinkingConfig(thinking_level="high")
            elif model_family == "2.5":
                return types.ThinkingConfig(thinking_budget=24576)
    except Exception:
        pass
    return None


@dataclass
class GenResult:
    text: str
    finish_reason: str
    input_tokens: int
    output_tokens: int


def call_model_stream(client, model_id, model_family, file_refs,
                       system_prompt, user_prompt, cfg, on_token,
                       stop_event, log, on_request: Optional[Callable[[str], None]] = None,
                       api_key: str = "") -> GenResult:  # ✅ v10.15: api_key للإيقاع
    parts = []
    for fref in file_refs:
        if fref is None:
            continue
        mime = "text/plain" if fref.uri and (
            fref.name.endswith(".txt") or
            "text" in (getattr(fref, "mime_type", "") or "").lower()
        ) else "application/pdf"
        parts.append(types.Part(file_data=types.FileData(
            mime_type=mime, file_uri=fref.uri)))
    parts.append(types.Part.from_text(text=user_prompt))

    contents = [types.Content(role="user", parts=parts)]
    cfg_kwargs = dict(
        temperature=cfg["temperature"],
        max_output_tokens=cfg["max_output_tokens"],
        system_instruction=[types.Part.from_text(text=system_prompt)],
        stop_sequences=[END_MARKER])
    th = build_thinking_config(model_family, cfg)
    if th is not None:
        cfg_kwargs["thinking_config"] = th
    gen_cfg = types.GenerateContentConfig(**cfg_kwargs)

    backoff = cfg["retry_backoff_base"]
    last_exc = None

    for net_attempt in range(1, cfg["network_max_retries"] + 1):
        if stop_event.is_set():
            raise InterruptedError("توقف")
        try:
            buf: List[str] = []
            finish_reason = "UNKNOWN"
            usage = {"in": 0, "out": 0}
            last_chunk = None
            if not wait_for_network_if_needed(cfg, stop_event, log):
                raise InterruptedError("توقف")
            # Notify UI that a real network request is about to be sent
            try:
                if on_request:
                    desc = f"model={model_id} files={len(file_refs)}"
                    try: on_request(desc)
                    except Exception: pass
            except Exception:
                pass

            if api_key:
                throttle_key_send(api_key, stop_event, log)  # ✅ v10.15
            stream = client.models.generate_content_stream(
                model=model_id, contents=contents, config=gen_cfg)
            try:
                register_stop_component("streams", stream)
            except Exception:
                pass
            try:
                for chunk in stream:
                    if stop_event.is_set():
                        try:
                            if hasattr(stream, "close"):
                                stream.close()
                            elif hasattr(stream, "_response") and hasattr(stream._response, "close"):
                                stream._response.close()
                        except Exception:
                            pass
                        raise InterruptedError("توقف فوري")
                    if chunk.text:
                        buf.append(chunk.text)
                        try:
                            on_token(chunk.text)
                        except Exception:
                            pass
                    last_chunk = chunk
            finally:
                try:
                    unregister_stop_component("streams", stream)
                except Exception:
                    pass

            if last_chunk is not None:
                cands = getattr(last_chunk, "candidates", None) or []
                if cands:
                    fr = cands[0].finish_reason
                    finish_reason = fr.name if hasattr(fr, "name") else str(fr)
                um = getattr(last_chunk, "usage_metadata", None)
                if um:
                    usage["in"] = getattr(um, "prompt_token_count", 0) or 0
                    usage["out"] = getattr(um, "candidates_token_count", 0) or 0

            text = "".join(buf)
            if END_MARKER in text:
                text = text.split(END_MARKER, 1)[0]
            return GenResult(text.rstrip(), finish_reason, usage["in"], usage["out"])

        except InterruptedError:
            raise
        except Exception as e:
            last_exc = e
            if is_quota_error(e) or is_file_lost_error(e):
                raise
            if (not is_retryable_network_error(e) or
                net_attempt == cfg["network_max_retries"]):
                raise
            # ✅ v24.4: تأخير أطول لـ 503 (خادم مشغول)
            if is_server_overloaded_error(e):
                wait = min(3.0, 1.0 * (1.5 ** net_attempt))
            else:
                wait = min(backoff, cfg["retry_backoff_max"]) + random.uniform(0, 2)
            try:
                log(f"⏳ شبكة (محاولة {net_attempt}): {e}")
                log(f"   إعادة بعد {wait:.1f}s...")
            except Exception:
                pass
            interruptible_sleep(wait, stop_event)
            backoff *= 2
    raise last_exc


