def build_txt_extract_prompt(shard: PDFShard, total_shards: int,
                             force: bool = False) -> str:
    if force:
        return (
            f"⚠️ إعادة استخراج إجبارية للجزء {shard.idx}/{total_shards}: "
            f"انسخ كامل نطاق الكلمات {shard.line_start}-{shard.line_end} من الملف الأول.\n\n"
            f"لا تختصر، ولا تكتفِ بأول سطرين أو بالعناوين؛ أخرج كل النص بالترتيب "
            f"حتى آخر كلمة في النطاق، مع الالتزام بتعليمات system instructions.\n"
            f"الملف الثاني مرجع للسياق فقط ولا تستبدل به نطاق الملف الأول.\n"
            f"عند اكتمال النطاق فعلياً اكتب: {END_MARKER}\n"
        )
    return (
        f"المطلوب: معالجة **نطاق الكلمات من {shard.line_start} إلى {shard.line_end}** فقط "
        f"(جزء {shard.idx}/{total_shards}، {shard.pages_count} كلمة تقريباً).\n\n"
        f"📎 الملف الأول المرفق = نص الجزء المحدد (ومعه رأس يوضح نطاق الكلمات).\n"
        f"📎 الملف الثاني المرفق (إن وُجد) = الملف الكامل كسياق مرجعي فقط.\n\n"
        f"📌 تعليمات:\n"
        f"• عالج نص النطاق المحدد فقط حسب قواعد system instructions.\n"
        f"• استفد من الملف الكامل لفهم السياق (ما قبل وما بعد).\n"
        f"• أخرج النص النهائي للنطاق فقط — بدون رأس نطاق الكلمات أو أي ترقيم.\n"
        f"• حافظ على الفقرات وترتيبها قدر الإمكان.\n"
        f"• عند الانتهاء فعلياً اكتب: {END_MARKER}\n"
    )


def extract_first_json_object(raw: str) -> Optional[str]:
    if not raw:
        return None
    start = raw.find('{')
    if start < 0:
        return None
    depth = 0
    in_string = False
    escape = False
    for pos in range(start, len(raw)):
        ch = raw[pos]
        if in_string:
            if escape:
                escape = False
            elif ch == '\\':
                escape = True
            elif ch == '"':
                in_string = False
            continue
        if ch == '"':
            in_string = True
        elif ch == '{':
            depth += 1
        elif ch == '}':
            depth -= 1
            if depth == 0:
                return raw[start:pos + 1]
    return raw[start:] if start >= 0 else None


def _repair_jsonish_text(raw: str) -> str:
    raw = (raw or '').strip()
    if raw.startswith('```'):
        raw = re.sub(r"^```(?:json)?\s*", "", raw)
        raw = re.sub(r"\s*```\s*$", "", raw)
    candidate = extract_first_json_object(raw) or raw
    candidate = (candidate.replace('“', '"').replace('”', '"')
                         .replace('‘', "'").replace('’', "'"))
    candidate = re.sub(r',\s*([}\]])', r'\1', candidate)
    candidate = re.sub(r'[\x00-\x08\x0b\x0c\x0e-\x1f]', ' ', candidate)
    return candidate.strip()


def parse_compare_response_json(raw: str) -> dict:
    candidate = _repair_jsonish_text(raw)
    raw = (raw or '').strip()
    tries = [candidate, raw]
    tries.append(re.sub(r'([,{]\s*)([A-Za-z_][A-Za-z0-9_]*)\s*:', r'\1"\2":', candidate))
    for item in tries:
        try:
            return json.loads(item)
        except Exception:
            pass

    search_space = candidate + "\n" + raw
    assessment = None
    coverage = None
    notes = ''
    missing_items = []

    assessment_patterns = [
        r'"shard_assessment"\s*:\s*"([^"]+)"',
        r'"assessment"\s*:\s*"([^"]+)"',
        r"'shard_assessment'\s*:\s*'([^']+)'",
        r"'assessment'\s*:\s*'([^']+)'",
        r'shard_assessment\s*[:=]\s*"?([^",\n}]+)"?',
        r'assessment\s*[:=]\s*"?([^",\n}]+)"?',
    ]
    for pat in assessment_patterns:
        m = re.search(pat, search_space, re.IGNORECASE)
        if m:
            assessment = m.group(1).strip()
            break
    if assessment is None:
        m = re.search(r'(ممتاز|جيد|متوسط|ضعيف)', search_space)
        if m:
            assessment = m.group(1).strip()

    coverage_patterns = [
        r'"coverage_pct"\s*:\s*(\d{1,3})',
        r"'coverage_pct'\s*:\s*(\d{1,3})",
        r'coverage_pct\s*[:=]\s*(\d{1,3})',
        r'coverage[^0-9]{0,20}(\d{1,3})',
    ]
    for pat in coverage_patterns:
        m = re.search(pat, search_space, re.IGNORECASE)
        if m:
            coverage = int(m.group(1))
            break

    note_patterns = [
        r'"notes"\s*:\s*"([^"]*)"',
        r'"notes"\s*:\s*"([^}]*)',
        r'notes\s*[:=]\s*"?(.+)$',
    ]
    for idx, pat in enumerate(note_patterns):
        flags = re.IGNORECASE | re.DOTALL if idx == 2 else re.DOTALL
        m = re.search(pat, search_space, flags)
        if m:
            notes = m.group(1).strip().rstrip('}"')
            break

    list_match = re.search(r'"missing_items"\s*:\s*(\[.*?\])', search_space, re.DOTALL)
    if list_match:
        list_candidate = re.sub(r',\s*([}\]])', r'\1', list_match.group(1))
        try:
            missing_items = json.loads(list_candidate)
        except Exception:
            missing_items = []

    if assessment is None and coverage is None and not any(k in search_space for k in ['shard_assessment', 'coverage_pct', 'missing_items', 'notes']):
        raise ValueError(f"لا JSON: {raw[:300]}")

    # ✅ v25.5 FIX: نتيجة "غير محدد" عند فشل التحليل (بدل "ضعيف" المضلل)
    return {
        "shard_assessment": assessment or "غير محدد",
        "coverage_pct": int(coverage) if coverage is not None else -1,
        "missing_items": missing_items or [],
        "notes": notes or "⚠️ فشل تحليل JSON — يحتاج إعادة فحص",
        "_parse_failed": True,
    }



