#  ✅ v25.0: عدّاد طلبات مركزي آمن الخيوط
# ═══════════════════════════════════════════════════════════════════

# ✅ إصلاح: بدون مهلة صريحة على عميل genai، عند انقطاع الشبكة فجأة أثناء
# استقبال stream، يبقى الخيط محظوراً على القراءة إلى الأبد حتى لو عادت
# الشبكة بعد ذلك — لأن الاتصال القديم لا يُخطر بانقطاعه فيبقى معلَّقاً
# ("يحجز مساراً" دون تقدم ولا فشل). هذه المهلة تجعل القراءة المحظورة تفشل
# بعد فترة انقطاع بلا استجابة، فيلتقطها منطق إعادة المحاولة الموجود أصلاً
# (network_max_retries) بدل أن تظل عالقة للأبد.
GENAI_HTTP_TIMEOUT_MS = 180_000  # 3 دقائق كحد أقصى للانتظار بلا أي استجابة


class CentralRequestCounter:
    """✅ v25.1: عدّاد مركزي لكل طلبات generate_content الفعلية (thread-safe)."""
    def __init__(self):
        self._count = 0
        self._lock = threading.Lock()

    @property
    def count(self) -> int:
        return self._count

    def increment(self, description: str = "") -> int:
        """يزيد العدّاد. يعيد الرقم الجديد."""
        with self._lock:
            self._count += 1
            return self._count

    def reset(self):
        with self._lock:
            self._count = 0


class PerKeyRateLimiter:
    """محدد اختياري لنافذة منزلقة 60 ثانية، لكل مفتاح API وبشكل آمن للخيوط.

    يحدّ طلبات استدلال النموذج (generate / generate_stream)؛ رفع الملفات لا
    يستهلك خانة من حد RPM حتى لا ينتظر كل توليد دقيقةً بعد رفع الملف.
    """

    def __init__(self, max_per_min: int = 2, window_sec: float = 60.0,
                 enabled: bool = True):
        self._lock = threading.RLock()
        self._hits = {}  # api_key -> طوابع طلبات النموذج داخل النافذة
        self.max_per_min = max(1, int(max_per_min))
        self.window_sec = max(1.0, float(window_sec))
        self.enabled = bool(enabled)

    @staticmethod
    def _masked(api_key: str) -> str:
        k = api_key or ""
        return (k[:6] + "..." + k[-4:]) if len(k) > 10 else "****"

    def set_limit(self, n: int) -> int:
        with self._lock:
            self.max_per_min = max(1, int(n))
            return self.max_per_min

    def set_enabled(self, enabled: bool) -> bool:
        with self._lock:
            self.enabled = bool(enabled)
            return self.enabled

    def seconds_until_available(self, api_key: str) -> float:
        """وقت انتظار до حصول المفتاح على خانة؛ صفر إن كانت متاحة الآن."""
        if not api_key:
            return 0.0
        with self._lock:
            if not self.enabled:
                return 0.0
            now = time.time()
            cutoff = now - self.window_sec
            hits = self._hits.setdefault(api_key, [])
            while hits and hits[0] <= cutoff:
                hits.pop(0)
            if len(hits) < self.max_per_min:
                return 0.0
            return max(0.0, hits[0] + self.window_sec - now)

    def acquire(self, api_key: str, stop_event=None) -> float:
        """ينتظر حتى تتوفر خانة، ثم يحجزها. يحترم الإيقاف أثناء الانتظار."""
        if not api_key:
            return 0.0
        waited = 0.0
        while True:
            with self._lock:
                if not self.enabled:
                    return waited
                now = time.time()
                cutoff = now - self.window_sec
                hits = self._hits.setdefault(api_key, [])
                while hits and hits[0] <= cutoff:
                    hits.pop(0)
                if len(hits) < self.max_per_min:
                    hits.append(now)
                    return waited
                sleep_for = max(0.05, hits[0] + self.window_sec - now)
            if stop_event is not None and stop_event.is_set():
                raise InterruptedError("توقف")
            step = min(sleep_for, 0.25)
            time.sleep(step)
            waited += step


_KEY_SEND_LIMITER = PerKeyRateLimiter(max_per_min=2, enabled=True)


def configure_key_rpm(n, enabled=None) -> int:
    """يضبط حد طلبات النموذج/دقيقة لكل مفتاح، مع تفعيل/تعطيل اختياري."""
    try:
        n = int(n)
    except Exception:
        n = 2
    actual = _KEY_SEND_LIMITER.set_limit(n)
    if enabled is not None:
        _KEY_SEND_LIMITER.set_enabled(bool(enabled))
    return actual


def get_key_rpm() -> int:
    """الحد الحالي لكل مفتاح (طلب نموذج/دقيقة)."""
    return _KEY_SEND_LIMITER.max_per_min


def is_key_rpm_enabled() -> bool:
    return bool(_KEY_SEND_LIMITER.enabled)


def throttle_key_send(api_key: str, stop_event=None, log=None,
                      purpose: str = "model") -> float:
    """بوابة معدل الطلبات؛ ملفات الرفع مستثناة عمداً من حد استدلال النموذج."""
    if not api_key or str(purpose or "model").lower() in {
            "upload", "file_upload", "files"}:
        return 0.0
    try:
        waited = _KEY_SEND_LIMITER.acquire(api_key, stop_event)
    except InterruptedError:
        raise
    except Exception:
        return 0.0
    if waited > 2.0 and log is not None:
        try:
            state = "مفعّل" if is_key_rpm_enabled() else "معطّل"
            log(f"⏳ إيقاع المفاتيح: انتظار {waited:.0f}s قبل طلب النموذج "
                f"(مفتاح {PerKeyRateLimiter._masked(api_key)} — "
                f"{state}، الحد {get_key_rpm()}/دقيقة)")
        except Exception:
            pass
    return waited



