#  InlineComparator
# ═══════════════════════════════════════════════════════════════════

class InlineComparator:
    def __init__(self, output_dir: Path, book_stem: str,
                  model_id: str, model_family: str, cfg: dict,
                  on_partial_result: Callable[[ShardComparisonResult], None],
                  on_log: Callable[[str], None],
                  stop_event: threading.Event,
                  api_keys: List[str],
                  global_key_mgr: 'GlobalKeyManager',
                  parallel_workers: int = 1,
                  request_counter: Optional['CentralRequestCounter'] = None):
        self.output_dir = output_dir
        self.book_stem = book_stem
        self.model_id = model_id
        self.request_counter = request_counter
        self.model_family = model_family
        self.cfg = cfg
        self.on_partial_result = on_partial_result
        self.on_log = on_log
        self.stop_event = stop_event
        self.api_keys = list(api_keys)
        self.global_key_mgr = global_key_mgr
        self.parallel_workers = max(1, min(25, int(parallel_workers)))

        self.compare_dir = get_book_compare_dir(output_dir, book_stem)
        self.compare_dir.mkdir(parents=True, exist_ok=True)
        self.results_file = self.compare_dir / "partial.json"
        self.partial_results: Dict[int, ShardComparisonResult] = {}
        self._load_existing()

        self._lock = threading.RLock()
        self._executor: Optional[ThreadPoolExecutor] = None
        self._pending_futures: List[Future] = []
        self._upload_cache: Dict[str, Dict[str, str]] = {}
        self._task_queue: queue.Queue = queue.Queue()
        self._dispatcher_thread: Optional[threading.Thread] = None
        self._running = False
        self._active_tasks = 0
        self._active_lock = threading.RLock()
        self._finished_task_ids: Set[int] = set()
        self._attempt_counts: Dict[int, int] = {}
        self._task_file_uris: Dict[int, Dict[str, str]] = {}
        self._network_state: Dict[str, Any] = {}
        self._client_cache: Dict[str, Any] = {}  # ✅ OPT9: تخزين مؤقت للعملاء

    def _load_existing(self):
        if self.results_file.exists():
            try:
                data = json.loads(self.results_file.read_text(encoding="utf-8"))
                for k, v in data.items():
                    self.partial_results[int(k)] = ShardComparisonResult(**v)
                self.on_log(f"♻️  محمّل {len(self.partial_results)} مقارنة سابقة")
            except Exception as e:
                self.on_log(f"⚠️  تعذر تحميل المقارنات السابقة: {e}")

    def _save_results(self):
        try:
            self.compare_dir.mkdir(parents=True, exist_ok=True)
            with self._lock:
                data = {str(k): v.to_dict()
                         for k, v in self.partial_results.items()}
            atomic_write_text(self.results_file, json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
        except Exception as e:
            self.on_log(f"⚠️  حفظ المقارنة فشل: {e}")

    # ✅ v24.0 MOD3: دوال عامة آمنة الخيوط
    def clear_result(self, idx: int):
        """يحذف نتيجة مقارنة جزء واحد ويحفظ (thread-safe)."""
        with self._lock:
            removed = self.partial_results.pop(idx, None)
            if removed is not None:
                self._save_results()
        return removed

    def clear_results(self, indices) -> int:
        """يحذف عدة نتائج مقارنة ويحفظ (thread-safe)."""
        with self._lock:
            n = 0
            for idx in indices:
                if self.partial_results.pop(idx, None) is not None:
                    n += 1
            if n:
                self._save_results()
        return n

    def get_result(self, idx: int):
        """يسترجع نتيجة مقارنة جزء (thread-safe)."""
        with self._lock:
            return self.partial_results.get(idx)

    def set_results(self, results_dict: dict):
        """يعيّن النتائج الجزئية (thread-safe) — يُستخدم في AutoLoop."""
        with self._lock:
            self.partial_results = dict(results_dict)

    def _finish_task(self, shard_idx: int):
        """✅ v24.0 MOD4: نقطة إنهاء وحيدة لكل مهمة (نجاح/فشل/توقف)."""
        with self._active_lock:
            if shard_idx in self._finished_task_ids:
                return
            self._finished_task_ids.add(shard_idx)
            self._active_tasks = max(0, self._active_tasks - 1)

    def start(self):
        if self._running:
            return
        self._running = True
        max_workers = self.parallel_workers
        self._executor = ThreadPoolExecutor(
            max_workers=max_workers, thread_name_prefix="CompareWorker")
        self._dispatcher_thread = threading.Thread(
            target=self._dispatcher_loop, daemon=True,
            name="CompareDispatcher")
        self._dispatcher_thread.start()
        self.on_log(f"🔍 المقارن المتوازي بدأ (عمال: {max_workers})")

    def submit(self, shard: PDFShard, extracted_text: str,
                api_key_hint: Optional[str], file_uri_hint: Optional[str],
                force: bool = False, with_repair: bool = False):
        if force:
            with self._lock:
                old = self.partial_results.pop(shard.idx, None)
                if old is not None:
                    self._save_results()
                    self.on_log(f"🗑️  [cache] نُسفت مقارنة جزء {shard.idx} القديمة (force)")
        if not force and shard.idx in self.partial_results and \
           self.partial_results[shard.idx].error is None:
            self.on_log(f"⏭️  مقارنة جزء {shard.idx} موجودة سابقاً")
            try:
                try:
                    setattr(self.partial_results[shard.idx], "book_stem", self.book_stem)
                except Exception:
                    pass
                self.on_partial_result(self.partial_results[shard.idx])
            except Exception:
                pass
            return
        with self._active_lock:
            self._attempt_counts[shard.idx] = 0
            self._finished_task_ids.discard(shard.idx)
            self._active_tasks += 1
        task = {
            "shard": shard,
            "text": extracted_text,
            "api_key_hint": api_key_hint,
            "file_uri_hint": file_uri_hint,
            "is_retry": False,
            "force_prompt": False,
            "with_repair": bool(with_repair),
        }
        if file_uri_hint and api_key_hint:
            self._task_file_uris.setdefault(shard.idx, {})[api_key_hint] = file_uri_hint
        self._task_queue.put(task)
        self.on_log(f"📋 جزء {shard.idx} أُضيف لطابور المقارنة "
                     f"(الطابور: {self._task_queue.qsize()})")

    def _resubmit_retry(self, task: dict, reason: str, use_force_prompt: bool = False):
        # ✅ v10.22: لا استسلام — الجزء يُعاد إرساله حتى ينجح أو يضغط المستخدم «إيقاف».
        shard = task["shard"]
        is_quota = str(reason).startswith("quota")
        with self._active_lock:
            n = self._attempt_counts.get(shard.idx, 0)
            if not is_quota:      # حظر الكوتة لا يُحسب محاولة فاشلة؛ الموزّع ينتظر مفتاحاً متاحاً
                n += 1
                self._attempt_counts[shard.idx] = n
        wait = 2.0 if is_quota else min(COMPARE_RETRY_BASE_WAIT * max(1, n), COMPARE_RETRY_MAX_WAIT)
        self.on_log(f"🔄 جزء {shard.idx}: إعادة محاولة (#{n + 1}) بعد {wait:g}s — السبب: {reason}")
        task["is_retry"] = True
        if use_force_prompt:
            task["force_prompt"] = True

        def _delayed_resubmit():
            try:
                interruptible_sleep(wait, self.stop_event)
                if not self.stop_event.is_set() and self._running:
                    self._task_queue.put(task)
                else:
                    self._finish_task(shard.idx)
            except InterruptedError:
                self._finish_task(shard.idx)

        t = threading.Thread(target=_delayed_resubmit, daemon=True,
                              name=f"CompareRetry-{shard.idx}")
        t.start()

    def _dispatcher_loop(self):
        while self._running and not self.stop_event.is_set():
            try:
                task = self._task_queue.get(timeout=0.5)
            except queue.Empty:
                continue
            if task is None:
                break
            if self.stop_event.is_set():
                self._finish_task(task['shard'].idx)
                break
            # ✅ v10.21: كان الانتظار هنا صامتاً حتى 600ث (لا لوج ولا طلبات) —
            # الآن ننتظر على شرائح 2ث ونكتب سبب التوقف كل 30ث.
            api_key = None
            _wait_t0 = time.time()
            _last_note = 0.0
            while self._running and not self.stop_event.is_set():
                try:
                    api_key = self._acquire_available_key(
                        timeout=2.0, preferred_key=task.get("api_key_hint"))
                except InterruptedError:
                    api_key = None
                if api_key is not None:
                    break
                _now = time.time()
                if _now - _last_note >= COMPARE_NO_KEY_LOG_EVERY_SEC:
                    _last_note = _now
                    try:
                        self._log_no_key_status(task, _now - _wait_t0)
                    except Exception:
                        pass
            if api_key is None:
                self._finish_task(task['shard'].idx)
                break
            task["api_key"] = api_key
            try:
                fut = self._executor.submit(self._compare_one_shard_safe, task)
                with self._lock:
                    self._pending_futures.append(fut)
                fut.add_done_callback(lambda f, k=api_key: self._release_key(k))
            except Exception as e:
                self.on_log(f"💥 فشل إرسال مهمة للـ executor: {e}")
                self._release_key(api_key)
                self._resubmit_retry(task, f"executor: {e}")
        if self.stop_event.is_set() or not self._running:
            self.on_log("⏹️ موزّع المقارنة أُوقف.")
        else:
            self.on_log("✅ موزّع المقارنة أنهى الطابور بنجاح.")

    def stall_info(self) -> Tuple[int, int, float]:
        """✅ v10.21: (المفاتيح المتاحة، إجمالي المفاتيح، أقرب فك حظر بالثواني) لنموذج المقارنة."""
        mgr = self.global_key_mgr
        avail = mgr.get_available_keys_for_model(self.api_keys, self.model_id)
        wait = 0.0 if avail else mgr.secs_until_any_available(self.api_keys, self.model_id)
        return len(avail), len(self.api_keys), wait

    def compared_ok_indices(self) -> Set[int]:
        """✅ v10.21: أجزاء لها نتيجة مقارنة سليمة (بلا خطأ)."""
        with self._lock:
            return {i for i, r in self.partial_results.items()
                    if r.error is None or r.error == "النص المستخرج فارغ"}

    def _log_no_key_status(self, task: dict, waited: float):
        n_avail, total, wait = self.stall_info()
        idx = task["shard"].idx
        if n_avail == 0:
            self.on_log(
                f"⏸️ المقارنة واقفة: كل مفاتيح المقارنة ({total}) محظورة لنموذج "
                f"{self.model_id} فلا يُرسل أي طلب. أقرب فك حظر بعد {fmt_duration(wait)} "
                f"(جزء {idx} وغيره في الانتظار).")
        else:
            try:
                with self.global_key_mgr._lock:
                    busy = len(self.global_key_mgr._busy.get(self.model_id, ()))
            except Exception:
                busy = -1
            self.on_log(
                f"⏳ المقارنة تنتظر مفتاحاً حراً لنموذج {self.model_id}: متاح {n_avail}/{total} "
                f"(مشغول {busy}) — جزء {idx} ينتظر منذ {fmt_duration(waited)}")

    def _acquire_available_key(self, timeout: float = 600,
                               preferred_key: Optional[str] = None) -> Optional[str]:
        return self.global_key_mgr.acquire_key(
            self.api_keys, self.model_id,
            preferred_key=preferred_key, timeout=timeout,
            stop_event=self.stop_event)

    def _release_key(self, api_key: str):
        self.global_key_mgr.release_key(api_key, self.model_id)

    def _compare_one_shard_safe(self, task: dict):
        try:
            self._compare_one_shard(task)
        except Exception as e:
            self.on_log(f"💥 خطأ في مقارنة جزء: {e}\n{traceback.format_exc()}")
            self._resubmit_retry(task, f"exception: {e}")

    def _compare_one_shard(self, task: dict):
        shard: PDFShard = task["shard"]
        text: str = task["text"]
        api_key: str = task["api_key"]
        use_force_prompt: bool = task.get("force_prompt", False)

        compare_custom_txt = bool(shard.is_txt and str(self.cfg.get("active_prompt_kind", "")) == "custom"
                                  and self.cfg.get("custom_compare_enabled", True)
                                  and str(self.cfg.get("custom_compare_prompt", "")).strip())
        if shard.is_txt and not compare_custom_txt:
            self.on_log(f"⏭️  جزء TXT {shard.idx}: المقارنة لا تنطبق إلا مع البرومبت المخصص وبرومبت مقارنة مفعّل")
            self._finish_task(shard.idx)
            return

        masked = api_key[:6] + "..." + api_key[-4:] if len(api_key) > 10 else "****"
        t0 = time.time()
        attempt_num = self._attempt_counts.get(shard.idx, 0) + 1
        retry_label = f" (محاولة {attempt_num})" if task.get("is_retry") else ""
        force_label = " [إجباري]" if use_force_prompt else ""
        unit_lbl = "كلمات" if shard.is_txt else "صفحات"
        self.on_log(f"🔬 مقارنة جزء {shard.idx} ({unit_lbl} "
                     f"{shard.page_start}-{shard.page_end}) "
                     f"بمفتاح {masked}{retry_label}{force_label}...")

        result = ShardComparisonResult(
            shard_idx=shard.idx,
            page_start=shard.page_start,
            page_end=shard.page_end,
            used_model=self.model_id,
            used_key=masked,
            attempts=attempt_num)

        max_chars = self.cfg.get("compare_max_input_chars", 200_000)
        if len(text) > max_chars:
            text = text[:max_chars] + "\n\n[...اقتُطع للمقارنة...]"

        # ✅ v24.0 MOD6.4: تحقق من النص الفارغ قبل الإرسال
        if not text.strip():
            self.on_log(f"⚠️  جزء {shard.idx}: النص المستخرج فارغ — تُسجَّل كتغطية 0%")
            result.coverage_pct = 0
            result.assessment = "ضعيف"
            result.error = "النص المستخرج فارغ"
            result.elapsed_sec = time.time() - t0
            with self._lock:
                self.partial_results[shard.idx] = result
                self._save_results()
            try:
                try:
                    setattr(result, "book_stem", self.book_stem)
                except Exception:
                    pass
                self.on_partial_result(result)
            except Exception:
                pass
            self._finish_task(shard.idx)
            return

        try:
            if not wait_for_network_if_needed(self.cfg, self.stop_event, self.on_log, self._network_state):
                raise InterruptedError("توقف")
            # ✅ OPT9: إعادة استخدام العميل المخزّن
            if api_key in self._client_cache:
                client = self._client_cache[api_key]
            else:
                client = genai.Client(api_key=api_key, http_options=types.HttpOptions(timeout=GENAI_HTTP_TIMEOUT_MS))
                self._client_cache[api_key] = client
                try:
                    register_stop_component("clients", client)
                except Exception:
                    pass

            uploader = ShardUploader(shard)
            file_uri = None
            with self._lock:
                cache = self._upload_cache.setdefault(api_key, {})
                # ✅ OPT1: جرّب أي URI مخزّن لهذا الجزء (من أي مفتاح)
                all_uris_for_shard = self._task_file_uris.get(shard.idx, {})
                hinted_uri = all_uris_for_shard.get(api_key)
            local_ks = KeyState(key=api_key, masked=masked, uploaded_shards=cache)
            try:
                # أولاً: جرّب URI المطابق لنفس المفتاح
                if hinted_uri:
                    file_uri = hinted_uri
                else:
                    # ثانياً: جرّب أي URI من مفتاح آخر (الملفات مشتركة عادة بين مفاتيح نفس المشروع)
                    reused = False
                    for other_key, other_uri in all_uris_for_shard.items():
                        if other_uri and other_key != api_key:
                            try:
                                f_check = client.files.get(name=other_uri.split("/")[-1] if "/" in other_uri else other_uri)
                                if hasattr(f_check, 'state') and f_check.state.name == "ACTIVE":
                                    file_uri = other_uri
                                    reused = True
                                    self.on_log(f"♻️  [compare] إعادة استخدام URI مرفوع لجزء {shard.idx}")
                                    break
                            except Exception:
                                pass
                    if not reused:
                        f = uploader.get_or_upload(
                            client, local_ks,
                            lambda m: self.on_log(m),
                            self.stop_event, None,
                            force_fresh=False)
                        file_uri = f.uri
                with self._lock:
                    self._task_file_uris.setdefault(shard.idx, {})[api_key] = file_uri
            except Exception as e:
                if is_quota_error(e):
                    kind, delay = parse_429(e)
                    self.global_key_mgr.mark_blocked(
                        api_key, self.model_id, kind, delay, self.cfg)
                    self.on_log(f"📛 مفتاح {masked} مع {self.model_id}: كوتة "
                                  f"({kind.value}) — حُظر مع هذا النموذج فقط.")
                    self._resubmit_retry(task, f"quota_upload({kind.value})")
                    return
                else:
                    self.on_log(f"⚠️  جزء {shard.idx}: فشل رفع — {e}")
                    self._resubmit_retry(task, f"upload: {e}")
                    return

            if use_force_prompt:
                user_prompt = (
                    f"⚠️ **تعليمات إجبارية**: أنت أداة تدقيق تقنية بحتة.\n"
                    f"الجزء يقابل {('كلمات' if shard.is_txt else 'صفحات')} {shard.page_start}-{shard.page_end} من {('الملف النصي الأصلي' if shard.is_txt else 'الكتاب')}.\n\n"
                    f"النص المستخرج:\n"
                    f"━━━━━━━━━ بداية ━━━━━━━━━\n"
                    f"{text}\n"
                    f"━━━━━━━━━ نهاية ━━━━━━━━━\n\n"
                    f"📌 قارن **بنداً ببند، فقرة بفقرة** وأخرج JSON فقط.\n"
                    f"📌 **لا تكتفِ بادعاء التطابق** — اقرأ الأصل المرفق كاملاً واقرأ الناتج كاملاً.\n"
                    f"📌 سجّل أي فقرة/جملة من الأصل غير موجودة أو غير محققة في الناتج.\n"
                    f"📌 **ممنوع** الرفض أو التعليق. واجعل الملاحظات بالعربية فقط."
                )
            else:
                user_prompt = (
                    f"الجزء يقابل {('كلمات' if shard.is_txt else 'صفحات')} {shard.page_start}-{shard.page_end} من {('الملف النصي الأصلي' if shard.is_txt else 'الكتاب')}.\n\n"
                    f"النص المستخرج:\n"
                    f"━━━━━━━━━ بداية ━━━━━━━━━\n"
                    f"{text}\n"
                    f"━━━━━━━━━ نهاية ━━━━━━━━━\n\n"
                    f"📌 قارن **بنداً ببند** بين الأصل المرفق والناتج.\n"
                    f"📌 **لا تفترض التطابق** — تحقق فعلياً من كل فقرة.\n"
                    f"📌 أخرج JSON فقط حسب system instructions، واجعل الملاحظات بالعربية فقط."
                )

            contents = [
                types.Content(role="user", parts=[
                    types.Part(file_data=types.FileData(
                        mime_type=("text/plain" if shard.is_txt else "application/pdf"), file_uri=file_uri)),
                    types.Part.from_text(text=user_prompt),
                ])
            ]
            # ✅ v28.0: برومبت المقارنة مرتبط بوضع الاستخراج + خيار الإصلاح
            with_repair = bool(task.get("with_repair", False) or self.cfg.get("recompare_with_repair", False))
            compare_prompt = resolve_compare_system_prompt(self.cfg, with_repair=with_repair)
            cfg_kwargs = dict(
                temperature=self.cfg.get("compare_temperature", 0.2),
                max_output_tokens=self.cfg.get("compare_max_tokens", 8000),
                system_instruction=[types.Part.from_text(text=compare_prompt)],
                response_mime_type="application/json")
            th = build_thinking_config(self.model_family, self.cfg)
            if th is not None:
                cfg_kwargs["thinking_config"] = th
            gen_cfg = types.GenerateContentConfig(**cfg_kwargs)

            if self.stop_event.is_set():
                raise InterruptedError("توقف")

            if not wait_for_network_if_needed(self.cfg, self.stop_event, self.on_log, self._network_state):
                raise InterruptedError("توقف")
            # ✅ v25.1: تسجيل طلب المقارنة
            if self.request_counter:
                n = self.request_counter.increment(f"مقارنة جزء {shard.idx}")
                self.on_log(f"🔁 طلب رقم {n} أُرسل (مقارنة جزء {shard.idx})")
            throttle_key_send(api_key, self.stop_event, self.on_log)  # ✅ v10.15
            resp = client.models.generate_content(
                model=self.model_id, contents=contents, config=gen_cfg)
            raw = (resp.text or "").strip()

            if not raw or is_model_refusal(raw):
                self.on_log(f"⚠️  جزء {shard.idx}: النموذج رفض/استجابة فارغة "
                              f"(المفتاح {masked} يبقى نشطاً)")
                self._resubmit_retry(task, "model_refusal", use_force_prompt=True)
                return

            data = parse_compare_response_json(raw)

            # ✅ v3.18: بعض برومبتات المقارنة المخصصة ترجع كل التقييم داخل كائن assessment
            # مثل: {"assessment": {"coverage_pct":100, "notes":"...", ...}}.
            # وحينها كان البرنامج يعرض assessment كقاموس ويترك coverage=0.
            nested = data.get("assessment")
            if isinstance(nested, dict):
                for k in ("coverage_pct", "missing_items", "notes", "shard_assessment"):
                    if k not in data and k in nested:
                        data[k] = nested.get(k)
                if "shard_assessment" not in data:
                    cov_tmp = int(data.get("coverage_pct", 0) or 0)
                    data["shard_assessment"] = "ممتاز" if cov_tmp >= 95 else "جيد" if cov_tmp >= 80 else "متوسط" if cov_tmp >= 60 else "ضعيف"
            assessment_value = data.get("shard_assessment") or data.get("assessment") or "—"
            if isinstance(assessment_value, dict):
                cov_tmp = int(data.get("coverage_pct", 0) or 0)
                assessment_value = "ممتاز" if cov_tmp >= 95 else "جيد" if cov_tmp >= 80 else "متوسط" if cov_tmp >= 60 else "ضعيف"

            result.assessment = str(assessment_value)
            result.coverage_pct = int(data.get("coverage_pct", 0) or 0)
            result.missing_items = data.get("missing_items", []) or []
            result.notes = str(data.get("notes", ""))
            result.elapsed_sec = time.time() - t0

            # ✅ v28.0: إن وُجد نص مُصلَح من وضع المقارنة+الإصلاح احفظه وأعد المقارنة
            repaired_flag = bool(data.get("repaired", False))
            repaired_text = str(data.get("repaired_text", "") or "").strip()
            with_repair = bool(task.get("with_repair", False) or self.cfg.get("recompare_with_repair", False))
            if with_repair and repaired_flag and repaired_text and count_words(repaired_text) >= 10:
                try:
                    # احفظ النص المُصلَح مكان الجزء
                    part_path = get_book_parts_dir(self.output_dir, self.book_stem) / f"{self.book_stem}_part_{shard.idx:04d}.txt"
                    atomic_write_text(part_path, repaired_text, encoding="utf-8")
                    self.on_log(f"🛠️  جزء {shard.idx}: حُفظ النص المُصلَح ({count_words(repaired_text):,} كلمة) — إعادة مقارنة...")
                    # إعادة مقارنة بدون إصلاح لتجنب حلقة لا نهائية
                    task_re = dict(task)
                    task_re["text"] = repaired_text
                    task_re["with_repair"] = False
                    task_re["is_retry"] = False
                    task_re["force_prompt"] = False
                    task_re["api_key"] = api_key
                    # سجّل نتيجة أولية ثم أعد الإرسال
                    note_extra = (result.notes + " | " if result.notes else "") + "أُصلح النص وأُعيدت المقارنة"
                    result.notes = note_extra
                    with self._lock:
                        self.partial_results[shard.idx] = result
                        self._save_results()
                    try:
                        setattr(result, "book_stem", self.book_stem)
                    except Exception:
                        pass
                    try:
                        self.on_partial_result(result)
                    except Exception:
                        pass
                    # أعد المقارنة بالنص المُصلَح
                    with self._active_lock:
                        self._finished_task_ids.discard(shard.idx)
                        # لا ننقص active_tasks — المهمة مستمرة
                    self._task_queue.put({
                        "shard": shard,
                        "text": repaired_text,
                        "api_key_hint": api_key,
                        "file_uri_hint": file_uri,
                        "is_retry": False,
                        "force_prompt": False,
                        "with_repair": False,
                    })
                    # لا ننهي المهمة الآن
                    return
                except Exception as e_fix:
                    self.on_log(f"⚠️  جزء {shard.idx}: فشل حفظ النص المُصلَح: {e_fix}")

            self.on_log(f"✅ مقارنة جزء {shard.idx}: {result.assessment} "
                         f"({result.coverage_pct}%, {len(result.missing_items)} فجوة, "
                         f"{result.elapsed_sec:.1f}s)")

            with self._lock:
                self.partial_results[shard.idx] = result
                self._save_results()
            try:
                try:
                    setattr(result, "book_stem", self.book_stem)
                except Exception:
                    pass
                self.on_partial_result(result)
            except Exception:
                pass
            self._finish_task(shard.idx)
            return

        except InterruptedError:
            result.error = "توقف"
            self.on_log(f"⛔ مقارنة جزء {shard.idx} أُلغيت")
            with self._lock:
                self.partial_results[shard.idx] = result
                self._save_results()
            try:
                try:
                    setattr(result, "book_stem", self.book_stem)
                except Exception:
                    pass
                self.on_partial_result(result)
            except Exception:
                pass
            self._finish_task(shard.idx)
            return
        except Exception as e:
            if is_quota_error(e):
                kind, delay = parse_429(e)
                self.global_key_mgr.mark_blocked(
                    api_key, self.model_id, kind, delay, self.cfg)
                self.on_log(f"📛 مفتاح {masked} مع {self.model_id}: "
                              f"كوتة حقيقية ({kind.value}) — حُظر لهذا النموذج فقط")
                self._resubmit_retry(task, f"quota({kind.value})")
                return
            self.on_log(f"⚠️  جزء {shard.idx}: خطأ في المقارنة — {e} "
                          f"(المفتاح {masked} يبقى نشطاً)")
            self._resubmit_retry(task, f"error: {str(e)[:100]}", use_force_prompt=True)
            return

    def wait_until_done(self, timeout: Optional[float] = None) -> bool:
        """✅ v10.22: ينتظر بلا مهلة (المعامل timeout يُتجاهل للتوافق) حتى تنتهي كل المهام أو يُضغط «إيقاف».
        المقارنة تستمر في إرسال الطلبات (وتنتظر فك حظر المفاتيح) ولا يُنهى الانتظار بسبب الوقت."""
        self.stall_reason = None
        while True:
            if self.stop_event.is_set():
                return False
            with self._active_lock:
                active = self._active_tasks
            if active <= 0 and self._task_queue.empty():
                with self._lock:
                    pending = [f for f in self._pending_futures if not f.done()]
                    self._pending_futures = pending
                if not pending:
                    return True
            try:
                interruptible_sleep(0.2, self.stop_event)
            except InterruptedError:
                return False

    def run_until_all_compared(self, shards, get_text) -> bool:
        """✅ v10.22: يضمن مقارنة كل الأجزاء: ينتظر الطابور، ثم يفحص الأجزاء بلا نتيجة سليمة
        ويعيد إرسالها، ويكرر حتى لا يبقى جزء أو يُضغط «إيقاف». يرجع True فقط عند اكتمال الكل."""
        def _needs_compare(sh):
            if not sh.is_txt:
                return True
            return bool(str(self.cfg.get("active_prompt_kind", "")) == "custom"
                        and self.cfg.get("custom_compare_enabled", True)
                        and str(self.cfg.get("custom_compare_prompt", "")).strip())
        required = [sh for sh in shards if _needs_compare(sh)]
        while not self.stop_event.is_set():
            if not self.wait_until_done():
                return False
            done = self.compared_ok_indices()
            missing = [sh for sh in required if sh.idx not in done]
            if not missing:
                return True
            self.on_log(f"🔁 {len(missing)} جزء بلا مقارنة سليمة بعد — إعادة إرسالها "
                        f"({[m.idx for m in missing][:15]}{'...' if len(missing) > 15 else ''})")
            for sh in missing:
                try:
                    txt = get_text(sh)
                except Exception as e:
                    self.on_log(f"⚠️  تعذر قراءة نص جزء {sh.idx} للمقارنة: {e}")
                    continue
                self.submit(sh, txt, None, None, force=False)
            try:
                interruptible_sleep(2.0, self.stop_event)
            except InterruptedError:
                return False
        return False

    def stop(self, wait: bool = True):
        self._running = False
        try:
            self._task_queue.put(None)
        except Exception:
            pass
        if self._executor:
            try:
                if wait:
                    self._executor.shutdown(wait=True, cancel_futures=False)
                else:
                    self._executor.shutdown(wait=False, cancel_futures=True)
            except Exception:
                pass
            self._executor = None
        if self._dispatcher_thread:
            try:
                self._dispatcher_thread.join(timeout=5)
            except Exception:
                pass
        if wait or self.stop_event.is_set():
            clients = list(self._client_cache.values())
            self._client_cache.clear()
            for client in clients:
                try:
                    unregister_stop_component("clients", client)
                except Exception:
                    pass
                try:
                    if hasattr(client, "close"):
                        client.close()
                    elif getattr(client, "_transport", None) is not None:
                        client._transport.close()
                except Exception:
                    pass

    def generate_final_report(self, total_shards: int) -> Optional[dict]:
        with self._lock:
            results = sorted(self.partial_results.values(),
                              key=lambda r: r.shard_idx)
        if not results:
            return None

        total_missing = sum(len(r.missing_items) for r in results)
        critical = sum(1 for r in results for m in r.missing_items
                        if m.get("severity") == "خطير")
        medium = sum(1 for r in results for m in r.missing_items
                      if m.get("severity") == "متوسط")
        minor = sum(1 for r in results for m in r.missing_items
                     if m.get("severity") == "بسيط")
        # ✅ v29.0: متوسط التغطية من المُقارَن الناجح فقط + not_compared_count مستقل
        compared_ok = [r for r in results if r.error is None and isinstance(r.coverage_pct, (int, float))]
        compared_indices = {r.shard_idx for r in compared_ok}
        not_compared_count = max(0, int(total_shards) - len(compared_indices))
        coverages = [max(0, min(100, int(r.coverage_pct))) for r in compared_ok]
        # ✅ v29.0: لا نضيف أصفار للأجزاء غير المقارنة
        avg_coverage = int(sum(coverages) / len(coverages)) if coverages else 0
        worst = sorted([r for r in results if r.error is None],
                        key=lambda r: r.coverage_pct)[:3]
        worst_idx = [r.shard_idx for r in worst]

        local_summary = {
            "overall_assessment": self._assess_overall(avg_coverage, critical),
            "coverage_estimate_pct": avg_coverage,
            "not_compared_count": not_compared_count,
            "total_missing_items": total_missing,
            "critical_count": critical,
            "medium_count": medium,
            "minor_count": minor,
            "summary": (f"تمت مقارنة {len(results)}/{total_shards} جزء. "
                         f"متوسط التغطية {avg_coverage}%. "
                         f"إجمالي الفجوات {total_missing} "
                         f"(خطير: {critical}, متوسط: {medium}, بسيط: {minor})."),
            "recommendations": self._build_recommendations(critical, medium, worst_idx),
            "worst_shards": worst_idx,
            "_compared_shards": len(results),
            "_total_shards": total_shards,
        }

        # ✅ OPT2: تخطي تلخيص AI إذا فجوات قليلة (توفير طلبات)
        # التلخيص AI مفيد فقط عند وجود فجوات كثيرة (≥3) أو تغطية منخفضة
        if total_missing >= 3 and avg_coverage < 95 and len(results) >= 2:
            try:
                deeper = self._ask_ai_for_synthesis(results)
                if deeper:
                    local_summary["summary"] = deeper.get(
                        "summary", local_summary["summary"])
                    local_summary["recommendations"] = deeper.get(
                        "recommendations", local_summary["recommendations"])
                    if deeper.get("overall_assessment"):
                        local_summary["overall_assessment"] = deeper["overall_assessment"]
            except Exception as e:
                self.on_log(f"⚠️  تلخيص AI فشل (استخدام المحلي): {e}")

        try:
            final_path = self.compare_dir / "final.json"
            final_path.write_text(
                json.dumps(local_summary, ensure_ascii=False, indent=2),
                encoding="utf-8")
            self.on_log(f"💾 تقرير شامل محفوظ: {final_path.name}")
            try:
                report_path = self.compare_dir / "report.txt"
                report_lines = [
                    "التقييم: " + local_summary["overall_assessment"],
                    "متوسط التغطية: " + str(local_summary["coverage_estimate_pct"]) + "%",
                    "إجمالي الفجوات: " + str(local_summary["total_missing_items"]),
                    "خطير: " + str(local_summary["critical_count"]),
                    "متوسط: " + str(local_summary["medium_count"]),
                    "بسيط: " + str(local_summary["minor_count"]),
                    "",
                    "الملخص:",
                    local_summary["summary"],
                    "",
                    "التوصيات:",
                    local_summary["recommendations"],
                ]
                report_path.write_text("\n".join(report_lines), encoding="utf-8")
                self.on_log(f"💾 تقرير للقراءة محفوظ: {report_path.name}")
            except Exception as e:
                self.on_log(f"⚠️  حفظ تقرير نصي فشل: {e}")
        except Exception as e:
            self.on_log(f"⚠️  حفظ تقرير شامل فشل: {e}")

        return local_summary

    def _assess_overall(self, avg_coverage: int, critical: int) -> str:
        if critical >= 5 or avg_coverage < 60: return "ضعيف"
        if critical >= 2 or avg_coverage < 80: return "متوسط"
        if avg_coverage < 95: return "جيد"
        return "ممتاز"

    def _build_recommendations(self, critical, medium, worst):
        recs = []
        if critical > 0:
            recs.append(f"⚠️ مراجعة فورية للأجزاء الخطيرة ({critical} فجوة).")
        if medium > 0:
            recs.append(f"📌 مراجعة الفجوات المتوسطة ({medium}).")
        if worst:
            recs.append(f"🔍 ركّز على الأجزاء الأقل تغطية: {worst}.")
        if not recs:
            recs.append("✅ النتائج ممتازة — لا توصيات حرجة.")
        return " ".join(recs)

    def _ask_ai_for_synthesis(self, results: List[ShardComparisonResult]
                                  ) -> Optional[dict]:
        partials_payload = []
        for r in results[:50]:
            partials_payload.append({
                "shard": r.shard_idx,
                "pages": f"{r.page_start}-{r.page_end}",
                "assessment": r.assessment,
                "coverage": r.coverage_pct,
                "missing_count": len(r.missing_items),
                "top_missing": [m.get("snippet", "")[:120]
                                  for m in r.missing_items[:3]],
                "notes": r.notes[:200],
            })

        user_prompt = (
            f"إليك تقارير جزئية ({len(results)} جزء):\n\n"
            f"{json.dumps(partials_payload, ensure_ascii=False, indent=2)}\n\n"
            f"لخّص في تقرير شامل (JSON فقط)."
        )

        avail = self.global_key_mgr.get_available_keys_for_model(
            self.api_keys, self.model_id)
        # ✅ v25.0-HF: حد أقصى 2 مفتاح للتلخيص (بدل كل المفاتيح!)
        for api_key in avail[:2]:
            if self.stop_event.is_set(): return None
            client = None
            try:
                client = genai.Client(api_key=api_key, http_options=types.HttpOptions(timeout=GENAI_HTTP_TIMEOUT_MS))
                try:
                    register_stop_component("clients", client)
                except Exception:
                    pass
                cfg_kwargs = dict(
                    temperature=0.3,
                    max_output_tokens=4000,
                    system_instruction=[types.Part.from_text(
                        text=COMPARE_FINAL_REPORT_PROMPT)],
                    response_mime_type="application/json")
                th = build_thinking_config(self.model_family, self.cfg)
                if th is not None:
                    cfg_kwargs["thinking_config"] = th
                gen_cfg = types.GenerateContentConfig(**cfg_kwargs)
                # ✅ v25.1: تسجيل طلب التلخيص
                if self.request_counter:
                    n = self.request_counter.increment("تلخيص شامل")
                    self.on_log(f"🔁 طلب رقم {n} أُرسل (تلخيص شامل)")
                throttle_key_send(api_key, self.stop_event, self.on_log)  # ✅ v10.15
                resp = client.models.generate_content(
                    model=self.model_id,
                    contents=[types.Content(role="user", parts=[
                        types.Part.from_text(text=user_prompt)])],
                    config=gen_cfg)
                raw = (resp.text or "").strip()
                if not raw or is_model_refusal(raw):
                    continue
                if raw.startswith("```"):
                    raw = re.sub(r"^```(?:json)?\s*", "", raw)
                    raw = re.sub(r"\s*```\s*$", "", raw)
                return json.loads(raw)
            except Exception as e:
                if is_quota_error(e):
                    kind, delay = parse_429(e)
                    self.global_key_mgr.mark_blocked(
                        api_key, self.model_id, kind, delay, self.cfg)
                    continue
                # ✅ v25.0-HF: خطأ غير كوتة → توقف (لا تجرب مفاتيح أخرى)
                self.on_log(f"⚠️  تلخيص AI فشل: {e}")
                break
            finally:
                if client is not None:
                    try:
                        unregister_stop_component("clients", client)
                    except Exception:
                        pass
                    try:
                        if hasattr(client, "close"):
                            client.close()
                        elif getattr(client, "_transport", None) is not None:
                            client._transport.close()
                    except Exception:
                        pass
        return None


# ═══════════════════════════════════════════════════════════════════
#  Runtime Context
# ═══════════════════════════════════════════════════════════════════

class ShardRuntimeContext:
    def __init__(self, pool: KeyPool, model_id: str, log,
                  global_key_mgr: GlobalKeyManager,
                  all_keys: List[str],
                  on_upload_progress: Callable[[int], None] = None,
                  txt_context_mgr: Optional[TxtContextManager] = None,
                  preferred_key: Optional[str] = None):
        self.pool = pool
        self.model_id = model_id
        self.log = log
        self.global_key_mgr = global_key_mgr
        self.all_keys = list(all_keys)
        self.on_upload_progress = on_upload_progress
        self.txt_context_mgr = txt_context_mgr
        self.preferred_key = preferred_key
        self.key_state: Optional[KeyState] = None
        self.client: Optional[genai.Client] = None
        self._leased_key: Optional[str] = None
        self._local_bans: Dict[str, float] = {}
        self._503_count: int = 0  # ✅ v25.5 FIX: عدّاد 503 محلي (بدل متغير دالة مشترك)

    def _release_current_key(self):
        if self._leased_key:
            try:
                self.global_key_mgr.release_key(self._leased_key, self.model_id)
            except Exception:
                pass
            self._leased_key = None
        # لا تحتفظ بسجل عالمي بعملاء انتهى دورهم: كان كل جزء يترك Client
        # جديداً مسجلاً حتى ضغط الإيقاف، ما يراكم الذاكرة ويبطئ الإغلاق.
        client = self.client
        self.client = None
        if client is not None:
            try:
                unregister_stop_component("clients", client)
            except Exception:
                pass
            try:
                if hasattr(client, "close"):
                    client.close()
                elif getattr(client, "_transport", None) is not None:
                    client._transport.close()
            except Exception:
                pass

    def _cleanup_local_bans(self):
        now = time.time()
        for key in list(self._local_bans.keys()):
            if self._local_bans[key] <= now:
                self._local_bans.pop(key, None)

    def ban_current_key(self, seconds: float = 120.0):
        if self.key_state is not None:
            self._local_bans[self.key_state.key] = time.time() + max(1.0, seconds)

    def acquire_key(self, stop_event: Optional[threading.Event] = None, timeout: float = 30.0) -> bool:
        if (self.key_state and self.client and self._leased_key == self.key_state.key and
                self.key_state.is_available_for_model(self.model_id)):
            return True

        self._release_current_key()
        self._cleanup_local_bans()
        avoid_keys = {k for k, until in self._local_bans.items() if until > time.time()}
        preferred_key = self.preferred_key if self.preferred_key not in avoid_keys else None
        leased = self.global_key_mgr.acquire_key(
            self.all_keys, self.model_id,
            preferred_key=preferred_key,
            timeout=timeout, stop_event=stop_event,
            avoid_keys=avoid_keys)
        if leased is None:
            return False
        ks = self.pool.states.get(leased)
        if ks is None or not ks.is_available_for_model(self.model_id):
            self.global_key_mgr.release_key(leased, self.model_id)
            return False
        self._leased_key = leased
        self.key_state = ks
        self.log(f"🔑 المفتاح النشط: {ks.masked} "
                  f"(نجاحات={ks.success_count}, إخفاقات={ks.fail_count})")
        self.client = genai.Client(api_key=ks.key, http_options=types.HttpOptions(timeout=GENAI_HTTP_TIMEOUT_MS))
        try:
            register_stop_component("clients", self.client)
        except Exception:
            pass
        return True

    def upload_shard(self, shard: PDFShard,
                       stop_event: threading.Event,
                       force_fresh: bool = False,
                       last_file_name: Optional[str] = None) -> types.File:
        """رفع الجزء مع محاولة إعادة استخدام ملف مرفوع سابقاً بمفتاح آخر."""
        # ✅ OPT-QUOTA: جرّب الملف المرفوع سابقاً مع المفتاح الجديد
        if not force_fresh and last_file_name and self.client:
            try:
                f = self.client.files.get(name=last_file_name)
                if f.state.name == "ACTIVE":
                    self.log(f"♻️  إعادة استخدام ملف مرفوع سابقاً بمفتاح آخر: جزء {shard.idx}")
                    self.key_state.uploaded_shards[shard.shard_md5] = last_file_name
                    return f
            except Exception:
                pass  # الملف غير متاح مع هذا المفتاح — نرفع من جديد
        uploader = ShardUploader(shard)
        return uploader.get_or_upload(
            self.client, self.key_state, self.log,
            stop_event, self.on_upload_progress,
            force_fresh=force_fresh)

    def get_txt_context(self, stop_event: threading.Event,
                          force_fresh: bool = False) -> Optional[types.File]:
        if not self.txt_context_mgr:
            return None
        return self.txt_context_mgr.get_or_upload(
            self.client, self.key_state.key, stop_event, force_fresh=force_fresh)

    def rotate_due_to_quota(self, exc, stop_event: Optional[threading.Event] = None) -> bool:
        det = parse_429_detail(exc)
        kind, delay = det.kind, det.delay
        self.log(f"📛 كوتة {self.key_state.masked} مع {self.model_id} "
                  f"(نوع={det.metric}: {det.note}) — بقية النماذج تبقى متاحة لهذا المفتاح")

        # ✅ v24.6: كوتة RPM = مشكلة سرعة وليست مشكلة مفتاح — انتظر ولا تبدّل!
        # ✅ v10.14: إصلاح علة min(10,...) — التعليق يقول «65 ثانية على الأقل»
        # والكود كان يعطي 10 ثوانٍ كحد أقصى! + تخفيف الحمل انتظار أقصر.
        if det.metric in ("rpm", "tpm", "shed", "?"):
            wait_rpm = max(delay, 30.0 if det.metric == "shed" else 65.0)
            self.log(f"⏳ كوتة RPM — انتظار {wait_rpm}s بنفس المفتاح (لا تبديل)...")
            self.pool.learn_from_429(self.key_state, self.model_id, exc)
            try:
                self.global_key_mgr.mark_blocked(
                    self.key_state.key, self.model_id, kind, wait_rpm, self.pool.cfg)
            except Exception:
                pass
            try:
                interruptible_sleep(wait_rpm, stop_event)
            except InterruptedError:
                return False
            if stop_event and stop_event.is_set():
                return False
            # نفس المفتاح — لا نحرره ولا نبدّله
            self.log(f"♻️  استئناف بنفس المفتاح {self.key_state.masked} بعد انتظار RPM")
            return True

        # كوتة يومية (RPD) — هنا نبدّل المفتاح فعلاً
        self.log(f"🌙 كوتة يومية — سيُفك الحظر عند منتصف الليل.")
        self.pool.learn_from_429(self.key_state, self.model_id, exc)
        try:
            self.global_key_mgr.mark_blocked(
                self.key_state.key, self.model_id, kind, delay, self.pool.cfg)
        except Exception:
            pass
        self._release_current_key()
        self.key_state = None
        self.client = None
        # انتظر حتى يتوفر مفتاح آخر
        wait_secs = self.global_key_mgr.secs_until_any_available(self.all_keys, self.model_id)
        if wait_secs > 5:
            self.log(f"⏳ انتظار {wait_secs:.0f}s حتى يتوفر مفتاح بديل...")
            try:
                interruptible_sleep(min(wait_secs + 2, 300), stop_event)
            except InterruptedError:
                return False
        if stop_event and stop_event.is_set():
            return False
        return self.acquire_key(stop_event=stop_event)

    def close(self):
        self._release_current_key()
        self.key_state = None
        self.client = None


# ═══════════════════════════════════════════════════════════════════
#  Process Shard
# ═══════════════════════════════════════════════════════════════════

@dataclass
class ProcessShardOutput:
    text: Optional[str]
    file_uri: Optional[str] = None
    used_api_key: Optional[str] = None
    quota_exhausted: bool = False
    failure_reason: str = ""
    retryable: bool = False
    used_model_id: str = ""
    auth_error: bool = False


def extraction_model_candidates(primary_model: dict, cfg: dict) -> List[dict]:
    """النموذج الأساسي، ثم البدائل المختارة فقط إن فُعّل التبديل صراحةً."""
    primary = dict(primary_model or {})
    primary_id = str(primary.get("id") or "")
    if primary_id and not primary.get("family"):
        primary["family"] = detect_model_family(primary_id)
    result = [primary] if primary_id else []
    if not bool((cfg or {}).get("model_failover_enabled", False)):
        return result
    seen = {primary_id}
    for candidate in ((cfg or {}).get("model_failover_models") or []):
        if not isinstance(candidate, dict):
            continue
        item = dict(candidate)
        mid = str(item.get("id") or "")
        if not mid or mid in seen:
            continue
        item.setdefault("family", detect_model_family(mid))
        item.setdefault("label", mid)
        result.append(item)
        seen.add(mid)
    return result


def minimum_extraction_word_count(shard) -> int:
    """حد أدنى متحفظ للناتج، مشترَك مع فحص الأجزاء المحفوظة."""
    units = max(1, int(getattr(shard, "pages_count", 1) or 1))
    return minimum_extraction_word_count_for_units(
        units, bool(getattr(shard, "is_txt", False)))


def process_shard(shard, total_shards, model, ctx, system_prompt, cfg,
                   on_token, on_progress, on_request: Optional[Callable[[str], None]],
                   on_key_used: Optional[Callable[[str], None]],
                   stop_event, log,
                   force_fresh_upload: bool = False,
                   on_attempt_restart: Optional[Callable[[str], None]] = None
                   ) -> ProcessShardOutput:
    accumulated = ""
    max_continuations = max(1, int(cfg.get("max_continuations", 10) or 10))
    estimated_words = max(1, shard.pages_count * 800)
    max_output = max(1, int(cfg.get("max_output_tokens", 65000) or 65000))
    estimated_rounds = max(1, (estimated_words * 2) // max_output) + 1
    max_continuations = min(max_continuations, max(2, estimated_rounds))
    rounds = 0
    last_file_uri = None
    last_api_key = None
    last_file_name = None
    empty_response_streak = 0
    use_force_prompt = False
    file_refresh_attempts = 0
    short_response_retries = 0
    min_output_words = minimum_extraction_word_count(shard)

    valid, validation_note = is_valid_split_input(shard)
    if not valid:
        log(f"⚠️ جزء {shard.idx}: فشل تحقق سلامة الجزء — {validation_note}")
        return ProcessShardOutput(None, failure_reason=f"سلامة الجزء: {validation_note}")

    while rounds <= max_continuations:
        if stop_event.is_set():
            raise InterruptedError("توقف بطلب المستخدم")
        if not wait_for_network_if_needed(cfg, stop_event, log):
            raise InterruptedError("توقف")
        if stop_event.is_set():
            raise InterruptedError("توقف بطلب المستخدم")
        if not ctx.acquire_key(stop_event=stop_event):
            wait = ctx.pool.secs_until_any_available_for_model(model["id"])
            note = f"كل المفاتيح مستنفدة لـ {model['id']} (أقرب توفر بعد {wait/3600:.1f}h)"
            log(f"🚫 {note}")
            return ProcessShardOutput(
                accumulated.strip() or None, last_file_uri, last_api_key,
                quota_exhausted=True, failure_reason=note)

        upload_attempts = 0
        while True:
            try:
                force_fresh = (force_fresh_upload and rounds == 0) or upload_attempts > 0
                file_ref = ctx.upload_shard(
                    shard, stop_event, force_fresh=force_fresh,
                    last_file_name=last_file_name)
                last_file_uri = file_ref.uri
                last_api_key = ctx.key_state.key
                last_file_name = file_ref.name
                break
            except InterruptedError:
                raise
            except Exception as exc:
                if is_quota_error(exc):
                    if ctx.rotate_due_to_quota(exc, stop_event=stop_event):
                        upload_attempts += 1
                        if upload_attempts <= 3:
                            continue
                    return ProcessShardOutput(
                        accumulated.strip() or None, last_file_uri, last_api_key,
                        quota_exhausted=True,
                        failure_reason=f"حصة رفع مستنفدة: {type(exc).__name__}")
                if is_key_auth_error(exc) and upload_attempts < 2:
                    upload_attempts += 1
                    ctx.ban_current_key(300)
                    ctx.close()
                    log(f"⚠️ تعذر اعتماد مفتاح الرفع؛ تجربة مفتاح آخر "
                        f"(محاولة {upload_attempts}/2).")
                    continue
                # fast_upload_pdf يعيد المحاولة من الإزاحة المؤكدة. لا نبدأ رفعاً
                # كاملاً جديداً بعد فشل شبكي، منعاً لإعادة بث الملف الضخم نفسه.
                retryable = is_retryable_network_error(exc)
                reason = f"فشل رفع الملف: {type(exc).__name__}: {str(exc)[:180]}"
                log(f"❌ {reason}")
                return ProcessShardOutput(
                    accumulated.strip() or None, last_file_uri, last_api_key,
                    failure_reason=reason, retryable=retryable)

        context_ref = None
        if shard.is_txt and ctx.txt_context_mgr:
            try:
                ff_ctx = force_fresh_upload and rounds == 0
                context_ref = ctx.get_txt_context(stop_event, force_fresh=ff_ctx)
            except Exception as exc:
                # الملف المرجعي تحسين اختياري، وفشله لا يكرر رفع الجزء ولا يجهضه.
                log(f"⚠️ تعذر السياق المرجعي TXT: {type(exc).__name__}: {str(exc)[:120]}")
                context_ref = None

        is_first = (rounds == 0)
        if is_first:
            unit_label = "أسطر" if shard.is_txt else "صفحات"
            log(f"━━━ جزء {shard.idx}/{total_shards} | {unit_label} "
                f"{shard.page_start}-{shard.page_end} | key={ctx.key_state.masked} ━━━")
            if shard.is_txt:
                prompt = build_txt_extract_prompt(
                    shard, total_shards, force=use_force_prompt)
                if use_force_prompt:
                    log("⚡ إعادة واحدة ببرومبت TXT الإجباري على الملف والمفتاح نفسيهما")
            elif use_force_prompt:
                prompt = build_force_extract_prompt(shard, total_shards)
                log("⚡ إعادة واحدة بالبرومبت الإجباري على الملف والمفتاح نفسيهما")
            else:
                prompt = build_extract_prompt(shard, total_shards)
        else:
            tail = accumulated[-2500:]
            log(f"━━━ جزء {shard.idx} | جولة إكمال {rounds} ━━━")
            prompt = build_continuation_prompt(shard, total_shards, tail, rounds)

        log("⏳ إرسال الطلب...")
        file_refs = [file_ref]
        if context_ref is not None:
            file_refs.append(context_ref)
        try:
            result = call_model_stream(
                ctx.client, model["id"], model.get("family") or detect_model_family(model["id"]),
                file_refs, system_prompt, prompt, cfg,
                on_token, stop_event, log, on_request=on_request,
                api_key=getattr(getattr(ctx, "key_state", None), "key", "") or "")
        except InterruptedError:
            raise
        except Exception as exc:
            if is_key_auth_error(exc):
                masked_key = getattr(ctx.key_state, "masked", "****")
                try:
                    ctx.ban_current_key(300)
                except Exception:
                    pass
                reason = f"مفتاح API غير معتمد ({masked_key}); أُوقف الجزء دون إعادة رفع الملف"
                log(f"📛 {reason}")
                return ProcessShardOutput(
                    accumulated.strip() or None, last_file_uri, last_api_key,
                    failure_reason=reason, auth_error=True)
            if is_permission_denied_error(exc):
                masked_key = getattr(ctx.key_state, "masked", "****")
                log(f"📛 رفض صلاحية الطلب على المفتاح {masked_key}; لا يُعاد رفع الملف.")
                try:
                    if on_key_used:
                        on_key_used(masked_key)
                except Exception:
                    pass
                return ProcessShardOutput(
                    accumulated.strip() or None, last_file_uri, last_api_key,
                    failure_reason=f"رفض صلاحية النموذج: {type(exc).__name__}: {str(exc)[:150]}")
            if is_quota_error(exc):
                if stop_event.is_set():
                    raise InterruptedError("توقف")
                if ctx.rotate_due_to_quota(exc, stop_event=stop_event):
                    if stop_event.is_set():
                        raise InterruptedError("توقف")
                    continue
                reason = f"حصة مستنفدة للنموذج {model['id']}"
                return ProcessShardOutput(
                    accumulated.strip() or None, last_file_uri, last_api_key,
                    quota_exhausted=True, failure_reason=reason)
            if is_file_lost_error(exc):
                file_refresh_attempts += 1
                if file_refresh_attempts <= 1:
                    log("📛 الملف لم يعد موجوداً على الخادم؛ إعادة رفع واحدة فقط للملف المفقود.")
                    try:
                        ctx.key_state.uploaded_shards.pop(shard.shard_md5, None)
                    except Exception:
                        pass
                    force_fresh_upload = True
                    continue
                reason = "الملف المرفوع غير متاح بعد إعادة رفع واحدة"
                return ProcessShardOutput(
                    accumulated.strip() or None, last_file_uri, last_api_key,
                    failure_reason=reason)
            if is_server_overloaded_error(exc):
                ctx._503_count += 1
                if ctx._503_count < 2:
                    wait_503 = min(3.0, float(ctx._503_count))
                    log(f"🔴 الخادم مشغول (503) — إعادة واحدة على الملف نفسه بعد {wait_503:.0f}s")
                    interruptible_sleep(wait_503, stop_event)
                    continue
                reason = f"الخادم مشغول بعد المحاولات الشبكية للنموذج {model['id']}"
                log(f"❌ {reason}")
                return ProcessShardOutput(
                    accumulated.strip() or None, last_file_uri, last_api_key,
                    failure_reason=reason, retryable=True)
            if is_retryable_network_error(exc):
                reason = f"فشل شبكي للنموذج {model['id']}: {type(exc).__name__}: {str(exc)[:150]}"
                log(f"⚠️ {reason} — لا إعادة رفع؛ يمكن تجربة نموذج بديل.")
                return ProcessShardOutput(
                    accumulated.strip() or None, last_file_uri, last_api_key,
                    failure_reason=reason, retryable=True)

            reason = f"رفض/خطأ طلب النموذج {model['id']}: {type(exc).__name__}: {str(exc)[:180]}"
            try:
                if ctx.key_state is not None:
                    ctx.key_state.fail_count += 1
                    ctx.pool._dirty = True
                    ctx.pool.maybe_save()
            except Exception:
                pass
            log(f"❌ {reason} — لن يُعاد رفع الجزء على مفاتيح أخرى.")
            return ProcessShardOutput(
                accumulated.strip() or None, last_file_uri, last_api_key,
                failure_reason=reason)

        if not result.text.strip() or is_model_refusal(result.text):
            empty_response_streak += 1
            try:
                ctx.pool.mark_empty_response(ctx.key_state)
            except Exception:
                pass
            log(f"⚠️ استجابة فارغة/رفض من {model['id']} "
                f"(محاولة {empty_response_streak}/2).")
            if not use_force_prompt and rounds == 0:
                use_force_prompt = True
                # يعاد الطلب على المفتاح والملف المرفوع نفسيهما؛ لا تبديل مفاتيح
                # ولا إعادة رفع لرفض محتوى/استجابة فارغة.
                continue
            reason = f"رفض/استجابة فارغة من النموذج {model['id']} بعد إعادة واحدة"
            return ProcessShardOutput(
                accumulated.strip() or None, last_file_uri, last_api_key,
                failure_reason=reason)

        empty_response_streak = 0
        use_force_prompt = False
        force_fresh_upload = False
        new_text = result.text.lstrip()
        if accumulated and not accumulated.endswith("\n"):
            accumulated += "\n"
        accumulated += new_text
        rounds += 1
        log(f"📊 finish={result.finish_reason} | out_tokens={result.output_tokens:,} | "
            f"كلمات تراكمي={count_words(accumulated):,}")
        try:
            on_progress({
                "batch_idx": shard.idx,
                "total_batches": total_shards,
                "round": rounds,
                "finish": result.finish_reason,
                "accumulated_words": count_words(accumulated),
                "accumulated_chars": count_chars(accumulated),
                "batch_pages": shard.pages_count,
            })
        except Exception:
            pass
        if result.finish_reason in ("STOP", "FINISH_REASON_STOP"):
            actual_words = count_words(accumulated)
            if actual_words < min_output_words:
                reason = (f"ناتج قصير جداً ({actual_words} كلمة؛ الحد الأدنى "
                          f"المتوقع {min_output_words})")
                if short_response_retries == 0:
                    short_response_retries += 1
                    accumulated = ""
                    rounds = 0
                    use_force_prompt = True
                    log(f"⚠️ جزء {shard.idx}: {reason} — إعادة واحدة ببرومبت النسخ الإجباري.")
                    try:
                        if on_attempt_restart:
                            on_attempt_restart(reason)
                    except Exception:
                        pass
                    continue
                if rounds < max_continuations:
                    log(f"⚠️ جزء {shard.idx}: {reason} بعد إعادة النسخ — طلب استكمال "
                        f"({rounds}/{max_continuations}).")
                    continue
                log(f"❌ جزء {shard.idx}: لم يتجاوز فحص الحد الأدنى بعد محاولات الاستكمال.")
                return ProcessShardOutput(
                    accumulated.strip() or None, last_file_uri, last_api_key,
                    failure_reason=reason,
                    used_model_id=str(model.get("id") or ""))
            ctx.pool.mark_success(ctx.key_state, ctx.model_id,
                                  getattr(result, "input_tokens", 0) or 0)
            ctx._rotation_count = 0
            ctx._503_count = 0
            log(f"✅ اكتمل جزء {shard.idx}")
            return ProcessShardOutput(
                accumulated, last_file_uri, last_api_key,
                used_model_id=str(model.get("id") or ""))
        if result.finish_reason == "MAX_TOKENS":
            log("⚠️ max_tokens — جولة إكمال...")
        else:
            log(f"⚠️ finish={result.finish_reason} — إكمال...")

    log(f"🛑 استُنفدت جولات الإكمال لجزء {shard.idx}")
    if accumulated.strip():
        actual_words = count_words(accumulated)
        reason = (f"استُنفدت جولات الإكمال قبل إشارة STOP "
                  f"(كلمات الناتج {actual_words}; الحد الأدنى {min_output_words})")
        log(f"❌ جزء {shard.idx}: {reason} — لن يُعتمد كجزء مكتمل.")
        return ProcessShardOutput(
            accumulated, last_file_uri, last_api_key,
            failure_reason=reason,
            used_model_id=str(model.get("id") or ""))
    return ProcessShardOutput(
        None, last_file_uri, last_api_key,
        failure_reason=f"لم يُنتج النموذج {model.get('id', '')} نصاً")


def process_shard_with_model_failover(
        shard, total_shards, model_candidates, context_factory,
        system_prompt, cfg, on_token, on_progress, on_request, on_key_used,
        stop_event, log, force_fresh_upload=False,
        on_attempt_restart: Optional[Callable[[str], None]] = None) -> ProcessShardOutput:
    """ينفّذ الجزء على النموذج الأساسي ثم البدائل المفعّلة؛ يغلق سياق كل محاولة."""
    candidates = list(model_candidates or [])
    if not candidates:
        return ProcessShardOutput(None, failure_reason="لا يوجد نموذج استخراج صالح")
    last = None
    best_partial = None
    for index, candidate in enumerate(candidates):
        if stop_event.is_set():
            raise InterruptedError("توقف")
        model_id = str(candidate.get("id") or "")
        ctx = context_factory(candidate)
        try:
            try:
                out = process_shard(
                    shard, total_shards, candidate, ctx, system_prompt, cfg,
                    on_token, on_progress, on_request, on_key_used,
                    stop_event, log, force_fresh_upload=force_fresh_upload,
                    on_attempt_restart=on_attempt_restart)
            except InterruptedError:
                raise
            except Exception as exc:
                reason = f"{type(exc).__name__}: {str(exc)[:180]}"
                out = ProcessShardOutput(
                    None, failure_reason=reason,
                    retryable=is_retryable_network_error(exc))
        finally:
            try:
                ctx.close()
            except Exception:
                pass
        if out is None:
            out = ProcessShardOutput(None, failure_reason="لم تُرجع المحاولة نتيجة")
        out.used_model_id = model_id
        if out.text and not out.failure_reason:
            return out
        if getattr(out, "auth_error", False):
            # اعتماد المفتاح يفشل للنماذج كلها؛ تجربة النموذج البديل بالمفتاح
            # نفسه ستكرر طلباً مرفوضاً بلا فائدة، فلا نعيد الرفع أو الطلب.
            return out
        if out.text:
            best_partial = out
        if index + 1 < len(candidates):
            try:
                if on_attempt_restart:
                    on_attempt_restart(
                        f"تعذر اعتماد نتيجة النموذج {model_id}؛ تجربة نموذج بديل")
            except Exception:
                pass
        last = out
        if index + 1 >= len(candidates):
            break
        next_model = candidates[index + 1]
        log(f"🔀 فشل الجزء {shard.idx} مع {model_id} "
            f"({out.failure_reason or 'لا ناتج'})؛ تجربة النموذج البديل "
            f"{next_model.get('id', '')} على الجزء نفسه.")
    return best_partial or last or ProcessShardOutput(
        None, failure_reason="فشل جميع النماذج البديلة")


class ParallelExtractionRunner:
    def __init__(self, *, shards: List[PDFShard], total_shards: int,
                 book_path: Path, parts_dir: Path, model: dict, pool: KeyPool,
                 global_key_mgr: GlobalKeyManager,
                 system_prompt: str, cfg: dict, ckpt: "Checkpoint",
                 comparator: Optional[InlineComparator],
                 on_token, on_log, on_progress, on_upload_progress,
                 on_compare_submit, on_request, on_key_used, on_stream_event,
                 stop_event: threading.Event, pause_event: threading.Event,
                 txt_context_mgr: Optional[TxtContextManager] = None,
                 force_fresh_upload: bool = False, already_done: int = 0,
                 book_stem: Optional[str] = None):
        self.shards = list(shards)
        self.total_shards = total_shards
        self.book_path = book_path
        self.book_stem = book_stem or Path(book_path).stem
        self.parts_dir = parts_dir
        # ✅ v29.0: output_dir مطلوب لمسارات book_meta/التحذيرات
        try:
            self.output_dir = Path(parts_dir).parent.parent if parts_dir is not None else Path(book_path).parent
            # parts_dir = .../_pdf_master_data/<book>/parts → parent.parent = output_dir
            # fallback أدق:
            p = Path(parts_dir)
            if p.name == "parts":
                self.output_dir = p.parent.parent
            else:
                self.output_dir = p.parent
        except Exception:
            self.output_dir = Path(book_path).parent
        self.model = model
        self.cfg = cfg
        self.models = extraction_model_candidates(self.model, self.cfg)
        self.pool = pool
        self.global_key_mgr = global_key_mgr
        self.system_prompt = system_prompt
        self.ckpt = ckpt
        self.comparator = comparator
        self.on_token = on_token
        self.on_log = on_log
        self.on_progress = on_progress
        self.on_upload_progress = on_upload_progress
        self.on_compare_submit = on_compare_submit
        self.on_request = on_request
        self.on_key_used = on_key_used
        self.on_stream_event = on_stream_event or (lambda _e: None)
        self.stop_event = stop_event
        self.pause_event = pause_event
        self.txt_context_mgr = txt_context_mgr
        self.force_fresh_upload = force_fresh_upload
        self.completed_count = already_done
        self._completed_lock = threading.RLock()
        self._failed_lock = threading.RLock()
        self.failed: List[int] = []
        self._attempts: Dict[int, int] = {}
        self._finalized: Set[int] = set()
        self._queue: queue.Queue = queue.Queue()
        for shard in self.shards:
            self._queue.put(shard)
        self._global_503_count = 0
        self._global_503_lock = threading.Lock()
        self._last_503_pause = 0.0
        requested_workers = max(1, min(int(self.cfg.get("parallel_extract_workers", 1) or 1), 25, max(1, len(self.shards))))
        self.all_keys = [s.key for s in sorted(self.pool.states.values(), key=lambda s: (s.fail_count, -s.success_count, s.masked))]
        # ✅ OPT-QUOTA: حد أقصى ذكي للمسارات المتوازية
        # نماذج preview لها حد RPM منخفض — كثرة المسارات تسبب كوتة متكررة
        available_keys = self.pool.count_available_for_model(self.model["id"])
        # عند تفعيل محدد RPM يمكن تشغيل مسار لكل مفتاح؛ وإلا تبقى الحماية
        # المحافظة القديمة (~3 مفاتيح لكل مسار) كما هي.
        safe_max = (max(1, available_keys) if is_key_rpm_enabled()
                    else max(1, available_keys // 3))
        if requested_workers > safe_max and available_keys > 0:
            self.on_log(f"⚠️ تقليل المسارات من {requested_workers} إلى {safe_max} "
                        f"(المفاتيح المتاحة: {available_keys})")
            self.workers = safe_max
        else:
            self.workers = requested_workers
        # ✅ v27.8: إبلاغ الواجهة بالعدد الفعلي دون تعديل القيمة المحفوظة في الإعدادات.
        self._lane_event(0, "workers_config", requested_workers=requested_workers,
                         actual_workers=self.workers, available_keys=available_keys,
                         model_id=self.model["id"])

    def _wait_if_paused(self):
        while self.pause_event.is_set() and not self.stop_event.is_set():
            try:
                interruptible_sleep(0.2, self.stop_event)
            except InterruptedError:
                break

    def _lane_log(self, lane_id: int, msg: str):
        self.on_log(f"[مسار {lane_id}] {msg}")

    def _lane_event(self, lane_id: int, event_type: str, shard: Optional[PDFShard] = None, **extra):
        payload = {
            "type": event_type,
            "lane_id": lane_id,
            "workers": self.workers,
        }
        if shard is not None:
            payload["shard_idx"] = shard.idx
            payload["page_start"] = shard.page_start
            payload["page_end"] = shard.page_end
            payload["pages_count"] = getattr(shard, "pages_count", max(0, shard.page_end - shard.page_start + 1))
        # ✅ v29.1: اسم الكتاب إن وُجد على الـ runner
        try:
            if getattr(self, "book_path", None) is not None:
                payload.setdefault("book_name", Path(self.book_path).name)
                payload.setdefault("book_stem", getattr(self, "book_stem", Path(self.book_path).stem))
        except Exception:
            pass
        payload.update(extra)
        try:
            self.on_stream_event(payload)
        except Exception as e:
            # ✅ v27.8: لا نكتم أخطاء بث أحداث المسارات لأنها تؤثر على وضوح الواجهة.
            safe_print(f"[ParallelExtractionRunner._lane_event] error: {e}")

    def _mark_failed(self, shard: PDFShard, note: str):
        self.ckpt.mark_failed(shard, note)
        with self._failed_lock:
            if shard.idx not in self.failed:
                self.failed.append(shard.idx)

    def _should_retry_shard(self, shard: PDFShard, reason: str,
                            retryable: Optional[bool] = None) -> bool:
        reason_l = (reason or '').lower()
        if retryable is None:
            retryable = any(x in reason_l for x in [
                'server disconnected', 'forcibly closed', 'connection', 'timeout',
                'temporarily', 'reset', 'unavailable', 'network', 'no output'
            ])
        if not retryable:
            return False
        n = self._attempts.get(shard.idx, 0) + 1
        self._attempts[shard.idx] = n
        if n > 1:
            return False
        # ✅ v24.4: تأخير قبل إعادة الجدولة لتجنب حرق الطلبات
        wait = 30
        self.on_log(f"♻️ إعادة جدولة جزء {shard.idx} (محاولة إضافية {n}/1) "
                     f"بعد {wait}s بسبب: {reason}")
        try:
            interruptible_sleep(wait, self.stop_event)
        except InterruptedError:
            return False
        if not self.stop_event.is_set():
            self._queue.put(shard)
            return True
        return False

    def _mark_progress_done(self, shard: PDFShard):
        with self._completed_lock:
            if shard.idx in self._finalized:
                return
            self._finalized.add(shard.idx)
            self.completed_count += 1
            done = self.completed_count
        try:
            self.on_progress({
                "current_batch": done,
                "total_batches": self.total_shards,
                "batch_pages": shard.pages_count,
                "shard_idx": shard.idx,
            })
        except Exception:
            pass

    def _lane_progress(self, lane_id: int, shard: PDFShard, info: dict):
        payload = dict(info or {})
        payload["lane_id"] = lane_id
        payload["shard_idx"] = shard.idx
        try:
            self.on_progress(payload)
        except Exception:
            pass

    def _make_preferred_keys(self) -> List[Optional[str]]:
        keys = list(self.all_keys)
        if not keys:
            return [None] * self.workers
        return [keys[i % len(keys)] for i in range(self.workers)]

    def _lane_worker(self, lane_id: int, preferred_key: Optional[str]):
        lane_contexts: Dict[str, ShardRuntimeContext] = {}

        def _context_for(candidate):
            model_id = str(candidate.get("id") or "")
            if model_id not in lane_contexts:
                lane_contexts[model_id] = ShardRuntimeContext(
                    self.pool, model_id,
                    lambda m, _lane=lane_id: self._lane_log(_lane, m),
                    self.global_key_mgr, self.all_keys,
                    self.on_upload_progress,
                    txt_context_mgr=self.txt_context_mgr,
                    preferred_key=preferred_key)
            return lane_contexts[model_id]

        while not self.stop_event.is_set():
            self._wait_if_paused()
            if self.stop_event.is_set():
                break
            try:
                # v8.4: الانتظار قليلاً في حال وجود أجزاء قيد إعادة الجدولة
                shard = self._queue.get(timeout=5)
            except queue.Empty:
                # إذا فرغ الطابور تماماً ولم يعد هناك أجزاء قيد المعالجة
                with self._completed_lock:
                    if self.completed_count + len(self.failed) >= self.total_shards:
                        break
                continue
            counted = False
            try:
                # ✅ v24.4: إيقاف مؤقت عند كثرة 503
                with self._global_503_lock:
                    if self._global_503_count >= 3:
                        wait_g = min(3.0, 1.0 * self._global_503_count)
                        now = time.time()
                        if now - self._last_503_pause > 30:
                            self._last_503_pause = now
                            self._lane_log(lane_id,
                                f"🔴 إيقاف مؤقت عام ({wait_g}s) — الخادم مشغول")
                            self._global_503_count = max(0, self._global_503_count - 2)
                if self._global_503_count >= 3:
                    try:
                        interruptible_sleep(min(60, 20 * self._global_503_count), self.stop_event)
                    except InterruptedError:
                        break
                self._lane_event(lane_id, "start", shard)
                valid, validation_note = is_valid_split_input(shard)
                if not valid:
                    msg = f"split validation failed: {validation_note}"
                    self._lane_log(lane_id, f"⚠️  جزء {shard.idx}: {validation_note} — سيتم تخطيه")
                    self._mark_failed(shard, msg)
                    self._lane_event(lane_id, "error", shard, message=validation_note, summary=validation_note)
                    counted = True
                    continue

                part_file = self.parts_dir / f"{self.book_stem}_part_{shard.idx:04d}.txt"
                psout = process_shard_with_model_failover(
                    shard, self.total_shards, self.models, _context_for,
                    self.system_prompt, self.cfg,
                    lambda t, _lane=lane_id, _shard=shard: self._lane_event(_lane, "token", _shard, text=t),
                    lambda info, _lane=lane_id, _shard=shard: self._lane_progress(_lane, _shard, info),
                    (lambda desc, _lane=lane_id, _shard=shard: self.on_request(f"lane={_lane} part={_shard.idx} {desc}")
                        if self.on_request else None),
                    self.on_key_used, self.stop_event,
                    lambda m: self._lane_log(lane_id, m),
                    force_fresh_upload=self.force_fresh_upload,
                    on_attempt_restart=lambda reason, _lane=lane_id, _shard=shard:
                        self._lane_event(_lane, "restart", _shard, message=reason))

                if psout.text and not psout.failure_reason:
                    try:
                        part_file.with_name(f"{part_file.stem}.partial").unlink()
                    except FileNotFoundError:
                        pass
                    except Exception:
                        pass
                    atomic_write_text(part_file, psout.text, encoding="utf-8")
                    self.ckpt.mark_ok(shard, str(part_file))
                    # ✅ v28.7: تحذير إن كانت كلمات الجزء < 40% من المعدل المتوقع
                    try:
                        if not shard.is_txt:
                            meta = load_book_meta(self.output_dir, self.book_stem)
                            wpp = float(meta.get("words_per_page") or meta.get("avg_words_per_page") or 0)
                            pages = max(1, int(getattr(shard, "pages_count", 0) or (shard.page_end - shard.page_start + 1)))
                            actual = count_words(psout.text)
                            # لا تسمح لأول جزء منخفض الحجم بتثبيت متوسط مضلل للكتاب.
                            calibration_floor = max(30, pages * 20)
                            if actual < calibration_floor:
                                self._lane_log(lane_id,
                                    f"ℹ️ جزء {shard.idx}: {actual} كلمة؛ لم يُحدّث متوسط الكلمات/صفحة "
                                    f"لأن الحد الأدنى للمعايرة {calibration_floor}.")
                            elif wpp <= 0:
                                wpp = actual / pages
                                save_book_meta(self.output_dir, self.book_stem, {
                                    "avg_words_per_page": round(wpp, 2),
                                    "words_per_page": round(wpp, 2),
                                })
                            else:
                                expected = wpp * pages
                                if expected > 0 and actual < 0.4 * expected:
                                    self._lane_log(lane_id,
                                        f"⚠️ جزء {shard.idx}: كلمات {actual} < 40% من المتوقع (~{int(expected)})")
                    except Exception as e:
                        try: LOGGER.debug("words/page warn: %s", e)
                        except Exception: pass
                    # ✅ v24.4: نجاح = الخادم عاد — نقلل عدّاد 503
                    with self._global_503_lock:
                        self._global_503_count = max(0, self._global_503_count - 1)
                    self._lane_log(lane_id,
                        f"💾 حُفظت: {part_file.name} (كلمات: {count_words(psout.text):,})")
                    if self.comparator and not self.stop_event.is_set():
                        try:
                            self.comparator.submit(
                                shard=shard,
                                extracted_text=psout.text,
                                api_key_hint=psout.used_api_key,
                                file_uri_hint=psout.file_uri,
                                force=True)
                        except Exception as e:
                            self._lane_log(lane_id, f"⚠️  تعذر إرسال للمقارن: {e}")
                    self._lane_event(lane_id, "finish", shard, status="ok",
                                     summary=tail_words(psout.text, STREAM_SUMMARY_WORDS))
                    # ✅ v27.8: عدّ الجزء الناجح كمحسوم لتحديث التقدم وتطبيق تأخير الدفعات.
                    counted = True
                else:
                    if psout.text:
                        # احفظ النص التشخيصي الجزئي باسم لا يطابق نمط ملفات الأجزاء
                        # المكتملة، حتى لا يُدمج أو يُتخطى في تشغيل لاحق.
                        partial_file = part_file.with_name(f"{part_file.stem}.partial")
                        try:
                            atomic_write_text(partial_file, psout.text, encoding="utf-8")
                            self._lane_log(lane_id,
                                f"🧩 حُفظ ناتج تشخيصي غير مكتمل: {partial_file.name}")
                        except Exception as e:
                            self._lane_log(lane_id, f"⚠️ تعذر حفظ النص الجزئي للتشخيص: {e}")
                    reason = psout.failure_reason or "لا ناتج من النموذج"
                    if psout.quota_exhausted:
                        self._lane_log(lane_id,
                            f"⏳ جزء {shard.idx}: نفدت الحصص المتاحة — انتظار دقيقة قبل إعادة المحاولة")
                        try:
                            interruptible_sleep(60, self.stop_event)
                        except InterruptedError:
                            break
                        if not self.stop_event.is_set():
                            self._queue.put(shard)
                    else:
                        scheduled = self._should_retry_shard(
                            shard, reason, retryable=bool(psout.retryable))
                        self._lane_event(lane_id, "error", shard,
                                         message=reason, summary=reason)
                        if not scheduled:
                            self._mark_failed(shard, reason)
                            self._lane_log(lane_id, f"🛑 فشل جزء {shard.idx}: {reason}")
                            counted = True
            except InterruptedError:
                self._lane_event(lane_id, "error", shard, message="توقف", summary="توقف")
                break
            except Exception as e:
                self._lane_log(lane_id, f"💥 خطأ في جزء {shard.idx}: {e}\n{traceback.format_exc()}")
                if not self._should_retry_shard(shard, str(e)):
                    self._mark_failed(shard, str(e))
                    self._lane_event(lane_id, "error", shard, message=str(e), summary=str(e))
                    counted = True
            finally:
                for _ctx in list(lane_contexts.values()):
                    try:
                        _ctx.close()
                    except Exception:
                        pass
                try:
                    self._queue.task_done()
                except Exception:
                    pass
                if counted:
                    self._mark_progress_done(shard)
                    # ✅ v27.8: حفظ KeyPool المجمع بعد حسم كل جزء بدون fsync لكل تحديث داخلي.
                    self.pool.maybe_save()
                    delay_s = float(self.cfg.get("delay_between_batches", 0) or 0)
                    # ✅ OPT-QUOTA: حد أدنى 1s تأخير عند تشغيل مسارات متعددة
                    if self.workers > 1 and delay_s < 1.0:
                        delay_s = 1.0
                    if delay_s > 0 and not self.stop_event.is_set():
                        try:
                            interruptible_sleep(delay_s, self.stop_event)
                        except InterruptedError:
                            break

    def run(self) -> List[int]:
        if not self.shards:
            return []
        preferred_keys = self._make_preferred_keys()
        self.on_log(f"⚙️ الاستخراج المتوازي: {self.workers} مسار")
        with ThreadPoolExecutor(max_workers=self.workers, thread_name_prefix="ExtractLane") as executor:
            futures = []
            for lane_id in range(self.workers):
                futures.append(
                    executor.submit(self._lane_worker, lane_id + 1, preferred_keys[lane_id]))
                # ✅ OPT-QUOTA: تأخير تدريجي بين بدء المسارات لتوزيع الحمل
                if lane_id < self.workers - 1 and self.workers > 2:
                    try:
                        interruptible_sleep(1.5, self.stop_event)
                    except InterruptedError:
                        break
            for future in futures:
                try:
                    future.result()
                except Exception as e:
                    self.on_log(f"💥 خطأ غير متوقع في مسار متوازٍ: {e}\n{traceback.format_exc()}")
        return sorted(self.failed)


# ═══════════════════════════════════════════════════════════════════
#  Checkpoint
# ═══════════════════════════════════════════════════════════════════

class Checkpoint:
    def __init__(self, path: Path):
        self.path = path
        self.data: Dict[str, dict] = {}
        self._lock = threading.RLock()
        # ✅ v28.7: علم يحمي من terminate أثناء كتابة checkpoint
        self.is_writing = False
        if path.exists():
            try:
                self.data = json.loads(path.read_text(
                    encoding="utf-8", errors="replace"))
            except Exception as e:
                try:
                    LOGGER.warning("Checkpoint load failed %s: %s", path, e)
                except Exception:
                    pass
                self.data = {}

    def is_done(self, idx: int) -> bool:
        # ✅ v29.0: status=ok وحده غير كافٍ — تحقق من جودة الملف
        rec = self.data.get(str(idx))
        if not (rec and rec.get("status") == "ok"):
            return False
        try:
            of = rec.get("output_file") or ""
            p = Path(of) if of else None
            if p is not None and p.exists():
                try:
                    units = max(1, int(rec.get("page_end")) - int(rec.get("page_start")) + 1)
                    min_words = minimum_extraction_word_count_for_units(
                        units, bool(rec.get("is_txt", False)))
                except Exception:
                    min_words = 10
                return is_part_complete(p, min_words=min_words)
        except Exception:
            return False
        return False

    def mark_ok(self, shard: PDFShard, output_file: str) -> None:
        with self._lock:
            self.data[str(shard.idx)] = {
                "status": "ok",
                "page_start": shard.page_start,
                "page_end": shard.page_end,
                "output_file": output_file,
                "is_txt": shard.is_txt}
            self._save()

    def mark_failed(self, shard: PDFShard, note: str) -> None:
        with self._lock:
            self.data[str(shard.idx)] = {
                "status": "failed",
                "page_start": shard.page_start,
                "page_end": shard.page_end,
                "note": note,
                "is_txt": shard.is_txt}
            self._save()

    def clear(self, idx: int) -> None:
        with self._lock:
            self.data.pop(str(idx), None)
            self._save()

    def _save(self) -> None:
        # ✅ v28.7: is_writing يحمي من terminate أثناء الحفظ
        self.is_writing = True
        try:
            atomic_write_text(
                self.path,
                json.dumps(self.data, ensure_ascii=False, indent=2),
                encoding="utf-8")
        except Exception as e:
            try:
                LOGGER.error("Checkpoint._save error %s: %s", self.path, e)
            except Exception:
                pass
            safe_print(f"[Checkpoint._save] error: {e}")
        finally:
            self.is_writing = False


# ═══════════════════════════════════════════════════════════════════
#  File Processor (PDF + TXT)
# ═══════════════════════════════════════════════════════════════════

@dataclass
class FileResult:
    success: bool
    final_path: Optional[Path]
    incomplete_path: Optional[Path]
    total_batches: int
    successful_batches: int
    failed_batches: List[int]
    message: str
    file_path: Optional[Path] = None
    compare_summary: Optional[dict] = None
    is_txt: bool = False


PDFResult = FileResult


class PDFProcessor:
    def __init__(self, in_path, output_dir, parts_dir, tokens_path,
                   system_prompt, model, compare_model, cfg,
                   on_token, on_log, on_progress, on_upload_progress,
                   on_compare_partial, on_compare_final,
                   on_request, on_key_used, on_stream_event,
                   stop_event, pause_event,
                   enable_inline_compare: bool,
                   global_key_mgr: GlobalKeyManager,
                   app_dir: Path,
                   custom_split_text: str,
                   custom_batch_text: str = ""):
        self.in_path = in_path
        self.output_dir = output_dir
        self.parts_dir = parts_dir
        self.tokens_path = tokens_path
        self.system_prompt = system_prompt
        self.model = model
        self.compare_model = compare_model
        self.cfg = cfg
        self.on_token = on_token
        self.on_log = on_log
        self.on_progress = on_progress
        self.on_upload_progress = on_upload_progress
        self.on_compare_partial = on_compare_partial
        self.on_compare_final = on_compare_final
        self.on_request = on_request
        self.on_key_used = on_key_used
        self.on_stream_event = on_stream_event
        self.stop_event = stop_event
        self.pause_event = pause_event
        self.enable_inline_compare = enable_inline_compare
        self.global_key_mgr = global_key_mgr
        self.app_dir = app_dir
        self.custom_split_text = custom_split_text
        self.custom_batch_text = custom_batch_text or ""
        self.book_stem = effective_book_stem_for(self.in_path, self.custom_split_text, self.custom_batch_text)
        self.request_counter: Optional[CentralRequestCounter] = None

    def _wait_if_paused(self):
        while self.pause_event.is_set() and not self.stop_event.is_set():
            try:
                interruptible_sleep(0.2, self.stop_event)
            except InterruptedError:
                break

    def _safe_log(self, msg: str):
        try:
            self.on_log(msg)
        except Exception:
            pass

    def run(self) -> FileResult:
        try:
            return self._run_impl()
        except Exception as e:
            tb = traceback.format_exc()
            self._safe_log(f"💥 استثناء غير متوقع: {e}\n{tb}")
            return FileResult(False, None, None, 0, 0, [],
                                f"استثناء: {e}",
                                file_path=self.in_path,
                                is_txt=is_txt_file(self.in_path))

    def _run_impl(self) -> FileResult:
        log = self._safe_log
        is_txt = is_txt_file(self.in_path)
        log(f"📄 الملف: {self.in_path.name} ({'TXT' if is_txt else 'PDF'})")

        if not self.in_path.exists():
            return FileResult(False, None, None, 0, 0, [],
                                f"غير موجود: {self.in_path}",
                                file_path=self.in_path, is_txt=is_txt)

        if is_txt:
            total_units = get_txt_word_count(self.in_path)
            log(f"   📝 الكلمات: {total_units}")
        else:
            total_units = get_pdf_page_count(self.in_path)
            log(f"   📃 الصفحات: {total_units}")

        custom_ranges = None
        custom_ranges_exact = False
        raw_custom_batch = normalize_custom_split_input(getattr(self, "custom_batch_text", ""))
        raw_custom_split = normalize_custom_split_input(self.custom_split_text)
        if raw_custom_batch:
            try:
                custom_ranges = parse_custom_batch_boundaries(raw_custom_batch, total_units)
                if not custom_ranges:
                    raise ValueError("لم ينتج parser أي نطاقات")
                custom_ranges_exact = True
                preview_ranges = ", ".join(f"{a}-{b}" for a, b in custom_ranges[:8])
                if len(custom_ranges) > 8:
                    preview_ranges += f", …, {custom_ranges[-1][0]}-{custom_ranges[-1][1]}"
                log(f"🔒 دفعات مخصصة مفعلة إلزامياً: {len(custom_ranges)} دفعة | النطاقات: {preview_ranges}")
            except Exception as e:
                # التقسيم المخصص اختيار صريح من المستخدم. لا نسمح بسقوط صامت
                # إلى pages_per_batch لأن ذلك ينفذ كتاباً بخطة مختلفة عن المعتمدة.
                msg = f"دفعات مخصصة غير صالحة — أُوقف الاستخراج حفاظاً على الحدود المعتمدة: {e}"
                log(f"⛔ {msg}")
                return FileResult(False, None, None, 0, 0, [], msg,
                                   file_path=self.in_path, is_txt=is_txt)
        elif raw_custom_split:
            try:
                custom_ranges = parse_custom_split_ranges(
                    raw_custom_split, total_units)
                if not custom_ranges:
                    raise ValueError("لم ينتج parser أي نطاقات")
                log(f"✂️ تقسيم مخصص مفعل: {len(custom_ranges)} قسم")
            except Exception as e:
                msg = f"تقسيم مخصص غير صالح — أُوقف الاستخراج بدلاً من استخدام القيم الافتراضية: {e}"
                log(f"⛔ {msg}")
                return FileResult(False, None, None, 0, 0, [], msg,
                                   file_path=self.in_path, is_txt=is_txt)

        self.output_dir.mkdir(parents=True, exist_ok=True)
        book_data_dir = self.parts_dir.parent
        book_data_dir.mkdir(parents=True, exist_ok=True)
        self.parts_dir.mkdir(parents=True, exist_ok=True)
        log(f"📁 مجلد الأجزاء النصية: {self.parts_dir}")

        suffix = "_معالج" if is_txt else "_مستخرج"
        final_path = self.output_dir / f"{self.book_stem}{suffix}.txt"

        checkpoints_dir = get_book_checkpoints_dir(self.output_dir, self.book_stem)
        checkpoints_dir.mkdir(parents=True, exist_ok=True)
        ckpt = Checkpoint(checkpoints_dir / "checkpoint.json")
        try:
            register_stop_component("checkpoints", ckpt)
        except Exception:
            pass

        shards_dir = get_book_shards_dir(self.output_dir, self.book_stem)
        log("━━━ مرحلة التقسيم ━━━")
        try:
            if is_txt:
                shards = split_txt_into_shards(
                    self.in_path, shards_dir,
                    self.cfg.get("lines_per_batch", 1000),
                    log, self.stop_event,
                    custom_ranges=custom_ranges, custom_ranges_exact=custom_ranges_exact)
            else:
                shards = split_pdf_into_shards(
                    self.in_path, shards_dir,
                    self.cfg["pages_per_batch"], log, self.stop_event,
                    custom_ranges=custom_ranges, custom_ranges_exact=custom_ranges_exact)
        except InterruptedError:
            return FileResult(False, None, None, 0, 0, [],
                                "أُلغي التقسيم", file_path=self.in_path,
                                is_txt=is_txt)
        except Exception as e:
            log(f"💥 فشل التقسيم: {e}")
            return FileResult(False, None, None, 0, 0, [],
                                f"فشل التقسيم: {e}",
                                file_path=self.in_path, is_txt=is_txt)

        if not shards:
            return FileResult(False, None, None, 0, 0, [],
                                "لم يُنتج أي جزء",
                                file_path=self.in_path, is_txt=is_txt)

        # ✅ v28.0: حفظ بيانات الكتاب (عدد الأجزاء + معدل الاستخراج)
        try:
            save_book_meta(self.output_dir, self.book_stem, {
                "book_stem": self.book_stem,
                "source_path": str(self.in_path),
                "is_txt": is_txt,
                "total_units": total_units,
                "parts_count": len(shards),
                "pages_per_batch": int(self.cfg.get("pages_per_batch", 25) or 25),
                "lines_per_batch": int(self.cfg.get("lines_per_batch", 2000) or 2000),
                "units_per_batch": int(self.cfg.get("lines_per_batch", 2000) if is_txt else self.cfg.get("pages_per_batch", 25)),
                "custom_split_text": normalize_custom_split_input(self.custom_split_text),
                "custom_batch_text": normalize_custom_split_input(getattr(self, "custom_batch_text", "")),
                "active_prompt_kind": str(self.cfg.get("active_prompt_kind", "default") or "default"),
                "remove_headers": bool(self.cfg.get("remove_headers", True)),
                "shard_ranges": [
                    {"idx": s.idx, "start": s.page_start, "end": s.page_end}
                    for s in shards
                ],
            })
            log(f"💾 حُفظت بيانات الكتاب: {len(shards)} جزء | معدل "
                f"{self.cfg.get('lines_per_batch' if is_txt else 'pages_per_batch')}"
                f"{' كلمة' if is_txt else ' صفحة'}/دفعة")
        except Exception as e_meta:
            log(f"⚠️  تعذر حفظ بيانات الكتاب: {e_meta}")

        global_state_path = self.app_dir / KeyPool.GLOBAL_STATE_FILENAME

        try:
            pool = KeyPool(
                self.tokens_path,
                checkpoints_dir / "keys_state.json",
                self.cfg,
                global_state_path=global_state_path)
        except Exception as e:
            return FileResult(False, None, None, 0, 0, [], str(e),
                                file_path=self.in_path, is_txt=is_txt)
        try:
            register_stop_component("keypools", pool)
        except Exception:
            pass

        log(f"🔑 المفاتيح الكلية: {len(pool.states)}")
        log(f"   متاحة لـ {self.model['id']}: "
            f"{pool.count_available_for_model(self.model['id'])}")

        try:
            self.on_progress({
                "total_batches": len(shards),
                "current_batch": 0,
                "total_pages": total_units,
            })
        except Exception as e:
            # ✅ v27.8: تسجيل تشخيصي لأخطاء callback بدل كتمانها.
            safe_print(f"[PDFProcessor.on_progress:init] error: {e}")

        txt_ctx_mgr = None
        if is_txt and should_upload_full_txt_context(self.cfg):
            txt_ctx_mgr = TxtContextManager(self.in_path, log)

        if pool.count_available_for_model(self.model["id"]) <= 0:
            wait = pool.secs_until_any_available_for_model(self.model["id"])
            # ✅ v27.8: حفظ إجباري لحالة المفاتيح عند إنهاء معالجة الملف مبكراً.
            pool.save_dirty()
            return FileResult(False, None, None, len(shards), 0, [],
                                f"لا مفتاح متاح لـ {self.model['id']}! "
                                f"بعد {wait/3600:.1f}h.",
                                file_path=self.in_path, is_txt=is_txt)

        comparator: Optional[InlineComparator] = None
        allow_txt_custom_compare = bool(is_txt and str(self.cfg.get("active_prompt_kind", "")) == "custom"
                                        and self.cfg.get("custom_compare_enabled", True)
                                        and str(self.cfg.get("custom_compare_prompt", "")).strip())
        if self.enable_inline_compare and (not is_txt or allow_txt_custom_compare):
            try:
                api_keys = [s.key for s in pool.states.values()]
                workers = self.cfg.get("compare_parallel_workers", 3)
                workers = max(1, min(workers, len(api_keys), 25))
                comparator = InlineComparator(
                    output_dir=self.output_dir,
                    book_stem=self.book_stem,
                    model_id=self.compare_model["id"],
                    model_family=self.compare_model["family"],
                    cfg=self.cfg,
                    on_partial_result=self.on_compare_partial,
                    on_log=self._safe_log,
                    stop_event=self.stop_event,
                    api_keys=api_keys,
                    global_key_mgr=self.global_key_mgr,
                    parallel_workers=workers,
                    request_counter=getattr(self, 'request_counter', None))
                comparator.start()
                try:
                    register_stop_component("comparators", comparator)
                except Exception:
                    pass
                log(f"🔍 مقارنة متوازية بنموذج {self.compare_model['id']} "
                    f"({workers} عمال)")
            except Exception as e:
                log(f"⚠️  تعذر بدء المقارن: {e}")
                comparator = None
        elif is_txt:
            log("ℹ️  المقارنة الموازية غير متاحة لملفات TXT إلا في وضع البرومبت المخصص مع برومبت مقارنة مفعّل.")

        failed: List[int] = []
        try:
            all_part_indices = {s.idx for s in shards}
            completed_existing = detect_completed_part_indices(
                self.output_dir, self.book_stem, all_part_indices)
            pending_shards: List[PDFShard] = []

            for shard in shards:
                part_file = self.parts_dir / f"{self.book_stem}_part_{shard.idx:04d}.txt"
                if shard.idx in completed_existing and part_file.exists():
                    log(f"⏭️  جزء {shard.idx}/{len(shards)} مكتمل سابقاً (set-based).")
                    if comparator:
                        prev = comparator.get_result(shard.idx)
                        if prev and prev.error is None:
                            try:
                                self.on_compare_partial(prev)
                            except Exception as e:
                                # ✅ v27.8: تسجيل تشخيصي لأخطاء callback بدل كتمانها.
                                safe_print(f"[PDFProcessor.on_compare_partial:resume] error: {e}")
                        else:
                            try:
                                txt = part_file.read_text(encoding="utf-8", errors="replace")
                                # ✅ OPT4: لا تستخدم force عند الاستئناف — المقارن سيتخطى إن وُجدت نتيجة صالحة
                                comparator.submit(shard, txt, None, None, force=False)
                            except Exception as e:
                                log(f"⚠️  تعذر إرسال جزء مكتمل للمقارن: {e}")
                    continue
                pending_shards.append(shard)

            if completed_existing and pending_shards:
                missing_now = sorted(all_part_indices - completed_existing)
                log(f"♻️ استئناف ذكي: المكتمل فعلياً {len(completed_existing)} | "
                    f"المطلوب الآن {len(missing_now)} جزء: {missing_now[:20]}"
                    f"{'...' if len(missing_now) > 20 else ''}")

            try:
                self.on_progress({
                    "current_batch": len(completed_existing),
                    "total_batches": len(shards),
                    "batch_pages": 0,
                })
            except Exception as e:
                # ✅ v27.8: تسجيل تشخيصي لأخطاء callback بدل كتمانها.
                safe_print(f"[PDFProcessor.on_progress:resume] error: {e}")

            if pending_shards:
                runner = ParallelExtractionRunner(
                    shards=pending_shards,
                    total_shards=len(shards),
                    book_path=self.in_path,
                    parts_dir=self.parts_dir,
                    model=self.model,
                    pool=pool,
                    global_key_mgr=self.global_key_mgr,
                    system_prompt=self.system_prompt,
                    cfg=self.cfg,
                    ckpt=ckpt,
                    comparator=comparator,
                    on_token=self.on_token,
                    on_log=log,
                    on_progress=self.on_progress,
                    on_upload_progress=self.on_upload_progress,
                    on_compare_submit=self.on_compare_partial,
                    on_request=self.on_request,
                    on_key_used=self.on_key_used,
                    on_stream_event=self.on_stream_event,
                    stop_event=self.stop_event,
                    pause_event=self.pause_event,
                    txt_context_mgr=txt_ctx_mgr,
                    force_fresh_upload=False,
                    already_done=len(completed_existing),
                    book_stem=self.book_stem,
                )
                try:
                    register_stop_component("runners", runner)
                except Exception:
                    pass
                try:
                    failed = runner.run()
                finally:
                    try:
                        unregister_stop_component("runners", runner)
                    except Exception:
                        pass
            else:
                log("✅ لا توجد أجزاء جديدة للمعالجة — كل الأجزاء مكتملة فعلياً.")
        except InterruptedError:
            log("⛔ مقاطعة فورية.")
        except Exception as e:
            log(f"💥 خطأ غير متوقع: {e}\n{traceback.format_exc()}")

        log("════ الدمج النهائي ════")
        extracted_set = detect_completed_part_indices(
            self.output_dir, self.book_stem, {s.idx for s in shards})
        missing = sorted({s.idx for s in shards} - extracted_set)
        pieces = []
        for s in shards:
            pf = self.parts_dir / f"{self.book_stem}_part_{s.idx:04d}.txt"
            if s.idx not in extracted_set or not pf.exists():
                continue
            try:
                pieces.append(pf.read_text(encoding="utf-8", errors="replace").rstrip())
            except Exception:
                if s.idx not in missing:
                    missing.append(s.idx)
        missing = sorted(set(missing))

        final_text = "\n\n".join(pieces)
        ok_count = len(extracted_set)
        failed_set = sorted(set(failed))
        log(f"  ناجحة: {ok_count}/{len(shards)} | "
            f"فاشلة: {len(failed_set)} | مفقودة: {len(missing)}")

        # ✅ v10.21: اكتمل الاستخراج → احفظ الكتاب فوراً باسم «<الكتاب>_غير مقارن.txt»
        # قبل انتظار المقارنات (حتى لا يضيع شيء لو توقفت المقارنة أو أُغلق البرنامج).
        uncompared_path = self.output_dir / f"{self.book_stem}{UNCOMPARED_SUFFIX}.txt"
        if comparator and not failed and not missing and final_text.strip():
            try:
                atomic_write_text(uncompared_path, final_text, encoding="utf-8")
                log(f"💾 اكتمل الاستخراج — حُفظ الكتاب غير المقارن: {uncompared_path.name} "
                    f"({count_words(final_text):,} كلمة)")
            except Exception as e:
                log(f"⚠️  تعذر حفظ نسخة «غير مقارن»: {e}")

        compare_summary = None
        if comparator:
            if self.stop_event.is_set():
                log("⛔ تم الإيقاف الفوري — تخطّي انتظار المقارنات.")
            else:
                log("⏳ انتظار اكتمال المقارنات الجزئية (يشمل إعادة المحاولات)...")
                try:
                    def _read_part_text(_sh):
                        return (self.parts_dir / f"{self.book_stem}_part_{_sh.idx:04d}.txt").read_text(
                            encoding="utf-8", errors="replace")
                    done = comparator.run_until_all_compared(shards, _read_part_text)
                    if done and not self.stop_event.is_set():
                        log("📊 توليد التقرير الشامل...")
                        try:
                            compare_summary = comparator.generate_final_report(
                                total_shards=len(shards))
                            if compare_summary:
                                try:
                                    self.on_compare_final(compare_summary)
                                except Exception as e:
                                    # ✅ v27.8: تسجيل تشخيصي لأخطاء callback بدل كتمانها.
                                    safe_print(f"[PDFProcessor.on_compare_final] error: {e}")
                        except Exception as e:
                            log(f"⚠️  فشل التقرير الشامل: {e}")
                except Exception as e:
                    log(f"⚠️  انتظار المقارن: {e}")
            try:
                comparator.stop(wait=True)
            except Exception:
                pass

        # ✅ v10.21: هل اكتملت المقارنة لكل الأجزاء؟
        compare_not_done: List[int] = []
        if comparator:
            try:
                compare_not_done = sorted({s.idx for s in shards} - comparator.compared_ok_indices())
            except Exception:
                compare_not_done = []

        try:
            if not failed and not missing and comparator and compare_not_done:
                # الاستخراج كامل لكن المقارنة ناقصة → يبقى «غير مقارن» فقط،
                # ولا نكتب الكتاب العادي ولا نحذف الأجزاء المؤقتة (لازمة لاستئناف المقارنة).
                log(f"⏹️ أُوقفت المقارنة قبل الاكتمال: بقي {len(compare_not_done)}/{len(shards)} جزء "
                    f"({compare_not_done[:20]}{'...' if len(compare_not_done) > 20 else ''})")
                log(f"📄 الملف المحفوظ حالياً: {uncompared_path.name} (غير مقارن). "
                    f"أعد تشغيل نفس الكتاب لاستئناف المقارنة؛ عند اكتمالها يُحذف هذا الملف "
                    f"ويُحفظ الكتاب الكامل المقارن.")
                log(f"ℹ️  الأجزاء محفوظة في: {shards_dir} (لاستئناف المقارنة)")
                pool.save_dirty()
                return FileResult(False, None, uncompared_path, len(shards),
                                    ok_count, [],
                                    f"اكتمل الاستخراج والمقارنة ناقصة ({len(compare_not_done)} جزء): "
                                    f"{uncompared_path}",
                                    file_path=self.in_path,
                                    compare_summary=compare_summary,
                                    is_txt=is_txt)
            if not failed and not missing:
                atomic_write_text(final_path, final_text, encoding="utf-8")
                # ✅ v10.21: اكتملت كل المقارنات → احذف «غير مقارن» (الكتاب العادي المقارن حُفظ للتو)
                try:
                    if uncompared_path.exists():
                        uncompared_path.unlink()
                        log(f"🗑️  حُذف «{uncompared_path.name}» — حُفظ الكتاب المقارن الكامل.")
                except Exception as _e_del:
                    log(f"⚠️  تعذر حذف «{uncompared_path.name}»: {_e_del}")
                try:
                    # ✅ v28.7: خزّن اسم الناتج الفعلي في book_meta
                    _fp = Path(final_path)
                    _name = _fp.name
                    for _suf in ["_مستخرج.INCOMPLETE.txt", "_معالج.INCOMPLETE.txt", "_مستخرج.txt", "_معالج.txt"]:
                        if _name.endswith(_suf):
                            _bstem = _name[:-len(_suf)]
                            break
                    else:
                        _bstem = _fp.stem
                    save_book_meta(_fp.parent, _bstem, {"final_output_file": str(_fp)})
                except Exception as _e_meta:
                    try:
                        LOGGER.debug("save final_output_file meta: %s", _e_meta)
                    except Exception:
                        pass

                log(f"✅ اكتمل! 📂 {final_path}")
                if not self.cfg.get("keep_shards_after_done", False):
                    cleanup_shards(shards_dir, log)
                else:
                    log(f"ℹ️  الأجزاء محفوظة في: {shards_dir}")
                # ✅ v27.8: حفظ إجباري لحالة المفاتيح عند نهاية معالجة كل ملف.
                pool.save_dirty()
                return FileResult(True, final_path, None, len(shards),
                                    ok_count, [],
                                    f"اكتمل: {final_path}",
                                    file_path=self.in_path,
                                    compare_summary=compare_summary,
                                    is_txt=is_txt)
            else:
                inc = final_path.with_suffix(".INCOMPLETE.txt")
                atomic_write_text(inc, final_text, encoding="utf-8")
                log(f"⚠️  ناتج جزئي: {inc}")
                log(f"ℹ️  الأجزاء محفوظة في: {shards_dir} (للاستئناف)")
                # ✅ v27.8: حفظ إجباري لحالة المفاتيح عند نهاية معالجة كل ملف.
                pool.save_dirty()
                return FileResult(False, None, inc, len(shards), ok_count,
                                    failed, f"ناتج جزئي. فاشلة: {failed}",
                                    file_path=self.in_path,
                                    compare_summary=compare_summary,
                                    is_txt=is_txt)
        except Exception as e:
            log(f"💥 فشل حفظ الناتج النهائي: {e}")
            # ✅ v27.8: حتى عند فشل الحفظ النهائي نحفظ حالة المفاتيح قبل الخروج.
            pool.save_dirty()
            return FileResult(False, None, None, len(shards), ok_count,
                                failed, f"فشل الحفظ: {e}",
                                file_path=self.in_path,
                                compare_summary=compare_summary,
                                is_txt=is_txt)


# ═══════════════════════════════════════════════════════════════════
#  Fetch Models
# ═══════════════════════════════════════════════════════════════════

def detect_model_family(model_id: str) -> str:
    mid = model_id.lower()
    if "gemini-3.1" in mid or "gemini-3-" in mid or "gemini-3." in mid:
        return "3"
    if "gemini-2.5" in mid: return "2.5"
    if "gemini-2.0" in mid: return "2.0"
    if "gemini-1.5" in mid: return "1.5"
    return "2.5"


def fetch_models_from_google(api_key: str, log=None) -> List[Dict[str, str]]:
    if log is None:
        log = lambda *a, **k: None
    client = genai.Client(
        api_key=api_key,
        http_options=types.HttpOptions(timeout=GENAI_HTTP_TIMEOUT_MS))
    try:
        register_stop_component("clients", client)
    except Exception:
        pass
    try:
        models_iter = client.models.list()
        result = []
        seen_ids = set()
        for model in models_iter:
            name = getattr(model, "name", "") or ""
            model_id = name.replace("models/", "").strip()
            if not model_id or model_id in seen_ids:
                continue
            if "gemini" not in model_id.lower():
                continue
            supported = (getattr(model, "supported_actions", None)
                         or getattr(model, "supported_generation_methods", None) or [])
            try:
                supported_list = [str(item).lower() for item in supported]
            except Exception:
                supported_list = []
            if supported_list and not any(
                    "generatecontent" in item or "generate_content" in item
                    for item in supported_list):
                continue
            if any(name in model_id.lower()
                   for name in ("embedding", "aqa", "imagen", "veo")):
                continue
            display = getattr(model, "display_name", None) or model_id
            description = getattr(model, "description", "") or ""
            result.append({
                "id": model_id,
                "label": f"{display} — {model_id}",
                "family": detect_model_family(model_id),
                "description": description[:200],
            })
            seen_ids.add(model_id)

        def sort_key(item):
            mid = item["id"].lower()
            if "gemini-3" in mid:
                return (0, mid)
            if "gemini-2.5" in mid:
                return (1, mid)
            if "gemini-2.0" in mid:
                return (2, mid)
            return (3, mid)

        result.sort(key=sort_key)
        log(f"✅ جُلب {len(result)} نموذج")
        return result
    finally:
        try:
            unregister_stop_component("clients", client)
        except Exception:
            pass
        try:
            if hasattr(client, "close"):
                client.close()
            elif getattr(client, "_transport", None) is not None:
                client._transport.close()
        except Exception:
            pass


# ═══════════════════════════════════════════════════════════════════
#  Recompare Worker (إعادة فحص مقارنات فاشلة فقط)
# ═══════════════════════════════════════════════════════════════════

# ═══════════════════════════════════════════════════════════════════
#  ✅ v24.0 MOD5: BaseCompareWorker — كلاس أساس مشترك للمقارنة
# ═══════════════════════════════════════════════════════════════════

class BaseCompareWorker(QObject):
    """كلاس أساس يحمل الإشارات المشتركة والمنطق المتكرر للمقارنة."""
    log = pyqtSignal(str)
    partial_result = pyqtSignal(object)
    final_result = pyqtSignal(dict)
    progress = pyqtSignal(int, int)
    finished = pyqtSignal()
    error = pyqtSignal(str)

    def _build_comparator(self, output_dir, book_stem, compare_model, cfg,
                           api_keys, global_key_mgr, stop_event) -> InlineComparator:
        return build_inline_comparator(
            output_dir, book_stem, compare_model, cfg,
            on_partial_result=lambda r: self.partial_result.emit(r),
            on_log=lambda m: self.log.emit(m),
            stop_event=stop_event,
            api_keys=api_keys,
            global_key_mgr=global_key_mgr,
            request_counter=getattr(self, 'request_counter', None)
        )

    def _wait_and_report(self, comparator: InlineComparator,
                          total_shards: int, timeout: float,
                          stop_event) -> None:
        wait_and_generate_final_report(
            comparator, total_shards, timeout, stop_event,
            log=lambda m: self.log.emit(m),
            on_final=lambda s: self.final_result.emit(s)
        )


class RecompareWorker(BaseCompareWorker):
    # ✅ الإشارات موروثة من BaseCompareWorker

    def __init__(self, output_dir: Path, book_stem: str,
                  shards: List[PDFShard], parts_dir: Path,
                  api_keys: List[str], compare_model: dict, cfg: dict,
                  shards_to_recompare: List[int],
                  global_key_mgr: GlobalKeyManager):
        super().__init__()
        self.output_dir = output_dir
        self.book_stem = book_stem
        self.shards = shards
        self.parts_dir = parts_dir
        self.api_keys = list(api_keys)
        self.compare_model = compare_model
        self.cfg = cfg
        self.shards_to_recompare = shards_to_recompare
        self.global_key_mgr = global_key_mgr
        self.request_counter: Optional[CentralRequestCounter] = None  # ✅ v25.5
        self.stop_event = threading.Event()

    def stop(self):
        self.stop_event.set()

    def run(self):
        try:
            comparator = self._build_comparator(
                self.output_dir, self.book_stem, self.compare_model,
                self.cfg, self.api_keys, self.global_key_mgr, self.stop_event)
            comparator.start()

            shard_map = {s.idx: s for s in self.shards}
            total = len(self.shards_to_recompare)
            done = 0
            skipped_no_text = []

            for idx in self.shards_to_recompare:
                if self.stop_event.is_set(): break
                shard = shard_map.get(idx)
                if not shard:
                    self.log.emit(f"⚠️  جزء {idx} غير موجود")
                    continue

                part_file = self.parts_dir / f"{self.book_stem}_part_{idx:04d}.txt"
                if not part_file.exists():
                    self.log.emit(
                        f"⏭️  جزء {idx}: لم يُستخرج بعد — يُتجاهل")
                    skipped_no_text.append(idx)
                    continue

                try:
                    extracted_text = part_file.read_text(
                        encoding="utf-8", errors="replace")
                    if not extracted_text.strip():
                        self.log.emit(
                            f"⏭️  جزء {idx}: ملف نصي فارغ — يُتجاهل")
                        skipped_no_text.append(idx)
                        continue
                except Exception as e:
                    self.log.emit(f"⚠️  فشل قراءة جزء {idx}: {e}")
                    continue

                # ✅ v24.0 MOD3: استخدام الدالة العامة الآمنة
                comparator.clear_result(idx)
                with_repair = bool(self.cfg.get("recompare_with_repair", False))
                self.log.emit(f"🗑️  [recompare] نُسفت مقارنة جزء {idx}"
                              + (" — وضع إصلاح" if with_repair else ""))
                comparator.submit(shard, extracted_text, None, None,
                                  force=True, with_repair=with_repair)
                done += 1
                self.progress.emit(done, total)

            if skipped_no_text:
                self.log.emit(
                    f"ℹ️  تم تجاهل {len(skipped_no_text)} جزء لم يُستخرج بعد: "
                    f"{skipped_no_text[:10]}"
                    f"{'...' if len(skipped_no_text) > 10 else ''}")

            # ✅ v24.0 MOD5: استخدام _wait_and_report الموحدة
            self._wait_and_report(comparator, len(self.shards), 1800, self.stop_event)
            comparator.stop(wait=True)
            self.finished.emit()
        except Exception as e:
            tb = traceback.format_exc()
            self.error.emit(f"{e}\n{tb}")


# ═══════════════════════════════════════════════════════════════════
#  ✨ v22: ManualRecheckWorker — إعادة فحص يدوي لأجزاء مختارة
#  (يرفع الـ PDF من جديد ويقارنه بالنص المستخرج الحالي)
# ═══════════════════════════════════════════════════════════════════

class ManualRecheckWorker(BaseCompareWorker):
    """
    إعادة فحص يدوي للأجزاء المختارة:
    - يحذف نتيجة المقارنة السابقة لكل جزء مختار
    - يرفع جزء الـ PDF من جديد (force_fresh)
    - يقارنه بالنص المستخرج الحالي من الملف
    - يستخدم برومبت أقوى يمنع ادعاء التطابق دون تدقيق
    """
    # ✅ v24.0 MOD5: الإشارات موروثة من BaseCompareWorker

    def __init__(self, output_dir: Path, book_stem: str,
                  shards: List[PDFShard], parts_dir: Path,
                  api_keys: List[str], compare_model: dict, cfg: dict,
                  selected_shards: List[int],
                  global_key_mgr: GlobalKeyManager):
        super().__init__()
        self.output_dir = output_dir
        self.book_stem = book_stem
        self.shards = shards
        self.parts_dir = parts_dir
        self.api_keys = list(api_keys)
        self.compare_model = compare_model
        self.cfg = cfg
        self.selected_shards = selected_shards
        self.global_key_mgr = global_key_mgr
        self.request_counter: Optional[CentralRequestCounter] = None  # ✅ v25.5
        self.stop_event = threading.Event()

    def stop(self):
        self.stop_event.set()

    def run(self):
        try:
            workers = self.cfg.get("compare_parallel_workers", 3)
            workers = max(1, min(workers, len(self.api_keys), 25))

            self.log.emit(
                f"🔬 بدء إعادة الفحص اليدوي لـ {len(self.selected_shards)} جزء مختار "
                f"(عمال متوازية: {workers})")
            self.log.emit("   📌 سيتم رفع PDF لكل جزء من جديد ومقارنته بنصه المستخرج")

            # ✅ v24.0 MOD5: استخدام _build_comparator الموحدة
            comparator = self._build_comparator(
                self.output_dir, self.book_stem, self.compare_model,
                self.cfg, self.api_keys, self.global_key_mgr, self.stop_event)
            comparator.start()

            shard_map = {s.idx: s for s in self.shards}
            total = len(self.selected_shards)
            done = 0
            skipped_no_text = []

            for idx in self.selected_shards:
                if self.stop_event.is_set(): break
                shard = shard_map.get(idx)
                if not shard:
                    self.log.emit(f"⚠️  جزء {idx} غير موجود في قائمة الأجزاء")
                    continue

                part_file = self.parts_dir / f"{self.book_stem}_part_{idx:04d}.txt"
                if not part_file.exists():
                    self.log.emit(
                        f"⏭️  جزء {idx}: لا يوجد نص مستخرج — يُتجاهل")
                    skipped_no_text.append(idx)
                    continue

                try:
                    extracted_text = part_file.read_text(
                        encoding="utf-8", errors="replace")
                    if not extracted_text.strip():
                        self.log.emit(f"⏭️  جزء {idx}: ملف نصي فارغ — يُتجاهل")
                        skipped_no_text.append(idx)
                        continue
                except Exception as e:
                    self.log.emit(f"⚠️  فشل قراءة جزء {idx}: {e}")
                    continue

                # ✅ v24.0 MOD3: استخدام الدالة العامة الآمنة
                comparator.clear_result(idx)
                with_repair = bool(self.cfg.get("recompare_with_repair", False))
                self.log.emit(f"🗑️  [manual] نُسفت مقارنة جزء {idx}"
                              + (" — وضع إصلاح" if with_repair else ""))
                # ✅ إرسال للمقارنة (سيرفع الـ PDF من جديد - force_fresh في الـ comparator)
                comparator.submit(shard, extracted_text, None, None,
                                  force=True, with_repair=with_repair)
                done += 1
                self.progress.emit(done, total)

            if skipped_no_text:
                self.log.emit(
                    f"ℹ️  تجاهل {len(skipped_no_text)} جزء بدون نص: "
                    f"{skipped_no_text[:10]}"
                    f"{'...' if len(skipped_no_text) > 10 else ''}")

            # ✅ v24.0 MOD5: استخدام _wait_and_report الموحدة
            self._wait_and_report(comparator, len(self.shards), 3600, self.stop_event)
            comparator.stop(wait=True)
            self.log.emit("✅ اكتملت إعادة الفحص اليدوي")
            self.finished.emit()
        except Exception as e:
            tb = traceback.format_exc()
            self.error.emit(f"{e}\n{tb}")


# ═══════════════════════════════════════════════════════════════════
#  Reextract Worker (إعادة استخراج + مقارنة)
# ═══════════════════════════════════════════════════════════════════

class ReextractWorker(QObject):
    log = pyqtSignal(str)
    token_received = pyqtSignal(str)
    stream_event = pyqtSignal(object)
    progress_one = pyqtSignal(int, int)
    partial_compare_ready = pyqtSignal(object)
    final_result = pyqtSignal(dict)
    finished = pyqtSignal()
    error = pyqtSignal(str)

    def __init__(self, book_path: Path, book_stem: str, output_dir: Path,
                  parts_dir: Path, shards: List[PDFShard],
                  shards_to_redo: List[int], tokens_path: Path,
                  system_prompt: str, model: dict,
                  compare_model: dict, cfg: dict,
                  enable_compare: bool,
                  global_key_mgr: GlobalKeyManager,
                  app_dir: Path):
        super().__init__()
        self.book_path = book_path
        self.book_stem = book_stem
        self.output_dir = output_dir
        self.parts_dir = parts_dir
        self.shards = shards
        self.shards_to_redo = shards_to_redo
        self.tokens_path = tokens_path
        self.system_prompt = system_prompt
        self.model = model
        self.compare_model = compare_model
        self.cfg = cfg
        self.enable_compare = enable_compare
        self.global_key_mgr = global_key_mgr
        self.app_dir = app_dir
        self.request_counter: Optional[CentralRequestCounter] = None  # ✅ v29.0
        self.stop_event = threading.Event()
        self.pause_event = threading.Event()

    def stop(self):
        self.stop_event.set()

    def run(self):
        try:
            def log(m):
                try:
                    self.log.emit(m)
                except RuntimeError:
                    safe_print(f"[AutoLoop] {m}")
            log(f"🔁 بدء إعادة استخراج {len(self.shards_to_redo)} جزء...")

            shard_map = {s.idx: s for s in self.shards}
            is_txt_book = is_txt_file(self.book_path)
            parent_stem = self.book_stem

            try:
                pool, ckpt, txt_ctx_mgr = bootstrap_book_runtime(
                    self.output_dir, parent_stem, self.tokens_path,
                    self.cfg, self.app_dir, is_txt_book, self.book_path, log_fn=log
                )
            except Exception as e:
                self.error.emit(f"فشل تحميل المفاتيح والبيئة: {e}"); return

            all_keys = [s.key for s in sorted(pool.states.values(), key=lambda s: (s.fail_count, -s.success_count, s.masked))]
            if not all_keys:
                self.error.emit("لا مفتاح متاح حالياً!"); return

            comparator: Optional[InlineComparator] = None
            allow_txt_custom_compare = bool(is_txt_book and str(self.cfg.get("active_prompt_kind", "")) == "custom"
                                            and self.cfg.get("custom_compare_enabled", True)
                                            and str(self.cfg.get("custom_compare_prompt", "")).strip())
            if self.enable_compare and (not is_txt_book or allow_txt_custom_compare):
                try:
                    api_keys = [s.key for s in pool.states.values()]
                    workers = self.cfg.get("compare_parallel_workers", 3)
                    workers = max(1, min(workers, len(api_keys), 25))
                    comparator = InlineComparator(
                        output_dir=self.output_dir,
                        book_stem=parent_stem,
                        model_id=self.compare_model["id"],
                        model_family=self.compare_model["family"],
                        cfg=self.cfg,
                        on_partial_result=lambda r: self.partial_compare_ready.emit(r),
                        on_log=log,
                        stop_event=self.stop_event,
                        api_keys=api_keys,
                        global_key_mgr=self.global_key_mgr,
                        parallel_workers=workers,
                        request_counter=self.request_counter)
                    comparator.start()
                    try:
                        register_stop_component("comparators", comparator)
                    except Exception:
                        pass
                except Exception as e:
                    log(f"⚠️  تعذر بدء المقارن: {e}")
                    comparator = None

            redo_shards: List[PDFShard] = []
            for idx in self.shards_to_redo:
                shard = shard_map.get(idx)
                if not shard:
                    log(f"⚠️  جزء {idx} غير موجود")
                    continue
                log(f"🗑️  [reextract] تجهيز جزء {idx} لإعادة الاستخراج")
                part_file = self.parts_dir / f"{self.book_stem}_part_{idx:04d}.txt"
                if part_file.exists():
                    try:
                        part_file.unlink()
                        log(f"🗑️  حُذف الملف القديم: {part_file.name}")
                    except Exception as e:
                        log(f"⚠️  تعذر حذف {part_file.name}: {e}")
                ckpt.clear(idx)
                if comparator:
                    comparator.clear_result(idx)
                redo_shards.append(shard)

            total = len(redo_shards)
            failed_idx = []
            if redo_shards:
                runner = ParallelExtractionRunner(
                    shards=redo_shards,
                    total_shards=len(self.shards),
                    book_path=self.book_path,
                    parts_dir=self.parts_dir,
                    model=self.model,
                    pool=pool,
                    global_key_mgr=self.global_key_mgr,
                    system_prompt=self.system_prompt,
                    cfg=self.cfg,
                    ckpt=ckpt,
                    comparator=comparator,
                    on_token=lambda t: self.token_received.emit(t),
                    on_log=log,
                    on_progress=lambda info: self.progress_one.emit(min(info.get("current_batch", 0), total), total) if "current_batch" in info and total > 0 else None,
                    on_upload_progress=lambda _p: None,
                    on_compare_submit=lambda _r: None,
                    on_request=(lambda desc: (
                                  self.request_counter.increment(f"إعادة استخراج {desc}"),
                                  log(f"🔁 طلب رقم {self.request_counter.count} أُرسل (إعادة استخراج {desc})")
                              ) if self.request_counter else None),
                    on_key_used=None,
                    on_stream_event=lambda e: self.stream_event.emit(e),
                    stop_event=self.stop_event,
                    pause_event=self.pause_event,
                    txt_context_mgr=txt_ctx_mgr,
                    force_fresh_upload=True,
                    already_done=0)
                try:
                    register_stop_component("runners", runner)
                except Exception:
                    pass
                try:
                    failed_idx = runner.run()
                finally:
                    try:
                        unregister_stop_component("runners", runner)
                    except Exception:
                        pass
            log("\n════ إعادة دمج الملف النهائي ════")
            rebuild_and_save_final_output(self.output_dir, parent_stem, self.parts_dir, self.shards, is_txt_book, log, make_backup=True)

            if comparator:
                if not self.stop_event.is_set():
                    log("⏳ انتظار اكتمال المقارنات (مع إعادة المحاولات)...")
                    try:
                        comparator.wait_until_done(timeout=1800)
                        if not self.stop_event.is_set():
                            log("📊 توليد التقرير الشامل...")
                            try:
                                summary = comparator.generate_final_report(
                                    total_shards=len(self.shards))
                                if summary:
                                    self.final_result.emit(summary)
                            except Exception as e:
                                log(f"⚠️  فشل التقرير: {e}")
                    except Exception as e:
                        log(f"⚠️  انتظار: {e}")
                try:
                    comparator.stop(wait=True)
                except Exception:
                    pass

            if failed_idx:
                log(f"⚠️  أجزاء فشلت: {failed_idx}")

            self.finished.emit()
        except Exception as e:
            tb = traceback.format_exc()
            self.error.emit(f"{e}\n{tb}")


# ═══════════════════════════════════════════════════════════════════
#  AutoLoopWorker — النظام التلقائي للحلقة
# ═══════════════════════════════════════════════════════════════════

class AutoLoopWorker(QObject):
    log = pyqtSignal(str)
    token_received = pyqtSignal(str)
    stream_event = pyqtSignal(object)
    iteration_started = pyqtSignal(int, int)
    partial_compare_ready = pyqtSignal(object)
    final_result = pyqtSignal(dict)
    progress_one = pyqtSignal(int, int)
    finished = pyqtSignal(dict)
    error = pyqtSignal(str)

    def __init__(self, book_path: Path, output_dir: Path,
                  parts_dir: Path, shards: List[PDFShard],
                  tokens_path: Path, system_prompt: str,
                  model: dict, compare_model: dict, cfg: dict,
                  threshold_pct: int, max_iterations: int,
                  global_key_mgr: GlobalKeyManager,
                  app_dir: Path,
                  initial_partial_results: Dict[int, ShardComparisonResult]):
        super().__init__()
        self.request_counter = None  # ✅ v29.0
        self.book_path = book_path
        self.output_dir = output_dir
        self.parts_dir = parts_dir
        self.shards = shards
        self.tokens_path = tokens_path
        self.system_prompt = system_prompt
        self.model = model
        self.compare_model = compare_model
        self.cfg = cfg
        self.threshold_pct = threshold_pct
        self.max_iterations = max_iterations
        self.global_key_mgr = global_key_mgr
        self.app_dir = app_dir
        self.partial_results = dict(initial_partial_results)
        self.stop_event = threading.Event()
        self.request_counter: Optional[CentralRequestCounter] = None

    def stop(self):
        self.stop_event.set()

    def _detect_weak_shards(self) -> List[int]:
        weak = []
        for shard in self.shards:
            if shard.is_txt:
                continue
            part_file = self.parts_dir / f"{self.book_stem}_part_{shard.idx:04d}.txt"
            if not part_file.exists() or part_file.stat().st_size <= 0:
                weak.append(shard.idx)
                continue
            r = self.partial_results.get(shard.idx)
            if r is None:
                continue  # لم تتم مقارنته بعد — يحتاج مقارنة أولاً، وليس إعادة استخراج
            if r.error is not None:
                weak.append(shard.idx)
                continue
            # ✅ v25.5: تجاهل الأجزاء التي فشل تحليل JSON فيها
            if r.coverage_pct == -1:
                continue  # غير محدد — يحتاج إعادة فحص لا إعادة استخراج
            if r.coverage_pct < self.threshold_pct:
                weak.append(shard.idx)
        return sorted(set(weak))

    def _detect_uncompared_shards(self) -> List[int]:
        uncompared = []
        for shard in self.shards:
            if shard.is_txt:
                continue
            part_file = self.parts_dir / f"{self.book_stem}_part_{shard.idx:04d}.txt"
            if part_file.exists() and part_file.stat().st_size > 0:
                r = self.partial_results.get(shard.idx)
                if r is None:
                    uncompared.append(shard.idx)
        return sorted(set(uncompared))

    def _compare_uncompared_shards(self):
        log = lambda m: self.log.emit(m)
        uncompared = self._detect_uncompared_shards()
        if not uncompared:
            return
            
        log(f"🔬 كُشف {len(uncompared)} جزء غير مقارن بعد. جاري بدء مقارنتها أولاً...")
        
        api_keys = []
        if self.tokens_path.exists():
            for line in self.tokens_path.read_text(encoding="utf-8", errors="replace").splitlines():
                line = line.strip()
                if line and not line.startswith("#"):
                    api_keys.append(line)
                    
        if not api_keys:
            log("🚫 لا مفاتيح API متاحة لمقارنة الأجزاء غير المقارنة.")
            return
            
        workers = self.cfg.get("compare_parallel_workers", 3)
        workers = max(1, min(workers, len(api_keys), 25))
        
        try:
            comparator = InlineComparator(
                output_dir=self.output_dir,
                book_stem=self.book_stem,
                model_id=self.compare_model["id"],
                model_family=self.compare_model["family"],
                cfg=self.cfg,
                on_partial_result=self._on_partial_compare,
                on_log=log,
                stop_event=self.stop_event,
                api_keys=api_keys,
                global_key_mgr=self.global_key_mgr,
                parallel_workers=workers,
                request_counter=self.request_counter)
            comparator.start()
            try:
                register_stop_component("comparators", comparator)
            except Exception:
                pass
            
            shard_map = {s.idx: s for s in self.shards}
            for idx in uncompared:
                if self.stop_event.is_set():
                    break
                shard = shard_map.get(idx)
                if not shard:
                    continue
                part_file = self.parts_dir / f"{self.book_stem}_part_{idx:04d}.txt"
                if part_file.exists():
                    try:
                        text = part_file.read_text(encoding="utf-8", errors="replace")
                        comparator.submit(shard, text, api_key_hint=None, file_uri_hint=None)
                    except Exception as e:
                        log(f"⚠️ فشل إرسال جزء {idx} للمقارنة: {e}")
                        
            comparator.wait_until_done(timeout=1800)
            comparator.stop(wait=True)
            try:
                unregister_stop_component("comparators", comparator)
            except Exception:
                pass
            log(f"✅ تم الانتهاء من مقارنة {len(uncompared)} جزء غير مقارن سابقاً.")
        except Exception as e:
            log(f"⚠️ فشل مقارنة الأجزاء غير المقارنة: {e}")

    def run(self):
        try:
            log = lambda m: self.log.emit(m)
            log(f"\n{'═' * 60}")
            log(f"  🤖 بدء النظام التلقائي (Auto-Loop)")
            log(f"  • الحد المطلوب: ≥ {self.threshold_pct}%")
            max_label = "∞ (لا نهائي)" if self.max_iterations <= 0 else str(self.max_iterations)
            log(f"  • الحد الأقصى للمحاولات: {max_label}")
            log(f"{'═' * 60}\n")

            iteration = 0
            history = []

            while not self.stop_event.is_set():
                iteration += 1
                if self.max_iterations > 0 and iteration > self.max_iterations:
                    log(f"⛔ تم بلوغ الحد الأقصى للمحاولات ({self.max_iterations})")
                    break

                self._compare_uncompared_shards()

                weak = self._detect_weak_shards()
                if not weak:
                    log(f"\n✅ ممتاز! كل الأجزاء فوق الحد ({self.threshold_pct}%) — التوقف.")
                    history.append({
                        "iteration": iteration,
                        "weak_count": 0,
                        "status": "completed"
                    })
                    break

                log(f"\n{'─' * 60}")
                log(f"🔄 المحاولة {iteration}"
                    + (f"/{self.max_iterations}" if self.max_iterations > 0 else "")
                    + f": كُشف {len(weak)} جزء تحت الحد ({self.threshold_pct}%)")
                log(f"   الأجزاء: {weak[:20]}{'...' if len(weak) > 20 else ''}")
                log(f"{'─' * 60}\n")

                self.iteration_started.emit(iteration, self.max_iterations)

                history.append({
                    "iteration": iteration,
                    "weak_count": len(weak),
                    "weak_shards": weak[:50],
                    "status": "running"
                })

                ok_extract = self._reextract_shards(weak)
                if not ok_extract or self.stop_event.is_set():
                    log("⛔ فشل/توقف إعادة الاستخراج")
                    history[-1]["status"] = "extract_failed"
                    break

                if self.stop_event.is_set():
                    break

                self._rebuild_final_file()

                history[-1]["status"] = "completed"

                if not self.stop_event.is_set():
                    try:
                        interruptible_sleep(2.0, self.stop_event)
                    except InterruptedError:
                        break

            final_weak = self._detect_weak_shards()
            summary = {
                "iterations_done": iteration - (1 if self.max_iterations > 0 and iteration > self.max_iterations else 0),
                "final_weak_count": len(final_weak),
                "final_weak_shards": final_weak,
                "threshold_pct": self.threshold_pct,
                "completed": len(final_weak) == 0,
                "stopped": self.stop_event.is_set(),
                "history": history,
            }

            log(f"\n{'═' * 60}")
            if summary["completed"]:
                log(f"  ✅ النظام التلقائي اكتمل بنجاح!")
                log(f"  • كل الأجزاء فوق {self.threshold_pct}%")
            elif summary["stopped"]:
                log(f"  ⛔ تم إيقاف النظام التلقائي")
                log(f"  • {len(final_weak)} جزء لا يزال تحت الحد")
            else:
                log(f"  ⚠️  انتهى عدد المحاولات")
                log(f"  • {len(final_weak)} جزء لا يزال تحت الحد")
            log(f"  • المحاولات: {summary['iterations_done']}")
            log(f"{'═' * 60}\n")

            try:
                self._generate_final_report()
            except Exception as e:
                log(f"⚠️  فشل التقرير الشامل: {e}")

            self.finished.emit(summary)

        except Exception as e:
            tb = traceback.format_exc()
            try:
                self.error.emit(f"{e}\n{tb}")
            except RuntimeError:
                safe_print(f"[AutoLoop] خطأ (الكائن محذوف): {e}\n{tb}")

    def _reextract_shards(self, shard_indices: List[int]) -> bool:
        log = lambda m: self.log.emit(m)

        checkpoints_dir = get_book_checkpoints_dir(self.output_dir, self.book_path.stem)
        checkpoints_dir.mkdir(parents=True, exist_ok=True)
        global_state_path = self.app_dir / KeyPool.GLOBAL_STATE_FILENAME
        try:
            pool = KeyPool(
                self.tokens_path,
                checkpoints_dir / "keys_state.json",
                self.cfg,
                global_state_path=global_state_path)
        except Exception as e:
            log(f"💥 فشل تحميل المفاتيح: {e}")
            return False
        try:
            register_stop_component("keypools", pool)
        except Exception:
            pass

        ckpt = Checkpoint(checkpoints_dir / "checkpoint.json")
        try:
            register_stop_component("checkpoints", ckpt)
        except Exception:
            pass
        is_txt_book = is_txt_file(self.book_path)

        txt_ctx_mgr = None
        if is_txt_book and should_upload_full_txt_context(self.cfg):
            txt_ctx_mgr = TxtContextManager(self.book_path, log)

        all_keys = [s.key for s in sorted(pool.states.values(), key=lambda s: (s.fail_count, -s.success_count, s.masked))]
        if not all_keys:
            log("🚫 لا مفتاح متاح حالياً!")
            return False

        comparator: Optional[InlineComparator] = None
        if not is_txt_book:
            try:
                api_keys = [s.key for s in pool.states.values()]
                workers = self.cfg.get("compare_parallel_workers", 3)
                workers = max(1, min(workers, len(api_keys), 25))
                comparator = InlineComparator(
                    output_dir=self.output_dir,
                    book_stem=self.book_path.stem,
                    model_id=self.compare_model["id"],
                    model_family=self.compare_model["family"],
                    cfg=self.cfg,
                    on_partial_result=self._on_partial_compare,
                    on_log=log,
                    stop_event=self.stop_event,
                    api_keys=api_keys,
                    global_key_mgr=self.global_key_mgr,
                    parallel_workers=workers,
                    request_counter=self.request_counter)
                comparator.start()
                try:
                    register_stop_component("comparators", comparator)
                except Exception:
                    pass
            except Exception as e:
                log(f"⚠️  تعذر بدء المقارن: {e}")
                comparator = None

        shard_map = {s.idx: s for s in self.shards}
        redo_shards: List[PDFShard] = []
        total = len(shard_indices)
        for idx in shard_indices:
            if self.stop_event.is_set():
                break
            shard = shard_map.get(idx)
            if not shard:
                log(f"⚠️  جزء {idx} غير موجود")
                continue
            log(f"\n════ ♻️ إعادة استخراج جزء {idx} (تلقائي) ════")
            part_file = self.parts_dir / f"{self.book_stem}_part_{idx:04d}.txt"
            if part_file.exists():
                try:
                    part_file.unlink()
                except Exception:
                    pass
            ckpt.clear(idx)
            if comparator:
                comparator.clear_result(idx)
                log(f"🗑️  [autoloop] نُسفت مقارنة جزء {idx} القديمة")
            self.partial_results.pop(idx, None)
            redo_shards.append(shard)

        if redo_shards:
            runner = ParallelExtractionRunner(
                shards=redo_shards,
                total_shards=len(self.shards),
                book_path=self.book_path,
                parts_dir=self.parts_dir,
                model=self.model,
                pool=pool,
                global_key_mgr=self.global_key_mgr,
                system_prompt=self.system_prompt,
                cfg=self.cfg,
                ckpt=ckpt,
                comparator=comparator,
                on_token=lambda t: self.token_received.emit(t),
                on_log=log,
                on_progress=lambda info: self.progress_one.emit(min(info.get("current_batch", 0), total), total) if "current_batch" in info and total > 0 else None,
                on_upload_progress=lambda _p: None,
                on_compare_submit=lambda _r: None,
                on_request=(lambda desc: (
                              self.request_counter.increment(f"تلقائي {desc}"),
                              log(f"🔁 طلب رقم {self.request_counter.count} أُرسل (تلقائي {desc})")
                          ) if self.request_counter else None),
                on_key_used=None,
                on_stream_event=lambda e: self.stream_event.emit(e),
                stop_event=self.stop_event,
                pause_event=threading.Event(),
                txt_context_mgr=txt_ctx_mgr,
                force_fresh_upload=True,
                already_done=0)
            try:
                register_stop_component("runners", runner)
            except Exception:
                pass
            try:
                runner.run()
            finally:
                try:
                    unregister_stop_component("runners", runner)
                except Exception:
                    pass

        if comparator:
            if not self.stop_event.is_set():
                log("⏳ انتظار اكتمال المقارنات...")
                try:
                    comparator.wait_until_done(timeout=1800)
                except Exception as e:
                    log(f"⚠️  انتظار: {e}")
            try:
                comparator.stop(wait=True)
            except Exception:
                pass

        return True

    def _on_partial_compare(self, result: ShardComparisonResult):
        # ✅ FIX: منع التكرار + logging
        old = self.partial_results.get(result.shard_idx)
        if old is not None and old is not result:
            self.log.emit(f"📊 [autoloop] تحديث جزء {result.shard_idx}: "
                          f"{old.coverage_pct}% → {result.coverage_pct}% "
                          f"({result.assessment})")
        self.partial_results[result.shard_idx] = result
        try:
            self.partial_compare_ready.emit(result)
        except Exception:
            pass

    def _rebuild_final_file(self):
        log = lambda m: self.log.emit(m)
        is_txt_book = is_txt_file(self.book_path)
        rebuild_and_save_final_output(self.output_dir, self.book_path.stem, self.parts_dir, self.shards, is_txt_book, log, make_backup=True)

    def _generate_final_report(self):
        # ✅ v24.2: حماية من حذف الكائن C++ أثناء التشغيل
        def safe_log(m):
            try:
                self.log.emit(m)
            except RuntimeError:
                safe_print(f"[AutoLoop-report] {m}")

        def safe_emit_result(summary):
            try:
                self.final_result.emit(summary)
            except RuntimeError:
                safe_print("[AutoLoop-report] تعذر إرسال النتيجة — الكائن محذوف")

        try:
            api_keys = []
            if self.tokens_path.exists():
                for line in self.tokens_path.read_text(
                    encoding="utf-8", errors="replace").splitlines():
                    line = line.strip()
                    if line and not line.startswith("#"):
                        api_keys.append(line)

            comparator = InlineComparator(
                output_dir=self.output_dir,
                book_stem=self.book_path.stem,
                model_id=self.compare_model["id"],
                model_family=self.compare_model["family"],
                cfg=self.cfg,
                on_partial_result=lambda r: None,
                on_log=safe_log,
                stop_event=self.stop_event,
                api_keys=api_keys,
                global_key_mgr=self.global_key_mgr,
                parallel_workers=1)
            comparator.set_results(self.partial_results)
            summary = comparator.generate_final_report(total_shards=len(self.shards))
            if summary:
                safe_emit_result(summary)
        except RuntimeError:
            safe_print("[AutoLoop-report] الكائن C++ محذوف — تخطي التقرير")
        except Exception as e:
            safe_log(f"⚠️  فشل التقرير: {e}")


# ═══════════════════════════════════════════════════════════════════
#  Workers: Fetch + Processing
# ═══════════════════════════════════════════════════════════════════


# ═══════════════════════════════════════════════════════════════════
#  ✅ v28.5: مقارنة كلية للكتاب (PDF كامل × الناتج النهائي)
# ═══════════════════════════════════════════════════════════════════

class FullBookCompareWorker(QObject):
    log = pyqtSignal(str)
    finished_result = pyqtSignal(dict)
    finished = pyqtSignal()
    error = pyqtSignal(str)
    progress = pyqtSignal(str)

    def __init__(self, original_pdf: Path, extracted_txt: Path,
                 api_keys: List[str], compare_model: dict, cfg: dict,
                 global_key_mgr: 'GlobalKeyManager', book_stem: str = ""):
        super().__init__()
        self.original_pdf = Path(original_pdf)
        self.extracted_txt = Path(extracted_txt)
        self.api_keys = list(api_keys or [])
        self.compare_model = compare_model or {}
        self.cfg = dict(cfg or {})
        self.global_key_mgr = global_key_mgr
        self.book_stem = book_stem or self.original_pdf.stem
        self.stop_event = threading.Event()
        self.request_counter: Optional[CentralRequestCounter] = None
        self._safe_temp_path: Optional[Path] = None
        self._held_key: Optional[str] = None
        self._held_model: Optional[str] = None

    def stop(self):
        self.stop_event.set()

    @staticmethod
    def _is_ascii_safe(s: str) -> bool:
        try:
            s.encode("ascii")
            return True
        except UnicodeEncodeError:
            return False

    @staticmethod
    def _safe_int(val, default: int = 0) -> int:
        try:
            if val is None:
                return default
            return int(float(str(val).strip().replace("%", "")))
        except Exception:
            return default

    def _ascii_upload_path(self, src_path: Path, log) -> Tuple[Path, str]:
        src_path = Path(src_path)
        try:
            digest = hashlib.md5(str(src_path.resolve()).encode("utf-8", errors="replace")).hexdigest()[:16]
        except Exception:
            digest = hashlib.md5(str(src_path).encode("utf-8", errors="replace")).hexdigest()[:16]
        cache_key = f"fullbook_{digest}"
        try:
            path, name = resolve_ascii_safe_upload_path(src_path, cache_key, ext=".pdf", original_fallback_name="book_original.pdf")
            self._safe_temp_path = path
            return path, name
        except Exception as e:
            raise RuntimeError(f"تعذر نسخ PDF لمسار ASCII آمن: {e}")

    def _release_key(self):
        if self._held_key and self._held_model and self.global_key_mgr:
            try:
                self.global_key_mgr.release_key(self._held_key, self._held_model)
            except Exception:
                pass
        self._held_key = None
        self._held_model = None

    def _wait_file_active(self, client, f_obj, log, timeout: float = 180.0):
        return wait_for_file_active(client, f_obj, self.stop_event, log=log, timeout=timeout)

    def run(self):
        api_key = None
        model_id = None
        client = None
        try:
            if self.stop_event.is_set():
                return
            if not self.original_pdf.exists():
                self.error.emit(f"ملف الأصل غير موجود:\n{self.original_pdf}")
                return
            if not self.extracted_txt.exists():
                self.error.emit(f"ملف الناتج النهائي غير موجود:\n{self.extracted_txt}")
                return
            if not self.api_keys:
                self.error.emit("لا مفاتيح API متاحة.")
                return
            model_id = self.compare_model.get("id") or self.cfg.get("model_id")
            model_family = self.compare_model.get("family") or self.cfg.get("model_family") or ""
            if not model_id:
                self.error.emit("لم يُحدد نموذج المقارنة.")
                return

            self.progress.emit("قراءة الناتج النهائي...")
            try:
                extracted = self.extracted_txt.read_text(encoding="utf-8", errors="replace")
            except Exception as e:
                self.error.emit(f"تعذر قراءة الناتج النهائي (تحقق من المسار العربي/الصلاحيات):\n{e}")
                return
            if not extracted.strip():
                self.error.emit("ملف الناتج النهائي فارغ.")
                return

            max_chars = int(self.cfg.get("compare_max_input_chars", 200000) or 200000)
            max_chars = max(max_chars, 200000)
            # سقف واقعي لطلب واحد
            max_chars = min(max_chars, 350000)
            truncated = False
            if len(extracted) > max_chars:
                extracted = extracted[:max_chars] + "\n\n[...اقتُطع جزء من النص للمقارنة بسبب الطول...]"
                truncated = True
                self.log.emit(f"⚠️ النص النهائي طويل — أُرسلت أول {max_chars:,} حرف للمقارنة")

            prompt_kind = str(self.cfg.get("active_prompt_kind", "default") or "default")
            remove_headers = bool(self.cfg.get("remove_headers", True))
            mode_note = {
                "default": "استخراج نص",
                "translate": "ترجمة",
                "summarize": "تلخيص",
                "custom": "مخصص",
            }.get(prompt_kind, prompt_kind)
            headers_note = "حذف الهوامش/الترويسات مفعّل" if remove_headers else "الاحتفاظ بالهوامش/الترويسات مفعّل"

            # مفتاح
            try:
                api_key = self.global_key_mgr.acquire_key(
                    self.api_keys, model_id, timeout=90.0, stop_event=self.stop_event)
            except Exception:
                api_key = None
            if not api_key:
                api_key = self.api_keys[0]
            else:
                self._held_key = api_key
                self._held_model = model_id

            masked = api_key[:6] + "..." + api_key[-4:] if len(api_key) > 10 else "****"
            self.progress.emit(f"تجهيز PDF للرفع (مفتاح {masked})...")
            self.log.emit(f"📘 مقارنة كلية: {self.original_pdf.name}  ×  {self.extracted_txt.name}")

            # مسار رفع ASCII-safe
            try:
                upload_path, safe_name = self._ascii_upload_path(self.original_pdf, self.log.emit)
            except Exception as e:
                self.error.emit(str(e))
                return

            if self.stop_event.is_set():
                return

            client = genai.Client(api_key=api_key, http_options=types.HttpOptions(timeout=GENAI_HTTP_TIMEOUT_MS))
            try:
                register_stop_component("clients", client)
            except Exception:
                pass
            self.progress.emit("رفع PDF الأصلي بالكامل...")
            throttle_key_send(api_key, self.stop_event, self.log.emit, purpose="upload")
            try:
                # display_name يجب أن يكون ASCII لتجنّب UnicodeEncodeError على Windows
                disp = safe_name if self._is_ascii_safe(safe_name) else "book_original.pdf"
                try:
                    f_obj = client.files.upload(
                        file=str(upload_path),
                        config=types.UploadFileConfig(
                            mime_type="application/pdf",
                            display_name=disp))
                except UnicodeEncodeError:
                    f_obj = client.files.upload(
                        file=str(upload_path),
                        config=types.UploadFileConfig(mime_type="application/pdf"))
                except TypeError:
                    # إصدارات أقدم من المكتبة
                    f_obj = client.files.upload(file=str(upload_path))
            except Exception as e:
                self.error.emit(
                    "فشل رفع PDF الأصلي.\n"
                    f"المسار الأصلي: {self.original_pdf}\n"
                    f"مسار الرفع: {upload_path}\n"
                    f"الخطأ: {e}")
                return

            try:
                self.progress.emit("انتظار تجهيز الملف على الخادم...")
                f_obj = self._wait_file_active(client, f_obj, self.log.emit, timeout=180.0)
                file_uri = getattr(f_obj, "uri", None)
                if not file_uri:
                    # بعض الإصدارات تستخدم name فقط
                    file_uri = getattr(f_obj, "name", None)
                if not file_uri:
                    self.error.emit("تم الرفع لكن لم يُرجع URI صالح للملف.")
                    return
            except InterruptedError:
                return
            except Exception as e:
                self.error.emit(f"الملف رُفع لكن لم يصبح جاهزاً: {e}")
                return

            if self.stop_event.is_set():
                return

            self.progress.emit("إرسال طلب المقارنة الكلية...")
            # لا تضع مسارات عربية طويلة داخل البرومبت إن سببت مشاكل ترميز — اسم مختصر فقط
            safe_book_label = self.book_stem
            try:
                if not self._is_ascii_safe(safe_book_label):
                    safe_book_label = f"book_{hashlib.md5(safe_book_label.encode('utf-8', errors='replace')).hexdigest()[:10]}"
            except Exception:
                safe_book_label = "book"

            user_prompt = (
                f"الكتاب: {self.book_stem}\n"
                f"وضع المعالجة: {mode_note}\n"
                f"إعداد الهوامش: {headers_note}\n"
                f"{'⚠️ النص النهائي مُقتطع للطول.' if truncated else ''}\n\n"
                f"النص المستخرج/المعالج النهائي:\n"
                f"━━━━━━━━━ بداية الناتج ━━━━━━━━━\n"
                f"{extracted}\n"
                f"━━━━━━━━━ نهاية الناتج ━━━━━━━━━\n\n"
                f"📌 افحص الكتاب الأصلي (PDF الكامل) مقابل الناتج النهائي فحصاً مدقّقاً.\n"
                f"📌 أخرج JSON فقط حسب system instructions."
            )
            # بناء المحتوى: فضّل file_uri، مع fallback على name
            try:
                file_part = types.Part(file_data=types.FileData(
                    mime_type="application/pdf", file_uri=str(file_uri)))
            except Exception:
                file_part = types.Part.from_uri(file_uri=str(file_uri), mime_type="application/pdf") if hasattr(types.Part, 'from_uri') else None
            if file_part is None:
                self.error.emit("تعذر بناء جزء ملف PDF للطلب.")
                return

            contents = [
                types.Content(role="user", parts=[
                    file_part,
                    types.Part.from_text(text=user_prompt),
                ])
            ]
            cfg_kwargs = dict(
                temperature=float(self.cfg.get("compare_temperature", 0.2) or 0.2),
                max_output_tokens=int(self.cfg.get("compare_max_tokens", 8000) or 8000),
                system_instruction=[types.Part.from_text(text=COMPARE_FULL_BOOK_PROMPT)],
                response_mime_type="application/json")
            try:
                th = build_thinking_config(model_family, cfg)
                if th is not None:
                    cfg_kwargs["thinking_config"] = th
            except Exception:
                pass
            gen_cfg = types.GenerateContentConfig(**cfg_kwargs)

            if self.request_counter:
                try:
                    n = self.request_counter.increment("مقارنة كلية للكتاب")
                    self.log.emit(f"🔁 طلب رقم {n} (مقارنة كلية)")
                except Exception:
                    pass

            if self.stop_event.is_set():
                return

            try:
                throttle_key_send(api_key, self.stop_event, self.log.emit)
                resp = client.models.generate_content(
                    model=model_id, contents=contents, config=gen_cfg)
                raw = (getattr(resp, "text", None) or "").strip()
            except Exception as e:
                msg = str(e)
                if is_quota_error(e):
                    try:
                        kind, delay = parse_429(e)
                        self.global_key_mgr.mark_blocked(api_key, model_id, kind, delay, self.cfg)
                    except Exception:
                        pass
                    self.error.emit(f"كوتة/حد استخدام أثناء المقارنة الكلية:\n{msg}")
                else:
                    self.error.emit(f"فشل طلب المقارنة الكلية:\n{msg}")
                return

            if not raw or is_model_refusal(raw):
                self.error.emit("النموذج رفض أو أعاد استجابة فارغة للمقارنة الكلية.")
                return

            try:
                data = parse_compare_response_json(raw)
            except Exception as e:
                self.error.emit(f"تعذر تحليل JSON من النموذج:\n{e}\n\n{raw[:1500]}")
                return
            if not isinstance(data, dict):
                data = {}

            result = {
                "overall_assessment": str(data.get("overall_assessment") or data.get("shard_assessment") or "—"),
                "coverage_estimate_pct": self._safe_int(data.get("coverage_estimate_pct", data.get("coverage_pct", 0)), 0),
                "structure_integrity": str(data.get("structure_integrity") or "—"),
                "order_integrity": str(data.get("order_integrity") or "—"),
                "headers_handling": str(data.get("headers_handling") or "—"),
                "total_missing_items": self._safe_int(data.get("total_missing_items"), 0) or len(data.get("missing_items") or []),
                "critical_count": self._safe_int(data.get("critical_count"), 0),
                "medium_count": self._safe_int(data.get("medium_count"), 0),
                "minor_count": self._safe_int(data.get("minor_count"), 0),
                "missing_items": data.get("missing_items") or [],
                "strengths": data.get("strengths") or [],
                "weaknesses": data.get("weaknesses") or [],
                "summary": str(data.get("summary") or data.get("notes") or ""),
                "recommendations": str(data.get("recommendations") or ""),
                "confidence": self._safe_int(data.get("confidence"), 0),
                "used_model": model_id,
                "original_pdf": str(self.original_pdf),
                "extracted_txt": str(self.extracted_txt),
                "truncated": truncated,
                "prompt_kind": prompt_kind,
                "remove_headers": remove_headers,
                "raw_json": data,
            }
            if (not result["critical_count"] and not result["medium_count"] and not result["minor_count"]
                    and result["missing_items"]):
                for it in result["missing_items"]:
                    sev = str((it or {}).get("severity") or "")
                    if "خطير" in sev:
                        result["critical_count"] += 1
                    elif "متوسط" in sev:
                        result["medium_count"] += 1
                    else:
                        result["minor_count"] += 1
                result["total_missing_items"] = len(result["missing_items"])

            self.progress.emit("اكتملت المقارنة الكلية")
            self.finished_result.emit(result)
        except InterruptedError:
            self.log.emit("⏹️ أُوقفت المقارنة الكلية")
        except Exception as e:
            tb = traceback.format_exc()
            try:
                self.error.emit(f"{e}\n{tb}")
            except Exception:
                pass
        finally:
            if client is not None:
                try:
                    unregister_stop_component("clients", client)
                except Exception:
                    pass
                try:
                    if hasattr(client, "close"):
                        client.close()
                    elif getattr(client, "_transport", None) is not None:
                        client._transport.close()
                except Exception:
                    pass
            self._release_key()
            try:
                self.finished.emit()
            except Exception:
                pass


class FullBookCompareDialog(QDialog):
    """نافذة المقارنة الكلية: أصل كامل × ناتج نهائي + تقرير موسّع."""

    def __init__(self, parent, book_stem: str, original_pdf: Path, extracted_txt: Path,
                 compare_models: List[dict], default_model: Optional[dict] = None):
        super().__init__(parent)
        self.main_window = parent
        self.book_stem = book_stem
        self.original_pdf = Path(original_pdf) if original_pdf else None
        self.extracted_txt = Path(extracted_txt) if extracted_txt else None
        self.compare_models = compare_models or []
        self.default_model = default_model
        self._worker = None
        self._thread = None
        self._result = None
        self._closing = False
        self.setWindowTitle(f"📘 مقارنة كلية — {book_stem}")
        self.resize(1000, 780)
        self.setLayoutDirection(Qt.LayoutDirection.RightToLeft)
        self._build_ui()

    def _build_ui(self):
        layout = QVBoxLayout(self)
        layout.setContentsMargins(14, 14, 14, 14)
        layout.setSpacing(10)

        header = QLabel(
            f"<b style='font-size:15px;color:#89b4fa'>📘 مقارنة كلية مدقّقة</b><br>"
            f"الكتاب: <b style='color:#f9e2af'>{self.book_stem}</b><br>"
            f"يرفع <b>ملف الأصل كاملاً</b> (بلا تقسيم) ويقارنه بالناتج النهائي للنموذج.")
        header.setWordWrap(True)
        header.setStyleSheet(
            "background-color:#181825;border:1px solid #45475a;border-radius:8px;"
            "padding:12px;color:#cdd6f4;")
        layout.addWidget(header)

        form = QFormLayout(); form.setSpacing(8)
        # original
        row_o = QHBoxLayout()
        self.ed_original = QLineEdit(str(self.original_pdf) if self.original_pdf else "")
        btn_o = QPushButton("📁 اختيار PDF")
        btn_o.clicked.connect(self._browse_original)
        row_o.addWidget(self.ed_original, 1); row_o.addWidget(btn_o)
        form.addRow(QLabel("📄 الأصل (PDF كامل):"), row_o)

        row_e = QHBoxLayout()
        self.ed_extracted = QLineEdit(str(self.extracted_txt) if self.extracted_txt else "")
        btn_e = QPushButton("📁 اختيار TXT")
        btn_e.clicked.connect(self._browse_extracted)
        row_e.addWidget(self.ed_extracted, 1); row_e.addWidget(btn_e)
        form.addRow(QLabel("📝 الناتج النهائي:"), row_e)

        self.model_combo = QComboBox()
        for m in self.compare_models:
            self.model_combo.addItem(m.get("label") or m.get("id") or "model", m)
        if self.default_model:
            for i in range(self.model_combo.count()):
                d = self.model_combo.itemData(i)
                if d and d.get("id") == self.default_model.get("id"):
                    self.model_combo.setCurrentIndex(i); break
        form.addRow(QLabel("🤖 نموذج المقارنة:"), self.model_combo)
        layout.addLayout(form)

        btns = QHBoxLayout()
        self.btn_run = QPushButton("🚀 بدء المقارنة الكلية")
        self.btn_run.setObjectName("primaryBtn")
        self.btn_run.clicked.connect(self._start)
        btns.addWidget(self.btn_run)
        self.btn_stop = QPushButton("⏹️ إيقاف")
        self.btn_stop.setObjectName("dangerBtn")
        self.btn_stop.setEnabled(False)
        self.btn_stop.clicked.connect(self._stop)
        btns.addWidget(self.btn_stop)
        self.btn_export = QPushButton("💾 تصدير التقرير")
        self.btn_export.setEnabled(False)
        self.btn_export.clicked.connect(self._export)
        btns.addWidget(self.btn_export)
        btns.addStretch(1)
        layout.addLayout(btns)

        self.status = QLabel("⚪ جاهز")
        self.status.setStyleSheet("color:#a6e3a1;font-weight:700;padding:4px;")
        layout.addWidget(self.status)

        self.report = QTextEdit()
        self.report.setReadOnly(True)
        self.report.setLayoutDirection(Qt.LayoutDirection.RightToLeft)
        self.report.setStyleSheet(
            "QTextEdit { background:#11111b; color:#cdd6f4; border:1px solid #45475a;"
            "border-radius:8px; padding:10px; font-size:13px; }")
        self.report.setMinimumHeight(420)
        layout.addWidget(self.report, 1)

        close_row = QHBoxLayout()
        close_row.addStretch(1)
        btn_close = QPushButton("إغلاق")
        btn_close.clicked.connect(self.reject)
        close_row.addWidget(btn_close)
        layout.addLayout(close_row)

    def _browse_original(self):
        f, _ = QFileDialog.getOpenFileName(self, "اختر PDF الأصلي", "", "PDF (*.pdf)")
        if f: self.ed_original.setText(f)

    def _browse_extracted(self):
        f, _ = QFileDialog.getOpenFileName(self, "اختر الناتج النهائي", "", "نص (*.txt);;الكل (*.*)")
        if f: self.ed_extracted.setText(f)

    def _start(self):
        if self._worker is not None:
            QMessageBox.information(self, "ℹ️", "المقارنة تعمل بالفعل.")
            return
        op = Path(self.ed_original.text().strip())
        ep = Path(self.ed_extracted.text().strip())
        if not op.exists() or op.suffix.lower() != ".pdf":
            QMessageBox.warning(self, "تنبيه", "حدّد ملف PDF أصلي صالح.")
            return
        if not ep.exists():
            QMessageBox.warning(self, "تنبيه", "حدّد ملف الناتج النهائي.")
            return
        model = self.model_combo.currentData()
        if not model:
            QMessageBox.critical(self, "خطأ", "لا نموذج مقارنة."); return
        mw = self.main_window
        if not mw._has_keys():
            QMessageBox.warning(self, "تنبيه", "أضف مفاتيح API أولاً."); return

        cfg = dict(mw.settings.data)
        try:
            cfg["active_prompt_kind"] = mw.prompt_kind_combo.currentData()
            cfg["remove_headers"] = mw.rb_remove_headers.isChecked()
            cfg["compare_temperature"] = mw.settings.get("compare_temperature", 0.2)
            cfg["compare_max_tokens"] = mw.settings.get("compare_max_tokens", 8000)
            cfg["compare_max_input_chars"] = mw.settings.get("compare_max_input_chars", 200000)
        except Exception:
            pass

        self.btn_run.setEnabled(False)
        self.btn_stop.setEnabled(True)
        self.btn_export.setEnabled(False)
        self.status.setText("🔄 جارٍ المقارنة الكلية...")
        self.report.setHtml("<p style='color:#89b4fa'>⏳ يتم رفع الأصل ومقارنته بالناتج النهائي...</p>")

        # ✅ v28.6: لا نجعل QThread ابناً للنافذة مباشرة قبل انتهاء التشغيل
        # (إغلاق النافذة أثناء العمل كان يسبب Destroyed while thread is still running)
        self._thread = QThread()
        self._worker = FullBookCompareWorker(
            original_pdf=op, extracted_txt=ep,
            api_keys=mw._get_all_keys(), compare_model=model, cfg=cfg,
            global_key_mgr=mw.global_key_mgr, book_stem=self.book_stem)
        self._worker.request_counter = getattr(mw, "_central_request_counter", None)
        self._worker.moveToThread(self._thread)
        self._worker.log.connect(lambda m: mw._append_log(m), Qt.ConnectionType.QueuedConnection)
        self._worker.progress.connect(self._on_progress, Qt.ConnectionType.QueuedConnection)
        self._worker.finished_result.connect(self._on_result, Qt.ConnectionType.QueuedConnection)
        self._worker.error.connect(self._on_error, Qt.ConnectionType.QueuedConnection)
        self._worker.finished.connect(self._thread.quit)
        self._thread.finished.connect(self._on_thread_finished)
        self._thread.started.connect(self._worker.run)
        self._thread.start()

    def _stop(self):
        if self._worker:
            self._worker.stop()
            self.status.setText("⏹️ طُلب الإيقاف...")
            self.btn_stop.setEnabled(False)
            try:
                threading.Thread(
                    target=request_stop,
                    kwargs={"timeout": 10.0, "log_fn": safe_print},
                    daemon=True,
                ).start()
            except Exception as e:
                safe_print(f"[request_stop] {e}")

    def _on_progress(self, msg: str):
        if getattr(self, '_closing', False):
            return
        try:
            self.status.setText(f"🔄 {msg}")
        except Exception:
            pass

    def _on_result(self, result: dict):
        if getattr(self, '_closing', False):
            return
        try:
            self._result = result
            self._render_report(result)
            self.btn_export.setEnabled(True)
            self.status.setText("✅ اكتملت المقارنة الكلية")
        except Exception as e:
            try: LOGGER.warning("fullcompare on_result: %s", e)
            except Exception: pass

    def _on_error(self, msg: str):
        try:
            safe = (msg or "").replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
            self.status.setText("❌ فشلت المقارنة الكلية")
            self.report.setHtml(
                f"<pre style='color:#f38ba8;white-space:pre-wrap'>{safe[:5000]}</pre>")
            self.btn_run.setEnabled(True)
            self.btn_stop.setEnabled(False)
            # لا تُظهر MessageBox إن كانت النافذة تُغلق
            if self.isVisible():
                QMessageBox.critical(self, "خطأ المقارنة الكلية", (msg or "")[:1500])
        except Exception:
            pass

    def _on_thread_finished(self):
        # ✅ v28.7: فصل الإشارات قبل التدمير
        th = self._thread
        w = self._worker
        self._worker = None
        self._thread = None
        try:
            if w is not None:
                for sig_name in ('log', 'progress', 'finished_result', 'error', 'finished'):
                    sig = getattr(w, sig_name, None)
                    if sig is None:
                        continue
                    try: sig.disconnect()
                    except Exception: pass
        except Exception:
            pass
        try:
            if th is not None:
                th.deleteLater()
        except Exception:
            pass
        if getattr(self, '_closing', False):
            try:
                QTimer.singleShot(0, lambda: QDialog.close(self))
            except Exception:
                pass
            return
        try:
            self.btn_run.setEnabled(True)
            self.btn_stop.setEnabled(False)
        except Exception:
            pass

    def _render_report(self, r: dict):
        def esc(x):
            return (str(x) if x is not None else "").replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
        verdict = r.get("overall_assessment", "—")
        color = {"ممتاز": "#a6e3a1", "جيد": "#94e2d5", "متوسط": "#f9e2af", "ضعيف": "#f38ba8"}.get(verdict, "#cdd6f4")
        cov = r.get("coverage_estimate_pct", 0)
        items = r.get("missing_items") or []
        strengths = r.get("strengths") or []
        weaknesses = r.get("weaknesses") or []
        def ul(lst):
            if not lst: return "<li>—</li>"
            return "".join(f"<li>{esc(x)}</li>" for x in lst[:30])
        miss_html = ""
        for it in items[:80]:
            sev = (it or {}).get("severity", "—")
            sn = (it or {}).get("snippet", "")
            loc = (it or {}).get("location_hint", "")
            sc = {"خطير": "#f38ba8", "متوسط": "#fab387", "بسيط": "#f9e2af"}.get(str(sev), "#cdd6f4")
            miss_html += (
                f"<tr><td style='color:{sc};font-weight:700'>{esc(sev)}</td>"
                f"<td>{esc(loc)}</td><td>{esc(sn)}</td></tr>")
        if not miss_html:
            miss_html = "<tr><td colspan='3'>—</td></tr>"
        html = f"""
        <h2 style='color:#89b4fa;margin:0 0 10px 0'>📘 تقرير المقارنة الكلية</h2>
        <p>
        <b>التقييم العام:</b> <span style='color:{color};font-size:16px;font-weight:800'>{verdict}</span><br>
        <b>التغطية التقديرية:</b> <span style='color:#a6e3a1;font-weight:800'>{cov}%</span><br>
        <b>سلامة البنية:</b> {r.get('structure_integrity','—')} |
        <b>سلامة الترتيب:</b> {r.get('order_integrity','—')} |
        <b>معالجة الهوامش:</b> {r.get('headers_handling','—')}<br>
        <b>الثقة:</b> {r.get('confidence',0)}% |
        <b>النموذج:</b> {r.get('used_model','—')}<br>
        <b>الفجوات:</b> إجمالي {r.get('total_missing_items',0)}
        (خطير {r.get('critical_count',0)} | متوسط {r.get('medium_count',0)} | بسيط {r.get('minor_count',0)})
        {" | <span style='color:#fab387'>النص مُقتطع للطول</span>" if r.get('truncated') else ""}
        </p>
        <h3 style='color:#cba6f7'>الملخص</h3>
        <p>{esc(r.get('summary') or '—')}</p>
        <h3 style='color:#a6e3a1'>نقاط القوة</h3><ul>{ul(strengths)}</ul>
        <h3 style='color:#f38ba8'>نقاط الضعف</h3><ul>{ul(weaknesses)}</ul>
        <h3 style='color:#f9e2af'>التوصيات</h3>
        <p>{esc(r.get('recommendations') or '—')}</p>
        <h3 style='color:#89b4fa'>الفجوات/الملاحظات التفصيلية</h3>
        <table border='1' cellspacing='0' cellpadding='6' width='100%'
               style='border-collapse:collapse;border-color:#45475a'>
        <tr style='background:#181825'><th>الخطورة</th><th>الموقع</th><th>التفاصيل</th></tr>
        {miss_html}
        </table>
        <p style='color:#6c7086;margin-top:12px'>
        الأصل: {r.get('original_pdf','')}<br>
        الناتج: {r.get('extracted_txt','')}
        </p>
        """
        self.report.setHtml(html)

    def _export(self):
        if not self._result:
            return
        f, _ = QFileDialog.getSaveFileName(
            self, "حفظ تقرير المقارنة الكلية",
            f"{self.book_stem}_full_compare.json",
            "JSON (*.json);;نص (*.txt)")
        if not f:
            return
        try:
            p = Path(f)
            if p.suffix.lower() == ".txt":
                p.write_text(self.report.toPlainText(), encoding="utf-8")
            else:
                p.write_text(json.dumps(self._result, ensure_ascii=False, indent=2), encoding="utf-8")
            QMessageBox.information(self, "✅", f"تم الحفظ:\n{p}")
        except Exception as e:
            QMessageBox.critical(self, "خطأ", str(e))

    def closeEvent(self, event):
        # ✅ v28.7: إغلاق مؤجل إن كان الخيط يعمل — بدون تجميد/انهيار
        self._closing = True
        try:
            th = self._thread
            if th is not None and th.isRunning():
                try:
                    if self._worker is not None:
                        self._worker.stop()
                except Exception:
                    pass
                try:
                    th.quit()
                except Exception:
                    pass
                try:
                    self.status.setText("⏳ جارٍ إيقاف المقارنة ثم الإغلاق...")
                except Exception:
                    pass
                event.ignore()
                QTimer.singleShot(12000, self._force_close_dialog)
                return
        except Exception as e:
            try: LOGGER.warning("FullBookCompare closeEvent: %s", e)
            except Exception: pass
        try:
            self._worker = None
            self._thread = None
        except Exception:
            pass
        super().closeEvent(event)

    def _force_close_dialog(self):
        # ✅ v29.0: لا تصفّر المراجع إن الخيط ما زال يعمل — أعد المحاولة
        try:
            th = self._thread
            if th is not None:
                try:
                    if th.isRunning():
                        try:
                            if self._worker is not None:
                                self._worker.stop()
                        except Exception:
                            pass
                        try:
                            th.quit()
                        except Exception:
                            pass
                        # أعد المحاولة بعد مهلة قصيرة بدل التدمير المبكر
                        QTimer.singleShot(1500, self._force_close_dialog)
                        return
                except RuntimeError:
                    pass
            # الخيط توقف: نظّف ثم أغلق
            try:
                w = self._worker
                if w is not None:
                    for sig_name in ('log', 'progress', 'finished_result', 'error', 'finished'):
                        sig = getattr(w, sig_name, None)
                        if sig is None:
                            continue
                        try:
                            sig.disconnect()
                        except Exception:
                            pass
            except Exception:
                pass
            self._worker = None
            self._thread = None
            try:
                QDialog.close(self)
            except Exception:
                pass
        except Exception as e:
            try:
                LOGGER.warning("force_close_dialog: %s", e)
            except Exception:
                pass

class FetchModelsWorker(QObject):
    finished = pyqtSignal(list)
    failed = pyqtSignal(str)
    log = pyqtSignal(str)

    def __init__(self, api_key: str):
        super().__init__()
        self.api_key = api_key

    def run(self):
        try:
            models = fetch_models_from_google(self.api_key, log=self.log.emit)
            self.finished.emit(models)
        except Exception as e:
            self.failed.emit(str(e))



# ═══════════════════════════════════════════════════════════════════
#  ✅ v29.1: استخراج عالمي متعدد الكتب — يملأ N مسارات من كل الكتب معاً
# ═══════════════════════════════════════════════════════════════════

@dataclass
class BookExtractJob:
    idx: int
    path: Path
    stem: str
    is_txt: bool
    total_units: int
    shards: List[PDFShard]
    pending: List[PDFShard]
    parts_dir: Path
    ckpt: Checkpoint
    system_prompt: str
    comparator: Optional[InlineComparator]
    txt_ctx: Optional[TxtContextManager]
    pool: KeyPool
    lock: threading.RLock = field(default_factory=threading.RLock)
    done_count: int = 0
    failed: List[int] = field(default_factory=list)
    finished: bool = False
    started: bool = False


class MultiBookParallelOrchestrator:
    """
    ✅ v29.1:
    - طابور موحّد لأجزاء كل الكتب.
    - عدد المسارات = min(الإعداد، إجمالي الأجزاء المعلقة).
    - إذا كتاب فيه 9 أجزاء وإعداد 12 → تُملأ 3 مسارات من كتب تالية فوراً.
    - تعليق/بطء جزء في كتاب لا يمنع تقدم كتب أخرى.
    """

    def __init__(self, jobs: List[BookExtractJob], *, model: dict, cfg: dict,
                 global_key_mgr: GlobalKeyManager,
                 on_token, on_log, on_progress, on_upload_progress,
                 on_compare_partial, on_compare_final, on_request, on_key_used,
                 on_stream_event, on_book_started, on_book_finished,
                 stop_event: threading.Event, pause_event: threading.Event,
                 request_counter=None):
        self.jobs = jobs
        self.model = model
        self.models = extraction_model_candidates(self.model, cfg)
        self.cfg = cfg
        self.global_key_mgr = global_key_mgr
        self.on_token = on_token
        self.on_log = on_log
        self.on_progress = on_progress
        self.on_upload_progress = on_upload_progress
        self.on_compare_partial = on_compare_partial
        self.on_compare_final = on_compare_final
        self.on_request = on_request
        self.on_key_used = on_key_used
        self.on_stream_event = on_stream_event or (lambda _e: None)
        self.on_book_started = on_book_started
        self.on_book_finished = on_book_finished
        self.stop_event = stop_event
        self.pause_event = pause_event
        self.request_counter = request_counter
        self._queue: queue.Queue = queue.Queue()
        self._active_books: Set[str] = set()
        self._active_lock = threading.RLock()
        self._lane_book: Dict[int, str] = {}
        total_pending = 0
        for job in jobs:
            for sh in job.pending:
                self._queue.put((job, sh))
                total_pending += 1
        self.total_pending = total_pending
        req = max(1, min(int(cfg.get("parallel_extract_workers", 1) or 1), 25, max(1, total_pending)))
        # مفاتيح من أول pool
        pool0 = jobs[0].pool if jobs else None
        available = pool0.count_available_for_model(model["id"]) if pool0 else req
        safe_max = ((max(1, available) if is_key_rpm_enabled()
                     else max(1, available // 3)) if available > 0 else req)
        if req > safe_max and available > 0:
            on_log(f"⚠️ تقليل المسارات العالمية من {req} إلى {safe_max} (مفاتيح متاحة: {available})")
            self.workers = safe_max
        else:
            self.workers = req
        self.all_keys = []
        if pool0:
            self.all_keys = [s.key for s in sorted(pool0.states.values(), key=lambda s: (s.fail_count, -s.success_count, s.masked))]
        on_log(f"⚙️ الاستخراج العالمي المتوازي: {self.workers} مسار | أجزاء معلّقة: {total_pending} | كتب: {len(jobs)}")
        try:
            self.on_stream_event({
                "type": "workers_config",
                "lane_id": 0,
                "workers": self.workers,
                "requested_workers": req,
                "actual_workers": self.workers,
                "available_keys": available,
                "model_id": model["id"],
                "multi_book": True,
                "books": len(jobs),
                "pending_shards": total_pending,
            })
        except Exception:
            pass

    def _wait_if_paused(self):
        while self.pause_event.is_set() and not self.stop_event.is_set():
            try:
                interruptible_sleep(0.2, self.stop_event)
            except InterruptedError:
                break

    def _lane_log(self, lane_id: int, msg: str):
        self.on_log(f"[مسار {lane_id}] {msg}")

    def _set_lane_book(self, lane_id: int, book_name: Optional[str]):
        with self._active_lock:
            if book_name:
                self._lane_book[lane_id] = book_name
                self._active_books.add(book_name)
            else:
                self._lane_book.pop(lane_id, None)
            active = sorted(set(self._lane_book.values()))
        try:
            self.on_stream_event({
                "type": "active_books",
                "lane_id": lane_id,
                "workers": self.workers,
                "active_books": active,
                "active_count": len(active),
            })
        except Exception:
            pass

    def _maybe_start_book(self, job: BookExtractJob):
        with job.lock:
            if job.started:
                return
            job.started = True
        try:
            self.on_book_started(job.path.name, job.idx)
        except Exception as e:
            safe_print(f"[multi] book_started: {e}")
        self.on_log(f"📘 بدء متوازٍ: {job.path.name} ({len(job.pending)}/{len(job.shards)} جزء معلّق)")

    def _finish_book_if_done(self, job: BookExtractJob):
        # ✅ v29.1: دمج الكتاب عند انتهاء كل أجزائه المعلّقة
        with job.lock:
            if job.finished:
                return
            target = len(job.pending)
            if target <= 0:
                job.finished = True
            else:
                finished_n = job.done_count + len(set(job.failed))
                if finished_n < target and not self.stop_event.is_set():
                    return
                job.finished = True
        self._merge_book(job)

    def _merge_book(self, job: BookExtractJob):
        try:
            # ✅ v29.15: دعم البنية الجديدة والقديمة معاً.
            # جديد: output_dir/<book>/parts  → output_dir = parent.parent
            # قديم: output_dir/_pdf_master_data/<book>/parts → output_dir = parent.parent.parent
            pdir = Path(job.parts_dir)
            if pdir.name == "parts" and pdir.parent.parent.name == "_pdf_master_data":
                out_dir = pdir.parent.parent.parent
            elif pdir.name == "parts":
                out_dir = pdir.parent.parent
            else:
                out_dir = pdir.parent
        except Exception:
            out_dir = job.path.parent
        log = self.on_log
        log(f"════ دمج نهائي: {job.path.name} ════")
        extracted_set = detect_completed_part_indices(out_dir, job.stem, {s.idx for s in job.shards})
        missing = sorted({s.idx for s in job.shards} - extracted_set)
        pieces = []
        for s in job.shards:
            pf = job.parts_dir / f"{job.stem}_part_{s.idx:04d}.txt"
            if s.idx not in extracted_set or not pf.exists():
                continue
            try:
                pieces.append(pf.read_text(encoding="utf-8", errors="replace").rstrip())
            except Exception:
                if s.idx not in missing:
                    missing.append(s.idx)
        missing = sorted(set(missing))
        final_text = "\n\n".join(pieces)
        ok_count = len(extracted_set)
        failed_set = sorted(set(job.failed))
        log(f"  [{job.stem}] ناجحة: {ok_count}/{len(job.shards)} | فاشلة: {len(failed_set)} | مفقودة: {len(missing)}")

        compare_summary = None
        if job.comparator:
            if not self.stop_event.is_set():
                try:
                    job.comparator.wait_until_done(timeout=1800)
                    if not self.stop_event.is_set():
                        compare_summary = job.comparator.generate_final_report(total_shards=len(job.shards))
                        if compare_summary:
                            try:
                                self.on_compare_final(compare_summary)
                            except Exception as e:
                                safe_print(f"[multi.on_compare_final] {e}")
                except Exception as e:
                    log(f"⚠️ انتظار/تقرير مقارنة {job.stem}: {e}")
            try:
                job.comparator.stop(wait=True)
            except Exception:
                pass

        suffix = "_معالج" if job.is_txt else "_مستخرج"
        final_path = out_dir / f"{job.stem}{suffix}.txt"
        incomplete_path = None
        success = False
        message = ""
        try:
            if not pieces:
                message = "لا أجزاء للدمج"
            elif missing or failed_set:
                incomplete_path = out_dir / f"{job.stem}{suffix}.INCOMPLETE.txt"
                atomic_write_text(incomplete_path, final_text, encoding="utf-8")
                try:
                    save_book_meta(out_dir, job.stem, {"final_output_file": str(incomplete_path)})
                except Exception:
                    pass
                message = f"ناقص: مفقود {missing[:20]} فاشل {failed_set[:20]}"
            else:
                # ✅ v9.2: أُزيلت خاصية النسخة الاحتياطية (.bak) هنا أيضاً لنفس السبب.
                atomic_write_text(final_path, final_text, encoding="utf-8")
                try:
                    save_book_meta(out_dir, job.stem, {"final_output_file": str(final_path)})
                except Exception:
                    pass
                success = True
                message = "اكتمل"
        except Exception as e:
            message = f"فشل الدمج: {e}"
            log(f"💥 {message}")

        result = FileResult(
            success=success,
            final_path=final_path if success else None,
            incomplete_path=incomplete_path,
            total_batches=len(job.shards),
            successful_batches=ok_count,
            failed_batches=failed_set,
            message=message,
            file_path=job.path,
            compare_summary=compare_summary,
            is_txt=job.is_txt,
        )
        try:
            self.on_book_finished(result, job.idx)
        except Exception as e:
            safe_print(f"[multi.book_finished] {e}")

    def run(self):
        if self.total_pending <= 0:
            for job in self.jobs:
                self._maybe_start_book(job)
                self._merge_book(job)
            return

        def lane_worker(lane_id: int):
            # rebuild process loop properly here
            preferred = None
            if self.all_keys:
                preferred = self.all_keys[(lane_id - 1) % len(self.all_keys)]
            while not self.stop_event.is_set():
                self._wait_if_paused()
                if self.stop_event.is_set():
                    break
                try:
                    job, shard = self._queue.get_nowait()
                except queue.Empty:
                    break
                if self.stop_event.is_set():
                    # ✅ v29.2: لا تبدأ أجزاء جديدة بعد الإيقاف
                    break
                self._maybe_start_book(job)
                self._set_lane_book(lane_id, job.path.name)
                try:
                    self.on_stream_event({
                        "type": "start", "lane_id": lane_id, "workers": self.workers,
                        "shard_idx": shard.idx, "page_start": shard.page_start, "page_end": shard.page_end,
                        "pages_count": getattr(shard, "pages_count", max(0, shard.page_end - shard.page_start + 1)),
                        "book_name": job.path.name, "book_stem": job.stem,
                        "book_units": job.total_units, "is_txt": job.is_txt, "multi_book": True,
                    })
                except Exception:
                    pass

                part_contexts: Dict[str, ShardRuntimeContext] = {}

                def _context_for(candidate, _job=job, _lane=lane_id):
                    model_id = str(candidate.get("id") or "")
                    if model_id not in part_contexts:
                        part_contexts[model_id] = ShardRuntimeContext(
                            _job.pool, model_id,
                            lambda m, _l=_lane: self._lane_log(_l, m),
                            self.global_key_mgr,
                            self.all_keys or [state.key for state in _job.pool.states.values()],
                            self.on_upload_progress,
                            txt_context_mgr=_job.txt_ctx,
                            preferred_key=preferred)
                    return part_contexts[model_id]

                part_file = job.parts_dir / f"{job.stem}_part_{shard.idx:04d}.txt"
                ok = False
                try:
                    if job.ckpt.is_done(shard.idx) and part_file.exists():
                        self._lane_log(lane_id, f"⏭️  {job.stem} جزء {shard.idx} مكتمل سابقاً")
                        ok = True
                    else:
                        def _on_tok(t, _lane=lane_id, _shard=shard, _job=job):
                            try:
                                self.on_stream_event({
                                    "type": "token", "lane_id": _lane, "workers": self.workers,
                                    "shard_idx": _shard.idx, "page_start": _shard.page_start,
                                    "page_end": _shard.page_end, "book_name": _job.path.name,
                                    "book_stem": _job.stem, "text": t, "multi_book": True,
                                })
                            except Exception:
                                pass
                            # ✅ v29.4-HF2: لا نرسل token_received خام في وضع تعدد الكتب؛
                            # stream_event أعلاه هو المسار الصحيح الوحيد لتحديث تبويب المسار.
                            # إرسال الاثنين كان يستدعي MainWindow._append_token ويقلب العرض إلى single.

                        psout = process_shard_with_model_failover(
                            shard, len(job.shards), self.models, _context_for,
                            job.system_prompt, self.cfg,
                            _on_tok,
                            self.on_progress,
                            self.on_request,
                            self.on_key_used,
                            self.stop_event,
                            lambda m, _l=lane_id: self._lane_log(_l, m),
                            force_fresh_upload=False,
                            on_attempt_restart=lambda reason, _l=lane_id, _s=shard, _j=job:
                                self.on_stream_event({
                                    "type": "restart", "lane_id": _l,
                                    "workers": self.workers, "shard_idx": _s.idx,
                                    "page_start": _s.page_start, "page_end": _s.page_end,
                                    "book_name": _j.path.name, "book_stem": _j.stem,
                                    "multi_book": True, "message": reason,
                                }),
                        )
                        if (psout is not None and getattr(psout, "text", None)
                                and not getattr(psout, "failure_reason", "")):
                            try:
                                part_file.with_name(f"{part_file.stem}.partial").unlink()
                            except FileNotFoundError:
                                pass
                            except Exception:
                                pass
                            atomic_write_text(part_file, psout.text, encoding="utf-8")
                            job.ckpt.mark_ok(shard, str(part_file))
                            ok = True
                            if job.comparator and not self.stop_event.is_set() and not job.is_txt:
                                try:
                                    job.comparator.submit(
                                        shard=shard, extracted_text=psout.text,
                                        api_key_hint=getattr(psout, "used_api_key", None),
                                        file_uri_hint=getattr(psout, "file_uri", None),
                                        force=False)
                                except Exception as e:
                                    self._lane_log(lane_id, f"⚠️ compare submit: {e}")
                        else:
                            if psout is not None and getattr(psout, "text", None):
                                partial_file = part_file.with_name(f"{part_file.stem}.partial")
                                try:
                                    atomic_write_text(partial_file, psout.text, encoding="utf-8")
                                    self._lane_log(lane_id,
                                        f"🧩 حُفظ ناتج تشخيصي غير مكتمل: {partial_file.name}")
                                except Exception as exc:
                                    self._lane_log(lane_id,
                                        f"⚠️ تعذر حفظ النص الجزئي للتشخيص: {exc}")
                            reason = (getattr(psout, "failure_reason", "")
                                      or "لم يُنتج النموذج نصاً")
                            # أعد المحاولة فقط عند فشل شبكي عابر أو انتظار كوتة؛
                            # أخطاء الرفض/الصلاحيات/المدخلات لا تعيد إرسال الجزء.
                            should_retry = bool(
                                getattr(psout, "retryable", False)
                                or getattr(psout, "quota_exhausted", False))
                            retries = getattr(shard, "_multi_retries", 0)
                            if should_retry and retries < 2 and not self.stop_event.is_set():
                                try:
                                    shard._multi_retries = retries + 1
                                except Exception:
                                    pass
                                delay_s = 60.0 if getattr(psout, "quota_exhausted", False) else 3.0 + retries * 2
                                self._lane_log(
                                    lane_id,
                                    f"🔄 إعادة جدولة {job.stem} جزء {shard.idx} "
                                    f"(محاولة {retries+1}/2) بعد {delay_s:.0f}s: {reason[:140]}")
                                try:
                                    interruptible_sleep(delay_s, self.stop_event)
                                except InterruptedError:
                                    pass
                                else:
                                    try:
                                        with self._queue.mutex:
                                            self._queue.queue.appendleft((job, shard))
                                    except Exception:
                                        self._queue.put((job, shard))
                                    try:
                                        self.on_stream_event({
                                            "type": "error", "lane_id": lane_id, "workers": self.workers,
                                            "shard_idx": shard.idx, "book_name": job.path.name,
                                            "book_stem": job.stem, "multi_book": True,
                                            "message": "requeued", "summary": reason,
                                        })
                                    except Exception:
                                        pass
                                    self._set_lane_book(lane_id, None)
                                    continue
                            job.ckpt.mark_failed(shard, reason)
                            with job.lock:
                                if shard.idx not in job.failed:
                                    job.failed.append(shard.idx)
                except InterruptedError:
                    with job.lock:
                        job.failed.append(shard.idx)
                except Exception as e:
                    self._lane_log(lane_id, f"💥 {job.stem} جزء {shard.idx}: {e}")
                    try:
                        job.ckpt.mark_failed(shard, str(e))
                    except Exception:
                        pass
                    with job.lock:
                        if shard.idx not in job.failed:
                            job.failed.append(shard.idx)
                finally:
                    for _ctx in list(part_contexts.values()):
                        try:
                            _ctx.close()
                        except Exception:
                            pass

                if ok:
                    with job.lock:
                        job.done_count += 1
                    try:
                        self.on_progress({
                            "current_batch": job.done_count,
                            "total_batches": len(job.shards),
                            "book_name": job.path.name,
                            "book_idx": job.idx,
                        })
                    except Exception:
                        pass

                try:
                    self.on_stream_event({
                        "type": "finish" if ok else "error",
                        "lane_id": lane_id, "workers": self.workers,
                        "shard_idx": shard.idx, "book_name": job.path.name,
                        "book_stem": job.stem, "multi_book": True,
                    })
                except Exception:
                    pass

                # book completion check
                with job.lock:
                    target = len(job.pending)
                    finished_n = job.done_count + len(set(job.failed))
                    should_finish = finished_n >= target
                if should_finish:
                    self._finish_book_if_done(job)
                self._set_lane_book(lane_id, None)

        with ThreadPoolExecutor(max_workers=self.workers, thread_name_prefix="GlobalLane") as ex:
            futs = [ex.submit(lane_worker, i + 1) for i in range(self.workers)]
            for fu in futs:
                try:
                    fu.result()
                except Exception as e:
                    self.on_log(f"💥 مسار عالمي: {e}\n{traceback.format_exc()}")

        # أي كتاب لم يُدمَج بعد
        for job in self.jobs:
            with job.lock:
                if not job.finished:
                    job.finished = True
            if job.started:
                self._merge_book(job)
            else:
                # لم يُبدأ؟ ربما لا pending — ادمج
                self._maybe_start_book(job)
                self._merge_book(job)


class ProcessingWorker(QObject):
    token_received = pyqtSignal(str)
    stream_event = pyqtSignal(object)
    log_received = pyqtSignal(str)
    request_sent = pyqtSignal(str)
    key_used = pyqtSignal(str)
    progress_updated = pyqtSignal(dict)
    upload_progress = pyqtSignal(int)
    book_started = pyqtSignal(str, int)
    book_finished = pyqtSignal(object, int)
    all_finished = pyqtSignal()
    error_occurred = pyqtSignal(str)
    compare_partial_ready = pyqtSignal(object)
    compare_final_ready = pyqtSignal(dict)

    def __init__(self, files, output_dir, parts_root_dir, tokens_path,
                   system_prompt_pdf, system_prompt_txt,
                   model, compare_model, cfg, enable_inline_compare: bool,
                   global_key_mgr: GlobalKeyManager, app_dir: Path,
                   custom_split_text: str,
                   custom_split_map: Optional[Dict[str, str]] = None,
                   custom_batch_map: Optional[Dict[str, str]] = None):
        super().__init__()
        self.files = files
        self.output_dir = output_dir
        self.parts_root_dir = parts_root_dir
        self.tokens_path = tokens_path
        self.system_prompt_pdf = system_prompt_pdf
        self.system_prompt_txt = system_prompt_txt
        self.model = model
        self.compare_model = compare_model
        self.cfg = cfg
        self.enable_inline_compare = enable_inline_compare
        self.global_key_mgr = global_key_mgr
        self.app_dir = app_dir
        self.custom_split_text = custom_split_text
        self.custom_split_map = custom_split_map or {}
        self.custom_batch_map = custom_batch_map or {}
        self.request_counter: Optional[CentralRequestCounter] = None
        self.stop_event = threading.Event()
        self.pause_event = threading.Event()

    def stop(self):
        # ✅ v29.2: إيقاف فوري لكل الكتب/المسارات (الوضع المتسلسل ومتعدد الكتب)
        self.stop_event.set()
        self.pause_event.clear()  # لا تبقَ معلّقاً على pause

    def pause(self):
        self.pause_event.set()

    def resume(self):
        self.pause_event.clear()

    def _emit_log_safe(self, text: str):
        try:
            if not isinstance(text, str):
                text = str(text)
            self.log_received.emit(text)
        except Exception:
            pass

    def _emit_token_safe(self, text: str):
        try:
            if not isinstance(text, str):
                text = str(text)
            self.token_received.emit(text)
        except Exception:
            pass

    def _emit_request_sent_safe(self, description: str):
        try:
            if not isinstance(description, str):
                description = str(description)
            self.request_sent.emit(description)
        except Exception:
            pass

    def _emit_key_used_safe(self, key: str):
        try:
            if not isinstance(key, str):
                key = str(key)
            self.key_used.emit(key)
        except Exception:
            pass

    def run(self):
        try:
            workers_cfg = max(1, int(self.cfg.get("parallel_extract_workers", 1) or 1))
            use_multi = len(self.files) > 1 and workers_cfg > 1
            if use_multi:
                self._run_multi_book_pool()
            else:
                self._run_sequential_books()
            try:
                self.all_finished.emit()
            except Exception:
                pass
        except Exception as e:
            tb = traceback.format_exc()
            try:
                self.error_occurred.emit(f"{e}\n{tb}")
            except Exception:
                pass
            try:
                self.all_finished.emit()
            except Exception:
                pass

    def _run_sequential_books(self):
        for i, in_path in enumerate(self.files):
            if self.stop_event.is_set():
                break
            try:
                self.book_started.emit(in_path.name, i)
                self._emit_log_safe(f"\n{'═' * 60}")
                self._emit_log_safe(f"  ملف {i+1}/{len(self.files)}: {in_path.name}")
                self._emit_log_safe(f"{'═' * 60}")
                sp = self.system_prompt_txt if is_txt_file(in_path) else self.system_prompt_pdf
                ctext = _custom_map_value(self.custom_split_map, in_path, self.custom_split_text)
                btext = _custom_map_value(self.custom_batch_map, in_path, "")
                eff_stem = effective_book_stem_for(in_path, ctext, btext)
                book_parts_dir = (self.parts_root_dir / safe_book_dir_name(eff_stem) / "parts")
                processor = PDFProcessor(
                    in_path=in_path, output_dir=self.output_dir, parts_dir=book_parts_dir,
                    tokens_path=self.tokens_path, system_prompt=sp, model=self.model,
                    compare_model=self.compare_model, cfg=self.cfg,
                    on_token=self._emit_token_safe, on_log=self._emit_log_safe,
                    on_progress=self.progress_updated.emit, on_upload_progress=self.upload_progress.emit,
                    on_compare_partial=self.compare_partial_ready.emit,
                    on_compare_final=self.compare_final_ready.emit,
                    on_request=self._emit_request_sent_safe, on_key_used=self._emit_key_used_safe,
                    on_stream_event=self.stream_event.emit, stop_event=self.stop_event,
                    pause_event=self.pause_event, enable_inline_compare=self.enable_inline_compare,
                    global_key_mgr=self.global_key_mgr, app_dir=self.app_dir,
                    custom_split_text=ctext, custom_batch_text=btext)
                processor.request_counter = self.request_counter
                try:
                    result = processor.run()
                except Exception as e:
                    tb = traceback.format_exc()
                    self._emit_log_safe(f"💥 خطأ: {e}\n{tb}")
                    result = FileResult(False, None, None, 0, 0, [], f"خطأ: {e}",
                                        file_path=in_path, is_txt=is_txt_file(in_path))
                self.book_finished.emit(result, i)
            except Exception as e:
                tb = traceback.format_exc()
                self._emit_log_safe(f"💥 خطأ خارجي على الملف {in_path.name}: {e}\n{tb}")
                try:
                    self.book_finished.emit(
                        FileResult(False, None, None, 0, 0, [], str(e),
                                   file_path=in_path, is_txt=is_txt_file(in_path)), i)
                except Exception:
                    pass

    def _run_multi_book_pool(self):
        """✅ v29.1: مسار عالمي يملأ المسارات من كل الكتب معاً."""
        self._emit_log_safe("🌐 وضع التوازي متعدد الكتب مفعّل — تعبئة المسارات من كل القائمة")
        jobs: List[BookExtractJob] = []
        global_state_path = self.app_dir / KeyPool.GLOBAL_STATE_FILENAME

        for i, in_path in enumerate(self.files):
            if self.stop_event.is_set():
                break
            is_txt = is_txt_file(in_path)
            sp = self.system_prompt_txt if is_txt else self.system_prompt_pdf
            ctext = _custom_map_value(self.custom_split_map, in_path, self.custom_split_text)
            btext = _custom_map_value(self.custom_batch_map, in_path, "")
            eff_stem = effective_book_stem_for(in_path, ctext, btext)
            parts_dir = self.parts_root_dir / safe_book_dir_name(eff_stem) / "parts"
            parts_dir.mkdir(parents=True, exist_ok=True)
            shards_dir = get_book_shards_dir(self.output_dir, eff_stem)
            checkpoints_dir = get_book_checkpoints_dir(self.output_dir, eff_stem)
            checkpoints_dir.mkdir(parents=True, exist_ok=True)
            ckpt = Checkpoint(checkpoints_dir / "checkpoint.json")
            try:
                register_stop_component("checkpoints", ckpt)
            except Exception:
                pass
            try:
                custom_ranges = None
                custom_ranges_exact = False
                if is_txt:
                    total_units = get_txt_word_count(in_path)
                else:
                    total_units = get_pdf_page_count(in_path)
                raw_batch = normalize_custom_ranges_text(btext)
                raw_custom = normalize_custom_ranges_text(ctext)
                if raw_batch:
                    custom_ranges = parse_custom_batch_boundaries(raw_batch, total_units)
                    if not custom_ranges:
                        raise ValueError("دفعات مخصصة فارغة بعد التحليل")
                    custom_ranges_exact = True
                    self._emit_log_safe(f"🔒 {in_path.name}: دفعات مخصصة إلزامية ({len(custom_ranges)} دفعة)")
                elif raw_custom:
                    custom_ranges = parse_custom_split_ranges(raw_custom, total_units)
                    if not custom_ranges:
                        raise ValueError("التقسيم المخصص فارغ بعد التحليل")
                    self._emit_log_safe(f"✂️ {in_path.name}: استخراج جزئي مخصص ({len(custom_ranges)} نطاق)")
                if is_txt:
                    shards = split_txt_into_shards(
                        in_path, shards_dir, self.cfg.get("lines_per_batch", 1000),
                        self._emit_log_safe, self.stop_event, custom_ranges=custom_ranges, custom_ranges_exact=custom_ranges_exact)
                else:
                    shards = split_pdf_into_shards(
                        in_path, shards_dir, self.cfg.get("pages_per_batch", 25),
                        self._emit_log_safe, self.stop_event, custom_ranges=custom_ranges, custom_ranges_exact=custom_ranges_exact)
            except Exception as e:
                self._emit_log_safe(f"💥 فشل تقسيم {in_path.name}: {e}")
                self.book_started.emit(in_path.name, i)
                self.book_finished.emit(
                    FileResult(False, None, None, 0, 0, [], f"فشل التقسيم: {e}",
                               file_path=in_path, is_txt=is_txt), i)
                continue

            try:
                pool = KeyPool(self.tokens_path, checkpoints_dir / "keys_state.json",
                               self.cfg, global_state_path=global_state_path)
            except Exception as e:
                self._emit_log_safe(f"💥 مفاتيح {in_path.name}: {e}")
                continue
            try:
                register_stop_component("keypools", pool)
            except Exception:
                pass

            pending = []
            completed = detect_completed_part_indices(
                self.output_dir, eff_stem, {s.idx for s in shards})
            for s in shards:
                pf = parts_dir / f"{eff_stem}_part_{s.idx:04d}.txt"
                if s.idx in completed and pf.exists():
                    continue
                pending.append(s)

            comparator = None
            allow_txt_custom_compare = bool(is_txt and str(self.cfg.get("active_prompt_kind", "")) == "custom"
                                            and self.cfg.get("custom_compare_enabled", True)
                                            and str(self.cfg.get("custom_compare_prompt", "")).strip())
            if self.enable_inline_compare and (not is_txt or allow_txt_custom_compare):
                try:
                    api_keys = [s.key for s in pool.states.values()]
                    w = max(1, min(int(self.cfg.get("compare_parallel_workers", 3) or 3), len(api_keys), 25))
                    comparator = InlineComparator(
                        output_dir=self.output_dir, book_stem=in_path.stem,
                        model_id=self.compare_model["id"], model_family=self.compare_model["family"],
                        cfg=self.cfg, on_partial_result=self.compare_partial_ready.emit,
                        on_log=self._emit_log_safe, stop_event=self.stop_event,
                        api_keys=api_keys, global_key_mgr=self.global_key_mgr,
                        parallel_workers=w, request_counter=self.request_counter)
                    comparator.start()
                    try:
                        register_stop_component("comparators", comparator)
                    except Exception:
                        pass
                except Exception as e:
                    self._emit_log_safe(f"⚠️ مقارن {in_path.name}: {e}")

            txt_ctx = TxtContextManager(in_path, self._emit_log_safe) if (is_txt and should_upload_full_txt_context(self.cfg)) else None
            jobs.append(BookExtractJob(
                idx=i, path=in_path, stem=eff_stem, is_txt=is_txt,
                total_units=total_units, shards=shards, pending=pending,
                parts_dir=parts_dir, ckpt=ckpt, system_prompt=sp,
                comparator=comparator, txt_ctx=txt_ctx, pool=pool,
            ))
            self._emit_log_safe(
                f"📚 {in_path.name}: {len(shards)} جزء | معلّق {len(pending)} | وحدات {total_units}")

        if not jobs:
            return
        orch = MultiBookParallelOrchestrator(
            jobs, model=self.model, cfg=self.cfg, global_key_mgr=self.global_key_mgr,
            on_token=self._emit_token_safe, on_log=self._emit_log_safe,
            on_progress=self.progress_updated.emit, on_upload_progress=self.upload_progress.emit,
            on_compare_partial=self.compare_partial_ready.emit,
            on_compare_final=self.compare_final_ready.emit,
            on_request=self._emit_request_sent_safe, on_key_used=self._emit_key_used_safe,
            on_stream_event=self.stream_event.emit,
            on_book_started=lambda name, idx: self.book_started.emit(name, idx),
            on_book_finished=lambda res, idx: self.book_finished.emit(res, idx),
            stop_event=self.stop_event, pause_event=self.pause_event,
            request_counter=self.request_counter)
        orch.run()


