class NoKeysWelcomeDialog(QDialog):
    def __init__(self, parent):
        super().__init__(parent)
        self.setWindowTitle("🔑 إنشاء مفتاح API")
        self.resize(820, 700)
        self.setLayoutDirection(Qt.LayoutDirection.RightToLeft)
        layout = QVBoxLayout(self)
        layout.setContentsMargins(24, 24, 24, 24)
        layout.setSpacing(14)
        try:
            self.setFont(QApplication.font())
        except Exception:
            self.setFont(QFont("Tahoma, Segoe UI, Arial", 10))
        header = QLabel("👋 <b>مرحباً بك في PDF Master Pro v10.20!</b>")
        header_font = QFont(self.font())
        header_font.setPointSize(21)
        header_font.setBold(True)
        header.setFont(header_font)
        header.setAlignment(Qt.AlignmentFlag.AlignCenter)
        header.setStyleSheet(
            "color:#89b4fa; font-size:21px; padding:10px; "
            "background:#181825; border:1px solid #45475a; border-radius:10px;")
        layout.addWidget(header)
        msg = QLabel(
            "<b style='color:#f9e2af'>⚠️ لا توجد مفاتيح API.</b><br><br>"
            "البرنامج يحتاج إلى مفتاح API واحد على الأقل من <b>Google AI Studio</b> "
            "حتى يبدأ الاستخراج والمقارنة."
        )
        msg.setWordWrap(True)
        msg_font = QFont(self.font())
        msg_font.setPointSize(13)
        msg.setFont(msg_font)
        msg.setTextFormat(Qt.TextFormat.RichText)
        msg.setStyleSheet("padding:12px; background:#11111b; border:1px solid #45475a; border-radius:10px;")
        layout.addWidget(msg)
        steps_label = QLabel("📋 <b>خطوات إنشاء مفتاح:</b>")
        steps_label.setStyleSheet("color:#f9e2af; padding:6px; font-size:14px; font-weight:800;")
        layout.addWidget(steps_label)
        steps = QPlainTextEdit()
        steps.setReadOnly(True)
        steps.setLayoutDirection(Qt.LayoutDirection.RightToLeft)
        steps.setPlainText(
            "1) افتح متصفح الإنترنت.\n\n"
            "2) اذهب إلى:\n   https://aistudio.google.com/app/apikey\n\n"
            "3) سجّل دخولك بحساب Google (Gmail).\n\n"
            "4) اضغط: Create API key.\n\n"
            "5) اختر: Create API key in new project.\n\n"
            "6) انسخ المفتاح (غالباً يبدأ بـ AIzaSy...).\n\n"
            "7) أضِفه في تبويب الإعدادات والمفاتيح ← المفاتيح.\n\n"
            "💡 يمكنك إنشاء عدة مفاتيح من حسابات مختلفة لتسريع المعالجة."
        )
        steps.setMaximumHeight(320)
        steps_font = QFont(self.font())
        steps_font.setPointSize(12)
        steps.setFont(steps_font)
        steps.setStyleSheet(
            "background-color:#181825; color:#cdd6f4; padding:14px; "
            "border:1px solid #45475a; border-radius:10px;")
        layout.addWidget(steps, 1)
        bottom_row = QHBoxLayout()
        self.dont_show_check = QCheckBox("لا تُظهر هذه الرسالة مرة أخرى")
        self.dont_show_check.setStyleSheet("font-size:13px; font-weight:700; color:#cdd6f4;")
        bottom_row.addWidget(self.dont_show_check)
        bottom_row.addStretch(1)
        btn_open = QPushButton("🌐 فتح Google AI Studio")
        btn_open.setObjectName("primaryBtn")
        btn_open.setMinimumHeight(36)
        btn_open.clicked.connect(self._open_studio)
        bottom_row.addWidget(btn_open)
        btn_close = QPushButton("✓ فهمت")
        btn_close.setObjectName("successBtn")
        btn_close.setMinimumHeight(36)
        btn_close.clicked.connect(self.accept)
        bottom_row.addWidget(btn_close)
        layout.addLayout(bottom_row)

    def _open_studio(self):
        url = "https://aistudio.google.com/app/apikey"
        try:
            if sys.platform == "win32":
                os.startfile(url)
            elif sys.platform == "darwin":
                subprocess.run(["open", url])
            else:
                subprocess.run(["xdg-open", url])
        except Exception as e:
            QMessageBox.warning(self, "خطأ",
                f"افتح يدوياً:\n{url}\n\n{e}")

    def dont_show_again(self) -> bool:
        return self.dont_show_check.isChecked()


class AddKeysDialog(QDialog):
    def __init__(self, parent):
        super().__init__(parent)
        self.setWindowTitle("➕ إضافة مفاتيح API")
        self.resize(700, 500)
        self.setLayoutDirection(Qt.LayoutDirection.RightToLeft)
        layout = QVBoxLayout(self)
        layout.setContentsMargins(15, 15, 15, 15); layout.setSpacing(10)
        info = QLabel("📋 ألصق المفاتيح (مفتاح في كل سطر):")
        info.setObjectName("headerLabel")
        layout.addWidget(info)
        self.editor = QPlainTextEdit()
        self.editor.setPlaceholderText("AIzaSy-xxx-1...\nAIzaSy-xxx-2...")
        self.editor.setFont(QFont("Cascadia Mono, Consolas", 11))
        layout.addWidget(self.editor, 1)
        self.replace_check = QCheckBox("استبدال الحالية")
        layout.addWidget(self.replace_check)
        btns = QDialogButtonBox(
            QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Cancel)
        btns.button(QDialogButtonBox.StandardButton.Ok).setText("✓ إضافة")
        btns.button(QDialogButtonBox.StandardButton.Cancel).setText("إلغاء")
        btns.accepted.connect(self.accept); btns.rejected.connect(self.reject)
        layout.addWidget(btns)

    def get_keys(self) -> List[str]:
        keys = []
        for line in self.editor.toPlainText().splitlines():
            line = line.strip()
            if line and not line.startswith("#"):
                keys.append(line)
        return keys

    def is_replace(self) -> bool:
        return self.replace_check.isChecked()


class ModelsSelectionDialog(QDialog):
    def __init__(self, parent, all_models, selected_ids):
        super().__init__(parent)
        self.setWindowTitle("🤖 اختر النماذج")
        self.resize(750, 650)
        self.setLayoutDirection(Qt.LayoutDirection.RightToLeft)
        self.all_models = all_models
        self.selected_ids = set(selected_ids)
        self.checkboxes = []
        layout = QVBoxLayout(self)
        layout.setContentsMargins(14, 14, 14, 14)
        info = QLabel(f"✅ {len(all_models)} نموذج متاح:")
        info.setObjectName("headerLabel")
        layout.addWidget(info)
        quick = QHBoxLayout()
        for txt, action in [("✅ الكل", self._select_all),
                              ("⬜ لا شيء", self._select_none),
                              ("⭐ الموصى به", self._select_recommended)]:
            b = QPushButton(txt); b.clicked.connect(action); quick.addWidget(b)
        quick.addStretch(1); layout.addLayout(quick)
        scroll = QScrollArea(); scroll.setWidgetResizable(True)
        container = QWidget(); v = QVBoxLayout(container); v.setSpacing(6)
        for m in all_models:
            cb = QCheckBox(m["label"])
            cb.setChecked(m["id"] in self.selected_ids)
            if m.get("description"):
                cb.setToolTip(m["description"])
            v.addWidget(cb); self.checkboxes.append((cb, m))
        v.addStretch(1); scroll.setWidget(container)
        layout.addWidget(scroll, 1)
        btns = QDialogButtonBox(
            QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Cancel)
        btns.button(QDialogButtonBox.StandardButton.Ok).setText("💾 حفظ")
        btns.button(QDialogButtonBox.StandardButton.Cancel).setText("إلغاء")
        btns.accepted.connect(self.accept); btns.rejected.connect(self.reject)
        layout.addWidget(btns)

    def _select_all(self):
        for cb, _ in self.checkboxes: cb.setChecked(True)
    def _select_none(self):
        for cb, _ in self.checkboxes: cb.setChecked(False)
    def _select_recommended(self):
        for cb, m in self.checkboxes:
            mid = m["id"].lower()
            cb.setChecked("gemini-2.5" in mid or "gemini-3" in mid)

    def get_selected(self):
        return [m for cb, m in self.checkboxes if cb.isChecked()]


class PromptEditorDialog(QDialog):
    def __init__(self, parent, title, content):
        super().__init__(parent)
        self.setWindowTitle(title); self.resize(900, 650)
        self.setLayoutDirection(Qt.LayoutDirection.RightToLeft)
        layout = QVBoxLayout(self); layout.setContentsMargins(15, 15, 15, 15)
        info = QLabel("✏️ عدّل البرومبت:"); info.setObjectName("headerLabel")
        layout.addWidget(info)
        self.editor = QPlainTextEdit()
        self.editor.setPlainText(content)
        self.editor.setFont(QFont("Cascadia Mono, Consolas", 11))
        self.editor.setLayoutDirection(Qt.LayoutDirection.RightToLeft)
        layout.addWidget(self.editor, 1)
        btns = QDialogButtonBox(
            QDialogButtonBox.StandardButton.Save | QDialogButtonBox.StandardButton.Cancel)
        btns.button(QDialogButtonBox.StandardButton.Save).setText("💾 حفظ")
        btns.button(QDialogButtonBox.StandardButton.Cancel).setText("إلغاء")
        btns.accepted.connect(self.accept); btns.rejected.connect(self.reject)
        layout.addWidget(btns)

    def get_content(self) -> str:
        return self.editor.toPlainText()


class CustomPromptEditorDialog(QDialog):
    """محرر البرومبت المخصص: تبويب للاستخراج وتبويب للمقارنة."""
    def __init__(self, parent, pdf_content: str, txt_content: str,
                 compare_content: str, compare_enabled: bool = True,
                 upload_full_txt_context: bool = False):
        super().__init__(parent)
        self.setWindowTitle("✏️ البرومبت المخصص")
        self.resize(1000, 720)
        self.setLayoutDirection(Qt.LayoutDirection.RightToLeft)
        layout = QVBoxLayout(self)
        layout.setContentsMargins(15, 15, 15, 15)
        tabs = QTabWidget()
        try:
            tabs.tabBar().setExpanding(True)
        except Exception:
            pass

        # تبويب الاستخراج: يحافظ على PDF و TXT بدون فقد ميزة دعم النصوص.
        extract_tab = QWidget()
        ev = QVBoxLayout(extract_tab)
        ev.setContentsMargins(8, 8, 8, 8)
        ev.addWidget(QLabel("📄 برومبت استخراج PDF:"))
        self.pdf_editor = QPlainTextEdit()
        self.pdf_editor.setPlainText(pdf_content or "")
        self.pdf_editor.setFont(QFont("Cascadia Mono, Consolas", 11))
        self.pdf_editor.setLayoutDirection(Qt.LayoutDirection.RightToLeft)
        ev.addWidget(self.pdf_editor, 1)
        ev.addWidget(QLabel("📝 برومبت معالجة الملفات النصية:"))
        self.txt_editor = QPlainTextEdit()
        self.txt_editor.setPlainText(txt_content or "")
        self.txt_editor.setFont(QFont("Cascadia Mono, Consolas", 11))
        self.txt_editor.setLayoutDirection(Qt.LayoutDirection.RightToLeft)
        ev.addWidget(self.txt_editor, 1)
        self.upload_full_txt_context_check = QCheckBox("📎 رفع الملف النصي الكامل كسياق مرجعي مع البرومبت المخصص")
        self.upload_full_txt_context_check.setChecked(bool(upload_full_txt_context))
        self.upload_full_txt_context_check.setToolTip("عند عدم التفعيل تُرفع الدفعات المقسمة فقط. هذا الخيار يخص البرومبت المخصص فقط.")
        ev.addWidget(self.upload_full_txt_context_check)
        tabs.addTab(extract_tab, "📝 برومبت الاستخراج")

        compare_tab = QWidget()
        cv = QVBoxLayout(compare_tab)
        cv.setContentsMargins(8, 8, 8, 8)
        self.compare_enabled_check = QCheckBox("✅ تفعيل المقارنة مع البرومبت المخصص")
        self.compare_enabled_check.setChecked(bool(compare_enabled))
        cv.addWidget(self.compare_enabled_check)
        hint = QLabel("اترك برومبت المقارنة فارغاً أو ألغِ التفعيل إذا كنت لا تريد مقارنة الناتج في وضع البرومبت المخصص.")
        hint.setWordWrap(True)
        hint.setStyleSheet("color:#f9e2af; padding:4px;")
        cv.addWidget(hint)
        self.compare_editor = QPlainTextEdit()
        self.compare_editor.setPlainText(compare_content or "")
        self.compare_editor.setPlaceholderText("اكتب هنا تعليمات مقارنة الناتج بالمطلوب عند استخدام البرومبت المخصص...")
        self.compare_editor.setFont(QFont("Cascadia Mono, Consolas", 11))
        self.compare_editor.setLayoutDirection(Qt.LayoutDirection.RightToLeft)
        cv.addWidget(self.compare_editor, 1)
        tabs.addTab(compare_tab, "🔍 برومبت المقارنة")

        layout.addWidget(tabs, 1)
        btns = QDialogButtonBox(QDialogButtonBox.StandardButton.Save | QDialogButtonBox.StandardButton.Cancel)
        btns.button(QDialogButtonBox.StandardButton.Save).setText("💾 حفظ")
        btns.button(QDialogButtonBox.StandardButton.Cancel).setText("إلغاء")
        btns.accepted.connect(self.accept)
        btns.rejected.connect(self.reject)
        layout.addWidget(btns)

    def get_pdf_prompt(self) -> str:
        return self.pdf_editor.toPlainText()

    def get_txt_prompt(self) -> str:
        return self.txt_editor.toPlainText()

    def get_compare_prompt(self) -> str:
        return self.compare_editor.toPlainText()

    def is_compare_enabled(self) -> bool:
        return self.compare_enabled_check.isChecked()

    def upload_full_txt_context(self) -> bool:
        return self.upload_full_txt_context_check.isChecked()


# ═══════════════════════════════════════════════════════════════════
#  ✨ v22: ManualShardSelectionDialog — نافذة اختيار الأجزاء يدوياً
# ═══════════════════════════════════════════════════════════════════

class VerificationResultsDialog(QDialog):
    """✅ v25.4: شاشة مستقلة لعرض نتائج المقارنة الأولى والثانية جنباً إلى جنب."""
    def __init__(self, parent, shards: List[PDFShard],
                  primary_results: Dict[int, 'ShardComparisonResult'],
                  secondary_results: Dict[int, 'ShardComparisonResult'],
                  book_stem: str):
        super().__init__(parent)
        self.setWindowTitle("🔍 نتائج المقارنة المزدوجة (تحقق)")
        self.resize(1000, 600)
        self.shards = [s for s in shards if not s.is_txt]
        self.primary = primary_results
        self.secondary = secondary_results

        layout = QVBoxLayout(self)
        layout.setContentsMargins(12, 12, 12, 12)

        header = QLabel(f"📊 <b>المقارنة المزدوجة — {book_stem}</b>")
        header.setStyleSheet("color: #cdd6f4; font-size: 14px; padding: 8px;"
                              "background: #181825; border-radius: 6px;")
        layout.addWidget(header)

        self.table = QTableWidget()
        self.table.setColumnCount(8)
        self.table.setHorizontalHeaderLabels([
            "جزء", "صفحات",
            "① تقييم", "① تغطية%",
            "② تقييم", "② تغطية%",
            "حكم", "ملاحظات"
        ])
        self.table.horizontalHeader().setSectionResizeMode(
            7, QHeaderView.ResizeMode.Stretch)
        for i in range(7):
            self.table.horizontalHeader().setSectionResizeMode(
                i, QHeaderView.ResizeMode.ResizeToContents)
        self._populate()
        layout.addWidget(self.table, 1)

        btn_close = QPushButton("إغلاق")
        btn_close.clicked.connect(self.accept)
        layout.addWidget(btn_close)

    def _color(self, assessment, pct):
        return coverage_color(pct, assessment)

    def _populate(self):
        sorted_shards = sorted(self.shards, key=lambda s: s.idx)
        # Only show shards that have at least one result
        rows = []
        for s in sorted_shards:
            r1 = self.primary.get(s.idx)
            r2 = self.secondary.get(s.idx)
            if r1 or r2:
                rows.append((s, r1, r2))

        self.table.setRowCount(len(rows))
        for row, (s, r1, r2) in enumerate(rows):
            self.table.setItem(row, 0, QTableWidgetItem(str(s.idx)))
            self.table.setItem(row, 1, QTableWidgetItem(f"{s.page_start}-{s.page_end}"))

            # Primary
            if r1 and r1.error is None:
                a1 = QTableWidgetItem(r1.assessment)
                a1.setForeground(QColor(self._color(r1.assessment, r1.coverage_pct)))
                self.table.setItem(row, 2, a1)
                c1 = QTableWidgetItem(f"{r1.coverage_pct}%")
                c1.setForeground(QColor(self._color(r1.assessment, r1.coverage_pct)))
                self.table.setItem(row, 3, c1)
            else:
                self.table.setItem(row, 2, QTableWidgetItem("—"))
                self.table.setItem(row, 3, QTableWidgetItem("—"))

            # Secondary
            if r2 and r2.error is None:
                a2 = QTableWidgetItem(r2.assessment)
                a2.setForeground(QColor(self._color(r2.assessment, r2.coverage_pct)))
                self.table.setItem(row, 4, a2)
                c2 = QTableWidgetItem(f"{r2.coverage_pct}%")
                c2.setForeground(QColor(self._color(r2.assessment, r2.coverage_pct)))
                self.table.setItem(row, 5, c2)
            else:
                self.table.setItem(row, 4, QTableWidgetItem("⏳"))
                self.table.setItem(row, 5, QTableWidgetItem("—"))

            # Verdict
            verdict = "—"
            if r1 and r2 and r1.error is None and r2.error is None:
                if r1.coverage_pct >= 95 and r2.coverage_pct >= 95:
                    verdict = "✅ ثقة عالية"
                elif abs(r1.coverage_pct - r2.coverage_pct) > 20:
                    verdict = "⚠️ تباين كبير"
                elif r1.coverage_pct < 80 and r2.coverage_pct < 80:
                    verdict = "❌ ضعيف مؤكد"
                else:
                    verdict = "🔶 مقبول"
            v_item = QTableWidgetItem(verdict)
            if "✅" in verdict: v_item.setForeground(QColor("#a6e3a1"))
            elif "❌" in verdict: v_item.setForeground(QColor("#f38ba8"))
            elif "⚠️" in verdict: v_item.setForeground(QColor("#fab387"))
            self.table.setItem(row, 6, v_item)

            # Notes
            notes_parts = []
            if r1 and r1.error is None and r1.notes: notes_parts.append(f"①{r1.notes[:40]}")
            if r2 and r2.error is None and r2.notes: notes_parts.append(f"②{r2.notes[:40]}")
            self.table.setItem(row, 7, QTableWidgetItem(" | ".join(notes_parts)))

        self.table.setUpdatesEnabled(True)


class ManualShardSelectionDialog(QDialog):
    """نافذة لاختيار الأجزاء لإعادة فحصها يدوياً أو إعادة استخراجها."""

    def __init__(self, parent, shards: List[PDFShard],
                  partial_results: Dict[int, ShardComparisonResult],
                  book_stem: str,
                  allow_reextract: bool = True,
                  title: Optional[str] = None):
        super().__init__(parent)
        self.setWindowTitle(title or "🔬 اختيار الأجزاء لإعادة الفحص اليدوي")
        self.resize(900, 700)
        self.setLayoutDirection(Qt.LayoutDirection.RightToLeft)
        self.shards = [s for s in shards if not s.is_txt]  # PDF فقط
        self.partial_results = partial_results
        self.book_stem = book_stem
        self.allow_reextract = allow_reextract
        self.checkboxes: List[Tuple[QCheckBox, PDFShard]] = []
        self._selected_indices: List[int] = []
        self._action_mode: str = "recheck"  # recheck | reextract
        self._build_ui()

    def _build_ui(self):
        layout = QVBoxLayout(self)
        layout.setContentsMargins(15, 15, 15, 15)
        layout.setSpacing(10)

        # ─── العنوان ───
        header = QLabel(
            f"🔬 <b>إعادة الفحص اليدوي للأجزاء</b><br>"
            f"الكتاب: <b style='color:#f9e2af'>{self.book_stem}</b><br>"
            f"إجمالي الأجزاء (PDF): <b style='color:#a6e3a1'>{len(self.shards)}</b>")
        header.setStyleSheet(
            "background-color: #181825; border: 2px solid #f5c2e7;"
            "border-radius: 8px; padding: 10px; color: #cdd6f4;")
        header.setWordWrap(True)
        layout.addWidget(header)

        # ─── شريط معلومات ───
        info = QLabel(
            "💡 <b>كيف يعمل؟</b><br>"
            "• اختر الأجزاء التي تريد إعادة مقارنتها بالـ PDF الأصلي.<br>"
            "• سيتم رفع PDF كل جزء <b>من جديد</b> ومقارنته بالنص المستخرج.<br>"
            "• <b style='color:#f5c2e7'>مفيد جداً</b> عندما يدّعي النموذج \"التطابق\" خطأً.<br>"
            "• يُستخدم برومبت مُشدَّد يمنع ادعاء التطابق دون تدقيق فعلي.")
        info.setWordWrap(True)
        info.setStyleSheet("color: #a6adc8; padding: 6px; font-weight: 600;")
        layout.addWidget(info)

        # ─── أزرار التحديد السريع ───
        quick_group = QGroupBox("⚡ تحديد سريع")
        quick_layout = QGridLayout(quick_group)
        quick_layout.setSpacing(6)
        quick_layout.setContentsMargins(10, 18, 10, 10)

        btn_all = QPushButton("✅ اختر الكل")
        btn_all.setObjectName("primaryBtn")
        btn_all.clicked.connect(self._select_all)
        quick_layout.addWidget(btn_all, 0, 0)

        btn_none = QPushButton("⬜ لا شيء")
        btn_none.clicked.connect(self._select_none)
        quick_layout.addWidget(btn_none, 0, 1)

        btn_invert = QPushButton("🔄 المعكوس")
        btn_invert.clicked.connect(self._select_invert)
        quick_layout.addWidget(btn_invert, 0, 2)

        btn_weak = QPushButton("🔴 الضعيف فقط (<100%)")
        btn_weak.setObjectName("warningBtn")
        btn_weak.clicked.connect(lambda: self._select_below(100))
        quick_layout.addWidget(btn_weak, 1, 0)

        btn_under80 = QPushButton("🟠 تحت 80%")
        btn_under80.clicked.connect(lambda: self._select_below(80))
        quick_layout.addWidget(btn_under80, 1, 1)

        btn_unchecked = QPushButton("⏳ لم تُقارن بعد")
        btn_unchecked.clicked.connect(self._select_never_compared)
        quick_layout.addWidget(btn_unchecked, 1, 2)

        layout.addWidget(quick_group)

        # ─── شريط البحث/الفلتر ───
        filter_row = QHBoxLayout()
        filter_row.addWidget(QLabel("🔍 تصفية بالنطاق:"))
        self.filter_from = QSpinBox()
        self.filter_from.setRange(0, 99999)
        self.filter_from.setPrefix("من جزء: ")
        self.filter_from.setMinimumWidth(120)
        filter_row.addWidget(self.filter_from)
        self.filter_to = QSpinBox()
        self.filter_to.setRange(0, 99999)
        self.filter_to.setPrefix("إلى: ")
        self.filter_to.setMinimumWidth(120)
        filter_row.addWidget(self.filter_to)
        btn_apply_filter = QPushButton("✅ اختر النطاق")
        btn_apply_filter.clicked.connect(self._select_range)
        filter_row.addWidget(btn_apply_filter)
        filter_row.addStretch(1)
        layout.addLayout(filter_row)

        # ─── الجدول ───
        if self.shards:
            min_idx = min(s.idx for s in self.shards)
            max_idx = max(s.idx for s in self.shards)
            self.filter_from.setValue(min_idx)
            self.filter_to.setValue(max_idx)

        self.table = QTableWidget()
        self.table.setColumnCount(6)
        self.table.setHorizontalHeaderLabels(
            ["✓", "جزء", "صفحات", "التغطية", "الفجوات", "التقييم"])
        self.table.horizontalHeader().setSectionResizeMode(
            5, QHeaderView.ResizeMode.Stretch)
        for i in range(5):
            self.table.horizontalHeader().setSectionResizeMode(
                i, QHeaderView.ResizeMode.ResizeToContents)
        self.table.setSelectionBehavior(QAbstractItemView.SelectionBehavior.SelectRows)
        self.table.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
        self._populate_table()
        layout.addWidget(self.table, 1)

        # ─── شريط الحالة (عدد المختار) ───
        self.status_label = QLabel("✅ المختار: 0 / 0")
        self.status_label.setStyleSheet(
            "color: #a6e3a1; font-weight: 800; font-size: 13px;"
            "background-color: #181825; border: 1px solid #a6e3a1;"
            "border-radius: 6px; padding: 8px;")
        layout.addWidget(self.status_label)

        # ─── أزرار الموافقة/الإلغاء + إعادة الاستخراج ───
        btns_row = QHBoxLayout()
        if self.allow_reextract:
            self.btn_reextract_selected = QPushButton("♻️ إعادة استخراج الأجزاء المختارة")
            self.btn_reextract_selected.setObjectName("warningBtn")
            self.btn_reextract_selected.setToolTip(
                "يحذف ناتج الأجزاء المختارة ويستخرجها من جديد (وليس فحصها فقط)")
            self.btn_reextract_selected.clicked.connect(self._on_accept_reextract)
            btns_row.addWidget(self.btn_reextract_selected)

        btns = QDialogButtonBox(
            QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Cancel)
        btns.button(QDialogButtonBox.StandardButton.Ok).setText(
            "🔬 تنفيذ إعادة الفحص للأجزاء المختارة")
        btns.button(QDialogButtonBox.StandardButton.Ok).setObjectName("manualBtn")
        btns.button(QDialogButtonBox.StandardButton.Cancel).setText("إلغاء")
        btns.accepted.connect(self._on_accept)
        btns.rejected.connect(self.reject)
        btns_row.addWidget(btns)
        layout.addLayout(btns_row)

        self._update_status()

    def _populate_table(self):
        self.table.setUpdatesEnabled(False)
        self.table.setRowCount(len(self.shards))
        self.table.verticalHeader().setDefaultSectionSize(38)
        self.checkboxes.clear()

        sorted_shards = sorted(self.shards, key=lambda s: s.idx)
        for row, shard in enumerate(sorted_shards):
            if row % 25 == 0:
                QApplication.processEvents()
            # ─── مربع الاختيار ───
            cb = QCheckBox()
            cb.stateChanged.connect(self._update_status)
            cell_widget = QWidget()
            cell_layout = QHBoxLayout(cell_widget)
            cell_layout.setContentsMargins(0, 0, 0, 0)
            cell_layout.addWidget(cb, alignment=Qt.AlignmentFlag.AlignCenter)
            self.table.setCellWidget(row, 0, cell_widget)
            self.checkboxes.append((cb, shard))

            # ─── رقم الجزء ───
            self.table.setItem(row, 1, QTableWidgetItem(str(shard.idx)))

            # ─── الصفحات ───
            self.table.setItem(row, 2, QTableWidgetItem(
                f"{shard.page_start}-{shard.page_end}"))

            # ─── معلومات المقارنة ───
            result = self.partial_results.get(shard.idx)
            if result is None:
                self.table.setItem(row, 3, QTableWidgetItem("⏳ لم تُقارن"))
                self.table.setItem(row, 4, QTableWidgetItem("—"))
                tag = QTableWidgetItem("⏳ في الانتظار")
                tag.setForeground(QColor("#a6adc8"))
                self.table.setItem(row, 5, tag)
            elif result.error is not None:
                self.table.setItem(row, 3, QTableWidgetItem("❌ خطأ"))
                self.table.setItem(row, 4, QTableWidgetItem("—"))
                tag = QTableWidgetItem(f"❌ {result.error[:60]}")
                tag.setForeground(QColor("#f38ba8"))
                self.table.setItem(row, 5, tag)
            else:
                cov = result.coverage_pct
                cov_item = QTableWidgetItem(f"{cov}%")
                if cov >= 95: cov_item.setForeground(QColor("#a6e3a1"))
                elif cov >= 80: cov_item.setForeground(QColor("#f9e2af"))
                else: cov_item.setForeground(QColor("#f38ba8"))
                self.table.setItem(row, 3, cov_item)

                gaps_item = QTableWidgetItem(str(len(result.missing_items)))
                if len(result.missing_items) == 0: gaps_item.setForeground(QColor("#a6e3a1"))
                elif len(result.missing_items) <= 2: gaps_item.setForeground(QColor("#f9e2af"))
                else: gaps_item.setForeground(QColor("#f38ba8"))
                self.table.setItem(row, 4, gaps_item)

                assess_item = QTableWidgetItem(result.assessment)
                color_map = {"ممتاز": "#a6e3a1", "جيد": "#94e2d5",
                              "متوسط": "#f9e2af", "ضعيف": "#f38ba8"}
                if result.assessment in color_map:
                    assess_item.setForeground(QColor(color_map[result.assessment]))
                self.table.setItem(row, 5, assess_item)

        self.table.setUpdatesEnabled(True)

    def _select_all(self):
        for cb, _ in self.checkboxes:
            cb.setChecked(True)

    def _select_none(self):
        for cb, _ in self.checkboxes:
            cb.setChecked(False)

    def _select_invert(self):
        for cb, _ in self.checkboxes:
            cb.setChecked(not cb.isChecked())

    def _select_below(self, threshold: int):
        for cb, shard in self.checkboxes:
            result = self.partial_results.get(shard.idx)
            if result is None or result.error is not None:
                cb.setChecked(False)
                continue
            cb.setChecked(result.coverage_pct < threshold)

    def _select_never_compared(self):
        for cb, shard in self.checkboxes:
            result = self.partial_results.get(shard.idx)
            cb.setChecked(result is None or result.error is not None)

    def _select_range(self):
        f = self.filter_from.value()
        t = self.filter_to.value()
        if f > t:
            f, t = t, f
        for cb, shard in self.checkboxes:
            cb.setChecked(f <= shard.idx <= t)

    def _update_status(self):
        selected = sum(1 for cb, _ in self.checkboxes if cb.isChecked())
        total = len(self.checkboxes)
        self.status_label.setText(f"✅ المختار: {selected} / {total}")
        if selected == 0:
            self.status_label.setStyleSheet(
                "color: #f38ba8; font-weight: 800; font-size: 13px;"
                "background-color: #181825; border: 1px solid #f38ba8;"
                "border-radius: 6px; padding: 8px;")
        elif selected == total:
            self.status_label.setStyleSheet(
                "color: #cba6f7; font-weight: 800; font-size: 13px;"
                "background-color: #181825; border: 1px solid #cba6f7;"
                "border-radius: 6px; padding: 8px;")
        else:
            self.status_label.setStyleSheet(
                "color: #a6e3a1; font-weight: 800; font-size: 13px;"
                "background-color: #181825; border: 1px solid #a6e3a1;"
                "border-radius: 6px; padding: 8px;")

    def _collect_selected(self) -> List[int]:
        return sorted([
            shard.idx for cb, shard in self.checkboxes if cb.isChecked()
        ])

    def _on_accept(self):
        self._selected_indices = self._collect_selected()
        if not self._selected_indices:
            QMessageBox.warning(self, "⚠️ تنبيه",
                "لم تختر أي جزء.\n\nاختر جزءاً واحداً على الأقل لإعادة فحصه.")
            return
        self._action_mode = "recheck"
        self.accept()

    def _on_accept_reextract(self):
        self._selected_indices = self._collect_selected()
        if not self._selected_indices:
            QMessageBox.warning(self, "⚠️ تنبيه",
                "لم تختر أي جزء.\n\nاختر جزءاً واحداً على الأقل لإعادة استخراجه.")
            return
        ans = QMessageBox.question(
            self, "تأكيد إعادة الاستخراج",
            f"♻️ سيتم <b>حذف ناتج</b> <b>{len(self._selected_indices)}</b> جزء "
            f"وإعادة استخراجها من جديد.<br><br>هل تريد المتابعة؟",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No)
        if ans != QMessageBox.StandardButton.Yes:
            return
        self._action_mode = "reextract"
        self.accept()

    def get_selected_indices(self) -> List[int]:
        return self._selected_indices

    def get_action_mode(self) -> str:
        return self._action_mode


