class PartsViewerDialog(QDialog):
    """✅ v24.7: متصفح الأجزاء — أزرار + تقرير مقارنة لكل جزء."""
    def __init__(self, parent, parts_dir: Path, book_stem: str,
                  shards_dir: Optional[Path] = None,
                  compare_results: Optional[Dict] = None,
                  secondary_results: Optional[Dict] = None):
        super().__init__(parent)
        self.parts_dir = parts_dir
        self.book_stem = book_stem
        self.shards_dir = shards_dir
        self._main_window = _resolve_part_actions_main_window(parent)
        self._waiting_for_reextract = False
        self._render_thread: Optional[QThread] = None
        self._render_worker: Optional[PdfPageRenderWorker] = None
        self._render_serial = 0
        self._render_active_serial = 0
        self._render_active_key = None
        self.compare_results = compare_results or {}
        self.secondary_results = secondary_results or {}  # idx → ShardComparisonResult
        self.setWindowTitle("📄 الأجزاء المستخرجة + تقارير المقارنة")
        self.setMinimumSize(620, 500)
        # حجم افتراضي أوسع قليلاً حتى تظهر أزرار الجزء وتفاصيله دون حجب.
        self.resize(960, 620)
        saved_size = {}
        try:
            saved_size = self._main_window.settings.get("parts_viewer_size", {}) or {}
        except Exception:
            pass
        try:
            saved_w = int(saved_size.get("width", 0) or 0)
            saved_h = int(saved_size.get("height", 0) or 0)
            if saved_w >= 620 and saved_h >= 500:
                self.resize(saved_w, saved_h)
        except Exception:
            pass
        self.setStyleSheet("""
            QDialog { background-color: #1e1e2e; }
            QPushButton {
                background-color: #313244; color: #cdd6f4;
                border: 1px solid #45475a; border-radius: 6px;
                padding: 6px 10px; font-size: 11px; font-weight: bold;
            }
            QPushButton:hover { background-color: #45475a; }
            QPushButton:disabled { background-color: #181825; color: #585b70; }
            QLabel { color: #cdd6f4; font-size: 12px; }
            QScrollArea { border: none; background-color: #1e1e2e; }
        """)
        layout = QVBoxLayout(self)
        layout.setSpacing(10)
        layout.setContentsMargins(15, 15, 15, 15)

        self.lbl_count = QLabel("⏳ جارٍ البحث...")
        layout.addWidget(self.lbl_count)

        scroll = QScrollArea()
        scroll.setWidgetResizable(True)
        self.scroll_widget = QWidget()
        self.vbox = QVBoxLayout(self.scroll_widget)
        self.vbox.setSpacing(6)
        self.vbox.setContentsMargins(5, 5, 5, 5)
        self.vbox.addStretch(1)
        scroll.setWidget(self.scroll_widget)
        layout.addWidget(scroll, 1)

        self._parts: dict = {}  # idx → (row_widget, lbl_compare)
        QTimer.singleShot(30, self._scan_parts)

    def _grade_color(self, assessment: str, pct: int) -> str:
        return coverage_color(pct, assessment)

    def refresh(self):
        """تحديث قائمة الأجزاء مع إبقاء الصفوف الموجودة وعدم تفريغ الشاشة."""
        self._scan_parts()

    def _scan_parts(self):
        if not self.parts_dir or not self.parts_dir.exists():
            self.lbl_count.setText(f"⚠️ مجلد الأجزاء غير موجود: {self.parts_dir}")
            return
        # ✅ v24.8: مسح كل ملفات الأجزاء (نمطين مختلفين)
        found = []
        for pattern in [f"{self.book_stem}_part_*.txt", "*_part_*.txt"]:
            found = sorted(self.parts_dir.glob(pattern))
            if found:
                break
        for pf in found:
            m = re.match(r".*_part_(\d+)\.txt$", pf.name)
            if not m:
                continue
            idx = int(m.group(1))
            if idx not in self._parts:
                self._add_part_row(idx, pf)
            self._update_compare_label(idx)

        self.lbl_count.setText(f"📄 {len(self._parts)} جزء مستخرج")

    def _add_part_row(self, idx: int, pf: Path):
        row = QHBoxLayout()
        row.setSpacing(8)

        # اسم الجزء
        lbl = QLabel(f"جزء {idx}")
        lbl.setFixedWidth(55)
        lbl.setStyleSheet("font-weight: bold; font-size: 12px;")
        row.addWidget(lbl)

        # زر النص
        btn_txt = QPushButton("📝 نص")
        btn_txt.setFixedWidth(65)
        btn_txt.setToolTip(f"فتح الملف النصي للجزء {idx}")
        btn_txt.clicked.connect(lambda checked, p=str(pf): self._open_file(p))
        row.addWidget(btn_txt)

        # زر PDF
        btn_pdf = QPushButton("📄 PDF")
        btn_pdf.setFixedWidth(65)
        btn_pdf.setToolTip(f"فتح جزء الـ PDF رقم {idx}")
        pdf_path = self._find_shard_pdf(idx)
        if pdf_path:
            btn_pdf.clicked.connect(lambda checked, p=pdf_path: self._open_file(p))
        else:
            btn_pdf.setEnabled(False)
        row.addWidget(btn_pdf)

        # إجراءات الجزء المطلوبة مباشرة داخل متصفح الأجزاء
        mw = _resolve_part_actions_main_window(self.parent())
        btn_recompare = QPushButton("🔍 إعادة المقارنة")
        btn_recompare.setFixedWidth(112)
        btn_recompare.setToolTip(f"إعادة مقارنة الجزء {idx} مع ملفه الأصلي")
        if hasattr(mw, "_recompare_single_part"):
            btn_recompare.clicked.connect(
                lambda checked=False, part_idx=idx: self._trigger_part_action("recompare", part_idx))
        else:
            btn_recompare.setEnabled(False)
        row.addWidget(btn_recompare)

        btn_reextract = QPushButton("♻️ إعادة الاستخراج")
        btn_reextract.setFixedWidth(118)
        btn_reextract.setToolTip(
            f"إعادة استخراج الجزء {idx} ثم إعادة تجميع الكتاب كاملاً تلقائياً")
        if hasattr(mw, "_reextract_single_part"):
            btn_reextract.clicked.connect(
                lambda checked=False, part_idx=idx: self._trigger_part_action("reextract", part_idx))
        else:
            btn_reextract.setEnabled(False)
        row.addWidget(btn_reextract)

        # تقرير المقارنة
        lbl_compare = QLabel("⏳")
        lbl_compare.setMinimumWidth(200)
        lbl_compare.setStyleSheet("font-size: 11px; padding: 2px 6px;")
        row.addWidget(lbl_compare, 1)

        insert_pos = self.vbox.count() - 1
        row_widget = QWidget()
        row_widget.setLayout(row)
        self.vbox.insertWidget(insert_pos, row_widget)
        self._parts[idx] = (row_widget, lbl_compare)

    def _trigger_part_action(self, action: str, idx: int):
        """تنفيذ إجراء جزء من خلال MainWindow بعد إغلاق الحوار الحالي."""
        mw = _resolve_part_actions_main_window(self.parent())
        method_name = {
            "recompare": "_recompare_single_part",
            "reextract": "_reextract_single_part",
        }.get(action)
        method = getattr(mw, method_name, None) if method_name else None
        if not callable(method):
            QMessageBox.warning(self, "غير متاح", "إجراء الجزء غير متاح في النافذة الحالية.")
            return
        self._waiting_for_reextract = True
        try:
            mw._parts_viewer_dialog = self
        except Exception:
            pass
        # لا نغلق exec() حتى يمكن إعادة إظهار نفس الشاشة بعد انتهاء الجزء؛
        # الإخفاء المؤقت يمنع نافذة الحوار من اعتراض نافذة التأكيد فقط.
        self.hide()
        QTimer.singleShot(0, lambda: method(idx))

    def _update_compare_label(self, idx: int):
        if idx not in self._parts:
            return
        _, lbl_compare = self._parts[idx]
        result = self.compare_results.get(idx)
        if result is None:
            lbl_compare.setText("⏳ لم تُقارن بعد")
            lbl_compare.setStyleSheet("font-size: 11px; color: #585b70; padding: 2px 6px;")
            return
        if result.error:
            lbl_compare.setText(f"❌ خطأ: {result.error[:40]}")
            lbl_compare.setStyleSheet("font-size: 11px; color: #f38ba8; padding: 2px 6px;")
            return
        color = self._grade_color(result.assessment, result.coverage_pct)
        gaps = len(result.missing_items) if result.missing_items else 0
        lbl_compare.setText(
            f"{'✅' if result.coverage_pct >= 95 else '⚠️'} "
            f"{result.coverage_pct}% — {result.assessment}"
            f"{f' — {gaps} فجوة' if gaps > 0 else ''}")
        lbl_compare.setStyleSheet(
            f"font-size: 11px; color: {color}; font-weight: bold; padding: 2px 6px;")
        # ✅ v25.3: إضافة نتيجة المقارنة الثانية إن وجدت
        r2 = self.secondary_results.get(idx)
        if r2 and r2.error is None:
            color2 = self._grade_color(r2.assessment, r2.coverage_pct)
            current = lbl_compare.text()
            lbl_compare.setText(f"{current}  |  ②{r2.coverage_pct}% {r2.assessment}")

    def _find_shard_pdf(self, idx: int) -> Optional[str]:
        """البحث عن ملف PDF الجزء في مجلد الأجزاء."""
        if self.shards_dir and self.shards_dir.exists():
            for f in self.shards_dir.glob(f"shard_{idx:04d}_*.pdf"):
                return str(f)
        return None

    def _open_file(self, path_str: str):
        try:
            p = Path(path_str)
            if not p.exists():
                QMessageBox.warning(self, "غير موجود", str(p))
                return
            if sys.platform == "win32":
                os.startfile(str(p))
            elif sys.platform == "darwin":
                subprocess.run(["open", str(p)])
            else:
                subprocess.run(["xdg-open", str(p)])
        except Exception as e:
            QMessageBox.warning(self, "خطأ", str(e))

    def closeEvent(self, event):
        try:
            if self._main_window is not None:
                self._main_window.settings.set("parts_viewer_size", {
                    "width": int(self.width()), "height": int(self.height())})
                self._main_window.settings.save()
                if getattr(self._main_window, "_parts_viewer_dialog", None) is self:
                    self._main_window._parts_viewer_dialog = None
        except Exception:
            pass
        self._waiting_for_reextract = False
        super().closeEvent(event)


class CompareResultsDiskDialog(QDialog):
    # ✅ v27.0: عرض partial.json/final.json من القرص في نافذة مستقلة
    def __init__(self, parent, book_stem: str,
                 partial_results: Dict[int, ShardComparisonResult],
                 final_summary: Optional[dict]):
        super().__init__(parent)
        self.setWindowTitle(f"📊 نتائج المقارنة — {book_stem}")
        self.resize(1000, 680)
        self.setLayoutDirection(Qt.LayoutDirection.RightToLeft)
        self.setStyleSheet(DARK_STYLE)
        self.partial_results = partial_results
        layout = QVBoxLayout(self)
        layout.setContentsMargins(12, 12, 12, 12)
        layout.setSpacing(10)
        title = QLabel(f"📊 <b>{book_stem}</b>")
        title.setObjectName("headerLabel")
        layout.addWidget(title)
        self.table = QTableWidget()
        self.table.setColumnCount(5)
        self.table.setHorizontalHeaderLabels(["جزء", "صفحات", "تقييم", "تغطية%", "فجوات"])
        self.table.setSelectionBehavior(QAbstractItemView.SelectionBehavior.SelectRows)
        self.table.setSelectionMode(QAbstractItemView.SelectionMode.SingleSelection)
        self.table.horizontalHeader().setSectionResizeMode(1, QHeaderView.ResizeMode.Stretch)
        for i in (0, 2, 3, 4):
            self.table.horizontalHeader().setSectionResizeMode(i, QHeaderView.ResizeMode.ResizeToContents)
        self.table.itemSelectionChanged.connect(self._on_selection_changed)
        _install_part_context_menu(self.table, self, idx_col=0)
        layout.addWidget(self.table, 1)
        self.detail = QTextEdit()
        self.detail.setReadOnly(True)
        self.detail.setLineWrapMode(QTextEdit.LineWrapMode.WidgetWidth)
        self.detail.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.detail.setMaximumHeight(180)
        layout.addWidget(self.detail)
        self.summary = QLabel('—')
        self.summary.setWordWrap(True)
        self.summary.setTextFormat(Qt.TextFormat.RichText)
        self.summary.setStyleSheet("QLabel { background-color: #181825; border: 1px solid #45475a; border-radius: 6px; padding: 12px; }")
        layout.addWidget(self.summary)
        buttons = QDialogButtonBox(QDialogButtonBox.StandardButton.Close)
        buttons.rejected.connect(self.reject)
        buttons.accepted.connect(self.accept)
        layout.addWidget(buttons)
        self._populate()
        self._render_summary(final_summary)

    def _populate(self):
        results = sorted(self.partial_results.values(), key=lambda r: r.shard_idx)
        self.table.setUpdatesEnabled(False)
        self.table.setRowCount(len(results))
        self.table.verticalHeader().setDefaultSectionSize(40)
        for row, r in enumerate(results):
            if row % 20 == 0:
                QApplication.processEvents()
            self.table.setItem(row, 0, QTableWidgetItem(str(r.shard_idx)))
            self.table.setItem(row, 1, QTableWidgetItem(f"{r.page_start}-{r.page_end}"))
            assess = QTableWidgetItem(r.assessment if r.error is None else '❌ خطأ')
            if r.error is not None:
                assess.setForeground(QColor('#f38ba8'))
            elif r.coverage_pct >= 95:
                assess.setForeground(QColor('#a6e3a1'))
            elif r.coverage_pct >= 80:
                assess.setForeground(QColor('#f9e2af'))
            elif r.coverage_pct >= 60:
                assess.setForeground(QColor('#fab387'))
            else:
                assess.setForeground(QColor('#f38ba8'))
            self.table.setItem(row, 2, assess)
            cov = QTableWidgetItem(f"{r.coverage_pct}%")
            if r.coverage_pct >= 95:
                cov.setForeground(QColor('#a6e3a1'))
            elif r.coverage_pct >= 80:
                cov.setForeground(QColor('#f9e2af'))
            elif r.coverage_pct >= 60:
                cov.setForeground(QColor('#fab387'))
            else:
                cov.setForeground(QColor('#f38ba8'))
            self.table.setItem(row, 3, cov)
            self.table.setItem(row, 4, QTableWidgetItem(str(len(r.missing_items))))
        self.table.setUpdatesEnabled(True)
        if results:
            self.table.selectRow(0)

    def _show_part_actions(self, idx: int):
        try:
            if hasattr(self.parent(), "_show_part_actions_menu"):
                self.parent()._show_part_actions_menu(int(idx))
            elif hasattr(self.parent(), "main_window"):
                self.parent().main_window._show_part_actions_menu(int(idx))
        except Exception as e:
            QMessageBox.warning(self, "خطأ", str(e))

    def _render_summary(self, summary: Optional[dict]):
        if not summary:
            self.summary.setText('لا يوجد تقرير شامل محفوظ لهذا الكتاب.')
            return
        verdict = summary.get('overall_assessment', '—')
        coverage = summary.get('coverage_estimate_pct', 0)
        worst = summary.get('worst_shards', [])
        verdict_color = {'ممتاز': '#a6e3a1', 'جيد': '#94e2d5', 'متوسط': '#f9e2af', 'ضعيف': '#f38ba8'}.get(verdict, '#cdd6f4')
        self.summary.setText(
            f"<b>التقييم:</b> <span style='color:{verdict_color}'>{verdict}</span><br>"
            f"<b>متوسط التغطية:</b> {coverage}%<br>"
            f"<b>الفجوات:</b> {summary.get('total_missing_items', 0)}<br>"
            f"<b>أسوأ الأجزاء:</b> {', '.join(map(str, worst)) if worst else '—'}<br><br>"
            f"<b>الملخص:</b><br>{summary.get('summary', '')}<br><br>"
            f"<b>التوصيات:</b><br>{summary.get('recommendations', '')}")

    def _on_selection_changed(self):
        row = self.table.currentRow()
        results = sorted(self.partial_results.values(), key=lambda r: r.shard_idx)
        if row < 0 or row >= len(results):
            return
        r = results[row]
        chunks = [
            f"<b>جزء {r.shard_idx}</b> — صفحات {r.page_start}-{r.page_end}<br>",
            f"<b>التقييم:</b> {r.assessment}<br>",
            f"<b>التغطية:</b> {r.coverage_pct}%<br>",
            f"<b>الملاحظات:</b> {r.error or r.notes or '—'}<br>",
        ]
        if r.missing_items:
            chunks.append('<br><b>الفجوات:</b><br>')
            for idx, item in enumerate(r.missing_items, 1):
                chunks.append(f"{idx}. {item.get('severity', '—')} — {item.get('location_hint', '')}<br>{item.get('snippet', '')}<br><br>")
        self.detail.setHtml(''.join(chunks))


