class TashkeelEvalWorker(QObject):
    """✅ v10.11: عامل تقييم التشكيل.

    تقسيم بالنص على **دفعات كلمات** (افتراضي 3000 كلمة/دفعة) مع
    **تداخل** (افتراضي 50 كلمة) من نهاية الدفعة السابقة في بداية
    التالية — حتى لا يفقد النموذج سياق المفارق. نتيجة كل دفعة تُبث
    فور اكتمالها (chunk_done) دون انتظار بقية الدفعات.
    """
    status = pyqtSignal(str)
    log = pyqtSignal(str)
    progress = pyqtSignal(int)
    chunk_done = pyqtSignal(object)   # (قائمة مواضع الدفعة، رقمها، إجمالي الدفعات)
    finished = pyqtSignal(object)     # (إجمالي المواقض، إجمالي غير المقروء)
    # ✅ v10.14: دفعة فاشلة سُجّلت كفجوة (رقمها، إجماليها، أول سطر، آخر سطر، السبب)
    batch_skipped = pyqtSignal(object)
    failed = pyqtSignal(str)

    def __init__(self, scope_lines: List[Tuple[int, str]], model: dict,
                 tokens_path: Path, app_dir: Path, settings: dict,
                 stop_event: threading.Event,
                 words_per_chunk: int = 3000, overlap_words: int = 50,
                 thinking_level: str = "low",
                 continue_on_error: bool = True):
        super().__init__()
        self.scope_lines = list(scope_lines)          # (رقم سطر في الملف، نص السطر)
        self.model = dict(model or {})
        self.tokens_path = Path(tokens_path)
        self.app_dir = Path(app_dir)
        self.cfg = dict(settings or {})
        self.cfg.setdefault("temperature", 0.0)
        self.stop_event = stop_event
        self.words_per_chunk = max(50, int(words_per_chunk or 3000))
        self.overlap_words = max(0, int(overlap_words or 0))
        self.overlap_words = min(self.overlap_words,
                                 max(0, self.words_per_chunk // 2))
        # ✅ v10.13: مستوى التفكير قابل للاختيار (الافتراضي منخفض) —
        # العالي/المتوسط يتجاوزان مهلة الخادم (504) على نماذج 3.x
        self.thinking_level = str(thinking_level or "low")
        # ✅ v10.14 (T1): فشل الدفعة يسجَّل فجوة وتُستأنف البقية
        self.continue_on_error = bool(continue_on_error)
        self._pool: Optional[KeyPool] = None
        self._client_lock = threading.RLock()
        self._clients = {}

    def stop(self):
        self.stop_event.set()
        with self._client_lock:
            clients = list(self._clients)
        for client in clients:
            try:
                if hasattr(client, "close"):
                    client.close()
                elif getattr(client, "_transport", None) is not None:
                    client._transport.close()
            except Exception:
                pass

    def _emit(self, message: str):
        try:
            self.status.emit(message)
        except Exception:
            pass

    def _log(self, message: str):
        try:
            self.log.emit(message)
        except Exception:
            pass

    def _make_chunks(self) -> List[List[Tuple[int, str]]]:
        """✅ v10.11: دفعات على مستوى الكلمة:
        الدفعة 1 = الكلمات 1–3000، الثانية تبدأ من 2950 (تداخل 50)،
        ثم 5950... — وتُوسَّع كل دفعة للأسطر الكاملة حتى لا يُقطع سياق."""
        flat: List[Tuple[int, str]] = []
        for n, t in self.scope_lines:
            for w in t.split():
                flat.append((n, w))
        if not flat:
            return []
        text_by_line = {n: t for n, t in self.scope_lines}
        N = self.words_per_chunk
        O = self.overlap_words
        windows: List[Tuple[int, int]] = []   # (بداية كلمة، نهاية كلمة حصرية)
        start = 0
        while start < len(flat):
            end = min(start + N, len(flat))
            windows.append((start, end))
            if end >= len(flat):
                break
            start = max(start + 1, end - O)
        chunks: List[List[Tuple[int, str]]] = []
        for ws, we in windows:
            first_line = flat[ws][0]
            last_line = flat[we - 1][0]
            chunks.append([(n, text_by_line[n])
                           for n in range(first_line, last_line + 1)
                           if n in text_by_line])
        return chunks or [self.scope_lines]

    def _call_model(self, prompt: str, model_id: str, model_family: str) -> str:
        """نداء تقييم نصي مع إيقاع لكل مفتاح، وإعادة شبكية محدودة دون إعادة إرسال ملف."""
        states = self._pool.get_all_available_for_model(model_id)
        if not states:
            raise RuntimeError(f"لا مفتاح متاح حاليًا للنموذج {model_id}.")
        errors: List[str] = []
        seen_504 = 0  # ✅ v10.20: استعادة سقف 504 (ضاع في 10.16/10.17)
        for state in states:
            if self.stop_event.is_set():
                raise InterruptedError("توقف")
            client = None
            try:
                self._log(f"⏳ جاري إرسال طلب تقييم التشكيل بالمفتاح {state.masked}...")
                client = genai.Client(
                    api_key=state.key,
                    http_options=types.HttpOptions(timeout=GENAI_HTTP_TIMEOUT_MS))
                try:
                    register_stop_component("clients", client)
                except Exception:
                    pass
                with self._client_lock:
                    self._clients[id(client)] = client
                try:
                    max_tokens = max(2048, min(65536, int(
                        self.cfg.get("tashkeel_max_output_tokens", 16384) or 16384)))
                except Exception:
                    max_tokens = 16384
                cfg_kwargs = dict(temperature=0.0, max_output_tokens=max_tokens)
                thinking = build_thinking_config(
                    model_family,
                    {**self.cfg, "thinking_level": self.thinking_level})
                if thinking is not None:
                    cfg_kwargs["thinking_config"] = thinking
                gen_cfg = types.GenerateContentConfig(**cfg_kwargs)
                for attempt in range(3):
                    if self.stop_event.is_set():
                        raise InterruptedError("توقف")
                    if not wait_for_network_if_needed(self.cfg, self.stop_event,
                                                      self._emit):
                        raise InterruptedError("توقف")
                    throttle_key_send(state.key, self.stop_event, self._emit)
                    self._log(
                        f"⏳ النموذج {model_id} يعالج الدفعة "
                        f"(محاولة شبكة {attempt + 1}/3)...")
                    try:
                        resp = client.models.generate_content(
                            model=model_id,
                            contents=[types.Content(role="user", parts=[
                                types.Part.from_text(text=prompt)])],
                            config=gen_cfg)
                    except InterruptedError:
                        raise
                    except Exception as exc:
                        if is_quota_error(exc):
                            self._pool.learn_from_429(state, model_id, exc)
                            self._pool.maybe_save()
                            errors.append(f"{state.masked}: كوتة {str(exc)[:100]}")
                            self._log(f"📛 نفدت حصة المفتاح {state.masked}; تجربة مفتاح آخر دون إعادة الملف.")
                            break
                        if is_key_auth_error(exc):
                            state.fail_count += 1
                            self._pool._dirty = True
                            self._pool.maybe_save()
                            errors.append(f"{state.masked}: مفتاح غير معتمد")
                            self._log(f"📛 المفتاح {state.masked} غير معتمد؛ الانتقال إلى مفتاح آخر.")
                            break
                        message = str(exc)
                        if "not_found" in message.lower() or "404" in message:
                            raise RuntimeError(
                                f"النموذج المختار غير متاح ({model_id}) — "
                                "اختر نموذجاً آخر من القائمة.") from exc
                        if is_permission_denied_error(exc):
                            raise RuntimeError(
                                f"لا يملك المفتاح صلاحية استخدام النموذج {model_id}: "
                                f"{message[:160]}") from exc
                        if "DEADLINE_EXCEEDED" in message or "504" in message:
                            # مهلة الخادم سببها غالباً مستوى التفكير/حجم الدفعة لا
                            # المفتاح: جرّب حتى 3 مفاتيح ثم أجهض برسالة واضحة بدل
                            # تدوير كل المفاتيح (كان يضيع دقائق بلا فائدة).
                            seen_504 += 1
                            state.fail_count += 1
                            self._pool._dirty = True
                            self._pool.maybe_save()
                            self._log(f"❌ تجاوز الطلب مهلة الخادم (504) — محاولة {seen_504}/3 بالمفتاح التالي...")
                            if seen_504 >= 3:
                                raise RuntimeError(
                                    "تجاوز الطلب مهلة الخادم (504) 3 مرات متتالية — خفّض "
                                    "«مستوى التفكير» إلى «منخفض» أو صغّر حجم الدفعة.") from exc
                            errors.append(f"504(timeout #{seen_504})")
                            break
                        if is_retryable_network_error(exc):
                            if attempt < 2:
                                delay = min(8.0, 1.5 * (2 ** attempt))
                                self._log(
                                    f"⚠️ انقطاع شبكي مؤقت ({type(exc).__name__})؛ "
                                    f"إعادة نفس الطلب بعد {delay:.0f}s، بلا إعادة تحميل النص.")
                                interruptible_sleep(delay, self.stop_event)
                                continue
                            errors.append(f"{state.masked}: شبكة {message[:110]}")
                            self._log(f"❌ فشل الشبكة بعد 3 محاولات للمفتاح {state.masked}.")
                            break
                        raise RuntimeError(
                            f"رفض/خطأ طلب التقييم ({type(exc).__name__}): {message[:180]}") from exc

                    raw = (getattr(resp, "text", "") or "").strip()
                    if not raw:
                        errors.append(f"{state.masked}: استجابة فارغة")
                        self._log(
                            f"⚠️ وصل رد فارغ من النموذج بالمفتاح {state.masked}; "
                            "سيُعرض سبب عدم وجود نتائج إن استمر.")
                        break
                    self._pool.mark_success(state, model_id, len(prompt) // 4)
                    self._pool._save()
                    self._log(f"✅ وصلت استجابة ({len(raw)} حرف) — جارٍ تحليل مواضع التشكيل...")
                    return raw
            except InterruptedError:
                raise
            except Exception as exc:
                errors.append(f"{state.masked}: {type(exc).__name__}: {str(exc)[:140]}")
                self._log(f"❌ تعذر تقييم الطلب بالمفتاح {state.masked}: {str(exc)[:140]}")
                # أخطاء النموذج/البرومبت لا تتحسن بتكرار الطلب على مفاتيح أخرى.
                if not is_key_auth_error(exc) and not is_quota_error(exc):
                    raise
            finally:
                if client is not None:
                    with self._client_lock:
                        self._clients.pop(id(client), None)
                    try:
                        unregister_stop_component("clients", client)
                    except Exception:
                        pass
                    try:
                        if hasattr(client, "close"):
                            client.close()
                        elif getattr(client, "_transport", None) is not None:
                            client._transport.close()
                    except Exception:
                        pass
        raise RuntimeError(
            "تعذر إكمال تقييم هذه الدفعة بعد تجربة المفاتيح المتاحة: "
            + "; ".join(errors[:3]))

    @staticmethod
    def _parse_response(raw: str, total_lines: int,
                        allowed_lines: Optional[Set[int]] = None) -> Tuple[List[dict], int]:
        """يفك تنسيقات الرد الشائعة ثم يتحقق من كل تصحيح قبل إظهاره."""
        issues: List[dict] = []
        skipped = 0
        text = (raw or "").strip()
        text = re.sub(r"^```(?:json|text|plaintext)?\s*|\s*```$", "", text,
                      flags=re.I | re.S).strip()
        # بعض النماذج تتبع التعليمات لكن تغلف القائمة في JSON؛ حوّلها إلى
        # الصيغة الداخلية نفسها حتى لا تختفي النتائج بسبب اختلاف التغليف.
        try:
            data = json.loads(text)
        except Exception:
            data = None
        if isinstance(data, dict):
            data = data.get("issues", data.get("corrections", data.get("results", [])))
        if isinstance(data, list):
            rows = []
            for item in data:
                if isinstance(item, dict):
                    line = item.get("line", item.get("line_number", item.get("السطر")))
                    wrong = item.get("wrong", item.get("original", item.get("الخطأ", "")))
                    right = item.get("right", item.get("correction", item.get("التصحيح", "")))
                    rows.append(f"{line} | {wrong} | {right}")
                elif isinstance(item, (list, tuple)) and len(item) >= 3:
                    rows.append(" | ".join(str(x) for x in item[:3]))
            text = "\n".join(rows)

        seen = set()
        for line_text in text.splitlines():
            line = line_text.strip().strip("|").strip()
            line = line.lstrip("-*•▪\u200f\u200e ").strip()
            mnum = re.match(r"^(?:سطر\s*)?(\d+)\s*[.)\-:]?\s+", line, flags=re.I)
            if mnum:
                rest = line[mnum.end():].strip()
                line = (mnum.group(1) + " " + rest) if rest.startswith("|") else (mnum.group(1) + " | " + rest)
            if not line or "NO_ISSUES" in line.upper() or "لا توجد أخطاء" in line:
                continue
            parts = [part.strip() for part in line.split("|")]
            if len(parts) < 3:
                skipped += 1
                continue
            head, wrong = parts[0], parts[1]
            right = "|".join(parts[2:]).strip().strip("`*_ ")
            head = re.sub(r"[^\d٠-٩۰-۹]", "", head)
            try:
                ln_no = int(head)
            except Exception:
                skipped += 1
                continue
            if (not (1 <= ln_no <= total_lines)
                    or (allowed_lines is not None and ln_no not in allowed_lines)):
                skipped += 1
                continue
            wrong = wrong.strip().strip("`*_ ")
            if not wrong or not right or wrong == right:
                skipped += 1
                continue
            if not re.search(r"[\u0600-\u06FF]", wrong):
                skipped += 1
                continue
            key = (ln_no, wrong, right)
            if key in seen:
                continue
            seen.add(key)
            issues.append({"line": ln_no, "wrong": wrong, "right": right})
        issues.sort(key=lambda item: item["line"])
        return issues, skipped

    @pyqtSlot()
    def run(self):
        try:
            self._pool = KeyPool(
                self.tokens_path,
                self.app_dir / "tashkeel_keys_state.json",
                self.cfg,
                global_state_path=self.app_dir / KeyPool.GLOBAL_STATE_FILENAME)
            model_id = str(self.model.get("id") or "")
            if not model_id:
                raise RuntimeError("لم يتم اختيار نموذج للتقييم.")
            if self._pool.count_available_for_model(model_id) <= 0:
                wait = self._pool.secs_until_any_available_for_model(model_id)
                hint = f" (متاح بعد {fmt_duration(wait)})" if wait else ""
                raise RuntimeError(f"لا مفتاح متاح حاليًا للنموذج {model_id}{hint}.")
            # ✅ v10.14 (T4): فحص مسبق استشاري — الدفعات المطلوبة مقابل الرصيد
            try:
                _need = max(1, len(self._make_chunks()))
                _pre = self._pool.estimate_call(model_id)
                _have = sum(int(r.get("rpd_left", 0) or 0)
                            for r in _pre.get("rows", []))
                if _have < _need:
                    self._emit(f"⚠️ تنبيه حصة: الدفعات المطلوبة {_need} والرصيد "
                               f"اليومي المتبقي {_have} طلبًا — قد يتوقف التقييم قبل النهاية.")
            except Exception:
                pass
            family = str(self.model.get("family") or detect_model_family(model_id))
            chunks = self._make_chunks()
            total_lines = self.scope_lines[-1][0] if self.scope_lines else 0
            total_found = 0
            total_skipped = 0
            for ci, chunk in enumerate(chunks, 1):
                if self.stop_event.is_set():
                    raise InterruptedError("توقف")
                span = f"الأسطر {chunk[0][0]}–{chunk[-1][0]}"
                self._emit(f"جارٍ تقييم التشكيل: {span} (الدفعة {ci} من {len(chunks)})...")
                self._log(f"📦 الدفعة {ci}/{len(chunks)} — {span}")
                numbered = "\n".join(f"{n:05d} | {t}" for n, t in chunk)
                prompt = (
                    TASHKEEL_PROMPT
                    + f"\n\nهذه دفعة من النطاق المحدد، أسطر الكتاب {chunk[0][0]}–{chunk[-1][0]}. "
                      "لا تُخرج إلا الأسطر الظاهرة أدناه، وانقل رقم كل سطر كما هو.\n"
                    + "\n=== النص ===\n" + numbered)
                # ✅ v10.14 (T1): فشل الدفعة لا يُجهض النطاق — تُسجَّل فجوة
                # وتُستأنف البقية، مع زر «إعادة الفوائت» بعد الاكتمال
                try:
                    raw = self._call_model(prompt, model_id, family)
                except InterruptedError:
                    raise
                except Exception as exc:
                    if not self.continue_on_error:
                        raise
                    self._log(f"⏭️ تخطي الدفعة {ci}/{len(chunks)} (فجوة): {exc}")
                    self.batch_skipped.emit(
                        (ci, len(chunks), chunk[0][0], chunk[-1][0], str(exc)[:150]))
                    self.progress.emit(int(ci * 100 / len(chunks)))
                    continue
                issues, skipped = self._parse_response(
                    raw, total_lines, allowed_lines={n for n, _text in self.scope_lines})
                total_skipped += skipped
                total_found += len(issues)
                if not issues:
                    if skipped:
                        self._log(
                            f"⚠️ لم تظهر مواضع قابلة للعرض: تعذر تحليل {skipped} "
                            "سطر/صيغة من رد النموذج؛ راجع لوج النموذج أدناه.")
                    elif "NO_ISSUES" in raw.upper():
                        self._log("✅ لم يُعثر على أخطاء تشكيل ثابتة في هذه الدفعة.")
                    else:
                        self._log(
                            "ℹ️ لم يرجع النموذج موضعاً قابلاً للتصحيح لهذه الدفعة؛ "
                            "قد تكون خالية من أخطاء ثابتة.")
                # نتيجة الدفعة تُعرض فوراً دون انتظار الباقي.
                self.chunk_done.emit((issues, ci, len(chunks)))
                self.progress.emit(int(ci * 100 / len(chunks)))
            self.finished.emit((total_found, total_skipped))
        except InterruptedError:
            self.failed.emit("أُلغي تقييم التشكيل.")
        except Exception as exc:
            self.failed.emit(f"حدث خطأ أثناء تقييم التشكيل: {exc}")


class QuotaViewerDialog(QDialog):
    """✅ v10.14: عارض حصص المفاتيح — الرصيد اليومي لكل (مفتاح × نموذج)."""
    def __init__(self, main_window, parent=None):
        super().__init__(parent)
        self.mw = main_window
        self.setWindowTitle("📊 حصص المفاتيح — PDF Master Pro")
        self.setModal(False)
        self.resize(780, 480)
        v = QVBoxLayout(self)
        try:
            tz = pacific_now().strftime("%Y-%m-%d %H:%M")
            v.addWidget(QLabel(
                f"اليوم الحالي بتوقيت المحيط الهادئ (مرجع Google): {tz} — "
                f"يُصفَّر الرصيد اليومي بعد {fmt_duration(seconds_until_pacific_midnight())}"))
        except Exception:
            pass
        self.table = QTableWidget(0, 5)
        self.table.setHorizontalHeaderLabels(
            ["المفتاح", "النموذج", "المستخدم/الحد (RPD)", "المتبقي", "الحالة"])
        try:
            self.table.horizontalHeader().setSectionResizeMode(QHeaderView.Stretch)
        except Exception:
            pass
        v.addWidget(self.table, 1)
        row = QHBoxLayout()
        self.refresh_btn = QPushButton("🔄 تحديث")
        self.refresh_btn.clicked.connect(self.refresh)
        row.addWidget(self.refresh_btn)
        row.addStretch(1)
        v.addLayout(row)
        self.refresh()

    @staticmethod
    def _mask(k: str) -> str:
        try:
            return k[:6] + "..." + k[-4:] if len(k) > 10 else "****"
        except Exception:
            return "****"

    def refresh(self):
        rows: List[Dict[str, Any]] = []
        try:
            path = self.mw.app_dir / KeyPool.GLOBAL_STATE_FILENAME
            data = json.loads(path.read_text(encoding="utf-8", errors="replace"))
            cooldowns = data.get("cooldowns") or {}
            usage = data.get("usage") or {}
            try:
                models = [m["id"] for m in (self.mw._get_active_models_list() or [])]
            except Exception:
                models = []
            models += [m["id"] for m in DEFAULT_MODELS if m["id"] not in models]
            for mc in list(cooldowns.values()) + list(usage.values()):
                for mid in (mc or {}).keys():
                    if mid not in models:
                        models.append(mid)
            keys = list(dict.fromkeys(list(cooldowns.keys()) + list(usage.keys())))
            try:
                day = pacific_today_key()
            except Exception:
                day = ""
            now = time.time()
            for mid in models:
                lim = quota_for_model(mid).get("rpd", 0)
                for k in keys:
                    u = (usage.get(k) or {}).get(mid) or {}
                    used = int(u.get("rpd_used", 0) or 0) if str(u.get("day", "")) == day else 0
                    info = (cooldowns.get(k) or {}).get(mid) or {}
                    kind = str(info.get("kind", "") or "")
                    blocked, why = False, ""
                    if kind == "rpd" and str(info.get("day", "")) == day:
                        blocked, why = True, "rpd"
                    elif kind in ("rpm", "tpm", "shed", "unknown") and float(
                            info.get("until", 0) or 0) > now:
                        blocked, why = True, kind
                    elif lim and used >= lim:
                        blocked, why = True, "ledger"
                    rows.append({"key": self._mask(k), "model": mid,
                                 "used": used, "lim": lim, "left": max(0, lim - used),
                                 "blocked": blocked, "why": why,
                                 "until": float(info.get("until", 0) or 0)})
        except Exception as exc:
            rows = []
            try:
                self.setWindowTitle(f"📊 حصص المفاتيح — لا بيانات بعد ({exc})")
            except Exception:
                pass
        self.table.setRowCount(len(rows))
        now = time.time()
        for i, r in enumerate(rows):
            self.table.setItem(i, 0, QTableWidgetItem(str(r["key"])))
            self.table.setItem(i, 1, QTableWidgetItem(str(r["model"])))
            self.table.setItem(i, 2, QTableWidgetItem(f"{r['used']}/{r['lim']}"))
            self.table.setItem(i, 3, QTableWidgetItem(str(r["left"])))
            if not r["blocked"]:
                st = "✅ متاح"
            elif r["why"] == "rpd" or r["why"] == "ledger":
                st = f"🌙 يومي — يُصفَّر بعد {fmt_duration(seconds_until_pacific_midnight())}"
            elif r["why"] in ("rpm", "tpm"):
                st = f"⏱️ معدل — يُفك بعد {fmt_duration(max(0.0, r['until'] - now))}"
            elif r["why"] == "shed":
                st = "⏱️ تخفيف حمل مؤقت"
            else:
                st = f"⏱️ محظور — يُفك بعد {fmt_duration(max(0.0, r['until'] - now))}"
            self.table.setItem(i, 4, QTableWidgetItem(st))


class TashkeelLoadWorker(QObject):
    """تحميل/تجهيز النص والنطاق في خيط خلفي كي لا تتجمد الواجهة مع الكتب الكبيرة."""
    loaded = pyqtSignal(object)
    failed = pyqtSignal(str)

    def __init__(self, source_paths: List[Path], source_file: Optional[Path],
                 copy_path: Optional[Path], display_name: str,
                 use_parts: bool, parts_text: str,
                 words_per_chunk: int, overlap_words: int,
                 stop_event: threading.Event):
        super().__init__()
        self.source_paths = [Path(x) for x in (source_paths or [])]
        self.source_file = Path(source_file) if source_file else None
        self.copy_path = Path(copy_path) if copy_path else None
        self.display_name = str(display_name or "النص")
        self.use_parts = bool(use_parts)
        self.parts_text = str(parts_text or "")
        self.words_per_chunk = max(50, int(words_per_chunk or 3000))
        self.overlap_words = max(0, min(int(overlap_words or 0), self.words_per_chunk // 2))
        self.stop_event = stop_event

    def _read_path(self, path: Path) -> str:
        pieces = []
        with path.open("r", encoding="utf-8", errors="replace", newline="") as fh:
            while True:
                if self.stop_event.is_set():
                    raise InterruptedError("أُلغي تحميل النص")
                block = fh.read(1024 * 1024)
                if not block:
                    break
                pieces.append(block)
        return "".join(pieces)

    @pyqtSlot()
    def run(self):
        try:
            if not self.source_paths:
                raise FileNotFoundError("لم يُحدَّد ملف نصي للتحميل.")
            text_parts = []
            for idx, path in enumerate(self.source_paths):
                if self.stop_event.is_set():
                    raise InterruptedError("أُلغي تحميل النص")
                if not path.is_file():
                    raise FileNotFoundError(f"تعذر العثور على النص: {path}")
                part = self._read_path(path)
                # عند دمج أجزاء الكتاب، ازل فواصل النهاية الداخلية كما كان السلوك.
                if len(self.source_paths) > 1:
                    part = part.rstrip("\r\n")
                text_parts.append(part)
            content = ("\n" if len(self.source_paths) > 1 else "").join(text_parts)
            if not content.strip():
                raise ValueError("الملف لا يحتوي نصاً.")
            line_ending = "\r\n" if "\r\n" in content else "\n"
            had_trailing_nl = content.endswith(("\n", "\r"))
            lines = content.splitlines()
            total = len(lines)
            if not total:
                raise ValueError("لم تُقرأ أي أسطر من النص.")

            if self.use_parts:
                points = sorted({n for n in (int(x) for x in re.findall(r"\d+", self.parts_text))
                                 if 1 <= n <= total})
                if not points:
                    raise ValueError(
                        "أدخل نقاط بداية صحيحة ضمن عدد الأسطر (مثال: 1-250-600=).")
                ranges = []
                for i, start in enumerate(points):
                    end = points[i + 1] - 1 if i + 1 < len(points) else total
                    ranges.append((start, end))
                scope_desc = (f"{len(ranges)} جزء — أسطر "
                              + " ،".join(f"{a}–{b}" for a, b in ranges))
            else:
                ranges = [(1, total)]
                scope_desc = f"الكتاب كاملًا ({total} سطر)"

            scope_word_count = 0
            for start, end in ranges:
                for i in range(start, min(end, total) + 1):
                    scope_word_count += len(lines[i - 1].split())
            n = self.words_per_chunk
            overlap = min(self.overlap_words, n // 2)
            if scope_word_count <= n:
                batches_note = "دفعة واحدة (النص كاملًا)"
            else:
                step = max(1, n - overlap)
                batches_note = f"≈ {int(math.ceil((scope_word_count - overlap) / step))} دفعات × {n} كلمة (تداخل {overlap})"
            self.loaded.emit({
                "lines": lines,
                "line_ending": line_ending,
                "had_trailing_nl": had_trailing_nl,
                "source_file": str(self.source_file) if self.source_file else "",
                "copy_path": str(self.copy_path) if self.copy_path else "",
                "scope_ranges": ranges,
                "scope_desc": scope_desc,
                "scope_word_count": scope_word_count,
                "total_lines": total,
                "batches_note": batches_note,
                "display_name": self.display_name,
            })
        except InterruptedError:
            self.failed.emit("أُلغي تحميل النص.")
        except Exception as exc:
            self.failed.emit(f"تعذر تحميل/تحضير النص: {exc}")


