    def _check_keys_on_startup(self):
        if self._has_keys():
            return
        if not self.settings.get("show_no_keys_dialog", True):
            return
        dlg = NoKeysWelcomeDialog(self)
        dlg.exec()
        if dlg.dont_show_again():
            self.settings.set("show_no_keys_dialog", False)
            self.settings.save()

    def _on_periodic_check(self):
        if self._closing:
            return
        try:
            cleaned = self.global_key_mgr.cleanup_and_save()
            if cleaned > 0:
                self.statusBar().showMessage(
                    f"🌙 فُك حظر {cleaned} (مفتاح+نموذج) تلقائياً", 5000)
                self._append_log(f"🌙 فُك حظر {cleaned} (مفتاح+نموذج) — يوم/دقيقة جديدة")
            # ✅ v26.0: تحديث فوري لجداول وعدّادات المفاتيح والـ UI عند فك الحظر
            self._update_keys_label()
        except Exception:
            pass

