    def _expand_tab_titles(self, tabs: QTabWidget):
        """اجعل عناوين التبويبات تملأ عرض شريط التبويب قدر الإمكان."""
        try:
            tabs.setUsesScrollButtons(False)
            tabs.setElideMode(Qt.TextElideMode.ElideNone)
            tabs.tabBar().setExpanding(True)
            tabs.tabBar().setDocumentMode(True)
            tabs.tabBar().setUsesScrollButtons(False)
            tabs.tabBar().setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)

            def _apply_equal_width(event=None):
                try:
                    count = tabs.count()
                    if count > 0:
                        w = max(40, tabs.width() // count)
                        tabs.tabBar().setStyleSheet(
                            "QTabBar::tab {"
                            f" min-width: {w}px; max-width: {w}px; padding: 9px 4px; margin-right: 2px;"
                            " background-color: #313244; color: #cdd6f4; font-weight: 700;"
                            " border: 1px solid #45475a; border-bottom: none;"
                            " border-top-left-radius: 6px; border-top-right-radius: 6px; }"
                            "QTabBar::tab:selected { background-color: #89b4fa; color: #1e1e2e; }"
                            "QTabBar::tab:hover:!selected { background-color: #45475a; }"
                        )
                except Exception:
                    pass

            if not hasattr(self, "_tab_resize_filters"):
                self._tab_resize_filters = []

            class _ResizeFilter(QObject):
                def eventFilter(self_filter, obj, event):
                    if event.type() == QEvent.Type.Resize:
                        _apply_equal_width()
                    return False

            _filter = _ResizeFilter(tabs)
            tabs.installEventFilter(_filter)
            self._tab_resize_filters.append(_filter)
            _apply_equal_width()
        except Exception:
            pass

    def _build_options_frame(self) -> QWidget:
        panel = QWidget(); panel.setMinimumWidth(120)
        panel.setMinimumHeight(60)
