        self.main_tabs = QTabWidget()
        self.main_tabs.setMinimumHeight(60)
        self.main_tabs.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        try:
            self.main_tabs.tabBar().setExpanding(True)
            self.main_tabs.tabBar().setUsesScrollButtons(False)
        except Exception:
            pass
        self.main_tabs.addTab(self._build_options_tab(), "📋 الخيارات")
        self.main_tabs.addTab(self._build_settings_tab(), "⚙️ الإعدادات والمفاتيح")
        self.main_tabs.addTab(self._build_compare_tab(), "🔍 المقارنة")
        self._expand_tab_titles(self.main_tabs)
        v.addWidget(self.main_tabs, 1)
        return panel

