    def _on_swap_translate_langs(self):
        src_idx = self.translate_src_combo.currentIndex()
        tgt_idx = self.translate_tgt_combo.currentIndex()
        self.translate_src_combo.setCurrentIndex(tgt_idx)
        self.translate_tgt_combo.setCurrentIndex(src_idx)

    def _on_prompt_kind_changed(self):
        kind = self.prompt_kind_combo.currentData()
        self.summary_pct_widget.setVisible(kind == "summarize")
        self.translate_lang_widget.setVisible(kind == "translate")
        try:
            self._update_session_info_labels()
        except Exception:
            pass

    def _build_settings_tab(self) -> QWidget:
        w = QWidget(); v = QVBoxLayout(w)
        v.setContentsMargins(4, 6, 4, 4); v.setSpacing(4)
        sub_tabs = QTabWidget()
        try:
            sub_tabs.tabBar().setExpanding(True)
            sub_tabs.tabBar().setUsesScrollButtons(False)
        except Exception:
            pass
        sub_tabs.addTab(self._build_model_pane(), "⚙️ النموذج")
        sub_tabs.addTab(self._build_keys_pane(), "🔑 المفاتيح")
        # ✅ نُقلت إعدادات المقارنة هنا من تبويب المقارنة.
        sub_tabs.addTab(self._build_compare_settings_pane(), "🔍 إعدادات المقارنة")
        self._expand_tab_titles(sub_tabs)
        v.addWidget(sub_tabs, 1)
        return w

