    def _on_manual_unblock_all(self):
        ans = QMessageBox.question(self, "تأكيد",
            "🧹 فك كل الحظر يدوياً؟<br><br>"
            "<b style='color:#f38ba8'>تحذير:</b> قد يؤدي لاستهلاك مفاتيح كوتتها فعلاً نفدت.",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No)
        if ans != QMessageBox.StandardButton.Yes:
            return
        try:
            # ✅ FIX: فك حظر شامل من كل المصادر
            self._append_log("🧹 [unblock] بدء فك الحظر اليدوي الشامل...")

            # 1) فك حظر الذاكرة (GlobalKeyManager)
            self.global_key_mgr._data = {}
            self.global_key_mgr.save()
            self._append_log("🧹 [unblock] فُك الحظر من GlobalKeyManager")

            # 2) فك حظر الملف العام (keys_global_state.json)
            gs_path = self.app_dir / KeyPool.GLOBAL_STATE_FILENAME
            if gs_path.exists():
                try:
                    gs_data = json.loads(gs_path.read_text(encoding="utf-8", errors="replace"))
                    gs_data["cooldowns"] = {}
                    gs_path.write_text(
                        json.dumps(gs_data, ensure_ascii=False, indent=2),
                        encoding="utf-8")
                    self._append_log("🧹 [unblock] فُك الحظر من الملف العام")
                except Exception as e:
                    self._append_log(f"⚠️  [unblock] فشل تنظيف الملف العام: {e}")

            # 3) فك حظر ملفات الكتب (keys_state.json لكل كتاب)
            out_dir_str = self.output_dir_edit.text().strip()
            if out_dir_str:
                out_dir = Path(out_dir_str)
                data_root = get_pdf_master_data_root(out_dir)
                if data_root.exists():
                    cleared_books = 0
                    for ks_file in data_root.rglob("keys_state.json"):
                        try:
                            ks_data = json.loads(ks_file.read_text(encoding="utf-8", errors="replace"))
                            changed = False
                            for key_state in ks_data.values():
                                if key_state.get("model_cooldowns"):
                                    key_state["model_cooldowns"] = {}
                                    changed = True
                            if changed:
                                ks_file.write_text(
                                    json.dumps(ks_data, ensure_ascii=False, indent=2),
                                    encoding="utf-8")
                                cleared_books += 1
                        except Exception:
                            pass
                    if cleared_books > 0:
                        self._append_log(f"🧹 [unblock] فُك الحظر من {cleared_books} كتاب")

            self._update_keys_label()
            self.statusBar().showMessage("🧹 تم فك كل الحظر يدوياً — كل المفاتيح متاحة الآن", 5000)
            self._append_log("🧹 [unblock] ✅ اكتمل فك الحظر الشامل")
        except Exception as e:
            self._append_log(f"💥 [unblock] خطأ: {e}")
            QMessageBox.critical(self, "خطأ", str(e))

