    def _schedule_persist_splitters(self):
        """حفظ مؤجّل خفيف بعد السحب (تلقائي)."""
        try:
            if getattr(self, "_closing", False):
                return
            t = getattr(self, "_splitter_save_timer", None)
            if t is None:
                self._persist_splitter_sizes()
                return
            t.stop()
            t.start(350)
        except Exception:
            try:
                self._persist_splitter_sizes()
            except Exception:
                pass

    def _persist_splitter_sizes(self):
        """✅ v28.4: حفظ مقاسات المقسّمات تلقائياً."""
        if getattr(self, "_closing", False):
            return
        try:
            # عند إخفاء الخيارات لا نحفظ [0, total] كعرض دائم
            if getattr(self, "_options_panel_visible", True) and hasattr(self, "top_hsplit"):
                sizes = list(self.top_hsplit.sizes())
                if len(sizes) == 2 and sizes[0] >= 40:
                    self.settings.set("splitter_main_sizes", sizes)
                    self.settings.set("splitter_bottom_sizes", sizes)  # نفس العرض دائماً
            elif getattr(self, "_saved_top_sizes", None):
                sizes = list(self._saved_top_sizes)
                if len(sizes) == 2 and sizes[0] >= 40:
                    self.settings.set("splitter_main_sizes", sizes)
                    self.settings.set("splitter_bottom_sizes", sizes)
            if hasattr(self, "outer_vsplit"):
                vs = list(self.outer_vsplit.sizes())
                if len(vs) == 2 and sum(vs) > 0:
                    self.settings.set("splitter_right_v_sizes", vs)
            self.settings.save()
        except Exception:
            pass

    def _apply_synced_column_sizes(self, sizes):
        """يفرض نفس عرض العمود الأيسر (خيارات=تحكم) والأيمن (عرض=سجل)."""
        if not sizes or len(sizes) != 2:
            return
        left, right = int(sizes[0]), int(sizes[1])
        # حماية حدود معقولة مع السماح بقرب المنتصف
        total = max(1, left + right)
        # لا تسمح بصفر كامل إلا في وضع إخفاء الخيارات
        if getattr(self, "_options_panel_visible", True):
            min_side = 60
            if left < min_side:
                left = min_side
                right = max(min_side, total - left)
            if right < min_side:
                right = min_side
                left = max(min_side, total - right)
        sizes = [left, right]
        self._syncing_splitters = True
        try:
            if hasattr(self, "top_hsplit") and self.top_hsplit is not None:
                if getattr(self, "_options_panel_visible", True) or sizes[0] > 0:
                    self.top_hsplit.setSizes(sizes)
            if hasattr(self, "bottom_hsplit") and self.bottom_hsplit is not None:
                self.bottom_hsplit.setSizes(sizes)
        finally:
            self._syncing_splitters = False

    def _on_top_hsplit_moved(self, pos=0, index=0):
        """سحب الحد الرأسي في الصف العلوي → يحرّك التحكم معه (نفس العرض)."""
        if getattr(self, "_closing", False) or getattr(self, "_syncing_splitters", False):
            return
        if not getattr(self, "_options_panel_visible", True):
            return
        try:
            sizes = list(self.top_hsplit.sizes())
            self._apply_synced_column_sizes(sizes)
            self._schedule_persist_splitters()
        except Exception as e:
            safe_print(f"top hsplit sync: {e}")

    def _on_bottom_hsplit_moved(self, pos=0, index=0):
        """سحب الحد الرأسي في الصف السفلي → يحرّك الخيارات معه (نفس العرض)."""
        if getattr(self, "_closing", False) or getattr(self, "_syncing_splitters", False):
            return
        try:
            sizes = list(self.bottom_hsplit.sizes())
            # إن كانت الخيارات مخفية: حدّث المحفوظ فقط ولا تُظهر العمود فجأة
            if not getattr(self, "_options_panel_visible", True):
                if sizes[0] >= 40:
                    self._saved_top_sizes = sizes
                self._syncing_splitters = True
                try:
                    # أبقِ الأعلى مخفياً [0, total] والأسفل كما سُحب
                    pass
                finally:
                    self._syncing_splitters = False
                self._schedule_persist_splitters()
                return
            self._apply_synced_column_sizes(sizes)
            self._schedule_persist_splitters()
        except Exception as e:
            safe_print(f"bottom hsplit sync: {e}")

    def _refresh_tab_bars_after_splitter(self):
        """✅ إصلاح: إجبار كل التبويبات (الخيارات/الإعدادات/المفاتيح...) على
        إعادة حساب وطلاء شريط تبويباتها. بدون هذا، كانت بعض التبويبات تختفي
        بصرياً بعد إخفاء/إظهار لوحة الخيارات أو التنقل المتكرر لشاشة المقارنة،
        ولا تعود للظهور إلا بعد تحريك المنزلق يدوياً (كان هذا الكود موجوداً
        سابقاً في نسخة مكرّرة من _on_splitter_moved تم تجاوزها بالكامل بتعريف
        لاحق بنفس الاسم فلم تُنفَّذ أبداً)."""
        for tab_widget in [getattr(self, "main_tabs", None)] + getattr(self, "_sub_tabs_list", []):
            try:
                if tab_widget and tab_widget.isVisible() and tab_widget.tabBar():
                    tab_widget.tabBar().updateGeometry()
                    tab_widget.tabBar().update()
                    tab_widget.updateGeometry()
                    tab_widget.update()
            except Exception:
                pass

    def _on_outer_vsplit_moved(self, pos=0, index=0):
        """
        ✅ الحد الفاصل الأفقي: يغيّر ارتفاع الصف العلوي (خيارات+عرض) معاً
        والصف السفلي (تحكم+سجل) معاً — نفس الارتفاع لكل زوج.
        مرن لأعلى/أسفل حتى أغلب الشاشة (لا سقف عند المنتصف).
        """
        if getattr(self, "_closing", False):
            return
        try:
            # لا نقيّد النسبة — فقط نضمن ألا يختفي الصف بالكامل إن أمكن
            sizes = list(self.outer_vsplit.sizes()) if hasattr(self, "outer_vsplit") else []
            if len(sizes) == 2:
                total = sizes[0] + sizes[1]
                # صف علوي يمكن تقليصه بقوة؛ السفلي (تحكم+سجل) لا يقل عن حد يحفظ ظهور التحكم
                floor_top = 24
                floor_bot = 140
                if total > floor_top + floor_bot:
                    top, bot = sizes[0], sizes[1]
                    if top < floor_top:
                        top, bot = floor_top, total - floor_top
                        self.outer_vsplit.setSizes([top, bot])
                    elif bot < floor_bot:
                        bot, top = floor_bot, total - floor_bot
                        self.outer_vsplit.setSizes([top, bot])
            self._schedule_persist_splitters()
            self._refresh_tab_bars_after_splitter()
        except Exception as e:
            safe_print(f"outer vsplit: {e}")

    def _on_splitter_moved(self, *args):
        # توافق خلفي إن وُجدت إشارات قديمة
        if getattr(self, "_closing", False):
            return
        self._reposition_custom_file_buttons()
        self._schedule_persist_splitters()
        self._refresh_tab_bars_after_splitter()

    def _restore_splitter_sizes(self):
        """استعادة المقاسات مع فرض تساوي عرض العمودين."""
        try:
            self._syncing_splitters = True
            main_sizes = self.settings.get("splitter_main_sizes")
            bottom_sizes = self.settings.get("splitter_bottom_sizes")
            # فضّل المقاس الرئيسي؛ وإن نقص استخدم السفلي
            col = None
            if main_sizes and len(main_sizes) == 2:
                col = [int(main_sizes[0]), int(main_sizes[1])]
            elif bottom_sizes and len(bottom_sizes) == 2:
                col = [int(bottom_sizes[0]), int(bottom_sizes[1])]
            if col and hasattr(self, "top_hsplit"):
                self.top_hsplit.setSizes(col)
            if col and hasattr(self, "bottom_hsplit"):
                self.bottom_hsplit.setSizes(col)
            right_sizes = self.settings.get("splitter_right_v_sizes")
            if right_sizes and len(right_sizes) == 2 and hasattr(self, "outer_vsplit"):
                # استعادة أي نسبة محفوظة (حتى لو الأسفل > نصف الشاشة)
                top_h = max(40, int(right_sizes[0]))
                bot_h = max(140, int(right_sizes[1]))
                self.outer_vsplit.setSizes([top_h, bot_h])
        except Exception:
            pass
        finally:
            self._syncing_splitters = False

    def _set_app_state(self, state: str):
        # ✅ v29.0
        self._app_state = state
        try:
            self._refresh_top_status_bar(force=True)
        except Exception:
            pass

    def _refresh_stream_books_label(self):
        """✅ v29.4: عرض الكتب النشطة فوق الستريم مفصولة بـ |"""
        if not hasattr(self, "stream_book_label"):
            return
        try:
            books = []
            seen = set()
            for _lane, name in sorted(getattr(self, "_stream_active_books", {}).items()):
                if name and name not in seen:
                    seen.add(name)
                    books.append(name)
            if not books:
                return
            if len(books) == 1:
                self.stream_book_label.setText(f"📚 {books[0]}")
            else:
                self.stream_book_label.setText("📚 " + " | ".join(books))
            self.stream_book_label.setToolTip("كتب قيد الاستخراج الآن:\n- " + "\n- ".join(books))
        except Exception:
            pass

    # ─────────────────────────────── أنيميشن مؤشر الاستخراج (v10.3)
    def _draw_stream_icon(self, state: str, phase: int) -> QPixmap:
        """رسم المؤشر: pulse = دائرة خضراء نابضة، ok = ✅، err = أحمر.
        ✅ v10.4: الرسم بمقاس العرض الفعلي (24×24) — قبل كده كانت الصورة
        48×48 وتُقص للإطار فتظهر «أسطوانة» بدل الدائرة."""
        size = 24
        pm = QPixmap(size, size)
        pm.fill(Qt.GlobalColor.transparent)
        p = QPainter(pm)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        try:
            c = QPointF(size / 2.0, size / 2.0)
            if state == "pulse":
                # نبضة كل ~1.4 ثانية: حجم + شفافية على موجة جيبية
                # ✅ v10.4: النقطة أكبر قليلا (0.20→0.33) والحلقة (0.43)
                t = (math.sin(2.0 * math.pi * phase / 14.0) + 1.0) / 2.0
                r = size * (0.20 + 0.13 * t)
                col = QColor("#a6e3a1")
                col.setAlpha(int(150 + 105 * t))
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(col)
                p.drawEllipse(c, r, r)
                # حلقة خارجية ثابتة شفافة
                ring = QColor("#a6e3a1")
                ring.setAlpha(70)
                p.setPen(QPen(ring, 2))
                p.setBrush(Qt.BrushStyle.NoBrush)
                p.drawEllipse(c, size * 0.43, size * 0.43)
            elif state == "ok":
                col = QColor("#a6e3a1")
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(col)
                p.drawEllipse(c, size * 0.36, size * 0.36)
                pen = QPen(QColor("#1e1e2e"), size * 0.09)
                pen.setCapStyle(Qt.PenCapStyle.RoundCap)
                p.setPen(pen)
                p.setBrush(Qt.BrushStyle.NoBrush)
                p.drawLine(QPointF(size * 0.33, size * 0.50),
                           QPointF(size * 0.45, size * 0.62))
                p.drawLine(QPointF(size * 0.45, size * 0.62),
                           QPointF(size * 0.68, size * 0.38))
            elif state == "err":
                col = QColor("#f38ba8")
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(col)
                p.drawEllipse(c, size * 0.36, size * 0.36)
                pen = QPen(QColor("#1e1e2e"), size * 0.09)
                pen.setCapStyle(Qt.PenCapStyle.RoundCap)
                p.setPen(pen)
                p.setBrush(Qt.BrushStyle.NoBrush)
                p.drawLine(QPointF(size * 0.37, size * 0.37),
                           QPointF(size * 0.63, size * 0.63))
                p.drawLine(QPointF(size * 0.63, size * 0.37),
                           QPointF(size * 0.37, size * 0.63))
        except Exception:
            pass
        finally:
            p.end()
        return pm

    def _stream_icon_set_state(self, state: str) -> None:
        """تبديل حالة مؤشر الشريط العلوي: pulse / ok / err / idle
        (idle = 📄 ثابت) — لا يتسرب أي خطأ للواجهة."""
        try:
            lbl = getattr(self, "stat_file_icon", None)
            if lbl is None:
                return
            if state == "idle":
                if getattr(self, "_stream_icon_timer", None) is not None:
                    self._stream_icon_timer.stop()
                self._stream_icon_state = "idle"
                lbl.setPixmap(QPixmap())
                lbl.setText("📄")
                lbl.setStyleSheet("font-size:15px;")
                return
            if state in ("ok", "err"):
                if getattr(self, "_stream_icon_timer", None) is not None:
                    self._stream_icon_timer.stop()
            if self._stream_icon_state != state:
                self._stream_icon_state = state
                self._stream_icon_phase = 0
                if state in ("ok", "err"):
                    # عرض النتيجة لثانية ونص ثم عودة (نبض لو فيه كتب، وإلا 📄)
                    QTimer.singleShot(1500, self._stream_icon_after_flash)
            lbl.setText("")
            pm = self._draw_stream_icon(state, self._stream_icon_phase)
            lbl.setPixmap(pm)
            if state == "pulse":
                timer = getattr(self, "_stream_icon_timer", None)
                if timer is None:
                    timer = QTimer(self)
                    timer.setInterval(100)
                    timer.timeout.connect(self._stream_icon_tick)
                    self._stream_icon_timer = timer
                if not timer.isActive():
                    timer.start()
        except Exception:
            pass

    def _stream_icon_tick(self) -> None:
        try:
            if getattr(self, "_stream_icon_state", None) != "pulse":
                return
            self._stream_icon_phase = (self._stream_icon_phase + 1) % 14
            pm = self._draw_stream_icon("pulse", self._stream_icon_phase)
            self.stat_file_icon.setPixmap(pm)
        except Exception:
            pass

    def _stream_icon_after_flash(self) -> None:
        try:
            if self._any_file_running() or getattr(self, "_stream_active_books", None):
                self._stream_icon_set_state("pulse")
            else:
                self._stream_icon_set_state("idle")
        except Exception:
            pass

    def _refresh_top_status_bar(self, force: bool = False):
        """✅ v29.0: تحديث خفيف للشريط العلوي (throttle ~700ms)."""
        try:
            now = time.monotonic()
            if not force and (now - getattr(self, "_ui_status_last_ts", 0.0)) < 0.7:
                return
            self._ui_status_last_ts = now
            # حالة التشغيل
            st = getattr(self, "_app_state", "IDLE")
            st_map = {
                "IDLE": "⚪ جاهز",
                "RUNNING": "🔄 يعمل",
                "PAUSED": "⏸️ مؤقت",
                "STOPPING": "⏹️ يتوقف",
                "CLOSING": "🚪 يُغلق",
            }
            # حدث معلومات الجلسة إن توفرت
            try:
                self._update_session_info_labels()
            except Exception:
                pass
            # لا MessageBox — فقط شريط الحالة باختصار
            if hasattr(self, "statusBar"):
                try:
                    if st != "IDLE":
                        self.statusBar().showMessage(st_map.get(st, st), 1500)
                except Exception:
                    pass
        except Exception:
            pass

    def _is_any_background_task_running(self) -> bool:
        # ✅ v28.3: يعتبر العملية نشطة إن وُجد عامل أو خيط حي
        if any(obj is not None for obj in [
            self.worker, self._reextract_worker, self._recompare_worker,
            self._autoloop_worker, self._manual_recheck_worker, self._fetch_worker,
            self._split_detection_worker]):
            return True
        try:
            # حساب بيانات الملف قراءة فقط، ولا يمنع فتح شاشات أخرى أو بدء كتاب.
            return self._any_bg_thread_alive(
                include_file_metrics=False, include_discovery=False)
        except Exception:
            return False

    def _current_book_is_txt(self) -> bool:
        # ✅ v27.0: تحديد نوع الكتاب حتى لو لم يعد المصدر الأصلي متاحاً
        try:
            if self._current_book_path is not None:
                return is_txt_file(self._current_book_path)
            if self._current_book_shards:
                return bool(self._current_book_shards[0].is_txt)
        except Exception:
            pass
        return False

    def _get_processing_book_path(self) -> Optional[Path]:
        # ✅ v27.0: مسار تشغيل بديل للأعمال التي تحتاج stem/الامتداد فقط
        if self._current_book_path is not None:
            return self._current_book_path
        if not self._current_book_stem:
            return None
        suffix = ".txt" if self._current_book_is_txt() else ".pdf"
        return Path(f"{self._current_book_stem}{suffix}")

    def _ensure_active_book_selected(self, silent: bool = False) -> bool:
        # ✅ v27.0: توحيد رسالة التحقق من الكتاب النشط
        if self._current_output_dir and self._current_book_stem:
            return True
        if not silent:
            QMessageBox.warning(self, "تنبيه", "حمّل كتاباً أولاً من المكتبة.")
        return False

    def _ensure_current_shards_available(self, silent: bool = False) -> bool:
        # ✅ v27.0: دعم إعادة إنشاء الشظايا المحذوفة من المصدر الأصلي إذا كان متاحاً
        if not self._ensure_active_book_selected(silent=silent):
            return False
        if not self._current_book_shards:
            if not silent:
                QMessageBox.warning(self, "تنبيه", "لا توجد بيانات أجزاء محمّلة لهذا الكتاب.")
            return False
        missing = [s for s in self._current_book_shards if not s.shard_path.exists()]
        if not missing:
            return True
        if self._current_book_path is not None and self._current_book_path.exists() and self._current_output_dir is not None:
            shards_dir = get_book_shards_dir(self._current_output_dir, self._current_book_stem)
            self._append_log(
                f"📚 تمت ملاحظة {len(missing)} shard مفقودة — محاولة إعادة إنشائها من المصدر...")
            rebuilt = rebuild_shards_from_source(
                self._current_book_path, shards_dir, self._current_book_shards, self._append_log)
            if rebuilt:
                self._current_book_shards = rebuilt
                self._append_log(f"✅ أُعيد إنشاء {len(rebuilt)} shard للكتاب المحمّل.")
                return True
        if not silent:
            QMessageBox.warning(
                self, "تنبيه",
                "ملفات shards غير موجودة، ولا يمكن إعادة إنشائها لأن المصدر الأصلي غير متاح.")
        return False

    def _ensure_active_book_context(self, *, silent: bool = False,
                                    require_shards: bool = False,
                                    require_runtime_path: bool = False,
                                    require_existing_source: bool = False,
                                    pdf_only: bool = False) -> Optional[Path]:
        # ✅ v27.0: فحص موحّد لكل أزرار المكتبة/إعادة الفحص
        if not self._ensure_active_book_selected(silent=silent):
            return None
        if require_shards and not self._ensure_current_shards_available(silent=silent):
            return None
        if pdf_only and self._current_book_is_txt():
            if not silent:
                QMessageBox.information(self, "ℹ️", "هذه العملية غير متاحة لملفات TXT.")
            return None
        if require_existing_source and not (self._current_book_path is not None and self._current_book_path.exists()):
            if not silent:
                QMessageBox.warning(self, "تنبيه", "المصدر الأصلي غير متاح لهذا الكتاب المحمّل.")
            return None
        if not require_runtime_path:
            return Path('.')
        book_path = self._get_processing_book_path()
        if book_path is None:
            if not silent:
                QMessageBox.warning(self, "تنبيه", "تعذر تجهيز مسار تشغيل للكتاب النشط.")
            return None
        return book_path

    def _resolve_library_output_dir(self) -> Optional[Path]:
        # ✅ v27.0: اختيار مجلد الإخراج المرجعي للمكتبة
        out_dir = self.output_dir_edit.text().strip()
        if out_dir:
            return Path(out_dir)
        if self._current_output_dir is not None:
            return self._current_output_dir
        return None

    def _discover_processed_books_async(self, roots, force_refresh: bool, callback):
        if self._closing or not callable(callback):
            return None
        thread = QThread(self)
        worker = ProcessedBooksDiscoveryWorker(self, roots, force_refresh)
        worker.moveToThread(thread)
        worker.completed.connect(callback, Qt.ConnectionType.QueuedConnection)
        worker.completed.connect(thread.quit)
        thread.finished.connect(self._on_discovery_thread_finished,
                                Qt.ConnectionType.QueuedConnection)
        thread.finished.connect(worker.deleteLater)
        thread.finished.connect(thread.deleteLater)
        thread.started.connect(worker.run)
        self._discovery_workers.append((thread, worker))
        thread.start()
        return thread

    def _on_discovery_thread_finished(self):
        thread = self.sender()
        try:
            if thread is not None and thread.isRunning():
                return
        except Exception:
            pass
        if thread is None:
            alive = []
            for th, wk in self._discovery_workers:
                try:
                    if th is not None and th.isRunning():
                        alive.append((th, wk))
                except Exception:
                    pass
            self._discovery_workers = alive
        else:
            self._discovery_workers = [
                (th, wk) for th, wk in self._discovery_workers if th is not thread]

    def _discover_processed_books_multi(self, roots: List[Path],
                                        force_refresh: bool = False,
                                        stop_event=None) -> List[dict]:
        if stop_event is not None and stop_event.is_set():
            return []
        if not hasattr(self, "_books_discovery_cache"): 
            self._books_discovery_cache = {}

        now = time.time()
        valid_roots = []
        for r in roots:
            if stop_event is not None and stop_event.is_set():
                return []
            try:
                r_path = Path(r)
                if r_path.exists():
                    valid_roots.append(r_path)
            except Exception:
                pass
                
        resolved = set()
        for root_path in valid_roots:
            if stop_event is not None and stop_event.is_set():
                return []
            try:
                resolved.add(str(root_path.resolve()))
            except Exception:
                resolved.add(str(root_path))
        resolved_strs = sorted(resolved)
        combined_str = ",".join(resolved_strs)
        cache_key = hashlib.md5(combined_str.encode("utf-8", errors="replace")).hexdigest() if combined_str else "empty_roots"

        if not force_refresh and cache_key in self._books_discovery_cache:
            cache_time, cached_books = self._books_discovery_cache[cache_key]
            if now - cache_time < 12.0:
                return cached_books

        books: List[dict] = []
        seen = set()

        for root in valid_roots:
            if stop_event is not None and stop_event.is_set():
                return []
            try:
                output_dir_p = Path(root)
                search_roots = []
                try:
                    search_roots.append(output_dir_p)
                    legacy = get_pdf_master_data_root(output_dir_p)
                    if legacy.exists():
                        search_roots.append(legacy)
                except Exception:
                    search_roots = [output_dir_p]

                for search_root in search_roots:
                    if stop_event is not None and stop_event.is_set():
                        return []
                    if not search_root.exists():
                        continue
                    for data_dir in search_root.iterdir():
                        if stop_event is not None and stop_event.is_set():
                            return []
                        if not data_dir.is_dir() or data_dir.name in {"_pdf_master_data", "system"}:
                            continue
                        try:
                            key = str(data_dir.resolve())
                            if key in seen:
                                continue

                            parts_dir = data_dir / 'parts'
                            compare_dir = data_dir / 'compare'
                            ckpt_path = data_dir / 'checkpoints' / 'checkpoint.json'
                            has_parts = parts_dir.exists()
                            has_compare = compare_dir.exists()
                            has_ckpt = ckpt_path.exists()
                            has_meta = (data_dir / 'book_meta.json').exists()

                            if not (has_parts or has_compare or has_ckpt or has_meta):
                                continue

                            seen.add(key)
                            mtimes = [data_dir.stat().st_mtime]
                            partial_path = compare_dir / 'partial.json'

                            compare_results = {}
                            if partial_path.exists():
                                mtimes.append(partial_path.stat().st_mtime)
                                compare_results = load_partial_compare_results_file(partial_path)

                            summary = None
                            if compare_dir.exists():
                                summary = load_final_compare_summary_file(compare_dir, compare_results, len(compare_results) or 1)

                            avg_coverage = int(summary.get('coverage_estimate_pct', 0)) if summary else 0
                            if not avg_coverage and compare_results:
                                valid_covs = [r.coverage_pct for r in compare_results.values() if r.error is None]
                                avg_coverage = int(sum(valid_covs) / len(valid_covs)) if valid_covs else 0

                            weak_count = len([r for r in compare_results.values() if r.error is not None or int(r.coverage_pct) < 90]) if compare_results else 0

                            parts_count = 0
                            if has_parts:
                                try:
                                    parts_count = sum(1 for p in parts_dir.iterdir() if p.name.endswith('.txt'))
                                except Exception:
                                    parts_count = 0

                            if not parts_count and compare_results:
                                parts_count = len(compare_results)

                            final_file = find_existing_final_output_file(output_dir_p, data_dir.name)
                            if final_file and final_file.exists():
                                mtimes.append(final_file.stat().st_mtime)

                            books.append({
                                'book_stem': data_dir.name,
                                'data_dir': data_dir,
                                'parts_count': parts_count,
                                'has_compare': bool(compare_results),
                                'avg_coverage': avg_coverage,
                                'weak_count': weak_count,
                                'last_modified': format_timestamp_human(max(mtimes)),
                                'final_file': final_file,
                                'root_dir': output_dir_p
                            })
                        except Exception:
                            continue
            except Exception:
                continue

        books.sort(key=lambda item: item.get('last_modified', ''), reverse=True)
        self._books_discovery_cache[cache_key] = (now, books)
        return books

    def _discover_processed_books(self, output_dir: Path, force_refresh: bool = False) -> List[dict]:
        return self._discover_processed_books_multi([output_dir], force_refresh)

    def _find_source_path_for_book(self, book_stem: str, safe_stem: str, output_dir: Path) -> Optional[Path]:
        # ✅ v27.0: البحث عن المصدر الأصلي من السجل أو الملفات الحالية أو مجلدات قريبة
        try:
            for record in self.history_manager.get_all():
                if safe_book_dir_name(str(record.get('book_stem') or '')) != safe_stem:
                    continue
                src = record.get('source_path')
                if src:
                    p = Path(src)
                    if p.exists():
                        return p
        except Exception:
            pass
        for candidate in self.input_files:
            try:
                if candidate.exists() and safe_book_dir_name(candidate.stem) == safe_stem:
                    return candidate
            except Exception:
                continue
        for root in [output_dir, output_dir.parent, self.app_dir]:
            try:
                if not root.exists():
                    continue
                for ext in ['.pdf', '.txt', '.text']:
                    cand = root / f'{book_stem}{ext}'
                    if cand.exists():
                        return cand
                    cand_safe = root / f'{safe_stem}{ext}'
                    if cand_safe.exists():
                        return cand_safe
            except Exception:
                continue
        return None

    def _derive_real_book_stem(self, safe_stem: str, output_dir: Path) -> str:
        # ✅ v27.0: محاولة استرجاع الاسم الأصلي للكتاب من parts/checkpoint/history
        parts_dir = get_book_parts_dir(output_dir, safe_stem)
        ckpt_path = get_book_checkpoints_dir(output_dir, safe_stem) / 'checkpoint.json'
        try:
            for pf in sorted(parts_dir.glob('*_part_*.txt')):
                m = re.match(r'(.+)_part_\d{4}\.txt$', pf.name)
                if m:
                    return m.group(1)
        except Exception:
            pass
        try:
            ckpt_data = read_json_file_safe(ckpt_path, {}) or {}
            for rec in ckpt_data.values():
                output_file = rec.get('output_file') or ''
                if output_file:
                    out_name = Path(output_file).name
                    m = re.match(r'(.+)_part_\d{4}\.txt$', out_name)
                    if m:
                        return m.group(1)
        except Exception:
            pass
        try:
            for record in self.history_manager.get_all():
                if safe_book_dir_name(str(record.get('book_stem') or '')) == safe_stem:
                    return str(record.get('book_stem') or safe_stem)
        except Exception:
            pass
        return safe_stem

    def _read_book_shards_from_storage(self, real_book_stem: str, output_dir: Path) -> List[PDFShard]:
        # ✅ v27.0: بناء قائمة shards من الملفات أو checkpoint مع دعم fallback للمصدر
        shards: List[PDFShard] = []
        shards_dir = get_book_shards_dir(output_dir, real_book_stem)
        ckpt_path = get_book_checkpoints_dir(output_dir, real_book_stem) / 'checkpoint.json'
        if shards_dir.exists():
            for shard_file in sorted(list(shards_dir.glob('shard_*.pdf')) + list(shards_dir.glob('shard_*.txt'))):
                parsed = parse_shard_filename(shard_file)
                if not parsed:
                    continue
                idx, start, end, is_txt = parsed
                shards.append(PDFShard(
                    idx=idx, page_start=start, page_end=end,
                    pages_count=max(0, end - start + 1), shard_path=shard_file,
                    shard_md5=_compute_md5(shard_file) if shard_file.exists() else '',
                    is_txt=is_txt, line_start=start if is_txt else 0,
                    line_end=end if is_txt else 0))
        if shards:
            return sorted(shards, key=lambda s: s.idx)
        ckpt_data = read_json_file_safe(ckpt_path, {}) or {}
        for key, rec in sorted(ckpt_data.items(), key=lambda item: int(item[0]) if str(item[0]).isdigit() else 10**9):
            try:
                idx = int(key)
                is_txt = bool(rec.get('is_txt', False))
                start = int(rec.get('page_start') or 0)
                end = int(rec.get('page_end') or start)
                suffix = '.txt' if is_txt else '.pdf'
                prefix = 'L' if is_txt else 'p'
                width = 6 if is_txt else 4
                shard_path = shards_dir / f"shard_{idx:04d}_{prefix}{start:0{width}d}-{end:0{width}d}{suffix}"
                shards.append(PDFShard(
                    idx=idx, page_start=start, page_end=end,
                    pages_count=max(0, end - start + 1), shard_path=shard_path,
                    shard_md5='', is_txt=is_txt,
                    line_start=start if is_txt else 0,
                    line_end=end if is_txt else 0))
            except Exception:
                continue
        return sorted(shards, key=lambda s: s.idx)

    def _load_previous_book(self, book_stem: str, output_dir: Path, silent: bool = False):
        self.roots_manager.add_or_update_root(str(output_dir))
        # ✅ v27.0: تحميل كتاب محفوظ سابقاً وإعادته ككتاب نشط في الواجهة
        if self._is_any_background_task_running():
            if not silent:
                QMessageBox.warning(self, 'تنبيه', 'لا يمكن تحميل كتاب محفوظ أثناء وجود عملية تعمل حالياً.')
            return False
        safe_stem = safe_book_dir_name(book_stem)
        data_dir = get_book_data_dir(output_dir, safe_stem)
        if not data_dir.exists():
            if not silent:
                QMessageBox.warning(self, 'غير موجود', f'بيانات الكتاب غير موجودة:\n{data_dir}')
            return False
        real_book_stem = self._derive_real_book_stem(safe_stem, output_dir)
        source_path = self._find_source_path_for_book(real_book_stem, safe_stem, output_dir)
        self._current_book_stem = real_book_stem
        self._current_output_dir = output_dir
        self._current_parts_dir = get_book_parts_dir(output_dir, real_book_stem)
        self._current_book_path = source_path if source_path and source_path.exists() else None
        self._current_book_shards = self._read_book_shards_from_storage(real_book_stem, output_dir)
        if self._current_book_shards and any(not s.shard_path.exists() for s in self._current_book_shards) and self._current_book_path is not None:
            rebuilt = rebuild_shards_from_source(
                self._current_book_path,
                get_book_shards_dir(output_dir, real_book_stem),
                self._current_book_shards,
                self._append_log)
            if rebuilt:
                self._current_book_shards = rebuilt

        compare_dir = get_book_compare_dir(output_dir, real_book_stem)
        self._partial_compare_results = load_partial_compare_results_file(compare_dir / 'partial.json')
        self._final_compare_result = load_final_compare_summary_file(
            compare_dir, self._partial_compare_results, len(self._current_book_shards))
        self._secondary_compare_results = {}
        # ✅ إصلاح: كان هناك قاموس منفصل (_session_compare_results_by_book) يجمع
        # نتائج مقارنة عدة كتب من الجلسة الحالية، وكانت شاشات المقارنة تُفضّله
        # دائماً على بيانات الكتاب المُحمَّل حديثاً إن لم يُصفَّر — فتظل تعرض
        # كتاباً قديماً من الجلسة رغم تحميل كتاب آخر من المكتبة/السجل بنجاح.
        # تصفيره هنا تجعل الشاشات تعتمد فوراً على بيانات الكتاب الذي حُمِّل الآن.
        self._session_compare_results_by_book = {}
        self._refresh_partial_compare_table()
        self.partial_compare_detail.clear()
        if self._final_compare_result:
            self._render_final_compare_summary(self._final_compare_result, switch_tab=False, allow_postprocess=False)
        else:
            self.final_compare_summary.setText('لم يُولّد التقرير الشامل بعد.')
        self._update_failed_count_label()
        self._update_weak_count_label()
        self._update_missing_extract_count_label()
        self._update_parts_counters()
        self.progress_bar.setValue(0)
        self.batch_extract_bar.setValue(0)
        self.upload_progress_bar.setValue(0)
        self._set_compare_ui_enabled(True)
        self.last_final_path = find_existing_final_output_file(output_dir, real_book_stem)
        self.btn_view_final.setEnabled(bool(self.last_final_path and self.last_final_path.exists()))
        self.stat_file.setText(f'الكتاب النشط: {real_book_stem}')
        total_units = sum(max(0, s.pages_count) for s in self._current_book_shards)
        self.stat_pages.setText(('📝 كلمات: ' if self._current_book_is_txt() else '📃 صفحات: ') + f'{total_units:,}')
        src_label = str(self._current_book_path) if self._current_book_path else 'المصدر غير معروف — تم التحميل من البيانات المحفوظة'
        self._append_log(f'📚 تم تحميل كتاب محفوظ: {real_book_stem}')
        self._append_log(f'📁 البيانات: {data_dir}')
        self._append_log(f'📎 المصدر: {src_label}')
        self.statusBar().showMessage(f'📚 تم تحميل الكتاب: {real_book_stem}', 6000)
        return True

    def _sessions_dir(self) -> Path:
        out = Path(self.output_dir_edit.text().strip()) if hasattr(self, "output_dir_edit") and self.output_dir_edit.text().strip() else self.app_dir
        return get_pdf_master_system_dir(out) / "sessions"

    def _save_current_session(self, status: str = "running"):
        try:
            sdir = self._sessions_dir(); sdir.mkdir(parents=True, exist_ok=True)
            if self._active_session_path is None:
                self._active_session_path = sdir / "last_session.json"
            payload = {
                "status": status,
                "updated_at": datetime.now().isoformat(timespec="seconds"),
                "output_dir": self.output_dir_edit.text().strip() if hasattr(self, "output_dir_edit") else "",
                "files": [str(p) for p in getattr(self, "input_files", [])],
                "custom_split_text": self.custom_split_text.text().strip() if hasattr(self, "custom_split_text") else "",
                "file_custom_splits": dict(getattr(self, "_file_custom_splits", {})),
                "file_custom_batches": dict(getattr(self, "_file_custom_batches", {})),
                "file_range_export_enabled": dict(getattr(self, "_file_range_export_enabled", {})),
                "file_range_export_group_size": dict(getattr(self, "_file_range_export_group_size", {})),
                "pages_per_batch": self.pages_per_batch_spin.value() if hasattr(self, "pages_per_batch_spin") else 25,
                "lines_per_batch": self.lines_per_batch_spin.value() if hasattr(self, "lines_per_batch_spin") else 2000,
                "finished_outputs": [(n, str(p)) for n, p in getattr(self, "_finished_output_files", [])],
                "scrollbar_pos": self.log_view.verticalScrollBar().value() if hasattr(self, "log_view") else 0,
            }
            atomic_write_text(self._active_session_path, json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
            atomic_write_text(sdir / "last_session.json", json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
        except Exception as e:
            safe_print(f"save session: {e}")

    def _auto_restore_last_session(self):
        try:
            sdir = self._sessions_dir()
            last_path = sdir / "last_session.json"
            if not last_path.exists():
                return
            data = read_json_file_safe(last_path, {}) or {}
            files = data.get("files") or []
            if not files:
                return
            out = data.get("output_dir") or ""
            if out and hasattr(self, "output_dir_edit"):
                self.output_dir_edit.setText(out)
                self.roots_manager.add_or_update_root(out)
            if hasattr(self, "custom_split_text"): self.custom_split_text.setText(data.get("custom_split_text", ""))
            self._file_custom_splits = {str(k): str(v) for k, v in (data.get("file_custom_splits") or {}).items()}
            self._file_custom_batches = {str(k): str(v) for k, v in (data.get("file_custom_batches") or {}).items()}
            self._file_range_export_enabled = {str(k): bool(v) for k, v in (data.get("file_range_export_enabled") or {}).items()}
            self._file_range_export_group_size = {str(k): int(v) for k, v in (data.get("file_range_export_group_size") or {}).items()}
            if "pages_per_batch" in data and hasattr(self, "pages_per_batch_spin"):
                self.pages_per_batch_spin.setValue(int(data["pages_per_batch"]))
            if "lines_per_batch" in data and hasattr(self, "lines_per_batch_spin"):
                self.lines_per_batch_spin.setValue(int(data["lines_per_batch"]))
            if "scrollbar_pos" in data and hasattr(self, "log_view"):
                QTimer.singleShot(1000, lambda v=data["scrollbar_pos"]: self.log_view.verticalScrollBar().setValue(v))
            self._active_session_path = last_path
            self._suppress_previous_prompt_once = True
            try:
                self._add_files_from_paths(files)
            finally:
                self._suppress_previous_prompt_once = False
            for i in range(self.files_list.count()):
                it = self.files_list.item(i); ps = it.data(Qt.ItemDataRole.UserRole)
                if ps in self._file_custom_splits and "✂️ جزئي" not in it.text():
                    it.setText(it.text() + "   │  ✂️ جزئي")
                if ps in self._file_custom_batches and "▦ دفعات" not in it.text():
                    it.setText(it.text() + "   │  ▦ دفعات")
            self.statusBar().showMessage("📂 تم استرجاع الجلسة السابقة تلقائياً بنطاقاتها وقت التقسيم", 5000)
            self._append_log("📂 تم استرجاع الجلسة السابقة تلقائياً وتقسيماتها المخصصة.")
        except Exception as e:
            safe_print(f"auto restore session error: {e}")

    def _on_restore_session(self):
        try:
            sdir = self._sessions_dir()
            sessions = sorted(sdir.glob("*.json"), key=lambda p: p.stat().st_mtime, reverse=True) if sdir.exists() else []
            if not sessions:
                QMessageBox.information(self, "ℹ️", "لا توجد جلسات عمل محفوظة في مسار الحفظ الحالي.")
                return
            dlg = QDialog(self); dlg.setWindowTitle("📂 جلسات العمل السابقة"); dlg.setLayoutDirection(Qt.LayoutDirection.RightToLeft); dlg.resize(700, 420)
            lay = QVBoxLayout(dlg); lay.addWidget(QLabel("اختر جلسة لاستعادتها:"))
            lst = QListWidget(); lst.setStyleSheet("QListWidget::item { padding:8px; }")
            data_by_row = []
            for sp in sessions:
                data = read_json_file_safe(sp, {}) or {}
                files = data.get("files") or []
                status = data.get("status", "—")
                # ✅ إصلاح: كانت القائمة تعرض التاريخ وعدد الملفات فقط بلا أي
                # اسم يوضّح أي كتاب/كتب تخص هذه الجلسة، فيصعب التمييز بينها.
                # الآن نعرض أسماء الملفات (بدون المسار والامتداد) مباشرة.
                names = [Path(str(f)).stem for f in files if f]
                if not names:
                    names_display = "بلا ملفات"
                elif len(names) <= 3:
                    names_display = "، ".join(names)
                else:
                    names_display = "، ".join(names[:3]) + f" و{len(names) - 3} آخرين"
                item = QListWidgetItem(
                    f"{data.get('updated_at', sp.stem)} | {status} | ملفات: {len(files)}\n📖 {names_display}")
                item.setToolTip("\n".join(names) if names else "بلا ملفات")
                item.setData(Qt.ItemDataRole.UserRole, str(sp))
                lst.addItem(item); data_by_row.append(data)
            lay.addWidget(lst, 1)
            row = QHBoxLayout(); btn_load = QPushButton("استعادة المحدد"); btn_cancel = QPushButton("إغلاق")
            row.addStretch(1); row.addWidget(btn_load); row.addWidget(btn_cancel); lay.addLayout(row)
            btn_cancel.clicked.connect(dlg.reject); btn_load.clicked.connect(dlg.accept)
            if lst.count(): lst.setCurrentRow(0)
            if dlg.exec() != QDialog.DialogCode.Accepted or not lst.currentItem():
                return
            sp = Path(lst.currentItem().data(Qt.ItemDataRole.UserRole))
            data = read_json_file_safe(sp, {}) or {}
            self._on_clear_files()
            out = data.get("output_dir") or ""
            if out:
                self.output_dir_edit.setText(out)
                self.roots_manager.add_or_update_root(out)
            self.custom_split_text.setText(data.get("custom_split_text", ""))
            self._file_custom_splits = {str(k): str(v) for k, v in (data.get("file_custom_splits") or {}).items()}
            self._file_custom_batches = {str(k): str(v) for k, v in (data.get("file_custom_batches") or {}).items()}
            self._file_range_export_enabled = {str(k): bool(v) for k, v in (data.get("file_range_export_enabled") or {}).items()}
            self._file_range_export_group_size = {str(k): int(v) for k, v in (data.get("file_range_export_group_size") or {}).items()}
            self._active_session_path = sp
            self._suppress_previous_prompt_once = True
            try:
                self._add_files_from_paths(data.get("files") or [])
            finally:
                self._suppress_previous_prompt_once = False
            # أعِد علامات الجزئي بصرياً بعد الإضافة.
            for i in range(self.files_list.count()):
                it = self.files_list.item(i); ps = it.data(Qt.ItemDataRole.UserRole)
                if ps in self._file_custom_splits and "✂️ جزئي" not in it.text():
                    it.setText(it.text() + "   │  ✂️ جزئي")
                if ps in self._file_custom_batches and "▦ دفعات" not in it.text():
                    it.setText(it.text() + "   │  ▦ دفعات")
            self.statusBar().showMessage("📂 تم استرجاع الجلسة — اضغط بدء للاستكمال", 5000)
        except Exception as e:
            QMessageBox.warning(self, "خطأ", str(e))

