    def _cached_file_metric(self, path: Path) -> Optional[dict]:
        key = _file_metrics_path_key(path)
        metric = self._file_metric_cache.get(key)
        if metric is None:
            return None
        try:
            stat = Path(path).stat()
        except Exception:
            return metric if not metric.get("exists", True) else None
        if (int(stat.st_mtime_ns), int(stat.st_size)) == (
                metric.get("mtime_ns"), metric.get("size")):
            return metric
        return None

    def _file_metrics_missing(self, paths=None) -> List[Path]:
        missing = []
        seen = set()
        for path in (self.input_files if paths is None else paths) or []:
            p = Path(path)
            key = _file_metrics_path_key(p)
            if key in seen:
                continue
            seen.add(key)
            if self._cached_file_metric(p) is None:
                missing.append(p)
        return missing

    def _format_input_file_label(self, path: Path, status: str = "pending",
                                 custom_batch_label: str = "دفعات") -> str:
        p = Path(path)
        is_txt = is_txt_file(p)
        icon = "📝" if is_txt else "📄"
        unit_label = "كلمة" if is_txt else "ص"
        metric = self._cached_file_metric(p)
        prefix = {"pending": "⏳", "running": "🔄", "done": "✅",
                  "failed": "❌", "partial": "⚠️"}.get(status, "⏳")
        if metric is None:
            details = "📃 جارٍ حساب الوحدات  │  💾 —"
        else:
            units = int(metric.get("units") or 0)
            size_mb = max(0, int(metric.get("size") or 0)) / 1024 / 1024
            details = f"📃 {units} {unit_label}  │  💾 {size_mb:.2f} MB"
        label = f"{prefix} {icon} {p.name}    │  {details}"
        if _custom_map_value(getattr(self, "_file_custom_splits", {}), p, ""):
            label += "   │  ✂️ جزئي"
        if _custom_map_value(getattr(self, "_file_custom_batches", {}), p, ""):
            label += f"   │  ▦ {custom_batch_label}"
        return label

    def _refresh_file_item_labels(self):
        if not hasattr(self, "files_list"):
            return
        for index in range(self.files_list.count()):
            item = self.files_list.item(index)
            if item is None:
                continue
            path = item.data(Qt.ItemDataRole.UserRole)
            status = str(item.data(Qt.ItemDataRole.UserRole + 1) or "pending")
            if path:
                item.setText(self._format_input_file_label(Path(str(path)), status))

    def _queue_file_metrics(self, paths):
        if self._closing:
            return
        pending_keys = {_file_metrics_path_key(p) for p in self._file_metrics_pending}
        for raw_path in paths or []:
            path = Path(raw_path)
            key = _file_metrics_path_key(path)
            if (self._cached_file_metric(path) is not None
                    or key in self._file_metrics_inflight
                    or key in pending_keys):
                continue
            self._file_metrics_pending.append(path)
            pending_keys.add(key)
        self._start_file_metrics_worker()

    def _start_file_metrics_worker(self):
        if self._closing or not self._file_metrics_pending:
            return
        current = self._file_metrics_thread
        if current is not None:
            try:
                if current.isRunning():
                    return
            except Exception:
                pass
            # انتظر callback finished لتنظيف الزوج قبل إنشاء QThread جديد.
            return
        paths = list(self._file_metrics_pending)
        self._file_metrics_pending.clear()
        self._file_metrics_batch_paths = paths
        self._file_metrics_inflight.update(_file_metrics_path_key(p) for p in paths)
        thread = QThread(self)
        worker = FileMetricsWorker(paths)
        worker.moveToThread(thread)
        worker.progress.connect(self._on_file_metrics_progress,
                                Qt.ConnectionType.QueuedConnection)
        worker.completed.connect(self._on_file_metrics_ready,
                                  Qt.ConnectionType.QueuedConnection)
        worker.completed.connect(thread.quit)
        thread.finished.connect(
            lambda th=thread, wk=worker: self._on_file_metrics_thread_finished(th, wk),
            Qt.ConnectionType.QueuedConnection)
        thread.finished.connect(worker.deleteLater)
        thread.finished.connect(thread.deleteLater)
        thread.started.connect(worker.run)
        self._file_metrics_thread = thread
        self._file_metrics_worker = worker
        thread.start()

    def _on_file_metrics_progress(self, path: str, current: int, total: int):
        if self._start_after_file_metrics and not self._closing:
            try:
                self.statusBar().showMessage(
                    f"⏳ تجهيز الملفات قبل البدء... {current}/{total} — {Path(path).name}")
            except Exception:
                pass

    def _on_file_metrics_ready(self, results):
        if self._closing:
            return
        try:
            for key, metric in dict(results or {}).items():
                self._file_metric_cache[str(key)] = dict(metric or {})
            while len(self._file_metric_cache) > 2048:
                self._file_metric_cache.pop(next(iter(self._file_metric_cache)), None)
            self._refresh_file_item_labels()
            self._update_files_stats()
        except Exception as exc:
            safe_print(f"[file-metrics] update error: {exc}")

    def _on_file_metrics_thread_finished(self, thread, worker):
        try:
            if thread is not None and thread.isRunning():
                return
        except Exception:
            pass
        for path in self._file_metrics_batch_paths:
            self._file_metrics_inflight.discard(_file_metrics_path_key(path))
        self._file_metrics_batch_paths = []
        if self._file_metrics_thread is thread:
            self._file_metrics_thread = None
            self._file_metrics_worker = None
        if self._file_metrics_pending and not self._closing:
            self._start_file_metrics_worker()
            return
        if not self._closing:
            # إذا تغيّر ملف أثناء العد، أعد حسابه ببصمته الجديدة.
            stale = self._file_metrics_missing()
            if stale:
                self._queue_file_metrics(stale)
                return
            self._maybe_resume_start_after_file_metrics()

    def _maybe_resume_start_after_file_metrics(self):
        if not self._start_after_file_metrics or self._closing:
            return
        if not self.input_files:
            self._cancel_pending_metric_start()
            return
        missing = self._file_metrics_missing()
        if missing:
            self._queue_file_metrics(missing)
            return
        if self._file_metrics_pending or self._file_metrics_thread is not None:
            return
        self._start_after_file_metrics = False
        try:
            self.btn_start.setEnabled(True)
            self.btn_start.setText("▶️ بدء")
            self.statusBar().showMessage("✅ اكتمل تجهيز الملفات؛ جارٍ بدء المعالجة...")
        except Exception:
            pass
        QTimer.singleShot(0, self._on_start)

    def _cancel_pending_metric_start(self):
        self._start_after_file_metrics = False
        try:
            if getattr(self, "_app_state", "IDLE") == "IDLE":
                self.btn_start.setEnabled(True)
                self.btn_start.setText("▶️ بدء")
        except Exception:
            pass

    def _add_files_from_paths(self, paths: List[str]):
        """إضافة ملفات من حوار الاختيار أو السحب والإفلات."""
        out_dir_str = self.output_dir_edit.text().strip() if hasattr(self, "output_dir_edit") else ""
        out_dir = Path(out_dir_str) if out_dir_str else None
        self._cancel_pending_metric_start()
        self._previous_book_choice_for_add_batch = None
        total_paths = len(paths)
        candidate_paths = [Path(f) for f in paths
                           if Path(f).suffix.lower() in SUPPORTED_EXTS]
        self._queue_file_metrics(candidate_paths)
        added_count = 0
        for _i, f in enumerate(paths):
            p = Path(f)
            if p in self.input_files:
                continue
            if p.suffix.lower() not in SUPPORTED_EXTS:
                continue
            # العد بدأ في الخلفية قبل عرض خيارات الاستعادة/النطاقات.
            if out_dir is not None and not getattr(self, "_suppress_previous_prompt_once", False):
                action = self._prompt_if_previous_book_exists(p, out_dir)
                if action == "cancel":
                    continue
                if action == "partial_new":
                    raw_ranges = self._ask_custom_ranges_for_path(p)
                    if not raw_ranges:
                        continue
                    self._file_custom_splits[str(p)] = raw_ranges
                    self._file_range_export_enabled[str(p)] = bool(getattr(self, "_last_range_export_enabled", False))
                    self._file_range_export_group_size[str(p)] = int(getattr(self, "_last_range_export_group_size", 1) or 1)
                if not hasattr(self, "_pending_book_actions"):
                    self._pending_book_actions = {}
                if action in ("reextract_all", "reextract_selected", "resume_missing"):
                    self._pending_book_actions[str(p)] = action
            self.input_files.append(p)
            added_count += 1
            item = QListWidgetItem(self._format_input_file_label(p, "pending"))
            item.setData(Qt.ItemDataRole.UserRole, str(p))
            item.setData(Qt.ItemDataRole.UserRole + 1, "pending")
            self.files_list.addItem(item)
            if total_paths > 3:
                try:
                    self.statusBar().showMessage(
                        f"⏳ جارٍ تجهيز قائمة الملفات... {_i + 1}/{total_paths}")
                except Exception:
                    pass
        self._update_files_stats()
        self._queue_file_metrics(self.input_files)
        if added_count and total_paths > 3:
            try:
                self.statusBar().showMessage(
                    f"⏳ تمت إضافة {added_count} ملفاً؛ جارٍ حساب الصفحات والكلمات في الخلفية.",
                    5000)
            except Exception:
                pass


    def _on_add_files(self):
        self._invalidate_expected_ranges_cache()
        files, _ = QFileDialog.getOpenFileNames(
            self, "اختر ملفات PDF أو نصوص أو أي ملف قابل للقراءة", "",
            "كل الملفات (*.*);;PDF (*.pdf);;نصوص شائعة (*.txt *.text *.md *.csv *.json *.xml *.html *.log *.srt *.rtf);;الكل (*.*)")
        self._add_files_from_paths(files)

    def _sessions_for_book(self, file_path: Path) -> List[Tuple[Path, dict, str]]:
        """جلسات محفوظة تخص هذا الكتاب، مع النص الجزئي إن وجد."""
        out = Path(self.output_dir_edit.text().strip()) if hasattr(self, "output_dir_edit") and self.output_dir_edit.text().strip() else None
        roots = []
        if out:
            roots.append(get_pdf_master_system_dir(out) / "sessions")
        roots.append(self.app_dir / "_pdf_master_data" / "system" / "sessions")
        result = []
        target = str(Path(file_path))
        for sdir in roots:
            try:
                if not sdir.exists():
                    continue
                for sp in sorted(sdir.glob("*.json"), key=lambda x: x.stat().st_mtime, reverse=True):
                    data = read_json_file_safe(sp, {}) or {}
                    files = [str(x) for x in (data.get("files") or [])]
                    if target not in files:
                        continue
                    ctext = str((data.get("file_custom_splits") or {}).get(target, "") or "")
                    result.append((sp, data, ctext))
            except Exception:
                continue
        # إزالة التكرار حسب المسار
        seen, out_items = set(), []
        for sp, data, ctext in result:
            if str(sp) in seen:
                continue
            seen.add(str(sp)); out_items.append((sp, data, ctext))
        return out_items

    def _choose_session_for_book(self, file_path: Path) -> Optional[str]:
        sessions = self._sessions_for_book(file_path)
        if not sessions:
            QMessageBox.information(self, "ℹ️", "لا توجد جلسات محفوظة لهذا الكتاب.")
            return None
        dlg = QDialog(self)
        dlg.setWindowTitle("📂 جلسات هذا الكتاب")
        dlg.setLayoutDirection(Qt.LayoutDirection.RightToLeft)
        dlg.resize(680, 420)
        lay = QVBoxLayout(dlg)
        lay.addWidget(QLabel(f"اختر جلسة لاستعادتها للكتاب:\n{file_path.name}"))
        lst = QListWidget()
        lst.setStyleSheet("QListWidget::item { padding:8px; }")
        for sp, data, ctext in sessions:
            kind = "✂️ جزئية" if ctext else "📘 كاملة"
            status = data.get("status", "—")
            updated = data.get("updated_at", sp.stem)
            item = QListWidgetItem(f"{kind} | {updated} | {status}\n{sp.name}")
            item.setData(Qt.ItemDataRole.UserRole, str(sp))
            item.setData(Qt.ItemDataRole.UserRole + 1, ctext)
            lst.addItem(item)
        lay.addWidget(lst, 1)
        row = QHBoxLayout()
        btn_load = QPushButton("استعادة المحدد")
        btn_cancel = QPushButton("إغلاق")
        row.addStretch(1); row.addWidget(btn_load); row.addWidget(btn_cancel); lay.addLayout(row)
        btn_load.clicked.connect(dlg.accept); btn_cancel.clicked.connect(dlg.reject)
        if lst.count(): lst.setCurrentRow(0)
        if dlg.exec() != QDialog.DialogCode.Accepted or not lst.currentItem():
            return None
        return str(lst.currentItem().data(Qt.ItemDataRole.UserRole + 1) or "")

    def _prompt_if_previous_book_exists(self, file_path: Path, output_dir: Path) -> str:
        """
        ✅ v8.4: إن وُجدت بيانات سابقة للكتاب → خيّر المستخدم.
        """
        try:
            stem = file_path.stem
            safe_stem = safe_book_dir_name(stem)
            candidates = []
            direct_dir = get_book_data_dir(output_dir, stem)
            legacy_dir = get_pdf_master_data_root(output_dir) / safe_stem
            for d in (direct_dir, legacy_dir):
                if d not in candidates:
                    candidates.append(d)

            data_dir = direct_dir
            parts_dir = direct_dir / "parts"
            meta = {}
            parts_count = 0
            has_data = False
            final_existing = find_existing_final_output_file(output_dir, stem)

            for cand in candidates:
                try:
                    c_parts = cand / "parts"
                    c_ckpt = cand / "checkpoints" / "checkpoint.json"
                    c_meta = cand / "book_meta.json"
                    c_compare = cand / "compare"
                    has_part_file = False
                    if c_parts.exists():
                        try:
                            has_part_file = next(c_parts.glob("*_part_*.txt"), None) is not None
                        except Exception:
                            has_part_file = False
                    cand_has = cand.exists() and (
                        has_part_file or c_ckpt.exists() or c_meta.exists() or
                        (c_compare.exists() and any(c_compare.glob("*.json")))
                    )
                    if cand_has:
                        data_dir = cand
                        parts_dir = c_parts
                        meta = read_json_file_safe(c_meta, {}) or {}
                        parts_count = int(meta.get("parts_count") or 0)
                        if parts_count <= 0 and c_parts.exists():
                            try:
                                parts_count = sum(1 for _ in c_parts.glob("*_part_*.txt"))
                            except Exception:
                                parts_count = 0
                        has_data = True
                        break
                except Exception:
                    continue

            if not has_data and final_existing and Path(final_existing).exists():
                has_data = True
                meta = load_book_meta(output_dir, stem)

            if not has_data:
                return "new"

            if parts_count <= 0:
                try:
                    parts_count = sum(1 for _ in parts_dir.glob("*_part_*.txt")) if parts_dir.exists() else 0
                except Exception:
                    parts_count = 0
            units_rate = meta.get("units_per_batch") or meta.get("pages_per_batch") or "—"
            rate_unit = "كلمة" if is_txt_file(file_path) else "صفحة"

            remembered = getattr(self, "_previous_book_choice_for_add_batch", None)
            if remembered in {"cancel", "new", "partial_new", "reextract_all", "resume_missing"}:
                if remembered == "reextract_all":
                    self._wipe_book_parts_for_full_reextract(output_dir, file_path.stem)
                return remembered

            # ✅ v8.4: إصلاح خطأ 'lay' عبر تعريف الحوار أولاً
            dlg = QDialog(self)
            dlg.setWindowTitle("📚 نسخة سابقة مكتشفة")
            dlg.setLayoutDirection(Qt.LayoutDirection.RightToLeft)
            dlg.resize(560, 260)
            lay = QVBoxLayout(dlg)
            
            info = QLabel(
                f"الكتاب <b>{file_path.name}</b> له بيانات سابقة محفوظة.<br><br>"
                f"• عدد الأجزاء السابق: <b>{parts_count or '—'}</b><br>"
                f"• معدل الاستخراج السابق: <b>{units_rate}</b> {rate_unit}/دفعة<br>"
                f"• الملف النهائي: <b>{Path(final_existing).name if final_existing else '—'}</b><br><br>"
                f"ماذا تريد؟")
            info.setTextFormat(Qt.TextFormat.RichText)
            info.setWordWrap(True)
            lay.addWidget(info)
            
            remember_cb = QCheckBox("تذكر اختياري لباقي الكتب في عملية الإضافة الحالية فقط")
            lay.addWidget(remember_cb)
            
            grid = QGridLayout()
            chosen = {"action": "new"}
            def choose(action):
                chosen["action"] = action
                dlg.accept()
            
            btn_cancel = QPushButton("❌ إلغاء إضافة هذا الملف")
            btn_resume = QPushButton("▶️ استكمال الناقص")
            btn_partial_new = QPushButton("✂️ استخراج جزئي جديد")
            btn_session = QPushButton("📂 جلسة عمل سابقة")
            btn_all = QPushButton("♻️ إعادة استخراج كامل")
            btn_parts = QPushButton("🧩 إعادة استخراج أجزاء محددة")
            
            btn_cancel.clicked.connect(lambda: choose("cancel"))
            btn_resume.clicked.connect(lambda: choose("resume_missing"))
            btn_partial_new.clicked.connect(lambda: choose("partial_new"))
            btn_session.clicked.connect(lambda: choose("restore_book_session"))
            btn_all.clicked.connect(lambda: choose("reextract_all"))
            btn_parts.clicked.connect(lambda: choose("reextract_selected"))
            
            grid.addWidget(btn_cancel, 0, 0)
            grid.addWidget(btn_resume, 0, 1)
            grid.addWidget(btn_partial_new, 1, 0)
            grid.addWidget(btn_session, 1, 1)
            grid.addWidget(btn_all, 2, 0)
            grid.addWidget(btn_parts, 2, 1)
            lay.addLayout(grid)
            
            if dlg.exec() != QDialog.DialogCode.Accepted:
                return "cancel"
                
            action = chosen.get("action", "new")
            if remember_cb.isChecked() and action not in {"reextract_selected", "restore_book_session"}:
                self._previous_book_choice_for_add_batch = action
                
            if action == "cancel":
                return "cancel"
            if action == "partial_new":
                return "partial_new"
            if action == "resume_missing":
                return "resume_missing"
            if action == "restore_book_session":
                ctext = self._choose_session_for_book(file_path)
                if ctext is None: return "cancel"
                if ctext: self._file_custom_splits[str(file_path)] = ctext
                else: self._file_custom_splits.pop(str(file_path), None)
                return "new"
            if action == "reextract_all":
                self._wipe_book_parts_for_full_reextract(output_dir, file_path.stem)
                return "reextract_all"
            if action == "reextract_selected":
                try:
                    self._load_previous_book(file_path.stem, output_dir, silent=True)
                except Exception: pass
                if self._current_book_shards:
                    pdf_shards = [s for s in self._current_book_shards if not s.is_txt] or list(self._current_book_shards)
                    dlg_sel = ManualShardSelectionDialog(
                        self, pdf_shards, self._partial_compare_results,
                        file_path.stem, allow_reextract=True,
                        title="🧩 اختر الأجزاء لإعادة استخراجها")
                    if dlg_sel.exec() == QDialog.DialogCode.Accepted:
                        selected = dlg_sel.get_selected_indices()
                        if selected:
                            if not hasattr(self, "_pending_partial_reextract"):
                                self._pending_partial_reextract = {}
                            self._pending_partial_reextract[str(file_path)] = selected
                            self._wipe_selected_parts(output_dir, file_path.stem, selected)
                            return "reextract_selected"
                return "new"
            return "new"
        except Exception as e:
            safe_print(f"previous book prompt: {e}")
            return "new"

    def _wipe_book_data_completely(self, output_dir: Path, book_stem: str):
        """✅ v8.3: حذف مجلد بيانات الكتاب بالكامل والملفات النهائية المرتبطة به لضمان بدء جديد تماماً عند تغيير الإعدادات."""
        try:
            # 1. حذف مجلد البيانات بالكامل (_pdf_master_data/<book>)
            data_dir = get_book_data_dir(output_dir, book_stem)
            if data_dir.exists():
                shutil.rmtree(data_dir, ignore_errors=True)
            
            # 2. حذف الملفات النهائية المكتملة أو غير المكتملة في مجلد الإخراج
            safe_stem = safe_book_dir_name(book_stem)
            candidates = [
                output_dir / f"{book_stem}.txt",
                output_dir / f"{safe_stem}.txt",
                output_dir / f"{book_stem}_مستخرج.txt",
                output_dir / f"{safe_stem}_مستخرج.txt",
                output_dir / f"{book_stem}_معالج.txt",
                output_dir / f"{safe_stem}_معالج.txt",
                output_dir / f"{book_stem}_مستخرج.INCOMPLETE.txt",
                output_dir / f"{safe_stem}_مستخرج.INCOMPLETE.txt",
            ]
            for c in candidates:
                if c.exists():
                    try: c.unlink()
                    except Exception: pass
            
            self._append_log(f"🗑️ تم حذف كافة البيانات السابقة للكتاب (بدء جديد): {book_stem}")
        except Exception as e:
            self._append_log(f"⚠️ تعذر حذف البيانات بالكامل: {e}")

    def _wipe_book_parts_for_full_reextract(self, output_dir: Path, book_stem: str):
        """حذف الأجزاء والـ checkpoint لفرض إعادة استخراج كامل."""
        self._wipe_book_data_completely(output_dir, book_stem)

    def _wipe_selected_parts(self, output_dir: Path, book_stem: str, indices: List[int]):
        try:
            parts_dir = get_book_parts_dir(output_dir, book_stem)
            ckpt_path = get_book_checkpoints_dir(output_dir, book_stem) / "checkpoint.json"
            ckpt = Checkpoint(ckpt_path) if ckpt_path.parent.exists() else None
            for idx in indices:
                pf = parts_dir / f"{book_stem}_part_{idx:04d}.txt"
                if pf.exists():
                    try: pf.unlink()
                    except Exception: pass
                if ckpt:
                    try: ckpt.clear(idx)
                    except Exception: pass
            self._append_log(f"🗑️  مُسحت {len(indices)} جزء لإعادة الاستخراج: {indices[:20]}")
        except Exception as e:
            self._append_log(f"⚠️  تعذر مسح الأجزاء المحددة: {e}")

    def _on_files_selection_changed(self):
        # الزر العائم يعتمد على المرور بالماوس لا على التحديد.
        pass

    def _reposition_custom_file_buttons(self):
        # أبقيت الدالة للتوافق مع الإصدارات السابقة؛ لم تعد هناك أزرار تظهر عند المرور.
        try:
            self.btn_custom_batches_for_file.hide()
            self.btn_custom_ranges_for_file.hide()
        except Exception:
            pass

    def eventFilter(self, obj, event):
        # السحب والإفلات يعملان كالسابق، أما إجراءات الكتاب فتظهر بالزر الأيمن فقط.
        try:
            return super().eventFilter(obj, event)
        except Exception:
            return False

    def _show_file_context_menu(self, item, global_pos):
        if item is None:
            return
        raw_path = item.data(Qt.ItemDataRole.UserRole)
        if not raw_path:
            return
        path = Path(str(raw_path))
        menu = QMenu(self)
        menu.setLayoutDirection(Qt.LayoutDirection.RightToLeft)

        act_partial = menu.addAction("✂️ استخراج جزئي")
        act_partial.triggered.connect(lambda: self._on_custom_ranges_for_item(item))
        act_batches = menu.addAction("▦ دفعات مخصصة")
        act_batches.triggered.connect(lambda: self._on_custom_batches_for_item(item))
        menu.addSeparator()
        act_open = menu.addAction("📖 فتح الكتاب")
        act_open.triggered.connect(lambda: self._open_path(str(path)))
        act_single = menu.addAction("▶️ بدء استخراج هذا الكتاب فقط")
        act_single.triggered.connect(lambda: self._start_single_book(path))
        menu.addSeparator()
        act_delete = menu.addAction("🗑️ حذف الكتاب")
        act_delete.triggered.connect(lambda: self._delete_single_book(item))
        menu.exec(global_pos)

    def _on_custom_ranges_for_item(self, item):
        self._hover_file_item = item
        self._on_custom_ranges_for_hovered_file()

    def _on_custom_batches_for_item(self, item):
        self._hover_file_item = item
        self._on_custom_batches_for_hovered_file()

    def _delete_single_book(self, item):
        raw = item.data(Qt.ItemDataRole.UserRole)
        if not raw:
            return
        path = Path(str(raw))
        answer = QMessageBox.question(
            self, "تأكيد حذف الكتاب",
            f"هل تريد حذف الكتاب من قائمة التشغيل؟<br><b>{path.name}</b><br><br>لن تُحذف الملفات من القرص.",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No)
        if answer != QMessageBox.StandardButton.Yes:
            return
        self._cancel_pending_metric_start()
        if path in self.input_files:
            self.input_files.remove(path)
        self._file_custom_splits.pop(str(path), None)
        self._file_custom_batches.pop(str(path), None)
        self._file_range_export_enabled.pop(str(path), None)
        self._file_range_export_group_size.pop(str(path), None)
        self.files_list.takeItem(self.files_list.row(item))
        self._update_files_stats()
        self._on_files_selection_changed()

    def _start_single_book(self, path: Path):
        if path not in self.input_files:
            return
        if self._is_any_background_task_running() or getattr(self, "_app_state", "IDLE") in ("RUNNING", "STOPPING", "CLOSING"):
            QMessageBox.warning(self, "انتظر", "لا يمكن بدء كتاب منفرد أثناء وجود عملية أخرى.")
            return
        if not self._has_keys():
            QMessageBox.warning(self, "المفاتيح", "أضف مفتاح API أولاً.")
            return
        self._restore_files_after_single_run = list(self.input_files)
        self._single_book_to_run_path = Path(path)
        self._on_start()
        if (self.worker is None and getattr(self, "_app_state", "IDLE") != "RUNNING"
                and not self._start_after_file_metrics):
            self._restore_files_after_single_run = None
            self._single_book_to_run_path = None

    def _ask_custom_ranges_for_path(self, path: Path, initial: str = "") -> Optional[str]:
        """حوار صغير لإدخال نطاقات استخراج مخصصة، يرجع النص المطبع أو None عند الإلغاء/الفراغ."""
        dlg = QDialog(self)
        dlg.setWindowTitle("✂️ نطاقات استخراج مخصصة")
        dlg.setLayoutDirection(Qt.LayoutDirection.RightToLeft)
        dlg.resize(420, 300)
        lay = QVBoxLayout(dlg)
        info = QLabel(
            f"اكتب النطاقات المطلوب استخراجها فقط من:<br><b>{path.name}</b><br><br>"
            "مثال:<br>45-70<br>300-350<br><br>"
            "اتركها فارغة لإلغاء الاستخراج الجزئي.")
        info.setWordWrap(True)
        info.setTextFormat(Qt.TextFormat.RichText)
        lay.addWidget(info)
        export_check = QCheckBox("📁 بعد الاستخراج: اجعل كل نطاق/عدة نطاقات في ملف نصي مستقل داخل مجلد باسم الكتاب")
        export_check.setChecked(bool(getattr(self, "_file_range_export_enabled", {}).get(str(path), False)))
        lay.addWidget(export_check)
        group_row = QHBoxLayout()
        group_row.addWidget(QLabel("عدد النطاقات في كل ملف:"))
        group_spin = QSpinBox()
        group_spin.setRange(1, 1000)
        group_spin.setValue(int(getattr(self, "_file_range_export_group_size", {}).get(str(path), 1) or 1))
        group_spin.setEnabled(export_check.isChecked())
        export_check.toggled.connect(group_spin.setEnabled)
        group_row.addWidget(group_spin)
        group_row.addStretch(1)
        lay.addLayout(group_row)
        edit = QPlainTextEdit()
        edit.setPlainText(initial or "")
        edit.setPlaceholderText("45-70\n300-350")
        lay.addWidget(edit, 1)

        # لوحة مفاتيح مدمجة خاصة بنافذة نطاقات الاستخراج: أرقام وشرطة فقط.
        keyboard_box = QGroupBox("⌨ لوحة المفاتيح")
        keyboard_layout = QVBoxLayout(keyboard_box)
        keyboard_layout.setContentsMargins(6, 6, 6, 6)
        keyboard_layout.setSpacing(4)
        range_keys = ["1", "2", "3", "4", "5", "6", "7", "8", "9", "0", "-"]

        def delete_range_character():
            cursor = edit.textCursor()
            if cursor.hasSelection():
                cursor.removeSelectedText()
            else:
                cursor.deletePreviousChar()
            edit.setTextCursor(cursor)
            edit.setFocus()

        for row_index, row_keys in enumerate((range_keys[:6], range_keys[6:])):
            row_layout = QHBoxLayout()
            row_layout.setSpacing(0)
            for key_text in row_keys:
                key_button = QPushButton(key_text)
                key_button.setFixedSize(38, 30)
                key_button.clicked.connect(
                    lambda checked=False, value=key_text: (edit.insertPlainText(value), edit.setFocus()))
                row_layout.addWidget(key_button)
            if row_index == 1:
                delete_button = QPushButton("⌫")
                delete_button.setFixedSize(38, 30)
                delete_button.setToolTip("حذف الحرف السابق")
                delete_button.clicked.connect(delete_range_character)
                row_layout.addWidget(delete_button)
            keyboard_layout.addLayout(row_layout)

        buttons = QDialogButtonBox(QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Cancel)
        buttons.button(QDialogButtonBox.StandardButton.Ok).setText("موافق")
        buttons.button(QDialogButtonBox.StandardButton.Cancel).setText("إلغاء")
        buttons.accepted.connect(dlg.accept)
        buttons.rejected.connect(dlg.reject)
        bottom_row = QHBoxLayout()
        bottom_row.addWidget(keyboard_box)
        bottom_row.addStretch(1)
        bottom_row.addWidget(buttons)
        lay.addLayout(bottom_row)
        if dlg.exec() != QDialog.DialogCode.Accepted:
            return None
        raw = normalize_custom_ranges_text(edit.toPlainText())
        if not raw:
            return None
        metric = self._cached_file_metric(path)
        if metric is None:
            self._queue_file_metrics([path])
            QMessageBox.information(
                self, "جارٍ الحساب",
                "يُحسب عدد الصفحات/الكلمات في الخلفية. أعد إدخال النطاقات بعد اكتمال الحساب.")
            return None
        total_units = int(metric.get("units") or 0)
        parse_custom_split_ranges(raw, total_units)
        self._last_range_export_enabled = bool(export_check.isChecked())
        self._last_range_export_group_size = int(group_spin.value())
        return raw

    def _on_custom_batches_for_hovered_file(self):
        item = getattr(self, "_hover_file_item", None) or self.files_list.currentItem()
        self._open_custom_batches_dialog(item)

    def _on_custom_ranges_for_hovered_file(self):
        self._invalidate_expected_ranges_cache()
        item = getattr(self, "_hover_file_item", None)
        if item is None:
            item = self.files_list.currentItem()
        if item is None:
            return
        ps = item.data(Qt.ItemDataRole.UserRole)
        if not ps:
            return
        path = Path(ps)
        old = self._file_custom_splits.get(str(path), "")
        try:
            raw = self._ask_custom_ranges_for_path(path, old)
        except Exception as e:
            QMessageBox.warning(self, "نطاقات غير صالحة", str(e))
            return
        if raw:
            self._file_custom_splits[str(path)] = raw
            self._file_range_export_enabled[str(path)] = bool(getattr(self, "_last_range_export_enabled", False))
            self._file_range_export_group_size[str(path)] = int(getattr(self, "_last_range_export_group_size", 1) or 1)
            if "✂️ جزئي" not in item.text():
                item.setText(item.text() + "   │  ✂️ جزئي")
        else:
            self._file_custom_splits.pop(str(path), None)
            self._file_range_export_enabled.pop(str(path), None)
            self._file_range_export_group_size.pop(str(path), None)
            item.setText(item.text().replace("   │  ✂️ جزئي", ""))
        self._update_files_stats()
        self._refresh_session_expected_totals()

    def _populate_split_detection_model_combo(self):
        if not hasattr(self, "split_detection_model_combo"):
            return
        current = self.settings.get("split_detection_model_id", "gemini-2.5-flash")
        self.split_detection_model_combo.blockSignals(True)
        self.split_detection_model_combo.clear()
        for model in self._get_active_models_list() or DEFAULT_MODELS:
            self.split_detection_model_combo.addItem(model["label"], model)
        idx = self.split_detection_model_combo.findData(current, Qt.ItemDataRole.UserRole)
        if idx < 0:
            for i in range(self.split_detection_model_combo.count()):
                item = self.split_detection_model_combo.itemData(i)
                if item and item.get("id") == current:
                    idx = i; break
        if idx < 0 and self.split_detection_model_combo.count() > 0:
            idx = 0
        if idx >= 0:
            self.split_detection_model_combo.setCurrentIndex(idx)
        self.split_detection_model_combo.blockSignals(False)

    def _on_split_detection_model_changed(self, *args):
        try:
            data = self.split_detection_model_combo.currentData()
            if data:
                self.settings.set("split_detection_model_id", data.get("id", ""))
                self.settings.set("split_detection_model_family", data.get("family", ""))
                self.settings.save()
        except Exception as exc:
            safe_print(f"save split detection model error: {exc}")

    def _get_split_detection_target_file(self) -> Optional[Path]:
        item = self.files_list.currentItem() if hasattr(self, "files_list") else None
        if item is not None:
            raw = item.data(Qt.ItemDataRole.UserRole)
            if raw:
                candidate = Path(str(raw))
                if candidate.exists() and not is_txt_file(candidate):
                    return candidate
        pdfs = [Path(p) for p in (getattr(self, "input_files", []) or []) if not is_txt_file(p)]
        return pdfs[0] if len(pdfs) == 1 else None

    def _validate_split_detection_settings(self) -> Optional[Tuple[int, int, int, int]]:
        min_pages = int(self.split_min_pages_spin.value())
        max_pages = int(self.split_max_pages_spin.value())
        tolerance = int(self.split_tolerance_spin.value())
        fallback = int(self.split_fallback_pages_spin.value())
        # «سماح البحث» لم يعد مستخدماً؛ الحقل الآن = عدد صفحات الدفعة قبل الرفع.
        if tolerance < max_pages:
            QMessageBox.warning(self, "إعدادات غير صالحة",
                                "صفحات الدفعة يجب ألا تقل عن الحد الأقصى للجزء.")
            return None
        if min_pages <= 0:
            QMessageBox.warning(self, "إعدادات غير صالحة", "الحد الأدنى للجزء يجب أن يكون أكبر من صفر.")
            return None
        if max_pages < min_pages:
            QMessageBox.warning(self, "إعدادات غير صالحة", "الحد الأقصى للجزء يجب ألا يقل عن الحد الأدنى.")
            return None
        if tolerance < 2:
            QMessageBox.warning(self, "إعدادات غير صالحة", "صفحات الدفعة يجب أن تكون صفحتين على الأقل.")
            return None
        if fallback <= 0:
            QMessageBox.warning(self, "إعدادات غير صالحة", "الحجم الافتراضي يجب أن يكون أكبر من صفر.")
            return None
        return min_pages, max_pages, tolerance, fallback

    def _sync_split_detection_boundaries_to_target(self):
        if not self._split_detection_exact_enabled or not self._split_detection_source_path:
            return
        key = str(self._split_detection_source_path)
        # التقسيم الذي اختاره المستخدم لكل كتاب من نافذة «دفعات مخصصة» له
        # أولوية مطلقة على الحقل العام القديم؛ لا تسمح هذه المزامنة بإزالته
        # قبل بدء الاستخراج وإعادته إلى حجم الدفعة العادي.
        if (getattr(self, "_file_custom_batches", {}).get(key) or
                getattr(self, "_file_custom_splits", {}).get(key)):
            return
        raw = self.custom_split_text.text().strip()
        if raw:
            self._file_custom_batches[key] = raw

    def _on_custom_split_text_changed(self, *args):
        # بعد التوليد، أي تعديل يدوي في الحقل يحدّث نفس خريطة الدفعات الدقيقة.
        self._sync_split_detection_boundaries_to_target()

    def _on_generate_split_boundaries(self):
        if self._split_detection_thread is not None:
            try:
                if self._split_detection_thread.isRunning():
                    return
            except Exception:
                pass
        source = self._get_split_detection_target_file()
        if source is None:
            QMessageBox.warning(self, "اختيار ملف", "اختر ملف PDF واحداً للتحليل أولاً.")
            return
        settings_values = self._validate_split_detection_settings()
        if settings_values is None:
            return
        model = self.split_detection_model_combo.currentData()
        if not model:
            QMessageBox.warning(self, "اختيار النموذج", "اختر نموذجاً لاكتشاف التقسيم.")
            return
        if not self._has_keys():
            QMessageBox.warning(self, "المفاتيح", "أضف مفتاح API أولاً لاستخدام توليد الحدود.")
            return
        self._save_ui_to_settings()
        min_pages, max_pages, tolerance, fallback = settings_values
        self.settings.set("split_detection_min_pages", min_pages)
        self.settings.set("split_detection_max_pages", max_pages)
        self.settings.set("split_detection_chunk_pages", tolerance)
        self.settings.set("split_detection_fallback_pages", fallback)
        self.settings.save()
        self._split_detection_source_path = source
        self._split_detection_exact_enabled = False
        self._split_detection_known = 0
        self._split_detection_shown = set()
        self._append_log("\n🔍 بدء فحص حدود الأجزاء — في اللوج أثناء العمل")
        self.btn_generate_split_boundaries.setEnabled(False)
        self.split_detection_status_label.setText("جارٍ رفع الملف الكامل للتحليل...")
        self.statusBar().showMessage("جارٍ تحليل بنية الكتاب قبل الاستخراج...", 8000)
        self._split_detection_thread = QThread(self)
        self._split_detection_worker = SplitDetectionWorker(
            source, model, self.tokens_path, self.app_dir,
            dict(self.settings.data), self.global_key_mgr)
        self._split_detection_worker.moveToThread(self._split_detection_thread)
        self._split_detection_worker.status.connect(self._on_split_detection_status, Qt.ConnectionType.QueuedConnection)
        self._split_detection_worker.progress.connect(lambda v: self.split_detection_status_label.setText(f"جارٍ التحليل... {int(v)}%"), Qt.ConnectionType.QueuedConnection)
        self._split_detection_worker.finished.connect(self._on_split_detection_finished, Qt.ConnectionType.QueuedConnection)
        self._split_detection_worker.failed.connect(self._on_split_detection_failed, Qt.ConnectionType.QueuedConnection)
        self._split_detection_worker.partial.connect(self._on_split_detection_partial, Qt.ConnectionType.QueuedConnection)
        self._split_detection_thread.started.connect(self._split_detection_worker.run)
        self._split_detection_worker.finished.connect(self._split_detection_thread.quit)
        self._split_detection_worker.failed.connect(self._split_detection_thread.quit)
        self._split_detection_thread.finished.connect(self._split_detection_worker.deleteLater)
        self._split_detection_thread.finished.connect(
            lambda: self._clear_thread_pair(
                "_split_detection_worker", "_split_detection_thread"),
            Qt.ConnectionType.QueuedConnection)
        self._split_detection_thread.finished.connect(self._split_detection_thread.deleteLater)
        self._split_detection_thread.start()

    def _on_split_detection_status(self, message: str):
        if hasattr(self, "split_detection_status_label"):
            known = int(getattr(self, "_split_detection_known", 0) or 0)
            prefix = f"✅ {known} جزء مؤكّد | " if known else ""
            self.split_detection_status_label.setText(prefix + str(message))
        try:
            self.statusBar().showMessage(str(message), 8000)
        except Exception:
            pass

    def _on_split_detection_finished(self, result: object):
        self.btn_generate_split_boundaries.setEnabled(True)
        data = result if isinstance(result, dict) else {}
        boundaries = data.get("boundaries", [])
        if not boundaries:
            self._on_split_detection_failed("لم ينتج النموذج حدوداً صالحة.")
            return
        raw = "-".join(str(int(x)) for x in boundaries)
        self._split_detection_exact_enabled = True
        self._split_detection_source_path = Path(self._split_detection_source_path)
        self.custom_split_text.setText(raw)
        self._file_custom_batches[str(self._split_detection_source_path)] = raw
        item = self.files_list.currentItem()
        if item is not None and str(item.data(Qt.ItemDataRole.UserRole)) == str(self._split_detection_source_path):
            if "▦ دفعات" not in item.text():
                item.setText(item.text() + "   │  ▦ دفعات")
        warnings = [str(x) for x in (data.get("warnings") or []) if x]
        message = f"تم توليد الحدود بنجاح: {raw} | الصفحات: {data.get('total_pages', '—')} | الأجزاء: {data.get('parts_count', len(boundaries))}"
        if warnings:
            message += "\n⚠️ " + "\n⚠️ ".join(dict.fromkeys(warnings))
        self.split_detection_status_label.setText(message)
        self._split_detection_known = 0
        self._append_log(f"🏁 اكتمل فحص الحدود: {len(boundaries)} جزء — {raw}")
        self.statusBar().showMessage("تم توليد الحدود؛ راجعها وعدّلها ثم اضغط بدء.", 10000)
        self._refresh_session_expected_totals()

    def _on_split_detection_partial(self, data: object):
        """يعرض حدود كل دفعة فور صدورها، دون انتظار اكتمال تحليل الكتاب."""
        payload = data if isinstance(data, dict) else {}
        boundaries = [int(x) for x in (payload.get("boundaries") or []) if str(x).isdigit()]
        if not boundaries:
            return
        try:
            raw = "-".join(str(int(x)) for x in boundaries)
            self.custom_split_text.setText(raw)
            key = str(self._split_detection_source_path) if self._split_detection_source_path else ""
            if key:
                self._file_custom_batches[key] = raw
            self._split_detection_exact_enabled = True
            # عدد الأجزاء يبقى ظاهراً في سطر الحالة ولو تغيّرت الرسالة بعده
            self._split_detection_known = len(boundaries)
            # كل حد جديد يُسجَّل في اللوج فوراً حتى يراه المستخدم ولا يُمحى
            shown = getattr(self, "_split_detection_shown", set())
            fresh = [x for x in boundaries if x not in shown]
            if fresh:
                self._split_detection_shown = set(boundaries)
                for page in sorted(fresh):
                    self._append_log(f"📍 حدّ جديد: جزء يبدأ من الصفحة {page}")
                self._append_log(
                    f"✅ الأجزاء المكتشفة حتى الآن: {len(boundaries)} — {raw}")
            chunk = int(payload.get("chunk") or 0)
            total = int(payload.get("chunks_total") or 0)
            tail = f" — الدفعة {chunk} من {total}" if chunk and total else ""
            self.split_detection_status_label.setText(
                f"✅ {len(boundaries)} جزء مؤكّد{tail} — جارٍ استكمال الفحص...")
            warnings = [str(x) for x in (payload.get("warnings") or []) if x]
            if warnings:
                try:
                    self.statusBar().showMessage("⚠️ " + warnings[-1], 8000)
                except Exception:
                    pass
        except Exception:
            pass

    def _on_split_detection_failed(self, error: str):
        self.btn_generate_split_boundaries.setEnabled(True)
        self.split_detection_status_label.setText(str(error))
        self.statusBar().showMessage("فشل توليد الحدود؛ التقسيم اليدوي ما زال متاحاً.", 8000)
        QMessageBox.warning(self, "فشل توليد الحدود", str(error))

    def _save_batch_analysis_record(self, path: Path, boundaries: List[int],
                                    total_pages: int, scope_start: int = 1,
                                    scope_end: Optional[int] = None, model: Optional[dict] = None,
                                    analysis_mode: str = "", warnings: Optional[List[str]] = None) -> dict:
        scope_end = int(scope_end or total_pages or 0)
        return self.batch_analysis_db.save(
            path, total_pages, scope_start, scope_end, boundaries,
            model=model, analysis_mode=analysis_mode, warnings=warnings)

    def _export_batch_analysis_txt(self, record: dict, parent=None):
        if not record:
            QMessageBox.information(parent or self, "ℹ️", "لا توجد سلسلة تحليل محفوظة للتصدير.")
            return
        default_name = f"{Path(record.get('source_name') or 'book').stem}_split_analysis.txt"
        target, _ = QFileDialog.getSaveFileName(
            parent or self, "تصدير تحليل الدفعات إلى TXT", default_name,
            "Text files (*.txt);;All files (*)")
        if not target:
            return
        lines = [
            "PDF Master Pro v10.20 — تحليل دفعات PDF",
            f"اسم الكتاب: {record.get('source_name', '')}",
            f"مسار الكتاب: {record.get('source_path', '')}",
            f"إجمالي الصفحات: {record.get('total_pages', '')}",
            f"نطاق التحليل: {record.get('scope_start', 1)}-{record.get('scope_end', '')}",
            f"السلسلة: {record.get('sequence_text', '')}",
            f"النموذج: {record.get('model_id', '')}",
            f"وضع التحليل: {record.get('analysis_mode', '')}",
            f"وقت الحفظ: {record.get('updated_at', '')}",
        ]
        warnings = record.get("warnings") or []
        if warnings:
            lines.append("التحذيرات:")
            lines.extend(f"- {w}" for w in warnings)
        try:
            atomic_write_text(Path(target), "\n".join(lines) + "\n", encoding="utf-8")
            QMessageBox.information(parent or self, "تم التصدير", f"تم حفظ الملف:\n{target}")
        except Exception as exc:
            QMessageBox.warning(parent or self, "فشل التصدير", str(exc))

    def _preview_custom_split_parts(self, path: Path, raw: str,
                                    scope_start: int, scope_end: int, parent=None,
                                    force_batch_mode: bool = False):
        """يفتح نافذة المعاينة فوراً، مع إمكانية تعديل السلسلة وإعادة التقسيم بأمان."""
        parent = parent or self
        path = Path(path)
        metric = self._cached_file_metric(path)
        if metric is None:
            self._queue_file_metrics([path])
            QMessageBox.information(parent, "جارٍ الحساب",
                                    "يُحسب عدد صفحات الملف في الخلفية. أعد فتح المعاينة بعد اكتمال الحساب.")
            return
        total_pages = int(metric.get("units") or 0)
        if total_pages <= 0:
            QMessageBox.warning(parent, "المعاينة", "تعذر معرفة عدد صفحات ملف PDF.")
            return
        scope_start = max(1, min(total_pages, int(scope_start or 1)))
        scope_end = max(scope_start, min(total_pages, int(scope_end or total_pages)))

        def parse_preview_ranges(value: str) -> List[Tuple[int, int]]:
            value = normalize_custom_ranges_text(value)
            if not value:
                raise ValueError("أدخل سلسلة حدود أولاً.")
            equals_at = value.find("=")
            has_equals = equals_at >= 0
            if has_equals:
                value_for_parse = value[:equals_at]
                if not value_for_parse.strip():
                    raise ValueError("يجب أن يسبق علامة = رقم صفحة صالح.")
            else:
                value_for_parse = value
            numbers = [int(x) for x in re.findall(r"\d+", value_for_parse)]
            tokens = [x.strip() for x in re.split(r"[\n,;]+", value_for_parse) if x.strip()]
            explicit = len(tokens) > 1 and all("-" in t and t.count("-") == 1 for t in tokens)
            if explicit:
                ranges = parse_custom_split_ranges(value_for_parse, total_pages)
                return [(max(scope_start, a), min(scope_end, b)) for a, b in ranges
                        if max(scope_start, a) <= min(scope_end, b)]
            numbers = [n for n in numbers if scope_start <= n <= scope_end]
            if has_equals:
                boundary_text = "-".join(str(n) for n in numbers) + "="
                return parse_custom_batch_boundaries(boundary_text, scope_end)
            return self._boundary_starts_to_explicit_ranges(numbers, scope_start, scope_end)

        try:
            initial_ranges = parse_preview_ranges(raw)
            if not initial_ranges:
                raise ValueError("لم تنتج السلسلة أي نطاق صالح للمعاينة.")
        except Exception as exc:
            QMessageBox.warning(parent, "حدود غير صالحة", str(exc))
            return

        output_dir = self._resolve_library_output_dir()
        if output_dir is None:
            base_files = list(getattr(self, "input_files", []) or [])
            output_dir = (base_files[0].parent if base_files else path.parent) / "pdf_extracted"
        output_dir = Path(output_dir)
        initial_raw = normalize_custom_ranges_text(raw)
        batch_text = initial_raw if "-" in initial_raw and "," not in initial_raw else ""
        split_text = initial_raw if not batch_text else ""
        book_stem = effective_book_stem_for(path, split_text, batch_text)
        shards_dir = get_book_shards_dir(output_dir, book_stem)
        shards_dir.mkdir(parents=True, exist_ok=True)

        class _SafePreviewDialog(QDialog):
            def __init__(self, dialog_parent=None):
                super().__init__(dialog_parent)
                self._preview_busy = False
                self._preview_status_widget = None

            def _block_close_while_preview_runs(self) -> bool:
                if not self._preview_busy:
                    return False
                try:
                    if self._preview_status_widget is not None:
                        self._preview_status_widget.setPlainText(
                            "⏳ لا يمكن إغلاق المعاينة أثناء إنشاء الأجزاء. "
                            "ستصبح أزرار الإغلاق متاحة بعد اكتمال العملية.")
                except Exception:
                    pass
                return True

            def closeEvent(self, event):
                if self._block_close_while_preview_runs():
                    event.ignore()
                    return
                super().closeEvent(event)

            def reject(self):
                if self._block_close_while_preview_runs():
                    return
                super().reject()

        dlg = _SafePreviewDialog(parent)
        dlg.setWindowTitle(f"👁️ معاينة أجزاء التقسيم — {path.name}")
        dlg.setLayoutDirection(Qt.LayoutDirection.RightToLeft)
        dlg.setWindowFlag(Qt.WindowType.WindowCloseButtonHint, False)
        dlg.resize(720, 580)
        lay = QVBoxLayout(dlg)
        info = QLabel(
            f"الأجزاء تُنشأ في نفس مسار أجزاء الاستخراج قبل البدء:\n{shards_dir}")
        info.setWordWrap(True); lay.addWidget(info)
        lay.addWidget(QLabel("السلسلة الحالية — يمكنك تعديل رقم الحد ثم اعتماد التعديل:"))
        sequence_edit = QPlainTextEdit(initial_raw)
        sequence_edit.setMaximumHeight(62); sequence_edit.setMinimumHeight(38)
        sequence_edit.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        lay.addWidget(sequence_edit)
        status = QPlainTextEdit("جارٍ إنشاء أجزاء المعاينة...\nيمكنك اعتماد تعديل السلسلة بعد اكتمال الإنشاء.")
        status.setReadOnly(True); status.setMaximumHeight(66)
        status.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        dlg._preview_status_widget = status
        lay.addWidget(status)
        scroll = QScrollArea(); scroll.setWidgetResizable(True)
        host = QWidget(); list_lay = QVBoxLayout(host)
        list_lay.setContentsMargins(4, 4, 4, 4); list_lay.setSpacing(2)
        list_lay.addWidget(QLabel("ستظهر أزرار فتح الأجزاء هنا بعد اكتمال التقسيم:"))
        list_lay.addStretch(1); scroll.setWidget(host); lay.addWidget(scroll, 1)
        bottom_row = QHBoxLayout(); bottom_row.setContentsMargins(0, 0, 0, 0); bottom_row.setSpacing(2)
        approve_btn = QPushButton("✅ اعتماد التعديل الحالي")
        approve_btn.setToolTip("حذف أجزاء هذا الكتاب القديمة وإعادة تقسيمه بالسلسلة المعدلة")
        approve_btn.setEnabled(False)
        close_btn = QPushButton("إغلاق"); close_btn.setToolTip("إغلاق نافذة المعاينة")
        close_btn.setEnabled(False)
        bottom_row.addWidget(approve_btn); bottom_row.addWidget(close_btn); lay.addLayout(bottom_row)

        state = {"thread": None, "worker": None, "busy": False, "last_shards": []}

        def clear_parts_list():
            while list_lay.count():
                child = list_lay.takeAt(0)
                if child.widget() is not None:
                    child.widget().deleteLater()

        def populate(shards):
            clear_parts_list()
            if not shards:
                list_lay.addWidget(QLabel("لم يتم إنشاء أجزاء للمعاينة."))
            else:
                for shard in sorted(shards, key=lambda x: x.idx):
                    row = QHBoxLayout()
                    label = QLabel(f"الجزء {shard.idx}: الصفحات {shard.page_start}-{shard.page_end} ({shard.pages_count} صفحة)")
                    label.setWordWrap(True); row.addWidget(label, 1)
                    open_btn = QPushButton("📖")
                    open_btn.setFixedSize(42, 34)
                    open_btn.setToolTip(f"فتح الجزء {shard.idx} ({shard.page_start}-{shard.page_end})")
                    open_btn.clicked.connect(lambda checked=False, p=str(shard.shard_path): self._open_path(p))
                    row.addWidget(open_btn); list_lay.addLayout(row)
            list_lay.addStretch(1)
            state["last_shards"] = list(shards or [])

        def failed(message):
            state["last_shards"] = []
            status.setPlainText(str(message))

        def on_thread_finished():
            state["busy"] = False
            dlg._preview_busy = False
            shards = state.get("last_shards") or []
            approve_btn.setEnabled(bool(shards))
            close_btn.setEnabled(True)
            thread = state.get("thread")
            worker = state.get("worker")
            if getattr(self, "_preview_shards_thread", None) is thread:
                self._preview_shards_thread = None
            if getattr(self, "_preview_shards_worker", None) is worker:
                self._preview_shards_worker = None
            state["thread"] = None; state["worker"] = None
            dlg._preview_thread = None; dlg._preview_worker = None

        def start_job(custom_ranges, replace_existing=False):
            if state.get("busy"):
                return
            state["busy"] = True
            dlg._preview_busy = True
            state["last_shards"] = []
            approve_btn.setEnabled(False); close_btn.setEnabled(False)
            status.setPlainText(
                "جارٍ حذف الأجزاء القديمة وإعادة التقسيم بالسلسلة المعدلة..." if replace_existing
                else "جارٍ إنشاء أجزاء المعاينة...\nيمكنك اعتماد تعديل السلسلة بعد اكتمال الإنشاء.")
            clear_parts_list()
            # Keep the thread parented to MainWindow, not this local dialog;
            # MainWindow tracks it and waits safely during application shutdown.
            thread = QThread(self)
            worker = PreviewShardsWorker(path, shards_dir, custom_ranges, replace_existing=replace_existing)
            worker.moveToThread(thread)
            worker.finished.connect(populate, Qt.ConnectionType.QueuedConnection)
            worker.failed.connect(failed, Qt.ConnectionType.QueuedConnection)
            worker.finished.connect(thread.quit); worker.failed.connect(thread.quit)
            thread.finished.connect(on_thread_finished, Qt.ConnectionType.QueuedConnection)
            thread.finished.connect(worker.deleteLater); thread.finished.connect(thread.deleteLater)
            thread.started.connect(worker.run)
            state["thread"] = thread; state["worker"] = worker
            dlg._preview_thread = thread; dlg._preview_worker = worker
            self._preview_shards_thread = thread
            self._preview_shards_worker = worker
            thread.start()

        def persist_approved_sequence(edited_raw, new_ranges, batch_mode: bool = False):
            cleaned = normalize_custom_ranges_text(edited_raw)
            equals_at = cleaned.find("=")
            if equals_at >= 0:
                cleaned = cleaned[:equals_at + 1]
            before_equals = cleaned[:-1] if cleaned.endswith("=") else cleaned
            tokens = [x.strip() for x in re.split(r"[\n,;]+", before_equals) if x.strip()]
            explicit = len(tokens) > 1 and all("-" in t and t.count("-") == 1 for t in tokens)
            key = str(path)
            if batch_mode or (scope_start == 1 and scope_end == total_pages and not explicit):
                # داخل نافذة «دفعات مخصصة»، تظل السلسلة دفعات مخصصة حتى لو
                # كان نطاق التحليل يبدأ من صفحة لاحقة. exact=True يمنع
                # pages_per_batch من تفتيت هذه الدفعات.
                if explicit:
                    raw_batch = ",".join(f"{a}-{b}" for a, b in new_ranges)
                else:
                    starts = [a for a, _b in new_ranges]
                    raw_batch = cleaned or "-".join(str(n) for n in starts)
                self._file_custom_batches[key] = raw_batch
                self._file_custom_splits.pop(key, None)
            else:
                # نطاقات صريحة من الحقل اليدوي الخاص بالاستخراج الجزئي.
                raw_ranges = ",".join(f"{a}-{b}" for a, b in new_ranges)
                self._file_custom_splits[key] = raw_ranges
                self._file_custom_batches.pop(key, None)
            try:
                self._save_batch_analysis_record(
                    path, [a for a, _b in new_ranges], total_pages,
                    scope_start, scope_end, analysis_mode="تعديل يدوي معتمد بعد المعاينة")
            except Exception:
                pass
            try:
                for idx in range(self.files_list.count()):
                    file_item = self.files_list.item(idx)
                    if str(file_item.data(Qt.ItemDataRole.UserRole)) == key:
                        label = file_item.text().replace("   │  ✂️ جزئي", "").replace("   │  ▦ دفعات", "")
                        label += "   │  ✂️ جزئي" if (explicit or scope_start != 1 or scope_end != total_pages) else "   │  ▦ دفعات"
                        file_item.setText(label)
                        break
                self._update_files_stats(); self._refresh_session_expected_totals()
            except Exception:
                pass

        def approve_current():
            edited_raw = sequence_edit.toPlainText()
            try:
                new_ranges = parse_preview_ranges(edited_raw)
                if not new_ranges:
                    raise ValueError("لم تنتج السلسلة المعدلة أي نطاق صالح.")
            except Exception as exc:
                QMessageBox.warning(dlg, "سلسلة غير صالحة", str(exc)); return
            # الاعتماد هنا دائم على مستوى البرنامج، وليس على ملفات المعاينة فقط.
            persist_approved_sequence(edited_raw, new_ranges, batch_mode=bool(getattr(dlg, "_preview_force_batch_mode", False)))
            approve_btn.setEnabled(False)
            start_job(new_ranges, replace_existing=True)

        approve_btn.clicked.connect(approve_current)
        close_btn.clicked.connect(dlg.accept)
        start_job(initial_ranges, replace_existing=False)
        dlg.exec()

    def _open_parts_review_screen(self, path: Path, raw: str,
                                  scope_start: int, scope_end: int, parent=None,
                                  force_batch_mode: bool = False, on_approved=None):
        """يفتح شاشة استعراض الأجزاء: كل جزء له زر يفتح ملفه نفسه داخل الشاشة
        (مع بيان من صفحة رقم كم يبدأ)، والسلسلة في لابل أسفل الشاشة قابلة
        للتعديل — الحفظ والاعتماد يجعل التقسيم على أساسها."""
        parent = parent or self
        if self._is_thread_alive("_parts_review_thread"):
            QMessageBox.information(
                parent, "شاشة الأجزاء",
                "ما زالت معاينة سابقة تنشئ الأجزاء في الخلفية؛ انتظر اكتمالها أولاً.")
            return
        path = Path(path)
        metric = self._cached_file_metric(path)
        if metric is None:
            self._queue_file_metrics([path])
            QMessageBox.information(
                parent, "جارٍ الحساب",
                "يُحسب عدد صفحات الملف في الخلفية. أعد فتح شاشة الأجزاء بعد اكتمال الحساب.")
            return
        total_pages = int(metric.get("units") or 0)
        if total_pages <= 0:
            QMessageBox.warning(parent, "شاشة الأجزاء", "تعذر معرفة عدد صفحات ملف PDF.")
            return
        scope_start = max(1, min(total_pages, int(scope_start or 1)))
        scope_end = max(scope_start, min(total_pages, int(scope_end or total_pages)))
        initial_raw = normalize_custom_ranges_text(raw)
        if not initial_raw:
            QMessageBox.warning(parent, "شاشة الأجزاء",
                                "ولّد أو أدخل سلسلة حدود صالحة أولاً.")
            return

        def parse_review_ranges(value: str) -> List[Tuple[int, int]]:
            # نفس منطق تحليل السلسلة المستخدم في نافذة المعاينة
            value = normalize_custom_ranges_text(value)
            if not value:
                raise ValueError("أدخل سلسلة حدود أولاً.")
            equals_at = value.find("=")
            has_equals = equals_at >= 0
            if has_equals:
                value_for_parse = value[:equals_at]
                if not value_for_parse.strip():
                    raise ValueError("يجب أن يسبق علامة = رقم صفحة صالح.")
            else:
                value_for_parse = value
            tokens = [x.strip() for x in re.split(r"[\n,;]+", value_for_parse) if x.strip()]
            explicit = len(tokens) > 1 and all("-" in t and t.count("-") == 1 for t in tokens)
            if explicit:
                ranges = parse_custom_split_ranges(value_for_parse, total_pages)
                return [(max(scope_start, a), min(scope_end, b)) for a, b in ranges
                        if max(scope_start, a) <= min(scope_end, b)]
            numbers = [int(x) for x in re.findall(r"\d+", value_for_parse)]
            numbers = [n for n in numbers if scope_start <= n <= scope_end]
            if not numbers:
                raise ValueError("لا توجد أرقام صفحات صالحة في السلسلة ضمن نطاق التحليل.")
            if has_equals:
                boundary_text = "-".join(str(n) for n in numbers) + "="
                return parse_custom_batch_boundaries(boundary_text, scope_end)
            return self._boundary_starts_to_explicit_ranges(numbers, scope_start, scope_end)

        try:
            initial_ranges = parse_review_ranges(initial_raw)
            if not initial_ranges:
                raise ValueError("لم تنتج السلسلة أي نطاق صالح لشاشة الأجزاء.")
        except Exception as exc:
            QMessageBox.warning(parent, "حدود غير صالحة", str(exc))
            return

        output_dir = self._resolve_library_output_dir()
        if output_dir is None:
            base_files = list(getattr(self, "input_files", []) or [])
            output_dir = (base_files[0].parent if base_files else path.parent) / "pdf_extracted"
        output_dir = Path(output_dir)
        batch_text = initial_raw if "-" in initial_raw and "," not in initial_raw else ""
        split_text = initial_raw if not batch_text else ""
        book_stem = effective_book_stem_for(path, split_text, batch_text)
        shards_dir = get_book_shards_dir(output_dir, book_stem)
        shards_dir.mkdir(parents=True, exist_ok=True)

        def _approved(edited_raw, new_ranges):
            try:
                self._commit_parts_review_sequence(
                    path, edited_raw, new_ranges, total_pages,
                    scope_start, scope_end, batch_mode=force_batch_mode)
            except Exception as exc:
                try:
                    QMessageBox.warning(parent, "تعذر الاعتماد", str(exc))
                except RuntimeError:
                    QMessageBox.warning(self, "تعذر الاعتماد", str(exc))
                return
            if on_approved is not None:
                try:
                    on_approved(edited_raw, new_ranges)
                except Exception:
                    pass

        # ✅ v10.19: شاشة عادية غير حاجبة (show بدل exec) ومرجع محفوظ.
        prev_dlg = getattr(self, "_parts_review_dialog", None)
        if prev_dlg is not None:
            try:
                if prev_dlg.isVisible():
                    prev_dlg.showNormal() if prev_dlg.isMinimized() else prev_dlg.show()
                    prev_dlg.raise_()
                    prev_dlg.activateWindow()
                    return
            except RuntimeError:
                pass
            self._parts_review_dialog = None
        dlg = PartsReviewDialog(
            path, shards_dir, initial_ranges, initial_raw, total_pages,
            parse_fn=parse_review_ranges, on_approved=_approved, parent=parent)
        dlg._main_window_owner = self
        self._parts_review_dialog = dlg
        self._parts_review_thread = dlg._job_thread
        self._parts_review_worker = dlg._job_worker

        def _forget_parts_review(_r=None, _d=dlg):
            if getattr(self, "_parts_review_dialog", None) is _d:
                self._parts_review_dialog = None

        dlg.finished.connect(_forget_parts_review)
        dlg.show()

    def _commit_parts_review_sequence(self, path: Path, edited_raw: str,
                                      new_ranges: List[Tuple[int, int]],
                                      total_pages: int, scope_start: int,
                                      scope_end: int, batch_mode: bool = False):
        """حفظ السلسلة المعتمدة من شاشة استعراض الأجزاء كتقسيم معتمد للكتاب
        (بنفس منطق اعتماد التعديل من نافذة المعاينة)."""
        cleaned = normalize_custom_ranges_text(edited_raw)
        equals_at = cleaned.find("=")
        if equals_at >= 0:
            cleaned = cleaned[:equals_at + 1]
        before_equals = cleaned[:-1] if cleaned.endswith("=") else cleaned
        tokens = [x.strip() for x in re.split(r"[\n,;]+", before_equals) if x.strip()]
        explicit = len(tokens) > 1 and all("-" in t and t.count("-") == 1 for t in tokens)
        key = str(path)
        if batch_mode or (scope_start == 1 and scope_end == total_pages and not explicit):
            # داخل نافذة «دفعات مخصصة» تظل السلسلة دفعات مخصصة؛ exact=True يمنع
            # pages_per_batch من تفتيت هذه الدفعات.
            if explicit:
                raw_batch = ",".join(f"{a}-{b}" for a, b in new_ranges)
            else:
                starts = [a for a, _b in new_ranges]
                raw_batch = cleaned or "-".join(str(n) for n in starts)
            self._file_custom_batches[key] = raw_batch
            self._file_custom_splits.pop(key, None)
        else:
            # نطاقات صريحة من الحقل الخاص بالاستخراج الجزئي.
            raw_ranges = ",".join(f"{a}-{b}" for a, b in new_ranges)
            self._file_custom_splits[key] = raw_ranges
            self._file_custom_batches.pop(key, None)
        try:
            self._save_batch_analysis_record(
                path, [a for a, _b in new_ranges], total_pages,
                scope_start, scope_end, analysis_mode="تعديل يدوي معتمد من شاشة استعراض الأجزاء")
        except Exception:
            pass
        try:
            for idx in range(self.files_list.count()):
                file_item = self.files_list.item(idx)
                if str(file_item.data(Qt.ItemDataRole.UserRole)) == key:
                    label = file_item.text().replace("   │  ✂️ جزئي", "").replace("   │  ▦ دفعات", "")
                    label += "   │  ✂️ جزئي" if (explicit or scope_start != 1 or scope_end != total_pages) else "   │  ▦ دفعات"
                    file_item.setText(label)
                    break
            self._update_files_stats(); self._refresh_session_expected_totals()
        except Exception:
            pass

    def _boundary_starts_to_explicit_ranges(self, starts: List[int], scope_start: int,
                                            scope_end: int) -> List[Tuple[int, int]]:
        nums = sorted(set(int(x) for x in starts if scope_start <= int(x) <= scope_end))
        if not nums or nums[0] != scope_start:
            nums.insert(0, scope_start)
        ranges = []
        for i, start_page in enumerate(nums):
            end_page = nums[i + 1] - 1 if i + 1 < len(nums) else scope_end
            if end_page >= start_page:
                ranges.append((start_page, end_page))
        return ranges

