#  Initial Splash Screen — شاشة التحميل الابتدائية
# ═══════════════════════════════════════════════════════════════════

class InitialSplashScreen(QDialog):
    """شاشة تحميل ابتدائية تفاعلية على نمط Gemini TTS Pro."""
    def __init__(self, app_dir: Path, parent=None):
        super().__init__(parent)
        self.app_dir = Path(app_dir)
        self.setWindowFlags(Qt.WindowType.FramelessWindowHint | Qt.WindowType.Dialog)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
        self.setLayoutDirection(Qt.LayoutDirection.RightToLeft)
        self.resize(760, 500)

        main_layout = QVBoxLayout(self)
        main_layout.setContentsMargins(10, 10, 10, 10)

        container = QFrame()
        container.setObjectName("initialSplashContainer")
        container.setStyleSheet("""
            QFrame#initialSplashContainer {
                background-color:#11111b;
                border:2px solid #89b4fa;
                border-radius:18px;
            }
            QLabel { border:none; background:transparent; }
            QLabel#splashTitle {
                font-size:30px; font-weight:900; color:#f9e2af; letter-spacing:1px;
            }
            QLabel#splashSubTitle {
                font-size:15px; font-weight:800; color:#89b4fa;
            }
            QFrame#featuresFrame {
                background-color:#181825;
                border:1px solid #313244;
                border-radius:12px;
                padding:8px;
            }
            QLabel#featuresHeader {
                color:#a6e3a1;
                font-size:14px;
                font-weight:900;
            }
            QLabel#featureLine {
                color:#cdd6f4;
                font-size:13px;
                font-weight:700;
            }
            QLabel#statusLabel {
                color:#fab387;
                font-size:14px;
                font-weight:900;
            }
            QProgressBar {
                background-color:#313244;
                border:1px solid #45475a;
                border-radius:7px;
                height:20px;
                text-align:center;
                color:#ffffff;
                font-weight:900;
            }
            QProgressBar::chunk {
                background-color:#a6e3a1;
                border-radius:6px;
            }
        """)
        cont_layout = QVBoxLayout(container)
        cont_layout.setContentsMargins(26, 24, 26, 22)
        cont_layout.setSpacing(14)

        hdr_layout = QHBoxLayout()
        icon_lbl = QLabel()
        try:
            icon_path = resolve_app_icon_path(self.app_dir)
            icon = QIcon(str(icon_path)) if icon_path else QApplication.windowIcon()
            pix = icon.pixmap(74, 74)
            if pix and not pix.isNull():
                icon_lbl.setPixmap(pix)
            else:
                icon_lbl.setText("📚")
                icon_lbl.setStyleSheet("font-size:58px;")
        except Exception:
            icon_lbl.setText("📚")
            icon_lbl.setStyleSheet("font-size:58px;")
        hdr_layout.addWidget(icon_lbl)

        title_box = QVBoxLayout()
        title_lbl = QLabel("PDF Master Pro")
        title_lbl.setObjectName("splashTitle")
        sub_lbl = QLabel("الإصدار v10.14 — استوديو استخراج ومعالجة ومقارنة الكتب")
        sub_lbl.setObjectName("splashSubTitle")
        title_box.addWidget(title_lbl)
        title_box.addWidget(sub_lbl)
        hdr_layout.addLayout(title_box)
        hdr_layout.addStretch(1)
        cont_layout.addLayout(hdr_layout)

        feat_frame = QFrame()
        feat_frame.setObjectName("featuresFrame")
        feat_layout = QVBoxLayout(feat_frame)
        feat_layout.setSpacing(8)
        feat_layout.setContentsMargins(12, 10, 12, 10)
        feat_hdr = QLabel("✨ جاري تهيئة بيئة العمل والميزات الأساسية")
        feat_hdr.setObjectName("featuresHeader")
        feat_layout.addWidget(feat_hdr)
        features = [
            "📄 تجهيز محرك PDF والملفات النصية وتقسيم الدفعات.",
            "🔑 تحميل إدارة المفاتيح والكوتة والحظر حسب النموذج.",
            "🔍 تهيئة المقارنة، إعادة الفحص، والجلسات السابقة.",
            "📁 تجهيز مجلدات الحفظ و _pdf_master_data ونقاط الاستكمال.",
            "🎨 بناء الواجهة، السجل الملون، وشاشات العرض المباشر."
        ]
        for item in features:
            fl = QLabel(item)
            fl.setObjectName("featureLine")
            fl.setWordWrap(True)
            feat_layout.addWidget(fl)
        cont_layout.addWidget(feat_frame, 1)

        self.status_lbl = QLabel("⚡ جاري تجهيز PDF Master Pro...")
        self.status_lbl.setObjectName("statusLabel")
        cont_layout.addWidget(self.status_lbl)

        self.progress = QProgressBar()
        self.progress.setRange(0, 100)
        self.progress.setValue(0)
        self.progress.setTextVisible(True)
        cont_layout.addWidget(self.progress)

        main_layout.addWidget(container)

        self._step = 0
        self._timer = QTimer(self)
        self._timer.timeout.connect(self._on_timer)
        self._timer.start(35)

    def _on_timer(self):
        self._step = min(98, self._step + 2)
        self.progress.setValue(self._step)
        if self._step == 20:
            self.status_lbl.setText("🔐 تحميل إعدادات المفاتيح والنماذج...")
        elif self._step == 46:
            self.status_lbl.setText("📚 تجهيز مسارات الكتب والجلسات السابقة...")
        elif self._step == 74:
            self.status_lbl.setText("🎨 بناء الواجهة وشاشة العرض والسجل...")

    def showMessage(self, message: str, alignment=None, color=None):
        try:
            self.status_lbl.setText(str(message))
        except Exception:
            pass

    def finish(self, widget):
        try:
            self._timer.stop()
            self.progress.setValue(100)
            self.status_lbl.setText("✨ اكتمل التحميل... جاري فتح النافذة الرئيسية")
            QApplication.processEvents()
            QTimer.singleShot(120, self.close)
        except Exception:
            self.close()


# ═══════════════════════════════════════════════════════════════════
#  main()
# ═══════════════════════════════════════════════════════════════════

def main():
    # ✅ إصلاح: عند التحزيم بـ PyInstaller (وضع onedir)، __file__ للسكربت
    # المُجمَّع قد لا يشير لمجلد الـ exe الفعلي (dist/PDFMasterPro)، فتفشل
    # resolve_app_icon_path دائماً في إيجاد ملف الأيقونة المرافق حتى لو كان
    # موجوداً فعلاً بجانب البرنامج — وهذا كان سبب عدم ظهور الأيقونة على
    # شريط المهام أثناء التشغيل. عند التشغيل المُجمَّع، المسار الصحيح هو
    # مجلد sys.executable نفسه (مكان ملف EXE)، وليس __file__.
    if getattr(sys, "frozen", False):
        app_dir = Path(sys.executable).resolve().parent
    else:
        app_dir = Path(__file__).resolve().parent
    try:
        # ✅ v28.7/v29.0: تهيئة السجل والتشخيص مبكراً
        try:
            setup_app_logging(app_dir)
        except Exception:
            pass
        try:
            # ✅ v29.0: تتبع الانهيارات الأصلية
            fh_path = app_dir / "pdf_master_fault.log"
            _fh = open(fh_path, "a", encoding="utf-8", errors="replace")
            faulthandler.enable(file=_fh, all_threads=True)
        except Exception:
            try:
                faulthandler.enable(all_threads=True)
            except Exception:
                pass
        try:
            import platform
            LOGGER.info("Python %s | platform %s | PDF_BACKEND later", sys.version.replace("\n"," "), platform.platform())
        except Exception:
            pass

        def _excepthook(exc_type, exc, tb):
            try:
                LOGGER.exception("Uncaught exception", exc_info=(exc_type, exc, tb))
            except Exception:
                pass
            try:
                sys.__excepthook__(exc_type, exc, tb)
            except Exception:
                pass
        sys.excepthook = _excepthook
        try:
            def _thread_excepthook(args):
                # ✅ v10.20: InterruptedError هو إشارة الإيقاف المعتادة (من
                # interruptible_sleep) وليس عطلاً؛ لا نسجّله كـ «Uncaught».
                if issubclass(args.exc_type, InterruptedError):
                    try:
                        LOGGER.info("خيط %s أُوقف بالإيقاف الطبيعي",
                                    getattr(getattr(args, "thread", None), "name", "?"))
                    except Exception:
                        pass
                    return
                try:
                    LOGGER.exception(
                        "Uncaught thread exception in %s", getattr(args, "thread", None),
                        exc_info=(args.exc_type, args.exc_value, args.exc_traceback))
                except Exception:
                    pass
            threading.excepthook = _thread_excepthook  # type: ignore[attr-defined]
        except Exception:
            pass

        set_windows_app_user_model_id()
        app = QApplication(sys.argv)
        app.setApplicationName("PDF Master Pro v10.20")
        try:
            LOGGER.info("PDF_BACKEND=%s, PDF_SPLIT_AVAILABLE=%s | PyQt6 app started", PDF_BACKEND, PDF_SPLIT_AVAILABLE)
        except Exception:
            pass
        if PDF_BACKEND == "builtin":
            LOGGER.warning("Builtin PDF backend is used. For better performance, install pikepdf, pypdf, or pdfrw.")
        app.setOrganizationName("PDF Master")
        app.setStyle("Fusion")
        app.setStyleSheet(DARK_STYLE)

        default_font = QFont("Tahoma, Segoe UI, Arial", 10)
        app.setFont(default_font)

        # ✅ v29.3: أيقونة التطبيق العامة (تظهر في شريط المهام بعد التحزيم)
        icon_path = resolve_app_icon_path(app_dir)
        if icon_path is not None:
            try:
                app.setWindowIcon(QIcon(str(icon_path)))
            except Exception:
                pass

        # ✅ v3.6: شاشة تحميل ابتدائية تفاعلية بدلاً من الصورة الثابتة.
        splash = None
        try:
            splash = InitialSplashScreen(app_dir)
            splash.show()
            app.processEvents()
        except Exception as e:
            try:
                LOGGER.debug("initial splash failed: %s", e)
            except Exception:
                pass
            splash = None

        win = MainWindow(app_dir)
        try:
            # ✅ v28.3: عرض آمن ضمن الشاشة المتاحة
            scr = app.primaryScreen()
            if scr is not None:
                ag = scr.availableGeometry()
                win.setMinimumSize(min(700, ag.width() - 40), min(480, ag.height() - 40))
            if splash is not None:
                try:
                    splash.showMessage(
                        "اكتمل التحميل...",
                        int(Qt.AlignmentFlag.AlignBottom | Qt.AlignmentFlag.AlignCenter),
                        QColor("#a6e3a1"))
                    app.processEvents()
                except Exception:
                    pass
            win.showMaximized()
            if splash is not None:
                try:
                    splash.finish(win)
                except Exception:
                    try: splash.close()
                    except Exception: pass
            QTimer.singleShot(0, win._clamp_window_to_screen)
        except Exception:
            try:
                if splash is not None:
                    splash.close()
            except Exception:
                pass
            win.showMaximized()

        def on_exit():
            try:
                win.settings.save()
                win.global_key_mgr.save()
            except Exception:
                pass
        atexit.register(on_exit)

        def signal_handler(sig, frame):
            safe_print("\n⛔ إشارة إيقاف — حفظ والخروج...")
            try:
                win._closing = True
                if win.worker:
                    win.worker.stop()
                if win._autoloop_worker:
                    win._autoloop_worker.stop()
                if win._manual_recheck_worker:
                    win._manual_recheck_worker.stop()
                win.settings.save()
                win.global_key_mgr.save()
            except Exception:
                pass
            app.quit()

        try:
            signal.signal(signal.SIGINT, signal_handler)
            signal.signal(signal.SIGTERM, signal_handler)
        except Exception:
            pass

        sys.exit(app.exec())

    except Exception as e:
        tb = traceback.format_exc()
        safe_print(f"💥 خطأ فادح: {e}\n{tb}")
        try:
            QMessageBox.critical(None, "خطأ فادح",
                f"البرنامج توقف بسبب خطأ:\n\n{e}\n\nراجع الكونسول.")
        except Exception:
            pass
        sys.exit(1)


def set_windows_app_user_model_id():
    try:
        if sys.platform == "win32":
            import ctypes
            ctypes.windll.shell32.SetCurrentProcessExplicitAppUserModelID("PDFMasterPro.v10.20.Personal")
    except Exception:
        pass


if __name__ == "__main__":
    main()


